/**
 * Stated equations: for each flashcard with equations, what every term means (?),
 * how each equation line is read aloud (…; `line` is its index in the card's body),
 * an explanation and origin, and common implementations. Keyed by card id.
 * Loaded on demand by modules/stated.js.
 */
(function (Site) {
  Site.statedEquations = {"T.1":{"spoken":[{"line":0,"text":"sine of theta equals opposite over hypotenuse; cosine of theta equals adjacent over hypotenuse; tangent of theta equals opposite over adjacent"},{"line":1,"text":"cosecant of theta equals 1 over sine of theta; secant of theta equals 1 over cosine of theta; cotangent of theta equals 1 over tangent of theta"}],"terms":[{"term":"sin","meaning":"Sine function: takes an acute angle of a right triangle and returns the ratio of the opposite side to the hypotenuse.","function":true},{"term":"θ","meaning":"Theta: the acute angle of the right triangle being measured, from whose position opposite and adjacent sides are named.","function":false},{"term":"opp","meaning":"Length of the leg directly across from angle theta in the right triangle.","function":false},{"term":"hyp","meaning":"Length of the hypotenuse, the longest side, which lies opposite the right angle.","function":false},{"term":"cos","meaning":"Cosine function: takes the angle theta and returns the ratio of the adjacent leg to the hypotenuse.","function":true},{"term":"adj","meaning":"Length of the leg that touches angle theta and is not the hypotenuse.","function":false},{"term":"tan","meaning":"Tangent function: takes the angle theta and returns opposite over adjacent, which also equals sine divided by cosine.","function":true},{"term":"csc","meaning":"Cosecant function: takes theta and returns the reciprocal of sine, hypotenuse over opposite.","function":true},{"term":"sec","meaning":"Secant function: takes theta and returns the reciprocal of cosine, hypotenuse over adjacent.","function":true},{"term":"cot","meaning":"Cotangent function: takes theta and returns the reciprocal of tangent, adjacent over opposite.","function":true}],"explanation":"In a right triangle, each trigonometric ratio compares two sides relative to an acute angle θ: sine is opposite over hypotenuse, cosine is adjacent over hypotenuse, and tangent is opposite over adjacent. Because similar right triangles share these ratios, they depend only on the angle. The second row defines cosecant, secant and cotangent as the reciprocals of sine, cosine and tangent.","origin":"Grew from Hipparchus's chord tables (2nd century BC) and the Indian sine (jya) used by Aryabhata around 500 AD; the six-function system was standardized in early modern Europe.","implementations":[{"name":"math.sin","library":"Python standard library","note":"Sine of an angle given in radians."},{"name":"math.cos","library":"Python standard library","note":"Cosine of an angle given in radians."},{"name":"math.tan","library":"Python standard library","note":"Tangent of an angle given in radians."},{"name":"=SIN()","library":"Excel","note":"Sine of an angle in radians."}]},"T.2":{"spoken":[{"line":0,"text":"pi radians equals 180 degrees"},{"line":1,"text":"theta in radians equals theta in degrees times pi over 180 degrees"},{"line":2,"text":"s equals r theta; v equals r omega"}],"terms":[{"term":"π","meaning":"Pi, about 3.14159; here pi radians is the measure of a half turn, the bridge between radians and degrees.","function":false},{"term":"rad","meaning":"Radian: the angle unit where one radian subtends an arc equal in length to the circle's radius.","function":false},{"term":"°","meaning":"Degree: the angle unit equal to one 360th of a full turn.","function":false},{"term":"θ","meaning":"Theta: an angle measure; the subscript tells whether it is expressed in radians or in degrees.","function":false},{"term":"π/180°","meaning":"Conversion factor; multiplying a degree measure by it cancels the degrees and gives the angle in radians.","function":false},{"term":"s","meaning":"Arc length: the distance along the circle swept out by central angle theta, valid with theta in radians.","function":false},{"term":"r","meaning":"Radius of the circle, the distance from the center to the point moving around it.","function":false},{"term":"v","meaning":"Linear speed: how fast a point on the circle travels along its path, in distance per unit time.","function":false},{"term":"ω","meaning":"Omega: angular speed, the rate at which the angle changes, in radians per unit time.","function":false}],"explanation":"A radian is the angle that cuts off an arc equal to the radius, so a full turn is 2π radians and π radians equals 180°. Converting degrees to radians multiplies by π/180. Measuring in radians makes arc length simply s = rθ, and dividing by time gives linear speed v = rω, where ω is angular speed.","origin":"Degrees come from Babylonian base-60 astronomy; Roger Cotes used the radian concept in 1714, and the name \"radian\" appeared in the 1870s, credited to James Thomson.","implementations":[{"name":"math.radians","library":"Python standard library","note":"Converts degrees to radians."},{"name":"math.degrees","library":"Python standard library","note":"Converts radians to degrees."},{"name":"numpy.deg2rad","library":"NumPy","note":"Element-wise degrees to radians."},{"name":"=RADIANS()","library":"Excel","note":"Converts degrees to radians."}]},"T.3":{"spoken":[{"line":0,"text":"the point cosine of theta, sine of theta"},{"line":1,"text":"a table: theta: 0, pi over 6, pi over 4, pi over 3, pi over 2. sine: 0, 1 over 2, the square root of 2 over 2, the square root of 3 over 2, 1. cosine: 1, the square root of 3 over 2, the square root of 2 over 2, 1 over 2, 0"}],"terms":[{"term":"(cos θ, sin θ)","meaning":"The coordinates of the point where the terminal side of angle theta meets the unit circle: x is cosine, y is sine.","function":false},{"term":"cos","meaning":"Cosine function: takes an angle and returns the x-coordinate of its point on the unit circle.","function":true},{"term":"θ","meaning":"Theta: an angle in standard position, measured in radians counterclockwise from the positive x-axis.","function":false},{"term":"sin","meaning":"Sine function: takes an angle and returns the y-coordinate of its point on the unit circle.","function":true},{"term":"π","meaning":"Pi, about 3.14159; pi over 6, 4, 3 and 2 are the special angles 30, 45, 60 and 90 degrees in radians.","function":false},{"term":"√","meaning":"Square root: takes a nonnegative number and returns the nonnegative number whose square is it; appears in exact values like root 3 over 2.","function":true}],"explanation":"On the unit circle (radius 1), the point at angle θ from the positive x-axis has coordinates (cos θ, sin θ), which extends sine and cosine to every angle. The table lists exact values at the standard angles 0, π/6, π/4, π/3 and π/2, which come from the 30-60-90 and 45-45-90 triangles. Reflecting across the axes gives values in the other quadrants, with signs set by the quadrant.","origin":"","implementations":[{"name":"sympy.sin","library":"SymPy","note":"Returns exact symbolic values, e.g. sin(pi/6) = 1/2."},{"name":"sympy.cos","library":"SymPy","note":"Exact symbolic cosine at special angles."},{"name":"numpy.sin","library":"NumPy","note":"Numerical element-wise sine."}]},"T.4":{"spoken":[{"line":0,"text":"sine squared theta plus cosine squared theta equals 1"},{"line":1,"text":"1 plus tangent squared theta equals secant squared theta; 1 plus cotangent squared theta equals cosecant squared theta"},{"line":2,"text":"sine of negative theta equals negative sine of theta; cosine of negative theta equals cosine of theta"}],"terms":[{"term":"sin² θ","meaning":"The square of the sine of theta, written with the exponent after sin; it means the quantity sine theta, squared.","function":true},{"term":"θ","meaning":"Theta: any angle for which the functions are defined; the identities hold for every such angle.","function":false},{"term":"cos² θ","meaning":"The square of the cosine of theta; added to sine squared it always gives 1, from the unit circle and Pythagoras.","function":true},{"term":"tan² θ","meaning":"The square of the tangent of theta, where tangent is sine over cosine; defined when cosine is not zero.","function":true},{"term":"sec² θ","meaning":"The square of the secant of theta, where secant is 1 over cosine.","function":true},{"term":"cot² θ","meaning":"The square of the cotangent of theta, where cotangent is cosine over sine; defined when sine is not zero.","function":true},{"term":"csc² θ","meaning":"The square of the cosecant of theta, where cosecant is 1 over sine.","function":true},{"term":"sin(−θ)","meaning":"Sine evaluated at the negative angle; it equals negative sine theta, so sine is an odd function.","function":true},{"term":"cos(−θ)","meaning":"Cosine evaluated at the negative angle; it equals cosine theta, so cosine is an even function.","function":true}],"explanation":"The Pythagorean identity sin²θ + cos²θ = 1 is the Pythagorean theorem applied to the point (cos θ, sin θ) on the unit circle. Dividing it by cos²θ or sin²θ gives the tangent-secant and cotangent-cosecant forms. The last line records parity: sine is odd, so sin(−θ) = −sin θ, while cosine is even. These identities are used constantly to simplify expressions and solve equations.","origin":"","implementations":[{"name":"sympy.trigsimp","library":"SymPy","note":"Simplifies expressions using trigonometric identities."},{"name":"sympy.simplify","library":"SymPy","note":"General simplification, including trig identities."}]},"T.5":{"spoken":[{"line":0,"text":"sine of the quantity alpha plus or minus beta equals sine alpha cosine beta plus or minus cosine alpha sine beta"},{"line":1,"text":"cosine of the quantity alpha plus or minus beta equals cosine alpha cosine beta minus or plus sine alpha sine beta"},{"line":2,"text":"tangent of the quantity alpha plus or minus beta equals the quantity tangent alpha plus or minus tangent beta, all over the quantity 1 minus or plus tangent alpha tangent beta"}],"terms":[{"term":"sin","meaning":"Sine function: takes an angle and returns its sine; here applied to a sum or difference of two angles.","function":true},{"term":"α, β","meaning":"Alpha and beta: the two angles being added or subtracted.","function":false},{"term":"±","meaning":"Plus or minus: read top sign for the sum formula and bottom sign for the difference formula, consistently across the line.","function":false},{"term":"cos","meaning":"Cosine function: takes an angle and returns its cosine; note the cosine formula flips the sign on the right.","function":true},{"term":"∓","meaning":"Minus or plus: the opposite sign of the ±, so the sum formula uses minus here and the difference formula uses plus.","function":false},{"term":"tan","meaning":"Tangent function: takes an angle and returns sine over cosine; its sum formula is a fraction built from the tangents of each angle.","function":true}],"explanation":"These formulas express the sine, cosine and tangent of a sum or difference of angles in terms of the functions of the individual angles. They can be derived from rotating points on the unit circle or from Euler's formula. They let you compute exact values such as sin 75° from known angles, and they are the source of the double-angle and product-to-sum identities.","origin":"Equivalent chord relations follow from Ptolemy's theorem, which Ptolemy used in the Almagest (2nd century AD) to build his chord tables.","implementations":[{"name":"sympy.expand_trig","library":"SymPy","note":"Expands trig functions of sums into products."},{"name":"sympy.trigsimp","library":"SymPy","note":"Recombines expanded trig expressions."}]},"T.6":{"spoken":[{"line":0,"text":"sine of 2 theta equals 2 sine theta cosine theta"},{"line":1,"text":"cosine of 2 theta equals cosine squared theta minus sine squared theta, equals 2 cosine squared theta minus 1, equals 1 minus 2 sine squared theta"},{"line":2,"text":"sine of theta over 2 equals plus or minus the square root of the quantity 1 minus cosine theta, all over 2; cosine of theta over 2 equals plus or minus the square root of the quantity 1 plus cosine theta, all over 2"}],"terms":[{"term":"sin","meaning":"Sine function: takes an angle and returns its sine; here evaluated at double and half angles.","function":true},{"term":"θ","meaning":"Theta: the original angle, which is doubled or halved by these formulas.","function":false},{"term":"cos","meaning":"Cosine function: takes an angle and returns its cosine; cos 2 theta has three equivalent forms.","function":true},{"term":"cos² θ, sin² θ","meaning":"The squares of cosine theta and sine theta; swapping one for the other using sine squared plus cosine squared equals 1 gives the alternate forms.","function":false},{"term":"θ/2","meaning":"Half of the angle theta, the input to the half-angle formulas.","function":false},{"term":"±","meaning":"Plus or minus: choose the sign according to the quadrant where theta over 2 lies.","function":false},{"term":"√","meaning":"Square root: takes the nonnegative quantity (1 minus or plus cos theta) over 2 and returns its nonnegative root.","function":true}],"explanation":"Setting α = β in the sum formulas gives the double-angle identities: sin 2θ = 2 sin θ cos θ, and cos 2θ in three equivalent forms using sin² + cos² = 1. Solving the cosine forms for sin² or cos² of half the angle yields the half-angle formulas, where the ± sign is chosen by the quadrant of θ/2. They are used to reduce powers and find exact values.","origin":"Equivalent half-chord results appear in Ptolemy's Almagest (2nd century AD), where they were used to compute chord tables.","implementations":[{"name":"sympy.expand_trig","library":"SymPy","note":"Rewrites sin(2x) and cos(2x) in terms of x."},{"name":"sympy.trigsimp","library":"SymPy","note":"Simplifies trig expressions using these identities."}]},"T.7":{"spoken":[{"line":0,"text":"a over sine A equals b over sine B equals c over sine C equals 2 R"},{"line":1,"text":"Area equals one half a b sine C"}],"terms":[{"term":"a, b, c","meaning":"The side lengths of the triangle, each named to match the angle directly opposite it.","function":false},{"term":"sin","meaning":"Sine function: takes an interior angle of the triangle and returns its sine.","function":true},{"term":"A, B, C","meaning":"The triangle's interior angles at its three vertices; angle A is opposite side a, and so on.","function":false},{"term":"R","meaning":"The circumradius: radius of the circle passing through all three vertices; 2R is the common ratio.","function":false},{"term":"Area","meaning":"The area of the triangle, found from two sides and the angle included between them.","function":false}],"explanation":"The law of sines says each side of any triangle divided by the sine of its opposite angle gives the same constant, equal to the diameter 2R of the circumscribed circle. It solves triangles when you know two angles and a side, or two sides and a non-included angle (the ambiguous case). The area formula ½ab sin C uses the height b sin C over base a.","origin":"The plane law of sines was clearly stated by Nasir al-Din al-Tusi in the 13th century, building on earlier Islamic astronomers' work in spherical trigonometry.","implementations":[{"name":"sympy.geometry.Triangle","library":"SymPy","note":"Triangle object with area, angles and circumradius properties."}]},"T.8":{"spoken":[{"line":0,"text":"c squared equals a squared plus b squared minus 2 a b cosine C"},{"line":1,"text":"cosine C equals the quantity a squared plus b squared minus c squared, all over 2 a b"}],"terms":[{"term":"a, b","meaning":"Lengths of the two sides that form angle C.","function":false},{"term":"c","meaning":"Length of the side opposite angle C, the side being found from the other two sides and their included angle.","function":false},{"term":"cos","meaning":"Cosine function: takes angle C and returns its cosine; the term 2ab cos C corrects Pythagoras for a non-right angle.","function":true},{"term":"C","meaning":"The interior angle between sides a and b, opposite side c; the second line solves for it from three sides.","function":false}],"explanation":"The law of cosines relates all three sides of a triangle to one angle: c² = a² + b² − 2ab cos C. When C is 90°, the cosine term vanishes and it reduces to the Pythagorean theorem. It solves triangles given two sides and the included angle, and the rearranged form finds any angle from three known sides.","origin":"A geometric version appears in Euclid's Elements (c. 300 BC, Book II, Propositions 12-13); the trigonometric form is associated with al-Kashi (15th century).","implementations":[{"name":"sympy.geometry.Triangle","library":"SymPy","note":"Triangle object whose angles property computes angles from vertices."}]},"T.9":{"spoken":[{"line":0,"text":"y equals A sine of the quantity B times the quantity x minus C, plus D"},{"line":1,"text":"amplitude: the absolute value of A; period: 2 pi over the absolute value of B"},{"line":2,"text":"phase shift: C; midline: y equals D"}],"terms":[{"term":"y","meaning":"The output value of the sinusoid, its height on the graph.","function":false},{"term":"A","meaning":"Amplitude factor: vertical stretch; its absolute value is the distance from midline to peak, and a negative A reflects the graph.","function":false},{"term":"sin","meaning":"Sine function: takes the transformed input B times (x minus C) and returns a value between negative 1 and 1.","function":true},{"term":"B","meaning":"Horizontal frequency factor: larger absolute value of B squeezes the wave and shortens the period.","function":false},{"term":"x","meaning":"The input variable, usually an angle or time.","function":false},{"term":"C","meaning":"Phase shift: the horizontal shift of the graph; positive C moves it right.","function":false},{"term":"D","meaning":"Vertical shift: moves the whole wave up or down and sets the midline y equals D.","function":false},{"term":"|·|","meaning":"Absolute value: takes a number and returns its distance from zero, so amplitude and period are positive.","function":true},{"term":"π","meaning":"Pi, about 3.14159; 2 pi is the period of the basic sine function.","function":false}],"explanation":"The general sinusoid y = A sin(B(x − C)) + D stretches and shifts the basic sine wave. |A| sets the amplitude (height above the midline), B compresses the wave so the period is 2π/|B|, C shifts it horizontally (phase shift), and D moves the midline to y = D. This form models periodic phenomena such as tides, sound and seasonal data.","origin":"","implementations":[{"name":"numpy.sin","library":"NumPy","note":"Evaluates the sinusoid over an array of x values."},{"name":"scipy.optimize.curve_fit","library":"SciPy","note":"Fits amplitude, period, phase and midline to data."}]},"T.10":{"spoken":[{"line":0,"text":"y equals arcsine x if and only if sine y equals x, with y in the closed interval from negative pi over 2 to pi over 2"},{"line":1,"text":"arccosine x is in the closed interval from 0 to pi; arctangent x is in the open interval from negative pi over 2 to pi over 2"}],"terms":[{"term":"y","meaning":"The angle returned by the inverse function, restricted to its principal range.","function":false},{"term":"arcsin","meaning":"Inverse sine: takes a number x between negative 1 and 1 and returns the angle in [negative pi over 2, pi over 2] whose sine is x.","function":true},{"term":"x","meaning":"The input ratio to the inverse function, a value of sine, cosine or tangent.","function":false},{"term":"⟺","meaning":"If and only if: the two statements are equivalent, each implies the other.","function":false},{"term":"sin","meaning":"Sine function: takes angle y and returns its sine.","function":true},{"term":"∈","meaning":"Is an element of: the value lies in the stated interval.","function":false},{"term":"π","meaning":"Pi, about 3.14159; the range endpoints are given in radians.","function":false},{"term":"[ , ], ( , )","meaning":"Interval notation: square brackets include an endpoint, parentheses exclude it.","function":false},{"term":"arccos","meaning":"Inverse cosine: takes x between negative 1 and 1 and returns the angle in [0, pi] whose cosine is x.","function":true},{"term":"arctan","meaning":"Inverse tangent: takes any real x and returns the angle strictly between negative pi over 2 and pi over 2 whose tangent is x.","function":true}],"explanation":"Because sine, cosine and tangent repeat, they are invertible only on restricted domains. arcsin returns the unique angle in [−π/2, π/2] whose sine is x, arccos returns an angle in [0, π], and arctan returns an angle in (−π/2, π/2). These principal ranges make each inverse a true function, used to recover angles from ratios.","origin":"","implementations":[{"name":"math.asin","library":"Python standard library","note":"Arcsine in radians, range [−π/2, π/2]."},{"name":"math.acos","library":"Python standard library","note":"Arccosine in radians, range [0, π]."},{"name":"math.atan","library":"Python standard library","note":"Arctangent in radians."},{"name":"numpy.arcsin","library":"NumPy","note":"Element-wise arcsine."}]},"T.11":{"spoken":[{"line":0,"text":"x equals r cosine theta; y equals r sine theta"},{"line":1,"text":"r equals the square root of x squared plus y squared; tangent theta equals y over x"}],"terms":[{"term":"x, y","meaning":"Rectangular (Cartesian) coordinates of the point: horizontal and vertical positions.","function":false},{"term":"r","meaning":"Polar radius: the distance from the origin to the point.","function":false},{"term":"cos","meaning":"Cosine function: takes the polar angle and returns the horizontal fraction of r.","function":true},{"term":"θ","meaning":"Polar angle: measured counterclockwise from the positive x-axis to the ray through the point.","function":false},{"term":"sin","meaning":"Sine function: takes the polar angle and returns the vertical fraction of r.","function":true},{"term":"√","meaning":"Square root: takes x squared plus y squared and returns the nonnegative distance r.","function":true},{"term":"tan","meaning":"Tangent function: takes theta and returns y over x; recovering theta requires checking the quadrant.","function":true}],"explanation":"Polar coordinates locate a point by its distance r from the origin and its angle θ from the positive x-axis. The first line converts polar to Cartesian using cosine and sine; the second converts back, with r from the Pythagorean theorem and θ from tan θ = y/x, adjusted for the correct quadrant. Polar form simplifies circles, spirals and rotational problems.","origin":"Polar-style coordinates were used by Isaac Newton and Jacob Bernoulli in the late 17th century.","implementations":[{"name":"math.atan2","library":"Python standard library","note":"Angle of (x, y) with correct quadrant."},{"name":"math.hypot","library":"Python standard library","note":"Distance r = √(x² + y²)."},{"name":"cmath.polar","library":"Python standard library","note":"Converts a complex number to (r, θ)."},{"name":"cmath.rect","library":"Python standard library","note":"Converts (r, θ) back to a complex number."}]},"T.12":{"spoken":[{"line":0,"text":"the norm of vector v equals the square root of the sum of v sub i squared"},{"line":1,"text":"vector u dot vector v equals the sum of u sub i v sub i, equals the norm of vector u times the norm of vector v times cosine theta"},{"line":2,"text":"cosine theta equals vector u dot vector v, all over the norm of vector u times the norm of vector v"}],"terms":[{"term":"‖·‖","meaning":"Norm (length): takes a vector and returns its nonnegative Euclidean length.","function":true},{"term":"𝐯, 𝐮","meaning":"Vectors: ordered lists of components, pictured as arrows with direction and length.","function":false},{"term":"√","meaning":"Square root: takes the sum of squared components and returns the vector's length.","function":true},{"term":"Σ","meaning":"Summation: adds the expression over every component index i from 1 to the dimension.","function":true},{"term":"vᵢ, uᵢ","meaning":"The i-th components of vectors v and u.","function":false},{"term":"·","meaning":"Dot product: takes two vectors and returns a scalar, the sum of products of matching components.","function":true},{"term":"cos","meaning":"Cosine function: takes the angle between the vectors and returns its cosine; here this is cosine similarity, from negative 1 to 1.","function":true},{"term":"θ","meaning":"Theta: the angle between vectors u and v when drawn from a common starting point.","function":false}],"explanation":"A vector's length is the square root of the sum of its squared components. The dot product multiplies matching components and adds them; geometrically it equals the product of the lengths times the cosine of the angle between the vectors. Solving for cos θ gives cosine similarity, which measures how aligned two vectors are regardless of size, a standard tool in search and machine learning.","origin":"Modern dot-product notation was developed by Josiah Willard Gibbs and Oliver Heaviside in the 1880s, building on Hamilton's quaternions and Grassmann's work.","implementations":[{"name":"numpy.dot","library":"NumPy","note":"Dot product of two arrays."},{"name":"numpy.linalg.norm","library":"NumPy","note":"Euclidean length of a vector."},{"name":"sklearn.metrics.pairwise.cosine_similarity","library":"scikit-learn","note":"Pairwise cosine similarity between rows."},{"name":"torch.nn.functional.cosine_similarity","library":"PyTorch","note":"Cosine similarity along a tensor dimension."}]},"T.13":{"spoken":[{"line":0,"text":"e to the i theta equals cosine theta plus i sine theta"},{"line":1,"text":"z equals r e to the i theta; z to the n equals r to the n e to the i n theta"},{"line":2,"text":"e to the i pi plus 1 equals 0"}],"terms":[{"term":"e","meaning":"Euler's number, about 2.71828, the base of the natural exponential function.","function":false},{"term":"i","meaning":"The imaginary unit, defined by i squared equals negative 1.","function":false},{"term":"θ","meaning":"Theta: an angle in radians; here it is the argument of the complex number.","function":false},{"term":"cos","meaning":"Cosine function: takes theta and returns the real part of e to the i theta.","function":true},{"term":"sin","meaning":"Sine function: takes theta and returns the imaginary part of e to the i theta.","function":true},{"term":"z","meaning":"A complex number written in polar (exponential) form.","function":false},{"term":"r","meaning":"The modulus of z: its distance from the origin in the complex plane.","function":false},{"term":"n","meaning":"An integer power; De Moivre's theorem raises the modulus to n and multiplies the angle by n.","function":false},{"term":"π","meaning":"Pi, about 3.14159; setting theta equal to pi gives Euler's identity.","function":false}],"explanation":"Euler's formula e^(iθ) = cos θ + i sin θ links the exponential function to trigonometry, placing e^(iθ) on the unit circle in the complex plane. Writing z = re^(iθ) makes powers easy: raising to n multiplies the angle by n and raises r to n, which is De Moivre's theorem. Setting θ = π gives Euler's identity e^(iπ) + 1 = 0.","origin":"De Moivre's formula dates to Abraham de Moivre in the early 1700s; Leonhard Euler published his formula in 1748 in Introductio in analysin infinitorum.","implementations":[{"name":"cmath.exp","library":"Python standard library","note":"Complex exponential, e.g. exp(1j*theta)."},{"name":"cmath.rect","library":"Python standard library","note":"Builds r·e^(iθ) from modulus and angle."},{"name":"numpy.exp","library":"NumPy","note":"Element-wise exponential, accepts complex input."}]},"G.1":{"spoken":[{"line":0,"text":"alpha plus beta equals 90 degrees (complementary)"},{"line":1,"text":"alpha plus beta equals 180 degrees (supplementary)"}],"terms":[{"term":"α, β","meaning":"Alpha and beta: two angle measures being compared.","function":false},{"term":"°","meaning":"Degrees: angle unit; 90 degrees is a right angle and 180 degrees is a straight angle.","function":false}],"explanation":"Two angles are complementary if they sum to 90° and supplementary if they sum to 180°. When two lines cross, opposite (vertical) angles are equal; when a transversal crosses parallel lines, corresponding angles and alternate interior angles are also equal. These relationships are the basic tools for finding unknown angles in geometry proofs and diagrams.","origin":"The equality of vertical angles is proved in Euclid's Elements (c. 300 BC, Book I, Proposition 15) and is traditionally attributed to Thales.","implementations":[]},"G.2":{"spoken":[{"line":0,"text":"A plus B plus C equals 180 degrees"},{"line":1,"text":"exterior equals sum of remote interiors"},{"line":2,"text":"the absolute value of a minus b is less than c, which is less than a plus b"}],"terms":[{"term":"A, B, C","meaning":"The three interior angles of a triangle; their measures always add to 180 degrees.","function":false},{"term":"°","meaning":"Degrees: the angle unit, with 180 degrees being a straight angle.","function":false},{"term":"exterior","meaning":"An exterior angle of the triangle, formed by one side and the extension of an adjacent side.","function":false},{"term":"remote interiors","meaning":"The two interior angles not adjacent to that exterior angle; their sum equals it.","function":false},{"term":"a, b, c","meaning":"Side lengths of a triangle; any side must be shorter than the sum and longer than the difference of the others.","function":false},{"term":"|·|","meaning":"Absolute value: takes a number and returns its distance from zero, so the difference of a and b is positive.","function":true},{"term":"<","meaning":"Strictly less than; equality would collapse the triangle into a line segment.","function":false}],"explanation":"The interior angles of any triangle sum to 180°, a consequence of the parallel postulate. An exterior angle equals the sum of the two interior angles not adjacent to it. The triangle inequality states each side must be shorter than the sum of the other two and longer than their difference, which determines whether three lengths can form a triangle.","origin":"Both the angle-sum and exterior-angle results are Euclid's Elements Book I, Proposition 32, and the triangle inequality is Proposition 20 (c. 300 BC).","implementations":[]},"G.3":{"spoken":[{"line":0,"text":"a squared plus b squared equals c squared"},{"line":1,"text":"c squared is less than a squared plus b squared: acute; c squared is greater than a squared plus b squared: obtuse"}],"terms":[{"term":"a, b","meaning":"Lengths of the two legs of a right triangle, or the two shorter sides of any triangle in the converse tests.","function":false},{"term":"c","meaning":"Length of the hypotenuse, or the longest side when classifying a triangle.","function":false},{"term":"<, >","meaning":"Comparisons of c squared with a squared plus b squared that classify the triangle as acute or obtuse.","function":false}],"explanation":"In a right triangle, the square of the hypotenuse equals the sum of the squares of the two legs. The converse classifies any triangle by its longest side c: if c² is less than a² + b² the triangle is acute, and if greater it is obtuse. It underlies the distance formula and is used to find a missing side length.","origin":"Named for Pythagoras (6th century BC), though Babylonian tablets such as Plimpton 322 show the relation was used over a thousand years earlier.","implementations":[{"name":"math.hypot","library":"Python standard library","note":"Hypotenuse length √(a² + b²) without overflow."},{"name":"numpy.hypot","library":"NumPy","note":"Element-wise hypotenuse of two arrays."}]},"G.4":{"spoken":[{"line":0,"text":"45 degrees, 45 degrees, 90 degrees: x to x to x times the square root of 2"},{"line":1,"text":"30 degrees, 60 degrees, 90 degrees: x to x times the square root of 3 to 2 x"}],"terms":[{"term":"°","meaning":"Degrees: the triangle's three angle measures, listed in order.","function":false},{"term":":","meaning":"Ratio separator: side lengths listed in the same order as their opposite angles.","function":false},{"term":"x","meaning":"The scale length: a leg of the 45-45-90 triangle, or the short leg opposite 30 degrees in the 30-60-90 triangle.","function":false},{"term":"√","meaning":"Square root: x root 2 is the isosceles right triangle's hypotenuse; x root 3 is the long leg opposite 60 degrees.","function":true}],"explanation":"Two right triangles have fixed side ratios. The 45-45-90 triangle is half a square, so its legs are equal and the hypotenuse is x√2. The 30-60-90 triangle is half an equilateral triangle, so the short leg is half the hypotenuse and the long leg is x√3. These ratios give exact trig values without a calculator.","origin":"","implementations":[]},"G.5":{"spoken":[{"line":0,"text":"A B over D E equals B C over E F equals A C over D F equals k"},{"line":1,"text":"area ratio k squared, volume ratio k cubed"}],"terms":[{"term":"AB, BC, AC","meaning":"Side lengths of the first triangle ABC, each a segment between two named vertices.","function":false},{"term":"DE, EF, DF","meaning":"Corresponding side lengths of the similar triangle DEF, matched vertex to vertex with ABC.","function":false},{"term":"k","meaning":"Scale factor: the common ratio of corresponding lengths in similar figures.","function":false},{"term":"k²","meaning":"Ratio of the areas of similar figures, the square of the length scale factor.","function":false},{"term":"k³","meaning":"Ratio of the volumes of similar solids, the cube of the length scale factor.","function":false}],"explanation":"Similar triangles have equal corresponding angles, so all corresponding sides share one ratio k, the scale factor. Because area is two-dimensional, areas scale by k², and volumes of similar solids scale by k³. Similarity is used for indirect measurement, such as finding heights from shadows, and for scaling maps and models.","origin":"Euclid's Elements Book VI (c. 300 BC) develops similar figures; tradition credits Thales with using similar triangles to measure the height of the pyramids.","implementations":[{"name":"sympy.geometry.are_similar","library":"SymPy","note":"Checks whether two geometric entities are similar."}]},"G.6":{"spoken":[{"line":0,"text":"d equals the square root of the quantity x sub 2 minus x sub 1 squared plus the quantity y sub 2 minus y sub 1 squared"},{"line":1,"text":"M equals the point x sub 1 plus x sub 2 over 2, y sub 1 plus y sub 2 over 2"},{"line":2,"text":"d of vector p, vector q equals the square root of the sum of the quantity p sub i minus q sub i squared"}],"terms":[{"term":"d","meaning":"Distance between two points, the length of the segment joining them.","function":false},{"term":"√","meaning":"Square root: takes the sum of squared coordinate differences and returns the straight-line distance.","function":true},{"term":"x₁, y₁","meaning":"The x- and y-coordinates of the first point, one endpoint of the segment.","function":false},{"term":"x₂, y₂","meaning":"The x- and y-coordinates of the second point, the other endpoint of the segment.","function":false},{"term":"M","meaning":"Midpoint of the segment: the point whose coordinates are the averages of the endpoints' coordinates.","function":false},{"term":"d(𝐩, 𝐪)","meaning":"Euclidean distance function: takes two points in n dimensions and returns the length of the segment between them.","function":true},{"term":"𝐩, 𝐪","meaning":"Two points written as vectors in n-dimensional space, each a list of coordinates.","function":false},{"term":"Σ","meaning":"Summation: adds the squared differences over every coordinate index i.","function":true},{"term":"pᵢ, qᵢ","meaning":"The i-th coordinates of points p and q.","function":false}],"explanation":"The distance formula is the Pythagorean theorem applied to the horizontal and vertical differences between two points. The midpoint averages the coordinates. The last line generalizes distance to n dimensions as the Euclidean distance, the square root of the summed squared differences, which is widely used in data science for nearest-neighbor and clustering methods.","origin":"Follows from the coordinate geometry introduced by René Descartes and Pierre de Fermat in the 17th century.","implementations":[{"name":"math.dist","library":"Python standard library","note":"Euclidean distance between two points."},{"name":"scipy.spatial.distance.euclidean","library":"SciPy","note":"Euclidean distance between two 1-D arrays."},{"name":"numpy.linalg.norm","library":"NumPy","note":"Norm of the difference vector gives distance."},{"name":"scipy.spatial.distance.cdist","library":"SciPy","note":"Pairwise distances between two sets of points."}]},"G.7":{"spoken":[{"line":0,"text":"sigma sub interior equals the quantity n minus 2 times 180 degrees"},{"line":1,"text":"sigma sub exterior equals 360 degrees"},{"line":2,"text":"diagonals equals n times the quantity n minus 3, all over 2"}],"terms":[{"term":"Σ_int","meaning":"The sum of the interior angle measures of a convex polygon.","function":false},{"term":"n","meaning":"The number of sides (and vertices) of the polygon.","function":false},{"term":"°","meaning":"Degrees, the unit of angle measure; each triangle in a polygon contributes 180 degrees.","function":false},{"term":"Σ_ext","meaning":"The sum of the exterior angles of a convex polygon, one at each vertex; always 360 degrees.","function":false},{"term":"diagonals","meaning":"The number of segments joining two non-adjacent vertices of the polygon.","function":false}],"explanation":"Any n-sided polygon splits into n − 2 triangles from one vertex, so its interior angles sum to (n − 2)·180°. Walking around a convex polygon turns you through one full rotation, so the exterior angles always total 360°. Each vertex connects to n − 3 non-adjacent vertices, and dividing by 2 for double counting gives n(n − 3)/2 diagonals.","origin":"","implementations":[]},"G.8":{"spoken":[{"line":0,"text":"A sub triangle equals one half b h; A sub trapezoid equals one half the quantity b sub 1 plus b sub 2, times h"},{"line":1,"text":"Heron: A equals the square root of s times the quantity s minus a times the quantity s minus b times the quantity s minus c"}],"terms":[{"term":"A△","meaning":"Area of a triangle: half the product of its base and height.","function":false},{"term":"b","meaning":"Length of the triangle's base, any side chosen as the base.","function":false},{"term":"h","meaning":"Height: the perpendicular distance from the base to the opposite vertex, or between a trapezoid's parallel sides.","function":false},{"term":"A_trap","meaning":"Area of a trapezoid: the average of the two bases times the height.","function":false},{"term":"b₁, b₂","meaning":"Lengths of the two parallel sides (bases) of the trapezoid.","function":false},{"term":"A","meaning":"Area of the triangle given by Heron's formula from its three sides alone.","function":false},{"term":"√","meaning":"Square root: takes the product s(s minus a)(s minus b)(s minus c) and returns the area.","function":true},{"term":"s","meaning":"Semiperimeter: half the triangle's perimeter, (a plus b plus c) over 2.","function":false},{"term":"a, b, c","meaning":"The three side lengths of the triangle in Heron's formula.","function":false}],"explanation":"A triangle's area is half its base times its height, since it is half a parallelogram. A trapezoid's area is the average of its parallel bases times the height. Heron's formula gives a triangle's area from its three sides alone, using the semiperimeter s = (a + b + c)/2, so no height or angle is needed.","origin":"Heron's formula is named for Heron of Alexandria, who gave a proof in his Metrica (1st century AD); it may have been known to Archimedes earlier.","implementations":[{"name":"sympy.geometry.Triangle","library":"SymPy","note":"Triangle object with an area property."},{"name":"shapely.geometry.Polygon","library":"Shapely","note":"Polygon object whose area attribute gives its area."}]},"G.9":{"spoken":[{"line":0,"text":"C equals 2 pi r; A equals pi r squared"},{"line":1,"text":"s equals r theta; A sub sector equals one half r squared theta"}],"terms":[{"term":"C","meaning":"Circumference: the distance all the way around the circle, its perimeter.","function":false},{"term":"π","meaning":"Pi, about 3.14159, the ratio of any circle's circumference to its diameter.","function":false},{"term":"r","meaning":"Radius of the circle: the distance from the center to any point on it.","function":false},{"term":"A","meaning":"The area of the region enclosed by the circle, proportional to the radius squared.","function":false},{"term":"s","meaning":"Arc length cut off by central angle theta.","function":false},{"term":"θ","meaning":"Central angle in radians; the arc and sector formulas require radians.","function":false},{"term":"A_sector","meaning":"Area of the pie-shaped sector bounded by two radii and the arc between them.","function":false}],"explanation":"A circle's circumference is 2πr and its area is πr², where π is the constant ratio of circumference to diameter. With θ in radians, an arc is the fraction θ/2π of the circle, giving arc length s = rθ and sector area ½r²θ. These formulas measure partial circles in wheels, pie charts and rotations.","origin":"Archimedes, in Measurement of a Circle (3rd century BC), showed a circle's area equals a triangle with base the circumference and height the radius, and bounded π.","implementations":[{"name":"math.pi","library":"Python standard library","note":"The constant π to double precision."},{"name":"numpy.pi","library":"NumPy","note":"The constant π."},{"name":"sympy.geometry.Circle","library":"SymPy","note":"Circle object with area and circumference properties."}]},"G.10":{"spoken":[{"line":0,"text":"angle inscribed equals one half angle central"},{"line":1,"text":"angle in a semicircle equals 90 degrees"},{"line":2,"text":"tangent is perpendicular to radius; a b equals c d"}],"terms":[{"term":"∠_inscribed","meaning":"An inscribed angle: vertex on the circle, sides are chords; it measures half its intercepted arc.","function":false},{"term":"∠_central","meaning":"A central angle: vertex at the circle's center, intercepting the same arc as the inscribed angle.","function":false},{"term":"°","meaning":"Degrees; an angle inscribed in a semicircle is a right angle.","function":false},{"term":"⟂","meaning":"Is perpendicular to: a tangent line meets the radius drawn to the point of tangency at 90 degrees.","function":false},{"term":"a, b, c, d","meaning":"Segment lengths of two chords crossing inside a circle: a and b on one chord, c and d on the other.","function":false}],"explanation":"An inscribed angle is half the central angle subtending the same arc. As a special case, any angle inscribed in a semicircle is a right angle. A tangent line is perpendicular to the radius at the point of contact. The intersecting chords theorem says that when two chords cross, the products of their segments are equal (ab = cd).","origin":"The angle in a semicircle is Thales' theorem (6th century BC); these results are proved in Book III of Euclid's Elements (c. 300 BC).","implementations":[]},"G.11":{"spoken":[{"line":0,"text":"V equals B h"},{"line":1,"text":"V sub cylinder equals pi r squared h"},{"line":2,"text":"S A sub cylinder equals 2 pi r squared plus 2 pi r h"}],"terms":[{"term":"V","meaning":"Volume of a prism or cylinder, the space it encloses.","function":false},{"term":"B","meaning":"Area of the base (the cross-section), which is constant along the height.","function":false},{"term":"h","meaning":"Height: the perpendicular distance between the two bases.","function":false},{"term":"V_cyl","meaning":"Volume of a cylinder: circular base area times height.","function":false},{"term":"π","meaning":"Pi, about 3.14159; pi r squared is the area of the cylinder's circular base.","function":false},{"term":"r","meaning":"Radius of the cylinder's circular base, the distance from the center of the base to its edge.","function":false},{"term":"SA_cyl","meaning":"Total surface area of a cylinder: two circular ends plus the curved lateral side.","function":false}],"explanation":"A prism or cylinder has the same cross-section all the way up, so its volume is base area B times height h. For a cylinder the base is a circle, giving πr²h. Its surface area adds the two circular ends, 2πr², to the lateral surface, which unrolls into a rectangle of width 2πr and height h.","origin":"","implementations":[]},"G.12":{"spoken":[{"line":0,"text":"V sub pyramid equals one third B h; V sub cone equals one third pi r squared h"},{"line":1,"text":"V sub sphere equals four thirds pi r cubed; S A sub sphere equals 4 pi r squared"}],"terms":[{"term":"V_pyr","meaning":"Volume of a pyramid, one third of the prism with the same base and height.","function":false},{"term":"B","meaning":"Area of the pyramid's base, whatever polygon shape that base is.","function":false},{"term":"h","meaning":"Height: the perpendicular distance from the base to the apex.","function":false},{"term":"V_cone","meaning":"Volume of a cone, one third of the matching cylinder.","function":false},{"term":"π","meaning":"Pi, about 3.14159, appearing because cones and spheres have circular cross-sections.","function":false},{"term":"r","meaning":"Radius of the cone's base, or of the sphere.","function":false},{"term":"V_sph","meaning":"Volume of a sphere, the space enclosed inside it, depending only on its radius.","function":false},{"term":"SA_sph","meaning":"Surface area of a sphere, four times the area of its great circle.","function":false}],"explanation":"A pyramid or cone has one-third the volume of the prism or cylinder with the same base and height, because the cross-sections shrink quadratically to a point. A sphere's volume is (4/3)πr³ and its surface area is 4πr², four times the area of its great circle. These formulas size tanks, containers and planetary bodies.","origin":"Eudoxus (4th century BC) proved the one-third rule for cones and pyramids; Archimedes found the sphere's volume and surface area in On the Sphere and Cylinder (3rd century BC).","implementations":[]},"G.13":{"spoken":[{"line":0,"text":"R sub theta equals the 2 by 2 matrix with rows: cosine theta, negative sine theta; and sine theta, cosine theta"},{"line":1,"text":"the point x, y maps to the point x plus a, y plus b"},{"line":2,"text":"reflect in y equals x: the point x, y maps to the point y, x"}],"terms":[{"term":"R_θ","meaning":"Rotation matrix: multiplying a column vector by it rotates the point counterclockwise by theta about the origin.","function":false},{"term":"θ","meaning":"Theta: the angle of rotation about the origin, with counterclockwise taken as positive.","function":false},{"term":"cos","meaning":"Cosine function: takes the rotation angle and returns its cosine, used as the matrix's diagonal entries.","function":true},{"term":"sin","meaning":"Sine function: takes the rotation angle and returns its sine, used as the off-diagonal entries.","function":true},{"term":"[ ]","meaning":"Matrix brackets: enclose the rectangular array of entries.","function":false},{"term":"(x, y)","meaning":"The coordinates of the original point before the translation or reflection is applied.","function":false},{"term":"→","meaning":"Maps to: sends the original point to its image.","function":false},{"term":"a, b","meaning":"Translation amounts: a shifts horizontally, b shifts vertically.","function":false},{"term":"y = x","meaning":"The diagonal line through the origin used as the mirror; reflecting across it swaps coordinates.","function":false}],"explanation":"Rigid transformations move shapes without changing size. Multiplying a point by the rotation matrix R_θ rotates it counterclockwise by θ about the origin. Translation adds a fixed (a, b) to every point, and reflection across the line y = x swaps the coordinates. Composing these operations is the basis of computer graphics and robotics.","origin":"","implementations":[{"name":"matplotlib.transforms.Affine2D","library":"Matplotlib","note":"2-D affine transform supporting rotate, translate and scale."},{"name":"scipy.spatial.transform.Rotation","library":"SciPy","note":"Represents and applies rotations in 3-D."},{"name":"scipy.ndimage.rotate","library":"SciPy","note":"Rotates an image array by an angle."}]},"A2.1":{"spoken":[{"line":0,"text":"f composed with g, of x, equals f of g of x"},{"line":1,"text":"f inverse of f of x equals x"}],"terms":[{"term":"f, g","meaning":"Functions: each takes an input and returns exactly one output.","function":true},{"term":"∘","meaning":"Composition: takes two functions and returns a new one that applies g first and then f.","function":true},{"term":"x","meaning":"The input variable, from the domain of the inner function.","function":false},{"term":"f⁻¹","meaning":"Inverse function of f: takes an output of f and returns the input that produced it; not 1 over f.","function":true}],"explanation":"Composition chains functions: (f∘g)(x) feeds x into g, then feeds the result into f, so order matters. An inverse function f⁻¹ undoes f, so composing them returns the original input. A function has an inverse only if it is one-to-one, and the graph of f⁻¹ is the reflection of f across the line y = x.","origin":"","implementations":[{"name":"sympy.compose","library":"SymPy","note":"Composes two polynomials, f(g(x))."},{"name":"sympy.solve","library":"SymPy","note":"Solve y = f(x) for x to find an inverse."}]},"A2.2":{"spoken":[{"line":0,"text":"y equals a f of the quantity b times the quantity x minus h, plus k"}],"terms":[{"term":"y","meaning":"The output of the transformed function, the new graph's height at x.","function":false},{"term":"a","meaning":"Vertical stretch factor: stretches by the absolute value of a, and negative a reflects over the x-axis.","function":false},{"term":"f","meaning":"The parent function: takes the adjusted input b(x minus h) and returns the base output before scaling and shifting.","function":true},{"term":"b","meaning":"Horizontal factor: compresses by the absolute value of b, and negative b reflects over the y-axis.","function":false},{"term":"x","meaning":"The input variable, the horizontal coordinate on the transformed graph.","function":false},{"term":"h","meaning":"Horizontal shift: positive h moves the graph right by h.","function":false},{"term":"k","meaning":"Vertical shift: positive k moves the graph up by k.","function":false}],"explanation":"The form y = a f(b(x − h)) + k describes every standard transformation of a parent graph. The constant a stretches vertically and reflects across the x-axis if negative; b compresses horizontally by 1/|b|; h shifts right; and k shifts up. Changes inside the parentheses affect x in the opposite direction from what they appear to do.","origin":"","implementations":[]},"A2.3":{"spoken":[{"line":0,"text":"i squared equals negative 1; z equals a plus b i"},{"line":1,"text":"z bar equals a minus b i; the absolute value of z equals the square root of a squared plus b squared"}],"terms":[{"term":"i","meaning":"The imaginary unit, defined so that i squared equals negative 1.","function":false},{"term":"z","meaning":"A complex number written in standard rectangular form, a real part plus an imaginary part.","function":false},{"term":"a","meaning":"The real part of z, its horizontal coordinate in the complex plane.","function":false},{"term":"b","meaning":"The imaginary part of z, the real coefficient of i.","function":false},{"term":"z̄","meaning":"Complex conjugate of z: same real part, opposite-sign imaginary part; reflects z across the real axis.","function":false},{"term":"|z|","meaning":"Modulus: takes a complex number and returns its distance from the origin in the complex plane.","function":true},{"term":"√","meaning":"Square root: takes a squared plus b squared and returns the modulus.","function":true}],"explanation":"Complex numbers extend the reals by the imaginary unit i, defined by i² = −1, giving numbers z = a + bi. The conjugate flips the sign of the imaginary part, and the modulus |z| = √(a² + b²) is the distance from the origin in the complex plane. Multiplying z by its conjugate gives |z|², which is used to divide complex numbers.","origin":"Gerolamo Cardano encountered square roots of negatives in 1545 and Rafael Bombelli gave rules for them in 1572; Euler introduced the symbol i in 1777.","implementations":[{"name":"complex","library":"Python standard library","note":"Built-in complex type, e.g. complex(3, 4) or 3+4j."},{"name":"abs","library":"Python standard library","note":"Modulus of a complex number."},{"name":"numpy.conj","library":"NumPy","note":"Element-wise complex conjugate."},{"name":"cmath.phase","library":"Python standard library","note":"Argument (angle) of a complex number."}]},"A2.4":{"spoken":[{"line":0,"text":"P of x equals the quantity x minus c times Q of x, plus P of c"},{"line":1,"text":"P of c equals 0 if and only if the quantity x minus c is a factor"},{"line":2,"text":"rational roots: plus or minus p over q, where p divides a sub 0 and q divides a sub n"}],"terms":[{"term":"P(x)","meaning":"A polynomial function: takes x and returns the polynomial's value; it is the dividend here.","function":true},{"term":"x","meaning":"The polynomial's variable, which can be replaced by any number such as c.","function":false},{"term":"c","meaning":"A number; dividing by (x minus c) leaves remainder P(c).","function":false},{"term":"Q(x)","meaning":"The quotient polynomial from dividing P(x) by (x minus c), one degree lower than P.","function":true},{"term":"P(c)","meaning":"The value of P at c, which equals the remainder of the division.","function":false},{"term":"⟺","meaning":"If and only if: c is a root exactly when (x minus c) is a factor.","function":false},{"term":"±","meaning":"Plus or minus: each candidate root must be tested with both signs.","function":false},{"term":"p","meaning":"An integer factor of the constant term a sub 0.","function":false},{"term":"q","meaning":"An integer factor of the leading coefficient a sub n.","function":false},{"term":"∣","meaning":"Divides: p divides a sub 0 means a sub 0 is an integer multiple of p.","function":false},{"term":"a₀","meaning":"The constant term of P(x), with integer coefficients assumed.","function":false},{"term":"aₙ","meaning":"The leading coefficient of P(x), the coefficient of its highest-degree term.","function":false}],"explanation":"Dividing a polynomial P(x) by (x − c) leaves remainder P(c), the remainder theorem. So (x − c) is a factor exactly when P(c) = 0, the factor theorem. The rational root theorem limits possible rational roots to ±p/q, where p divides the constant term and q divides the leading coefficient, giving a finite list of candidates to test.","origin":"","implementations":[{"name":"numpy.polyval","library":"NumPy","note":"Evaluates a polynomial at a point, giving P(c)."},{"name":"numpy.polydiv","library":"NumPy","note":"Polynomial division, returning quotient and remainder."},{"name":"sympy.div","library":"SymPy","note":"Symbolic polynomial division with remainder."},{"name":"sympy.roots","library":"SymPy","note":"Finds polynomial roots; filter='Q' keeps rational ones."}]},"A2.5":{"spoken":[{"line":0,"text":"f of x equals P of x over Q of x"},{"line":1,"text":"V A: Q of c equals 0, P of c is not equal to 0"},{"line":2,"text":"degree of P is less than degree of Q implies H A y equals 0"},{"line":3,"text":"degree of P equals degree of Q implies H A y equals a sub n over b sub n"}],"terms":[{"term":"f(x)","meaning":"A rational function: takes x and returns the ratio of two polynomials, undefined where Q is zero.","function":true},{"term":"P(x)","meaning":"The numerator polynomial: takes x and returns the top of the fraction; its zeros give x-intercepts.","function":true},{"term":"Q(x)","meaning":"The denominator polynomial: takes x and returns the bottom of the fraction; its zeros mark where f is undefined.","function":true},{"term":"VA","meaning":"Vertical asymptote: a line x equals c where the graph shoots toward positive or negative infinity.","function":false},{"term":"c","meaning":"A value of x that makes the denominator zero but not the numerator, giving the asymptote x equals c.","function":false},{"term":"≠","meaning":"Is not equal to; if P(c) were also zero there might be a hole instead.","function":false},{"term":"deg","meaning":"Degree: takes a polynomial and returns its highest exponent.","function":true},{"term":"⇒","meaning":"Implies: the degree condition determines the horizontal asymptote.","function":false},{"term":"HA","meaning":"Horizontal asymptote: the line y approaches as x goes to positive or negative infinity.","function":false},{"term":"aₙ, bₙ","meaning":"Leading coefficients of P and Q; their ratio is the asymptote when the degrees are equal.","function":false}],"explanation":"A rational function is a ratio of polynomials. Vertical asymptotes occur where the denominator is zero but the numerator is not. Horizontal asymptotes depend on degrees: if the numerator's degree is smaller, y = 0; if the degrees are equal, y is the ratio of leading coefficients. If the top's degree is one higher, there is a slant asymptote instead.","origin":"","implementations":[{"name":"sympy.limit","library":"SymPy","note":"Limits at infinity give horizontal asymptotes."},{"name":"sympy.apart","library":"SymPy","note":"Partial fractions reveal slant asymptotes."},{"name":"sympy.singularities","library":"SymPy","note":"Finds points where the function is undefined."}]},"A2.6":{"spoken":[{"line":0,"text":"A equals P times the quantity 1 plus r over n, to the n t; A equals P e to the r t"},{"line":1,"text":"t sub one half equals the natural log of 2 over the absolute value of k"}],"terms":[{"term":"A","meaning":"The amount after time t, the future value.","function":false},{"term":"P","meaning":"The principal or initial amount at time zero.","function":false},{"term":"r","meaning":"The annual interest or growth rate as a decimal.","function":false},{"term":"n","meaning":"The number of compounding periods per year, such as 12 for monthly compounding.","function":false},{"term":"t","meaning":"Time elapsed since the start, usually measured in years.","function":false},{"term":"e","meaning":"Euler's number, about 2.71828, the base used for continuous compounding.","function":false},{"term":"t₁/₂","meaning":"Half-life (or doubling time for growth): the time for the quantity to halve or double.","function":false},{"term":"ln","meaning":"Natural logarithm: takes a positive number and returns the power of e that gives it; ln 2 is about 0.693.","function":true},{"term":"|k|","meaning":"Absolute value of the continuous growth or decay constant k in A equals A sub 0 e to the kt.","function":true}],"explanation":"Compound interest A = P(1 + r/n)^(nt) grows a principal P at annual rate r compounded n times per year for t years. As n grows without bound, the formula approaches continuous compounding, A = Pe^(rt). For decay with rate constant k, the half-life is the time to halve the quantity, ln 2 divided by |k|.","origin":"Jacob Bernoulli discovered the constant e in 1683 while studying the limit of continuously compounded interest.","implementations":[{"name":"=FV()","library":"Excel","note":"Future value of an investment with periodic compounding."},{"name":"math.exp","library":"Python standard library","note":"Computes e^x for continuous growth."},{"name":"numpy.exp","library":"NumPy","note":"Element-wise exponential."}]},"A2.7":{"spoken":[{"line":0,"text":"log base b of x equals y if and only if b to the y equals x"},{"line":1,"text":"log of x y equals log x plus log y"},{"line":2,"text":"log of x over y equals log x minus log y; log of x to the p equals p log x"}],"terms":[{"term":"log_b","meaning":"Logarithm base b: takes a positive x and returns the exponent to which b must be raised to give x.","function":true},{"term":"b","meaning":"The base: a positive number not equal to 1.","function":false},{"term":"x, y","meaning":"In the definition, x is the positive input and y the exponent; in the rules, x and y are positive numbers.","function":false},{"term":"⟺","meaning":"If and only if: the logarithmic and exponential statements say the same thing.","function":false},{"term":"log","meaning":"Logarithm in any fixed base: turns products into sums, quotients into differences and powers into multiples.","function":true},{"term":"p","meaning":"Any real exponent; the power rule moves it in front of the log.","function":false}],"explanation":"A logarithm is an exponent: log_b x is the power to which b must be raised to get x. Because exponents add when powers multiply, the log of a product is the sum of logs, the log of a quotient is the difference, and the log of a power brings the exponent down as a multiplier. These rules turn multiplication into addition.","origin":"Introduced by John Napier in 1614; Henry Briggs then developed base-10 (common) logarithms in the following decade.","implementations":[{"name":"math.log","library":"Python standard library","note":"Natural log, or log to a given base."},{"name":"math.log10","library":"Python standard library","note":"Base-10 logarithm."},{"name":"numpy.log","library":"NumPy","note":"Element-wise natural logarithm."},{"name":"=LOG()","library":"Excel","note":"Logarithm to a specified base (default 10)."}]},"A2.8":{"spoken":[{"line":0,"text":"log base b of x equals the natural log of x over the natural log of b"},{"line":1,"text":"b to the x equals c implies x equals the natural log of c over the natural log of b"}],"terms":[{"term":"log_b","meaning":"Logarithm base b: takes a positive x and returns the exponent that b needs to produce x.","function":true},{"term":"b","meaning":"The base: positive and not equal to 1.","function":false},{"term":"x","meaning":"In line one, the log's positive input; in line two, the unknown exponent being solved for.","function":false},{"term":"ln","meaning":"Natural logarithm (base e): takes a positive number and returns its log base e; used to compute any other base.","function":true},{"term":"c","meaning":"The positive target value of the exponential equation.","function":false},{"term":"⇒","meaning":"Implies: taking ln of both sides and dividing gives the solution.","function":false}],"explanation":"The change-of-base formula rewrites a logarithm in any base as a ratio of natural (or common) logs, so calculators with only ln or log can evaluate it. It also solves exponential equations: taking ln of both sides of b^x = c brings x down, giving x = ln c / ln b. This is how growth-time and doubling-time problems are solved.","origin":"","implementations":[{"name":"math.log","library":"Python standard library","note":"math.log(x, b) computes log base b directly."},{"name":"=LOG()","library":"Excel","note":"Logarithm with an arbitrary base argument."},{"name":"sympy.solve","library":"SymPy","note":"Solves exponential equations symbolically."}]},"A2.9":{"spoken":[{"line":0,"text":"a sub n equals a sub 1 plus the quantity n minus 1 times d"},{"line":1,"text":"S sub n equals n times the quantity a sub 1 plus a sub n, all over 2"}],"terms":[{"term":"aₙ","meaning":"The n-th term of the arithmetic sequence, the term in position n.","function":false},{"term":"a₁","meaning":"The first term of the arithmetic sequence, where it starts.","function":false},{"term":"n","meaning":"The term's position, or the number of terms being added.","function":false},{"term":"d","meaning":"Common difference: the constant amount added to get from one term to the next.","function":false},{"term":"Sₙ","meaning":"The sum of the first n terms: the number of terms times the average of the first and last.","function":false}],"explanation":"An arithmetic sequence adds a constant difference d each step, so the nth term is a₁ + (n − 1)d. Its sum pairs the first and last terms, second and second-last, and so on, each pair having the same total, giving n times the average of the first and last terms. It models steady linear growth such as fixed savings.","origin":"The pairing trick is famously attributed to a young Carl Friedrich Gauss (1780s), though sums of arithmetic series were known much earlier.","implementations":[{"name":"numpy.arange","library":"NumPy","note":"Generates evenly spaced values with a fixed step."},{"name":"range","library":"Python standard library","note":"Integer arithmetic sequence with a given step."},{"name":"sum","library":"Python standard library","note":"Adds the terms of a sequence."}]},"A2.10":{"spoken":[{"line":0,"text":"a sub n equals a sub 1 r to the n minus 1"},{"line":1,"text":"S sub n equals a sub 1 times the quantity 1 minus r to the n, all over 1 minus r; S sub infinity equals a sub 1 over 1 minus r, for the absolute value of r less than 1"}],"terms":[{"term":"aₙ","meaning":"The n-th term of the geometric sequence, the term in position n.","function":false},{"term":"a₁","meaning":"The first term of the geometric sequence, which every later term is a multiple of.","function":false},{"term":"r","meaning":"Common ratio: the constant factor multiplying each term to get the next; r not equal to 1 in the sum formula.","function":false},{"term":"n","meaning":"The term's position, or the number of terms summed.","function":false},{"term":"Sₙ","meaning":"The sum of the first n terms of the geometric series.","function":false},{"term":"S∞","meaning":"The sum of the infinite geometric series, which converges only when the absolute value of r is below 1.","function":false},{"term":"|r|","meaning":"Absolute value of the ratio: takes r and returns its size; must be less than 1 for convergence.","function":true}],"explanation":"A geometric sequence multiplies by a constant ratio r each step, so a_n = a₁rⁿ⁻¹. Its finite sum comes from subtracting r times the sum from itself, leaving a₁(1 − rⁿ)/(1 − r). When |r| < 1, rⁿ shrinks to zero, so the infinite series converges to a₁/(1 − r). It models compound growth, decay and repeating decimals.","origin":"A finite geometric sum appears in Euclid's Elements (Book IX, Proposition 35, c. 300 BC), and Archimedes summed an infinite geometric series in his quadrature of the parabola.","implementations":[{"name":"numpy.geomspace","library":"NumPy","note":"Generates numbers spaced evenly on a log scale."},{"name":"sympy.summation","library":"SymPy","note":"Symbolic sum of a finite or infinite series."}]},"A2.11":{"spoken":[{"line":0,"text":"the sum from i equals 1 to n of i equals n times the quantity n plus 1, all over 2; the sum from i equals 1 to n of i squared equals n times the quantity n plus 1 times the quantity 2 n plus 1, all over 6"},{"line":1,"text":"the sum of the quantity c a sub i plus b sub i equals c times the sum of a sub i plus the sum of b sub i"}],"terms":[{"term":"Σ","meaning":"Summation: takes an expression in the index and returns the total over every index value from the lower to the upper limit.","function":true},{"term":"i","meaning":"The index of summation, a counter stepping through 1, 2, up to n.","function":false},{"term":"n","meaning":"The upper limit: the last index value, so the number of terms.","function":false},{"term":"c","meaning":"A constant multiplier, which can be pulled out in front of the sum.","function":false},{"term":"aᵢ, bᵢ","meaning":"Terms of two sequences indexed by i; the sum splits across their addition.","function":false}],"explanation":"Sigma notation writes a sum compactly by giving an index, its limits and a general term. Closed forms give the sums of the first n integers, n(n + 1)/2, and of the first n squares, n(n + 1)(2n + 1)/6. Linearity lets constants factor out and sums split apart, which is how more complex sums are reduced to these known formulas.","origin":"Leonhard Euler introduced the Σ notation in 1755; the sum-of-squares formula was known to Archimedes.","implementations":[{"name":"sum","library":"Python standard library","note":"Adds the items of an iterable."},{"name":"numpy.sum","library":"NumPy","note":"Sums array elements, optionally along an axis."},{"name":"sympy.summation","library":"SymPy","note":"Closed-form symbolic sums."},{"name":"=SUM()","library":"Excel","note":"Adds a range of cells."}]},"A2.12":{"spoken":[{"line":0,"text":"the quantity a plus b, to the n, equals the sum from k equals 0 to n of n choose k, a to the n minus k, b to the k"},{"line":1,"text":"n choose k equals n factorial over k factorial times the quantity n minus k factorial"}],"terms":[{"term":"a, b","meaning":"The two terms of the binomial being expanded.","function":false},{"term":"n","meaning":"The nonnegative integer power the binomial is raised to.","function":false},{"term":"Σ","meaning":"Summation: adds the terms for k equals 0 through n, giving n plus 1 terms in the expansion.","function":true},{"term":"k","meaning":"The term index; it is the power on b, while a gets n minus k.","function":false},{"term":"(n k)","meaning":"Binomial coefficient n choose k: takes n and k and returns the number of ways to pick k items from n; the term's coefficient.","function":true},{"term":"!","meaning":"Factorial: takes a nonnegative integer and returns the product of all positive integers up to it; 0 factorial is 1.","function":true}],"explanation":"The binomial theorem expands (a + b)ⁿ as a sum of terms aⁿ⁻ᵏbᵏ weighted by binomial coefficients C(n, k). Each coefficient counts the ways to choose k of the n factors to contribute b, which is why it equals n!/(k!(n − k)!). The coefficients form the rows of Pascal's triangle, and the theorem underlies the binomial probability distribution.","origin":"Pascal's triangle was known to al-Karaji, Jia Xian and Yang Hui centuries before Blaise Pascal's 1654 treatise; Isaac Newton extended the theorem to non-integer exponents around 1665.","implementations":[{"name":"math.comb","library":"Python standard library","note":"Binomial coefficient n choose k."},{"name":"scipy.special.comb","library":"SciPy","note":"Binomial coefficient, exact or floating point."},{"name":"sympy.binomial","library":"SymPy","note":"Symbolic binomial coefficient."},{"name":"=COMBIN()","library":"Excel","note":"Number of combinations of n items taken k at a time."}]},"A2.13":{"spoken":[{"line":0,"text":"the i j entry of A B equals the sum over k of a sub i k times b sub k j"},{"line":1,"text":"the matrix a, b; c, d times the matrix e, f; g, h equals the matrix with rows: a e plus b g, a f plus b h; and c e plus d g, c f plus d h"}],"terms":[{"term":"A, B","meaning":"Matrices being multiplied; A's column count must equal B's row count.","function":false},{"term":"(AB)ᵢⱼ","meaning":"The entry in row i, column j of the product matrix AB.","function":false},{"term":"i, j","meaning":"Row index of A and column index of B, which locate the product entry.","function":false},{"term":"Σ","meaning":"Summation over k: adds the products of matching entries along row i of A and column j of B.","function":true},{"term":"k","meaning":"The shared index running along A's row and down B's column.","function":false},{"term":"aᵢₖ, bₖⱼ","meaning":"Entries of A (row i, column k) and B (row k, column j).","function":false},{"term":"a, b, c, d","meaning":"Entries of the first 2 by 2 matrix: top row a, b; bottom row c, d.","function":false},{"term":"e, f, g, h","meaning":"Entries of the second 2 by 2 matrix: top row e, f; bottom row g, h.","function":false}],"explanation":"Matrix multiplication computes each entry of AB as the dot product of a row of A with a column of B, so the inner dimensions must match. The 2×2 example shows each entry assembled this way. The product represents applying one linear transformation after another, and it is generally not commutative, so AB and BA usually differ.","origin":"Arthur Cayley formalized matrix algebra, including multiplication, in his 1858 memoir; James Joseph Sylvester had coined the term \"matrix\" in 1850.","implementations":[{"name":"numpy.matmul","library":"NumPy","note":"Matrix product, also available as the @ operator."},{"name":"numpy.dot","library":"NumPy","note":"Dot product, which is matrix multiplication for 2-D arrays."},{"name":"torch.matmul","library":"PyTorch","note":"Matrix product of tensors."},{"name":"=MMULT()","library":"Excel","note":"Matrix product of two arrays."}]},"A2.14":{"spoken":[{"line":0,"text":"the determinant of A equals a d minus b c"},{"line":1,"text":"A inverse equals 1 over the quantity a d minus b c, times the matrix d, negative b; negative c, a"},{"line":2,"text":"x equals the determinant of A sub x over the determinant of A"}],"terms":[{"term":"det","meaning":"Determinant: takes a square matrix and returns a scalar; it is nonzero exactly when the matrix is invertible.","function":true},{"term":"A","meaning":"A 2 by 2 matrix with top row a, b and bottom row c, d; in Cramer's rule, the coefficient matrix.","function":false},{"term":"a, b, c, d","meaning":"The entries of A: a and d on the main diagonal, b and c off the diagonal.","function":false},{"term":"A⁻¹","meaning":"Inverse matrix of A: multiplying by A gives the identity; exists only when ad minus bc is not 0.","function":false},{"term":"x","meaning":"The unknown being solved for in the linear system A times the unknowns vector equals the constants vector.","function":false},{"term":"Aₓ","meaning":"The matrix A with its x column replaced by the column of constants.","function":false}],"explanation":"The determinant of a 2×2 matrix, ad − bc, measures how the matrix scales area and is zero exactly when the matrix has no inverse. The inverse swaps the diagonal entries, negates the off-diagonal entries and divides by the determinant. Cramer's rule solves a linear system by dividing the determinant with one column replaced by the constants by det A.","origin":"Gabriel Cramer published his rule in 1750; determinants had been introduced earlier by Seki Takakazu and Gottfried Leibniz in the late 17th century.","implementations":[{"name":"numpy.linalg.det","library":"NumPy","note":"Determinant of a square matrix."},{"name":"numpy.linalg.inv","library":"NumPy","note":"Inverse of a square matrix."},{"name":"=MDETERM()","library":"Excel","note":"Determinant of a square array."},{"name":"=MINVERSE()","library":"Excel","note":"Inverse of a square array."}]},"A2.15":{"spoken":[{"line":0,"text":"circle: the quantity x minus h squared plus the quantity y minus k squared equals r squared"},{"line":1,"text":"ellipse: the quantity x minus h squared over a squared plus the quantity y minus k squared over b squared equals 1"},{"line":2,"text":"hyperbola: the quantity x minus h squared over a squared minus the quantity y minus k squared over b squared equals 1"}],"terms":[{"term":"x, y","meaning":"The coordinates of any point lying on the conic curve.","function":false},{"term":"h, k","meaning":"Coordinates of the center (h, k) of the conic.","function":false},{"term":"r","meaning":"Radius of the circle: the fixed distance from the center (h, k) to every point on it.","function":false},{"term":"a","meaning":"Ellipse: horizontal semi-axis length; hyperbola: distance from center to each vertex along the x-direction.","function":false},{"term":"b","meaning":"Ellipse: vertical semi-axis length; hyperbola: the conjugate semi-axis that sets the asymptote slopes plus or minus b over a.","function":false}],"explanation":"Conic sections are curves formed by slicing a cone, written here in standard form centered at (h, k). A circle is all points at distance r from the center. An ellipse divides each squared offset by a² or b² and adds them to 1; a hyperbola subtracts them. The focal distance c satisfies c² = a² − b² for ellipses and c² = a² + b² for hyperbolas.","origin":"Studied by Menaechmus in the 4th century BC; Apollonius of Perga named the ellipse, parabola and hyperbola in his Conics around 200 BC.","implementations":[{"name":"sympy.geometry.Ellipse","library":"SymPy","note":"Ellipse object with foci, eccentricity and area."},{"name":"sympy.geometry.Circle","library":"SymPy","note":"Circle object from center and radius."},{"name":"matplotlib.patches.Ellipse","library":"Matplotlib","note":"Draws an ellipse patch on a plot."}]},"A1.1":{"spoken":[{"line":0,"text":"a times the quantity b plus c equals a b plus a c"},{"line":1,"text":"P, then E, then M or D, then A or S"}],"terms":[{"term":"a, b, c","meaning":"Any real numbers; the distributive property multiplies a across each term inside the parentheses.","function":false},{"term":"P","meaning":"Parentheses: evaluate expressions inside grouping symbols first, before anything else.","function":false},{"term":"E","meaning":"Exponents: evaluate powers and roots next, after the parentheses are done.","function":false},{"term":"M/D","meaning":"Multiplication and division, done together from left to right.","function":false},{"term":"A/S","meaning":"Addition and subtraction, done last together from left to right.","function":false},{"term":"→","meaning":"Then: shows the order in which the operations are performed.","function":false}],"explanation":"Real numbers obey properties such as commutativity, associativity and the distributive law, a(b + c) = ab + ac, which justify rearranging and expanding expressions. The order of operations is a convention that fixes how an expression is evaluated: parentheses first, then exponents, then multiplication and division left to right, then addition and subtraction left to right.","origin":"","implementations":[{"name":"sympy.expand","library":"SymPy","note":"Applies the distributive law to expand expressions."}]},"A1.2":{"spoken":[{"line":0,"text":"a to the m times a to the n equals a to the m plus n; a to the m over a to the n equals a to the m minus n"},{"line":1,"text":"the quantity a to the m, to the n, equals a to the m n; a to the 0 equals 1; a to the negative n equals 1 over a to the n"}],"terms":[{"term":"a","meaning":"The base: the number being repeatedly multiplied; nonzero for the zero, negative and quotient rules.","function":false},{"term":"m, n","meaning":"Exponents: how many times the base is used as a factor.","function":false},{"term":"a⁰","meaning":"Any nonzero base to the zero power, which equals 1.","function":false},{"term":"a⁻ⁿ","meaning":"A negative exponent, meaning the reciprocal of a to the n.","function":false}],"explanation":"Exponent rules follow from treating aⁿ as n copies of a multiplied together. Multiplying powers of the same base adds exponents, dividing subtracts them, and raising a power to a power multiplies them. Extending these rules consistently forces a⁰ = 1 and a⁻ⁿ = 1/aⁿ for nonzero a. They are used to simplify expressions and in scientific notation.","origin":"Modern superscript exponent notation was popularized by René Descartes in La Géométrie (1637).","implementations":[{"name":"pow","library":"Python standard library","note":"Raises a number to a power."},{"name":"math.pow","library":"Python standard library","note":"Floating-point power."},{"name":"numpy.power","library":"NumPy","note":"Element-wise power."},{"name":"=POWER()","library":"Excel","note":"Raises a number to a power."}]},"A1.3":{"spoken":[{"line":0,"text":"a to the m over n equals the n-th root of a to the m, equals the quantity n-th root of a, to the m"},{"line":1,"text":"the square root of a b equals the square root of a times the square root of b"}],"terms":[{"term":"a","meaning":"The base, the radicand; nonnegative when n is even so the root is real.","function":false},{"term":"m/n","meaning":"Rational exponent: the denominator n gives the root, the numerator m gives the power.","function":false},{"term":"ⁿ√","meaning":"n-th root: takes a number and returns the value whose n-th power is that number.","function":true},{"term":"√","meaning":"Square root: takes a nonnegative number and returns its nonnegative root; it splits over products when a, b are nonnegative.","function":true},{"term":"b","meaning":"A second nonnegative number multiplied with a under the radical.","function":false}],"explanation":"A rational exponent combines a power and a root: a^(m/n) is the nth root of a raised to the m, in either order. This makes the exponent rules apply to radicals too. The product rule for radicals, √a·√b = √(ab), holds for nonnegative a and b and is used to simplify roots by pulling out perfect squares.","origin":"The radical sign √ appeared in Christoph Rudolff's 1525 algebra text; fractional exponents were later standardized by John Wallis and Isaac Newton.","implementations":[{"name":"math.sqrt","library":"Python standard library","note":"Square root."},{"name":"math.cbrt","library":"Python standard library","note":"Cube root (Python 3.11+)."},{"name":"numpy.cbrt","library":"NumPy","note":"Element-wise cube root."},{"name":"sympy.root","library":"SymPy","note":"Symbolic nth root."}]},"A1.4":{"spoken":[{"line":0,"text":"m equals the quantity y sub 2 minus y sub 1, all over the quantity x sub 2 minus x sub 1, equals delta y over delta x"}],"terms":[{"term":"m","meaning":"Slope: the line's steepness, rise over run; positive rises, negative falls.","function":false},{"term":"x₁, y₁","meaning":"Coordinates of the first point on the line.","function":false},{"term":"x₂, y₂","meaning":"Coordinates of the second point; x sub 2 must differ from x sub 1.","function":false},{"term":"Δ","meaning":"Delta: change in; delta y is the rise and delta x is the run.","function":false}],"explanation":"Slope measures a line's steepness as the change in y divided by the change in x between any two points on it. Because a line has constant slope, any two points give the same value. Positive slope rises left to right, negative slope falls, zero slope is horizontal, and a vertical line has undefined slope. Slope is a rate of change.","origin":"","implementations":[{"name":"=SLOPE()","library":"Excel","note":"Slope of the linear regression line through data."},{"name":"numpy.polyfit","library":"NumPy","note":"With degree 1, fits a line and returns slope and intercept."},{"name":"scipy.stats.linregress","library":"SciPy","note":"Least-squares line with slope, intercept and r."}]},"A1.5":{"spoken":[{"line":0,"text":"y equals m x plus b"},{"line":1,"text":"y minus y sub 1 equals m times the quantity x minus x sub 1"},{"line":2,"text":"A x plus B y equals C"}],"terms":[{"term":"y, x","meaning":"The coordinates of any point lying on the line.","function":false},{"term":"m","meaning":"The slope of the line: its rise over run, the same in every form.","function":false},{"term":"b","meaning":"The y-intercept: the y-value where the line crosses the y-axis.","function":false},{"term":"x₁, y₁","meaning":"Coordinates of one known point on the line, used in point-slope form.","function":false},{"term":"A, B, C","meaning":"Constants of standard form, usually integers with A nonnegative; the slope is negative A over B.","function":false}],"explanation":"A line can be written three standard ways. Slope-intercept form y = mx + b shows the slope and the y-intercept directly. Point-slope form y − y₁ = m(x − x₁) builds the line from one point and the slope. Standard form Ax + By = C treats x and y symmetrically, handles vertical lines, and makes intercepts easy to find.","origin":"Representing lines by equations comes from the analytic geometry of René Descartes and Pierre de Fermat in the 17th century.","implementations":[{"name":"numpy.polyfit","library":"NumPy","note":"Fits y = mx + b to points with degree 1."},{"name":"numpy.poly1d","library":"NumPy","note":"Builds an evaluable polynomial from coefficients."},{"name":"=INTERCEPT()","library":"Excel","note":"y-intercept of the regression line."}]},"A1.6":{"spoken":[{"line":0,"text":"parallel: m sub 1 equals m sub 2"},{"line":1,"text":"perpendicular: m sub 1 m sub 2 equals negative 1, if and only if m sub 2 equals negative 1 over m sub 1"}],"terms":[{"term":"∥","meaning":"Is parallel to: the lines never meet, so they have equal slopes.","function":false},{"term":"m₁, m₂","meaning":"The slopes of the two lines being compared.","function":false},{"term":"⟂","meaning":"Is perpendicular to: the lines meet at a right angle, so their slopes are negative reciprocals.","function":false},{"term":"⟺","meaning":"If and only if: the product condition and the negative-reciprocal condition are equivalent.","function":false}],"explanation":"Parallel lines never meet, so they must have the same slope. Perpendicular lines meet at a right angle, and their slopes multiply to −1, so each slope is the negative reciprocal of the other. A vertical and a horizontal line are also perpendicular, the exception where one slope is undefined. These rules are used to write lines through given points.","origin":"","implementations":[]},"A1.7":{"spoken":[{"line":0,"text":"the absolute value of x equals x if x is greater than or equal to 0, and negative x if x is less than 0"},{"line":1,"text":"the absolute value of x minus a is less than r if and only if a minus r is less than x, which is less than a plus r"}],"terms":[{"term":"|·|","meaning":"Absolute value: takes a real number and returns its nonnegative distance from zero.","function":true},{"term":"x","meaning":"The variable or real number whose absolute value is taken.","function":false},{"term":"{","meaning":"Piecewise brace: the rule chosen depends on which condition on x holds.","function":false},{"term":"a","meaning":"The center point on the number line; |x minus a| is the distance from x to a.","function":false},{"term":"r","meaning":"A positive radius: the maximum allowed distance from a.","function":false},{"term":"⟺","meaning":"If and only if: the absolute value inequality is equivalent to the compound inequality.","function":false}],"explanation":"Absolute value is the distance from zero, defined piecewise as x for nonnegative x and −x otherwise. So |x − a| < r means x lies within distance r of a, which unfolds into the compound inequality a − r < x < a + r. A greater-than inequality instead splits into two separate rays joined by \"or\".","origin":"The vertical-bar notation |x| was introduced by Karl Weierstrass in 1841.","implementations":[{"name":"abs","library":"Python standard library","note":"Built-in absolute value."},{"name":"numpy.abs","library":"NumPy","note":"Element-wise absolute value."},{"name":"sympy.Abs","library":"SymPy","note":"Symbolic absolute value."},{"name":"=ABS()","library":"Excel","note":"Absolute value of a number."}]},"A1.8":{"spoken":[{"line":0,"text":"the system: a sub 1 x plus b sub 1 y equals c sub 1, and a sub 2 x plus b sub 2 y equals c sub 2"}],"terms":[{"term":"{","meaning":"System brace: both equations must hold at the same time.","function":false},{"term":"x, y","meaning":"The unknowns; a solution is an (x, y) pair satisfying both equations.","function":false},{"term":"a₁, b₁, c₁","meaning":"The coefficients of x and y and the constant term in the first equation.","function":false},{"term":"a₂, b₂, c₂","meaning":"The coefficients of x and y and the constant term in the second equation.","function":false}],"explanation":"A system of two linear equations in two unknowns asks for the point satisfying both, which is where the two lines intersect. Lines that cross give exactly one solution; parallel lines give none; and identical lines give infinitely many. Systems are solved by substitution, elimination, graphing or matrices.","origin":"Elimination methods for linear systems appear in the Chinese Nine Chapters on the Mathematical Art (compiled by about the 1st century AD), a method now named for Gauss.","implementations":[{"name":"numpy.linalg.solve","library":"NumPy","note":"Solves a square linear system Ax = b."},{"name":"sympy.linsolve","library":"SymPy","note":"Symbolic solution set of a linear system."},{"name":"scipy.linalg.solve","library":"SciPy","note":"Solves a linear system with options for matrix structure."}]},"A1.9":{"spoken":[{"line":0,"text":"the quantity a plus or minus b, squared, equals a squared plus or minus 2 a b plus b squared"},{"line":1,"text":"the quantity a plus b times the quantity a minus b equals a squared minus b squared"}],"terms":[{"term":"a, b","meaning":"Any two terms or numbers in the binomial.","function":false},{"term":"±","meaning":"Plus or minus: use the same sign on both sides; only the middle term 2ab changes sign.","function":false}],"explanation":"Multiplying polynomials applies the distributive law to every pair of terms, which FOIL organizes for two binomials. Two patterns recur so often they are memorized: the square of a binomial, (a ± b)² = a² ± 2ab + b², whose middle term is easy to forget, and the product of conjugates, (a + b)(a − b) = a² − b², where the middle terms cancel.","origin":"Geometric versions of these identities appear in Book II of Euclid's Elements (c. 300 BC).","implementations":[{"name":"sympy.expand","library":"SymPy","note":"Multiplies out polynomial products."},{"name":"numpy.polymul","library":"NumPy","note":"Multiplies polynomials given as coefficient arrays."}]},"A1.10":{"spoken":[{"line":0,"text":"x squared plus the quantity p plus q times x, plus p q equals the quantity x plus p times the quantity x plus q"},{"line":1,"text":"a squared minus b squared equals the quantity a minus b times the quantity a plus b"},{"line":2,"text":"a cubed plus or minus b cubed equals the quantity a plus or minus b times the quantity a squared minus or plus a b plus b squared"}],"terms":[{"term":"x","meaning":"The variable of the quadratic trinomial being factored.","function":false},{"term":"p, q","meaning":"Two numbers whose sum is the middle coefficient and whose product is the constant term.","function":false},{"term":"a, b","meaning":"Terms being squared or cubed in the difference of squares and sum or difference of cubes patterns.","function":false},{"term":"±","meaning":"Plus or minus: top sign gives the sum of cubes, bottom sign the difference of cubes.","function":false},{"term":"∓","meaning":"Minus or plus: the opposite sign of the ±, on the middle ab term.","function":false}],"explanation":"Factoring reverses multiplication by rewriting a polynomial as a product. A monic quadratic factors as (x + p)(x + q) when p and q add to the middle coefficient and multiply to the constant. The difference of squares and the sum or difference of cubes are special patterns. Factored form reveals the roots through the zero product property.","origin":"","implementations":[{"name":"sympy.factor","library":"SymPy","note":"Factors a polynomial over the rationals."},{"name":"sympy.factor_list","library":"SymPy","note":"Returns the list of irreducible factors."}]},"A1.11":{"spoken":[{"line":0,"text":"a x squared plus b x plus c equals 0"},{"line":1,"text":"x equals the quantity negative b plus or minus the square root of b squared minus 4 a c, all over 2 a"}],"terms":[{"term":"a","meaning":"The coefficient of x squared; it can't be 0, and its sign sets whether the parabola opens up or down.","function":false},{"term":"x","meaning":"The unknown; its solutions are the roots, the x-intercepts of the parabola.","function":false},{"term":"b","meaning":"The coefficient of x, the linear term; it shifts the parabola's vertex sideways.","function":false},{"term":"c","meaning":"The constant term, which is also the y-intercept.","function":false},{"term":"±","meaning":"Plus or minus: gives the two roots, one with each sign.","function":false},{"term":"√","meaning":"Square root: takes the discriminant b squared minus 4ac; its sign decides two real, one repeated, or two complex roots.","function":true}],"explanation":"The quadratic formula solves any equation ax² + bx + c = 0 and is derived by completing the square. The discriminant b² − 4ac under the root decides the roots: positive gives two real roots, zero gives one repeated root, and negative gives two complex conjugate roots. The ± produces the two solutions, symmetric about x = −b/2a.","origin":"Babylonians solved quadratic problems by completing the square around 2000 BC; Brahmagupta gave a general rule in 628 AD and al-Khwarizmi treated them systematically around 820 AD.","implementations":[{"name":"numpy.roots","library":"NumPy","note":"Roots of a polynomial from its coefficients."},{"name":"sympy.solve","library":"SymPy","note":"Exact symbolic solutions of the equation."},{"name":"scipy.optimize.root_scalar","library":"SciPy","note":"Numerical root of a scalar function."}]},"A1.12":{"spoken":[{"line":0,"text":"y equals a times the quantity x minus h, squared, plus k"},{"line":1,"text":"h equals negative b over 2 a, k equals f of h"}],"terms":[{"term":"y","meaning":"The output of the quadratic function, the height of the parabola at x.","function":false},{"term":"a","meaning":"The leading coefficient: opens up if positive, down if negative; larger absolute value means narrower.","function":false},{"term":"x","meaning":"The input variable, the horizontal coordinate on the parabola.","function":false},{"term":"h","meaning":"The x-coordinate of the vertex and the axis of symmetry x equals h.","function":false},{"term":"k","meaning":"The y-coordinate of the vertex, the minimum or maximum value of the function.","function":false},{"term":"b","meaning":"The coefficient of x in standard form a x squared plus b x plus c.","function":false},{"term":"f(h)","meaning":"The quadratic function evaluated at h: takes the vertex's x-value and returns its y-value.","function":true}],"explanation":"Vertex form y = a(x − h)² + k shows a parabola's vertex (h, k) directly, with a setting its direction and width. From standard form ax² + bx + c, the vertex's x-coordinate is h = −b/2a, the axis of symmetry, and k is found by evaluating the function there. Completing the square converts between the two forms.","origin":"","implementations":[]},"A1.13":{"spoken":[{"line":0,"text":"y equals k x (direct)"},{"line":1,"text":"y equals k over x (inverse)"}],"terms":[{"term":"y","meaning":"The dependent variable, whose value changes in response to x.","function":false},{"term":"k","meaning":"The constant of variation, a nonzero constant: y over x for direct, x times y for inverse.","function":false},{"term":"x","meaning":"The independent variable; it must be nonzero in inverse variation.","function":false}],"explanation":"In direct variation y = kx, y is proportional to x: doubling x doubles y, and the graph is a line through the origin. In inverse variation y = k/x, the product xy is constant, so doubling x halves y, and the graph is a hyperbola. The constant of variation k is found from one known pair of values.","origin":"","implementations":[]},"A1.14":{"spoken":[{"line":0,"text":"percent change equals the quantity new minus old, all over old, times 100 percent"},{"line":1,"text":"a over b equals c over d if and only if a d equals b c"}],"terms":[{"term":"%Δ","meaning":"Percent change: the change relative to the original value, positive for an increase.","function":false},{"term":"new","meaning":"The value after the change, the later or final amount.","function":false},{"term":"old","meaning":"The original value, the reference, which must be nonzero.","function":false},{"term":"%","meaning":"Percent: per hundred; multiplying by 100 percent converts the ratio to a percentage.","function":false},{"term":"a, b, c, d","meaning":"Terms of a proportion with b and d nonzero; a d and b c are the cross products.","function":false},{"term":"⟺","meaning":"If and only if: the proportion holds exactly when the cross products are equal.","function":false}],"explanation":"Percent change measures relative change as the difference between new and old values divided by the old value, times 100%. A proportion states that two ratios are equal, and cross-multiplying gives ad = bc, the standard way to solve for a missing term. These are used in scaling recipes, unit rates, maps and financial reporting.","origin":"Euclid's Elements Book V (c. 300 BC) presents a general theory of proportion attributed to Eudoxus.","implementations":[{"name":"pandas.Series.pct_change","library":"pandas","note":"Fractional change between consecutive elements."}]},"A1.15":{"spoken":[{"line":0,"text":"a is less than b implies a plus c is less than b plus c"},{"line":1,"text":"c is greater than 0: a c is less than b c; c is less than 0: a c is greater than b c"}],"terms":[{"term":"a, b","meaning":"Two real numbers related by an inequality on both sides of the comparison.","function":false},{"term":"<, >","meaning":"Less than and greater than: the order relation that must be preserved or flipped.","function":false},{"term":"⇒","meaning":"Implies: adding c to both sides keeps the inequality true.","function":false},{"term":"c","meaning":"A real number added to or multiplied on both sides; multiplying by negative c flips the inequality.","function":false}],"explanation":"Linear inequalities are solved like equations, with one exception. Adding or subtracting the same number from both sides keeps the inequality true, as does multiplying or dividing by a positive number. Multiplying or dividing by a negative number reverses the order on the number line, so the inequality sign must flip. Solutions are usually ranges written in interval notation.","origin":"The symbols < and > were introduced by Thomas Harriot in a work published posthumously in 1631.","implementations":[{"name":"sympy.solve_univariate_inequality","library":"SymPy","note":"Solves a one-variable inequality."},{"name":"sympy.reduce_inequalities","library":"SymPy","note":"Reduces a system of inequalities."}]},"A1.16":{"spoken":[{"line":0,"text":"A union B, A intersect B, A complement, A minus B"},{"line":1,"text":"the size of A union B equals the size of A plus the size of B minus the size of A intersect B"},{"line":2,"text":"the complement of A union B equals A complement intersect B complement"},{"line":3,"text":"the interval from a, closed, to b, open, equals the set of x such that a is less than or equal to x, which is less than b"}],"terms":[{"term":"A, B","meaning":"Sets: collections of distinct elements within some universal set.","function":false},{"term":"∪","meaning":"Union: takes two sets and returns the set of elements in either one or both.","function":true},{"term":"∩","meaning":"Intersection: takes two sets and returns the set of elements in both.","function":true},{"term":"Aᶜ","meaning":"Complement of A: everything in the universal set that is not in A.","function":true},{"term":"∖","meaning":"Set difference: A minus B is the elements of A that are not in B.","function":true},{"term":"|·|","meaning":"Cardinality: takes a finite set and returns how many elements it has.","function":true},{"term":"[a, b)","meaning":"Half-open interval: all real numbers from a up to b, including a but excluding b.","function":false},{"term":"{x : …}","meaning":"Set-builder notation: the set of all x satisfying the condition after the colon.","function":false},{"term":"x","meaning":"A real number that belongs to the interval.","function":false},{"term":"≤","meaning":"Is less than or equal to: allows the endpoint a to be included.","function":false}],"explanation":"Sets combine by union (in either), intersection (in both), complement (not in the set) and difference (in A but not B). Inclusion-exclusion counts a union by adding the sizes and subtracting the overlap, which was counted twice. De Morgan's law turns the complement of a union into the intersection of complements. Interval notation uses brackets for included endpoints and parentheses for excluded ones.","origin":"Set theory was founded by Georg Cantor in the 1870s; De Morgan's laws are named for Augustus De Morgan (19th century).","implementations":[{"name":"set.union","library":"Python standard library","note":"Union of Python sets, also the | operator."},{"name":"set.intersection","library":"Python standard library","note":"Intersection of sets, also the & operator."},{"name":"set.difference","library":"Python standard library","note":"Set difference, also the - operator."},{"name":"sympy.Interval","library":"SymPy","note":"Real interval with open or closed endpoints."}]},"V.1":{"spoken":[{"line":0,"text":"The partial derivative of f with respect to x equals the limit as h approaches 0 of the quantity f of x plus h comma y, minus f of x comma y, all over h."},{"line":1,"text":"f sub x y equals f sub y x, Clairaut."}],"terms":[{"term":"∂f/∂x","meaning":"The partial derivative of f with respect to x: takes the function f(x, y) and returns its rate of change in x while y is held fixed.","function":true},{"term":"f","meaning":"A function of two variables, f(x, y), whose partial derivatives are being defined and compared on this card.","function":true},{"term":"x","meaning":"The first input variable of f; the one being varied in the partial derivative with respect to x.","function":false},{"term":"y","meaning":"The second input variable of f; held constant (frozen) when taking the partial derivative with respect to x.","function":false},{"term":"lim","meaning":"The limit operator: takes the difference quotient as a function of h and returns the value it approaches as h shrinks to 0.","function":true},{"term":"h","meaning":"A small increment added to x only; the step size in the difference quotient that shrinks to zero.","function":false},{"term":"f_xy, f_yx","meaning":"Mixed second partial derivatives: f_xy differentiates f first in x then in y; f_yx does it in the opposite order.","function":true},{"term":"Clairaut","meaning":"Clairaut's theorem: if the mixed partials are continuous, the order of differentiation does not matter, so f_xy equals f_yx.","function":false}],"explanation":"A partial derivative measures how a multivariable function changes as one input varies while all others are held fixed. The limit definition is the ordinary difference quotient applied along one coordinate direction. Clairaut's theorem states that if the mixed second partials are continuous, the order of differentiation does not matter, so f_xy equals f_yx.","origin":"Euler and Clairaut stated the symmetry of mixed partials in the 1740s; Hermann Schwarz gave a rigorous proof in 1873.","implementations":[{"name":"sympy.diff","library":"SymPy","note":"Symbolic partial derivative with respect to a chosen variable."},{"name":"numpy.gradient","library":"NumPy","note":"Finite-difference partial derivatives of gridded data along each axis."},{"name":"jax.grad","library":"JAX","note":"Automatic differentiation returning derivatives with respect to chosen arguments."}]},"V.2":{"spoken":[{"line":0,"text":"Del f equals the vector with components the partial derivative of f with respect to x, the partial derivative of f with respect to y, and the partial derivative of f with respect to z."},{"line":1,"text":"D sub u f equals del f dot u, where the norm of u equals 1."},{"line":2,"text":"The max of D sub u f equals the norm of del f."}],"terms":[{"term":"∇f","meaning":"The gradient of f: takes a scalar function f(x, y, z) and returns the vector of its partial derivatives, pointing in the direction of steepest ascent.","function":true},{"term":"∇","meaning":"The del operator, a vector of partial derivative operators; applied to a scalar function it produces the gradient.","function":true},{"term":"f","meaning":"A scalar-valued function of x, y and z whose gradient and directional derivatives are taken.","function":true},{"term":"∂f/∂x, ∂f/∂y, ∂f/∂z","meaning":"Partial derivatives of f in each coordinate direction; they are the components of the gradient vector.","function":true},{"term":"x, y, z","meaning":"The three input coordinates of the function f.","function":false},{"term":"D_𝐮 f","meaning":"The directional derivative: takes f and a unit direction u, and returns the rate of change of f when moving in direction u.","function":true},{"term":"𝐮","meaning":"A unit vector giving the direction of travel for the directional derivative.","function":false},{"term":"·","meaning":"The dot product: combines the gradient and the direction vector u into a single number, the directional derivative.","function":true},{"term":"‖𝐮‖","meaning":"The norm (length) of the vector u; requiring it to equal 1 makes u a unit direction vector.","function":true},{"term":"max","meaning":"The maximum over all unit directions u; the largest directional derivative equals the length of the gradient.","function":true},{"term":"‖∇f‖","meaning":"The magnitude of the gradient vector, which is the steepest possible rate of increase of f at the point.","function":false}],"explanation":"The gradient collects all first partial derivatives into a vector. The directional derivative, the rate of change in a unit direction u, is the dot product of the gradient with u. Because a dot product is largest when the vectors align, the gradient points in the direction of steepest ascent, and its length is that maximum rate. This is why gradient descent steps opposite to it.","origin":"Hamilton introduced the ∇ operator in the 1830s–40s; Gibbs and Heaviside shaped modern vector analysis in the 1880s.","implementations":[{"name":"numpy.gradient","library":"NumPy","note":"Finite-difference gradient of an array sampled on a grid."},{"name":"sympy.vector.gradient","library":"SymPy","note":"Symbolic gradient of a scalar field in a coordinate system."},{"name":"torch.autograd.grad","library":"PyTorch","note":"Computes gradients of outputs with respect to inputs via autodiff."},{"name":"jax.grad","library":"JAX","note":"Returns a function that evaluates the gradient."}]},"V.3":{"spoken":[{"line":0,"text":"d z d t equals the partial derivative of z with respect to x times d x d t, plus the partial derivative of z with respect to y times d y d t."},{"line":1,"text":"The partial derivative of z with respect to s equals the partial derivative of z with respect to x times the partial derivative of x with respect to s, plus the partial derivative of z with respect to y times the partial derivative of y with respect to s."}],"terms":[{"term":"dz/dt","meaning":"The total derivative of z with respect to t, where z depends on x and y, which in turn both depend on t.","function":true},{"term":"z","meaning":"The output variable, a function z = f(x, y) of two intermediate variables x and y.","function":false},{"term":"t","meaning":"A single independent parameter on which both x and y depend.","function":false},{"term":"∂z/∂x, ∂z/∂y","meaning":"Partial derivatives of z with respect to each intermediate variable, measuring how z responds to x or y alone.","function":true},{"term":"x, y","meaning":"Intermediate variables: inputs to z that are themselves functions of t, or of s and other variables.","function":false},{"term":"dx/dt, dy/dt","meaning":"Ordinary derivatives giving how fast each intermediate variable changes as the parameter t changes.","function":true},{"term":"∂z/∂s","meaning":"The partial derivative of z with respect to s, when x and y depend on several variables such as s and t.","function":true},{"term":"s","meaning":"One of several independent variables on which x and y depend; the others are held fixed.","function":false},{"term":"∂x/∂s, ∂y/∂s","meaning":"Partial derivatives of the intermediate variables x and y with respect to the independent variable s.","function":true}],"explanation":"The multivariable chain rule differentiates a function whose inputs themselves depend on other variables. Each intermediate variable contributes a path from the input to the output; multiply the derivatives along each path and add the paths together. The first formula handles a single parameter t, the second a partial derivative with respect to one of several parameters. Backpropagation in neural networks is this rule applied systematically.","origin":"","implementations":[{"name":"sympy.diff","library":"SymPy","note":"Differentiates composite expressions, applying the chain rule automatically."},{"name":"torch.autograd.backward","library":"PyTorch","note":"Reverse-mode autodiff applying the chain rule through a computation graph."},{"name":"jax.vjp","library":"JAX","note":"Vector–Jacobian product, the building block of reverse-mode chain rule."}]},"V.4":{"spoken":[{"line":0,"text":"J equals the matrix whose entries are the partial derivative of f sub i with respect to x sub j."},{"line":1,"text":"Vector f of the quantity vector x plus vector h is approximately vector f of vector x plus J times vector h."},{"line":2,"text":"d A equals the absolute value of the determinant of J, d u d v."}],"terms":[{"term":"J","meaning":"The Jacobian matrix: takes a vector function f and returns the matrix of all first partial derivatives, its best linear approximation at a point.","function":true},{"term":"∂f_i/∂x_j","meaning":"The entry in row i, column j of the Jacobian: the partial derivative of the i-th output with respect to the j-th input.","function":true},{"term":"f_i","meaning":"The i-th component (output) of the vector-valued function f; it indexes the rows of J.","function":true},{"term":"x_j","meaning":"The j-th input variable of f; it indexes the columns of J.","function":false},{"term":"𝐟","meaning":"A vector-valued function mapping an input vector x to an output vector; the map whose Jacobian is taken.","function":true},{"term":"𝐱","meaning":"The input point (vector) at which f is evaluated and linearized.","function":false},{"term":"𝐡","meaning":"A small displacement vector added to x; J times h gives the approximate change in f.","function":false},{"term":"≈","meaning":"Approximately equal: the linear approximation is accurate for small h.","function":false},{"term":"dA","meaning":"The area element in the original (x, y) coordinates, expressed through the new coordinates u and v.","function":false},{"term":"det J","meaning":"The Jacobian determinant: takes the Jacobian matrix and returns a number; its absolute value is the local area-stretch factor.","function":true},{"term":"|…|","meaning":"Absolute value, ensuring the area scaling factor is nonnegative regardless of orientation.","function":true},{"term":"du dv","meaning":"The area element in the new (u, v) coordinates, scaled by the absolute Jacobian determinant to give dA.","function":false}],"explanation":"The Jacobian matrix of a vector function lists every first partial derivative, with one row per output and one column per input. It is the best linear approximation of the function near a point, so f(x+h) ≈ f(x) + Jh. When changing variables in an integral, the absolute value of its determinant measures how much the map locally stretches area or volume.","origin":"Named after Carl Gustav Jacob Jacobi, who studied functional determinants in an 1841 memoir.","implementations":[{"name":"sympy.Matrix.jacobian","library":"SymPy","note":"Symbolic Jacobian of a vector of expressions."},{"name":"jax.jacobian","library":"JAX","note":"Returns a function computing the Jacobian via autodiff."},{"name":"torch.autograd.functional.jacobian","library":"PyTorch","note":"Computes the Jacobian of a function at given inputs."},{"name":"jacobian","library":"MATLAB Symbolic Math Toolbox","note":"Symbolic Jacobian matrix of a vector function."}]},"V.5":{"spoken":[{"line":0,"text":"H equals the matrix with first row f sub x x, f sub x y, and second row f sub y x, f sub y y."},{"line":1,"text":"D equals f sub x x times f sub y y minus f sub x y squared."},{"line":2,"text":"D greater than 0 and f sub x x greater than 0: min; D greater than 0 and f sub x x less than 0: max."},{"line":3,"text":"D less than 0: saddle."}],"terms":[{"term":"H","meaning":"The Hessian matrix: takes a function f(x, y) and returns the 2 by 2 matrix of its second partial derivatives at a point.","function":true},{"term":"f_xx","meaning":"The second partial derivative of f with respect to x twice; its sign tells concavity in the x direction.","function":true},{"term":"f_xy, f_yx","meaning":"Mixed second partial derivatives of f; equal under Clairaut's theorem, forming the off-diagonal entries of the Hessian.","function":true},{"term":"f_yy","meaning":"The second partial derivative of f with respect to y twice; concavity in the y direction.","function":true},{"term":"D","meaning":"The discriminant, the determinant of the Hessian, evaluated at a critical point to classify it.","function":false},{"term":"f_xy²","meaning":"The square of the mixed partial derivative, subtracted in the discriminant formula.","function":false},{"term":"min","meaning":"A local minimum: occurs when D is positive and f_xx is positive (the surface is a bowl).","function":false},{"term":"max","meaning":"A local maximum: occurs when D is positive and f_xx is negative (the surface is a dome).","function":false},{"term":"saddle","meaning":"A saddle point: occurs when D is negative; the surface curves up in one direction and down in another.","function":false}],"explanation":"The Hessian is the matrix of second partial derivatives and describes the local curvature of a function. At a critical point, its determinant D and the sign of f_xx classify the point: positive D with positive f_xx gives a minimum, positive D with negative f_xx a maximum, and negative D a saddle. Equivalently, the test checks whether the Hessian is positive definite, negative definite, or indefinite.","origin":"Named after Ludwig Otto Hesse, who used these determinants in the 1840s; James Joseph Sylvester coined the name.","implementations":[{"name":"sympy.hessian","library":"SymPy","note":"Symbolic Hessian matrix of an expression."},{"name":"jax.hessian","library":"JAX","note":"Returns a function computing the Hessian via autodiff."},{"name":"torch.autograd.functional.hessian","library":"PyTorch","note":"Computes the Hessian of a scalar function at given inputs."},{"name":"hessian","library":"MATLAB Symbolic Math Toolbox","note":"Symbolic Hessian matrix of a scalar function."}]},"V.6":{"spoken":[{"line":0,"text":"The double integral over R of f, d A, equals the integral from a to b of the integral from c to d of f of x comma y, d y d x."},{"line":2,"text":"The triple integral over E of f, d V."}],"terms":[{"term":"∬_R","meaning":"The double integral over region R: takes a function of two variables and returns its accumulated total over the region.","function":true},{"term":"R","meaning":"The two-dimensional region of integration, here the rectangle with x from a to b and y from c to d.","function":false},{"term":"f","meaning":"The integrand, a function of x and y (or x, y, z in the triple integral) being integrated.","function":true},{"term":"dA","meaning":"The area element of the region R; in rectangular coordinates it becomes dy dx.","function":false},{"term":"∫_a^b ∫_c^d","meaning":"Iterated integrals: the inner integral in y from c to d is computed first, then the outer integral in x from a to b.","function":true},{"term":"a, b","meaning":"The lower and upper limits of the outer integral in x.","function":false},{"term":"c, d","meaning":"The lower and upper limits of the inner integral in y.","function":false},{"term":"f(x, y)","meaning":"The value of the integrand at the point (x, y).","function":true},{"term":"dy dx","meaning":"Differentials indicating integration first with respect to y, then with respect to x.","function":false},{"term":"∭_E","meaning":"The triple integral over solid region E: takes a function of three variables and returns its total over the volume.","function":true},{"term":"E","meaning":"A three-dimensional solid region of space over which the triple integral of f is taken.","function":false},{"term":"dV","meaning":"The volume element of the solid region E.","function":false}],"explanation":"Double and triple integrals add up a function over a two- or three-dimensional region, giving quantities such as volume, mass, or average value. They are evaluated as iterated single integrals, working from the inside out while treating outer variables as constants. Fubini's theorem guarantees that, for well-behaved functions, the order of integration can be swapped, which often makes a hard integral easy.","origin":"Guido Fubini proved the general theorem on iterated integrals in 1907.","implementations":[{"name":"scipy.integrate.dblquad","library":"SciPy","note":"Numerically computes a double integral over a region."},{"name":"scipy.integrate.tplquad","library":"SciPy","note":"Numerically computes a triple integral over a region."},{"name":"sympy.integrate","library":"SymPy","note":"Symbolic iterated integration over multiple variables."},{"name":"integral2","library":"MATLAB","note":"Numerically integrates a function over a planar region."}]},"V.7":{"spoken":[{"line":0,"text":"d A equals r d r d theta."},{"line":1,"text":"d V equals r d z d r d theta."},{"line":2,"text":"d V equals rho squared sine phi, d rho d phi d theta."},{"line":3,"text":"The integral from negative infinity to infinity of e to the negative x squared, d x, equals the square root of pi."}],"terms":[{"term":"dA","meaning":"The area element; in polar coordinates it equals r dr dθ.","function":false},{"term":"r","meaning":"The radial distance from the origin (or from the z-axis in cylindrical coordinates); the extra factor r is the Jacobian.","function":false},{"term":"dr","meaning":"The differential of the radial coordinate r, a small change in distance from the origin or axis.","function":false},{"term":"dθ","meaning":"The differential of the angle theta, a small change in angle around the origin or z-axis.","function":false},{"term":"θ","meaning":"The polar angle measured in the xy-plane from the positive x-axis.","function":false},{"term":"dV","meaning":"The volume element, expressed in cylindrical or spherical coordinates with the appropriate Jacobian factor.","function":false},{"term":"dz","meaning":"The differential of height z in cylindrical coordinates.","function":false},{"term":"ρ","meaning":"Rho: the distance from the origin to the point in spherical coordinates.","function":false},{"term":"sin ϕ","meaning":"The sine function applied to the polar angle phi; part of the spherical Jacobian factor rho squared sine phi.","function":true},{"term":"ϕ","meaning":"Phi: the angle measured down from the positive z-axis in spherical coordinates.","function":false},{"term":"dρ, dϕ","meaning":"Differentials of the spherical coordinates rho and phi.","function":false},{"term":"∫_{−∞}^{∞}","meaning":"An improper integral over the entire real line, from negative infinity to infinity.","function":true},{"term":"e^{−x²}","meaning":"The Gaussian function: takes x and returns e raised to minus x squared; its total area is found with polar coordinates.","function":true},{"term":"dx","meaning":"The differential indicating integration with respect to x.","function":false},{"term":"√π","meaning":"The square root of pi, the value of the Gaussian integral over the whole real line.","function":false}],"explanation":"Polar, cylindrical, and spherical coordinates simplify integrals over circles, cylinders, and balls. Changing coordinates requires the Jacobian factor: r for polar and cylindrical, ρ² sin φ for spherical, which accounts for how area and volume elements stretch. A classic payoff is the Gaussian integral: squaring it and switching to polar coordinates turns an impossible single integral into an easy one equal to √π.","origin":"Laplace evaluated the Gaussian integral in the 1780s; the polar-coordinates squaring trick is usually credited to Poisson.","implementations":[{"name":"scipy.integrate.dblquad","library":"SciPy","note":"Numerical double integral; polar integrand includes the r factor."},{"name":"sympy.integrate","library":"SymPy","note":"Symbolic integration, including in transformed coordinates."},{"name":"scipy.special.erf","library":"SciPy","note":"Error function, the antiderivative-based form of the Gaussian integral."}]},"V.8":{"spoken":[{"line":0,"text":"Vector F equals the vector P, Q, R."},{"line":1,"text":"The line integral over C of vector F dot d vector r equals the integral from a to b of vector F of vector r of t, dot vector r prime of t, d t."}],"terms":[{"term":"𝐅","meaning":"A vector field: takes a point in space and returns a vector, here with component functions P, Q and R.","function":true},{"term":"P, Q, R","meaning":"The component functions of F in the x, y and z directions, each a scalar function of position.","function":true},{"term":"∫_C","meaning":"The line integral along curve C: accumulates the tangential component of F along the path, such as work done.","function":true},{"term":"C","meaning":"The oriented curve along which the line integral is taken, parametrized by r(t).","function":false},{"term":"·","meaning":"The dot product, which picks out the component of F along the direction of motion.","function":true},{"term":"d𝐫","meaning":"The vector line element: an infinitesimal displacement along C, equal to r′(t) dt.","function":false},{"term":"𝐫(t)","meaning":"The parametrization of C: takes parameter t and returns the position vector on the curve.","function":true},{"term":"a, b","meaning":"The starting and ending parameter values of t along the curve.","function":false},{"term":"𝐅(𝐫(t))","meaning":"The vector field evaluated at the point r(t) on the curve.","function":true},{"term":"𝐫′(t)","meaning":"The derivative of the parametrization, the velocity or tangent vector to the curve at t.","function":true},{"term":"dt","meaning":"The differential of the parameter t, indicating the line integral is computed as an ordinary integral in t.","function":false}],"explanation":"A vector field assigns a vector to every point in space, such as a force or velocity. A line integral of a vector field along a curve C adds up the component of the field along the direction of motion, giving work done by a force or circulation of a flow. It is computed by parametrizing the curve as r(t) and integrating F(r(t))·r′(t) over the parameter interval.","origin":"","implementations":[{"name":"scipy.integrate.quad","library":"SciPy","note":"Numerically integrates the parametrized integrand F(r(t))·r′(t)."},{"name":"sympy.vector.ParametricIntegral","library":"SymPy","note":"Integrates a field over a parametrized curve or surface."}]},"V.9":{"spoken":[{"line":0,"text":"Vector F equals del phi."},{"line":1,"text":"The line integral over C of vector F dot d vector r equals phi of B minus phi of A."},{"line":2,"text":"2-D test: the partial derivative of P with respect to y equals the partial derivative of Q with respect to x."}],"terms":[{"term":"𝐅","meaning":"A conservative vector field, one that is the gradient of a scalar potential function.","function":true},{"term":"∇φ","meaning":"The gradient of the potential φ: takes the scalar function φ and returns its vector of partial derivatives, which equals F.","function":true},{"term":"φ","meaning":"The potential function: a scalar function whose gradient is F; its values at the endpoints give the line integral.","function":true},{"term":"∫_C","meaning":"The line integral along curve C, which for a conservative field depends only on the endpoints.","function":true},{"term":"C","meaning":"A curve running from point A to point B.","function":false},{"term":"d𝐫","meaning":"The vector line element, an infinitesimal displacement along C.","function":false},{"term":"A, B","meaning":"The starting point A and ending point B of the curve C.","function":false},{"term":"∂P/∂y","meaning":"The partial derivative of the x-component P with respect to y.","function":true},{"term":"∂Q/∂x","meaning":"The partial derivative of the y-component Q with respect to x; equality with ∂P/∂y tests a 2-D field for being conservative.","function":true},{"term":"P, Q","meaning":"The x and y component functions of a two-dimensional vector field F = (P, Q).","function":true}],"explanation":"A vector field is conservative when it is the gradient of a scalar potential φ. For such fields the line integral depends only on the endpoints, equalling φ(B) − φ(A), just as the Fundamental Theorem of Calculus does in one dimension; integrals around closed loops vanish. In two dimensions, on a simply connected region, a field (P, Q) is conservative exactly when ∂P/∂y = ∂Q/∂x.","origin":"","implementations":[{"name":"sympy.vector.is_conservative","library":"SymPy","note":"Checks whether a vector field has zero curl."},{"name":"sympy.vector.scalar_potential","library":"SymPy","note":"Finds a scalar potential function for a conservative field."}]},"V.10":{"spoken":[{"line":0,"text":"Del dot vector F equals the partial derivative of P with respect to x, plus the partial derivative of Q with respect to y, plus the partial derivative of R with respect to z."},{"line":1,"text":"Del cross vector F equals the vector R sub y minus Q sub z, P sub z minus R sub x, Q sub x minus P sub y."}],"terms":[{"term":"∇·𝐅","meaning":"The divergence: takes a vector field F and returns a scalar measuring net outflow (spreading) per unit volume at each point.","function":true},{"term":"∇","meaning":"The del operator, the vector of partial derivative operators, combined with F by dot or cross product.","function":true},{"term":"𝐅","meaning":"A vector field with components P, Q and R.","function":true},{"term":"P, Q, R","meaning":"The x, y and z component functions of the vector field F.","function":true},{"term":"∂P/∂x, ∂Q/∂y, ∂R/∂z","meaning":"Partial derivatives of each component in its own direction; their sum is the divergence.","function":true},{"term":"∇×𝐅","meaning":"The curl: takes a vector field F and returns a vector field measuring local rotation, its axis and strength.","function":true},{"term":"R_y, Q_z, P_z, R_x, Q_x, P_y","meaning":"Subscript notation for partial derivatives of the components, for example R_y is the partial of R with respect to y.","function":true}],"explanation":"Divergence and curl are the two basic derivatives of a vector field. Divergence, a scalar, measures net outflow per unit volume at a point: positive at sources, negative at sinks. Curl, a vector, measures local rotation, with its direction given by the right-hand rule and its size by the spin rate. They are built from the ∇ operator via dot and cross products.","origin":"Maxwell coined the term 'curl' in 1871; Gibbs and Heaviside formalized divergence and curl in vector notation in the 1880s.","implementations":[{"name":"sympy.vector.divergence","library":"SymPy","note":"Symbolic divergence of a vector field."},{"name":"sympy.vector.curl","library":"SymPy","note":"Symbolic curl of a vector field."},{"name":"divergence","library":"MATLAB","note":"Computes divergence of a vector field."},{"name":"curl","library":"MATLAB","note":"Computes curl and angular velocity of a vector field."}]},"V.11":{"spoken":[{"line":0,"text":"The closed line integral around C of P d x plus Q d y equals the double integral over D of the quantity the partial derivative of Q with respect to x minus the partial derivative of P with respect to y, d A."},{"line":1,"text":"Area equals one half times the closed line integral around C of the quantity x d y minus y d x."}],"terms":[{"term":"∮_C","meaning":"The closed line integral around curve C: accumulates a quantity around the full loop, taken counterclockwise.","function":true},{"term":"C","meaning":"The simple closed boundary curve of region D, oriented counterclockwise.","function":false},{"term":"P, Q","meaning":"The component functions of the vector field F = (P, Q) in the plane.","function":true},{"term":"dx, dy","meaning":"Differentials of x and y along the curve C.","function":false},{"term":"∬_D","meaning":"The double integral over the region D enclosed by C.","function":true},{"term":"D","meaning":"The plane region bounded by the closed curve C.","function":false},{"term":"∂Q/∂x − ∂P/∂y","meaning":"The scalar curl (circulation density) of the field (P, Q), integrated over D.","function":true},{"term":"dA","meaning":"The area element of region D, a tiny patch of area in the double integral.","function":false},{"term":"Area","meaning":"The area of region D, computed from a line integral around its boundary.","function":false},{"term":"x, y","meaning":"The coordinates of points along the boundary curve C.","function":false}],"explanation":"Green's theorem relates a line integral around a closed plane curve to a double integral over the region it encloses. The integrand ∂Q/∂x − ∂P/∂y is the two-dimensional curl, so circulation around the boundary equals total rotation inside, with counterclockwise orientation taken as positive. Choosing P and Q so the curl is 1 yields the area formula, the principle behind planimeters and the shoelace formula.","origin":"George Green published the theorem in his 1828 essay on electricity and magnetism.","implementations":[]},"V.12":{"spoken":[{"line":0,"text":"The surface integral over S of vector F dot vector n, d S, equals the triple integral over E of del dot vector F, d V."}],"terms":[{"term":"∬_S","meaning":"The surface integral over the closed surface S: here it computes the total flux of F out through S.","function":true},{"term":"S","meaning":"The closed boundary surface of the solid region E.","function":false},{"term":"𝐅","meaning":"A vector field, for example a fluid velocity field, whose flux is measured.","function":true},{"term":"·","meaning":"The dot product, picking out the component of F normal to the surface.","function":true},{"term":"𝐧","meaning":"The outward-pointing unit normal vector to the surface S.","function":false},{"term":"dS","meaning":"The surface area element on S, a tiny patch of the boundary surface through which flux passes.","function":false},{"term":"∭_E","meaning":"The triple integral over the solid region E enclosed by S.","function":true},{"term":"E","meaning":"The solid region bounded by the surface S.","function":false},{"term":"∇·𝐅","meaning":"The divergence of F: takes the vector field and returns the scalar source density at each point.","function":true},{"term":"dV","meaning":"The volume element of region E, a tiny piece of volume in the triple integral.","function":false}],"explanation":"Flux measures how much of a vector field passes through a surface. The divergence theorem says that the total flux outward through a closed surface S equals the integral of the divergence over the solid E it encloses. Intuitively, whatever flows out through the boundary must be produced by sources inside. It underlies conservation laws and Gauss's law in electromagnetism.","origin":"Stated by Lagrange (1762) and Gauss (1813); Mikhail Ostrogradsky gave the first general proof in 1826.","implementations":[]},"V.13":{"spoken":[{"line":0,"text":"The closed line integral around C of vector F dot d vector r equals the surface integral over S of the quantity del cross vector F, dot vector n, d S."}],"terms":[{"term":"∮_C","meaning":"The closed line integral around the boundary curve C: gives the circulation of F around C.","function":true},{"term":"C","meaning":"The closed boundary curve of surface S, oriented by the right-hand rule relative to n.","function":false},{"term":"𝐅","meaning":"A vector field in three-dimensional space whose circulation around C equals the flux of its curl through S.","function":true},{"term":"d𝐫","meaning":"The vector line element along the curve C.","function":false},{"term":"∬_S","meaning":"The surface integral over S, here of the normal component of the curl.","function":true},{"term":"S","meaning":"An oriented surface whose boundary is the curve C.","function":false},{"term":"∇×𝐅","meaning":"The curl of F: takes the vector field and returns a vector field measuring local rotation.","function":true},{"term":"𝐧","meaning":"The unit normal vector to S, oriented consistently with C by the right-hand rule.","function":false},{"term":"dS","meaning":"The surface area element on S, a tiny patch of the surface in the surface integral.","function":false},{"term":"·","meaning":"The dot product, taking tangential (for dr) or normal (for n) components.","function":true}],"explanation":"Stokes' theorem equates the circulation of a vector field around a closed curve C to the flux of its curl through any surface S bounded by that curve. Orientation follows the right-hand rule: curling the fingers along C points the thumb along the normal n. It generalizes Green's theorem to curved surfaces in three dimensions and is central to Maxwell's equations.","origin":"Lord Kelvin communicated the result to George Stokes in 1850, and Stokes set it as a Smith's Prize exam question in 1854.","implementations":[]},"V.14":{"spoken":[{"line":0,"text":"Del squared f equals f sub x x plus f sub y y plus f sub z z."},{"line":1,"text":"Heat: u sub t equals alpha times del squared u."},{"line":2,"text":"Wave: u sub t t equals c squared times del squared u."},{"line":3,"text":"Laplace: del squared u equals 0."}],"terms":[{"term":"∇²","meaning":"The Laplacian operator: takes a scalar function and returns the sum of its unmixed second partial derivatives, the divergence of the gradient.","function":true},{"term":"f","meaning":"A scalar function of x, y and z whose Laplacian is being defined.","function":true},{"term":"f_xx, f_yy, f_zz","meaning":"Second partial derivatives of f with respect to x, y and z respectively.","function":true},{"term":"u","meaning":"The unknown function in the PDEs, such as temperature or displacement, depending on position and time t.","function":true},{"term":"u_t","meaning":"The first partial derivative of u with respect to time; the rate of change in the heat equation.","function":true},{"term":"α","meaning":"Alpha: the thermal diffusivity constant controlling how fast heat spreads.","function":false},{"term":"u_tt","meaning":"The second partial derivative of u with respect to time; acceleration in the wave equation.","function":true},{"term":"c","meaning":"The wave speed constant; c squared multiplies the Laplacian in the wave equation.","function":false},{"term":"heat, wave, Laplace","meaning":"Names of the three classic PDEs: diffusion, wave propagation, and steady-state (equilibrium) equations.","function":false}],"explanation":"The Laplacian is the sum of a function's unmixed second partial derivatives, equal to the divergence of the gradient. It measures how a point's value compares to the average of its neighbors. It appears in the heat equation (diffusion smooths out differences), the wave equation (disturbances propagate at speed c), and Laplace's equation, whose solutions are harmonic functions describing steady states.","origin":"Laplace studied the equation in the 1780s; d'Alembert derived the wave equation in 1747 and Fourier the heat equation in the early 1800s.","implementations":[{"name":"scipy.ndimage.laplace","library":"SciPy","note":"Discrete Laplacian of an array using second-difference filters."},{"name":"sympy.vector.laplacian","library":"SymPy","note":"Symbolic Laplacian of a field in a coordinate system."},{"name":"del2","library":"MATLAB","note":"Discrete Laplacian of gridded data."},{"name":"Laplacian","library":"Mathematica","note":"Symbolic Laplacian of a function."}]},"C2.1":{"spoken":[{"line":0,"text":"The integral of u d v equals u v minus the integral of v d u."},{"line":1,"text":"The integral from a to b of u d v equals u v evaluated from a to b minus the integral from a to b of v d u."}],"terms":[{"term":"∫","meaning":"The integral operator: takes an integrand and returns its antiderivative, or with limits its accumulated value.","function":true},{"term":"u","meaning":"The part of the integrand chosen to be differentiated, often picked by the LIATE order.","function":true},{"term":"dv","meaning":"The remaining part of the integrand, chosen to be integrated to find v.","function":false},{"term":"v","meaning":"An antiderivative of dv: the function obtained by integrating the dv part of the original integrand.","function":true},{"term":"du","meaning":"The differential of u, equal to u′(x) dx.","function":false},{"term":"a, b","meaning":"Lower and upper limits of integration for the definite version.","function":false},{"term":"[uv]_a^b","meaning":"Evaluation notation: the product uv evaluated at b minus its value at a.","function":true}],"explanation":"Integration by parts is the product rule run backward: it trades the integral of u dv for uv minus the integral of v du. It helps when one factor gets simpler on differentiating and the other is easy to integrate, as in x eˣ or ln x. The definite version evaluates the uv term at the endpoints. The LIATE ordering is a heuristic for choosing u.","origin":"Brook Taylor is usually credited with first stating integration by parts, in 1715.","implementations":[{"name":"sympy.integrate","library":"SymPy","note":"Symbolic integration that applies by-parts reduction automatically."},{"name":"sympy.integrals.manualintegrate.manualintegrate","library":"SymPy","note":"Integrates using textbook rules such as integration by parts."}]},"C2.2":{"spoken":[{"line":0,"text":"Sine squared x equals the quantity 1 minus cosine of 2 x, all over 2; cosine squared x equals the quantity 1 plus cosine of 2 x, all over 2."},{"line":1,"text":"a squared minus x squared: x equals a sine theta."},{"line":2,"text":"a squared plus x squared: x equals a tangent theta."},{"line":3,"text":"x squared minus a squared: x equals a secant theta."}],"terms":[{"term":"sin²x","meaning":"The square of the sine of x; the power-reducing identity rewrites it using cos 2x so it can be integrated.","function":true},{"term":"x","meaning":"The variable of integration; in trig substitution it is replaced by a trig expression in θ.","function":false},{"term":"cos 2x","meaning":"The cosine of twice x, the double-angle term in the power-reducing identities.","function":true},{"term":"cos²x","meaning":"The square of the cosine of x, rewritten by the power-reducing identity as one plus cos 2x over 2.","function":true},{"term":"a","meaning":"A positive constant appearing in the expression under the square root.","function":false},{"term":"a² − x²","meaning":"An expression (usually under a square root) suggesting the substitution x = a sin θ.","function":false},{"term":"sin θ","meaning":"The sine function of θ; substituting x = a sin θ turns a² − x² into a² cos² θ.","function":true},{"term":"θ","meaning":"The new angle variable introduced by trigonometric substitution.","function":false},{"term":"tan θ","meaning":"The tangent function of θ; x = a tan θ turns a² + x² into a² sec² θ.","function":true},{"term":"sec θ","meaning":"The secant function, 1 over cos θ; x = a sec θ turns x² − a² into a² tan² θ.","function":true}],"explanation":"Trigonometric integrals use identities such as the half-angle formulas to reduce powers of sine and cosine to integrable forms. Trigonometric substitution handles square roots of quadratics: substituting x = a sin θ, a tan θ, or a sec θ turns a² − x², a² + x², or x² − a² into a perfect square via a Pythagorean identity, removing the root. Afterward, a reference triangle converts back to x.","origin":"","implementations":[{"name":"sympy.integrate","library":"SymPy","note":"Symbolic integration including trigonometric forms and radicals."},{"name":"sympy.trigsimp","library":"SymPy","note":"Simplifies expressions using trigonometric identities."}]},"C2.3":{"spoken":[{"line":0,"text":"The quantity p x plus q, all over the quantity x minus a times the quantity x minus b, equals A over the quantity x minus a, plus B over the quantity x minus b."},{"line":1,"text":"Repeated: A over the quantity x minus a, plus B over the quantity x minus a squared."}],"terms":[{"term":"p, q","meaning":"Constant coefficients of the linear numerator px + q of the rational function.","function":false},{"term":"x","meaning":"The variable of the rational function being decomposed for integration.","function":false},{"term":"a, b","meaning":"Distinct roots of the denominator, giving linear factors x − a and x − b.","function":false},{"term":"A, B","meaning":"Unknown constants of the partial fraction decomposition, found by matching numerators or plugging in roots.","function":false},{"term":"(x − a)²","meaning":"A repeated linear factor; it requires one term for each power, A over x − a and B over (x − a) squared.","function":false}],"explanation":"Partial fraction decomposition rewrites a rational function as a sum of simpler fractions whose denominators are factors of the original denominator. Each simple term integrates to a logarithm or an inverse tangent, so the method makes rational functions integrable. Distinct linear factors get one constant each, while a repeated factor (x − a)ᵏ needs a term for every power up to k.","origin":"Leibniz and Johann Bernoulli developed partial fractions for integrating rational functions around 1702.","implementations":[{"name":"sympy.apart","library":"SymPy","note":"Partial fraction decomposition of a rational expression."},{"name":"scipy.signal.residue","library":"SciPy","note":"Partial fraction expansion of a ratio of polynomials."},{"name":"partfrac","library":"MATLAB Symbolic Math Toolbox","note":"Partial fraction decomposition of a rational expression."},{"name":"Apart","library":"Mathematica","note":"Rewrites a rational expression as partial fractions."}]},"C2.4":{"spoken":[{"line":0,"text":"The integral from a to infinity of f of x, d x, equals the limit as b approaches infinity of the integral from a to b of f of x, d x."},{"line":1,"text":"The integral from 1 to infinity of d x over x to the p equals 1 over the quantity p minus 1, for p greater than 1."},{"line":2,"text":"Diverges if p is less than or equal to 1."}],"terms":[{"term":"∫_a^∞","meaning":"An improper integral with an infinite upper limit, defined as a limit of ordinary definite integrals.","function":true},{"term":"a","meaning":"The finite lower limit of integration where the improper integral starts.","function":false},{"term":"f(x)","meaning":"The integrand function being integrated over an unbounded interval.","function":true},{"term":"dx","meaning":"The differential indicating integration with respect to x.","function":false},{"term":"lim","meaning":"The limit operator: takes the definite integral as a function of b and returns its value as b grows without bound.","function":true},{"term":"b","meaning":"A finite upper limit that is sent to infinity.","function":false},{"term":"∞","meaning":"Infinity: indicates the interval of integration is unbounded.","function":false},{"term":"x^p","meaning":"x raised to the power p; the denominator of the p-integral.","function":true},{"term":"p","meaning":"The exponent in the p-test; the integral converges exactly when p is greater than 1.","function":false},{"term":"diverges","meaning":"The improper integral has no finite value; the limit is infinite or does not exist.","function":false}],"explanation":"An improper integral has an infinite limit of integration or an unbounded integrand, and is defined as a limit of ordinary definite integrals. If the limit is finite the integral converges; otherwise it diverges. The p-test is the key benchmark: the integral of 1/xᵖ from 1 to infinity converges to 1/(p − 1) exactly when p > 1, and comparison with it settles many other cases.","origin":"","implementations":[{"name":"scipy.integrate.quad","library":"SciPy","note":"Numerical integration that accepts infinite limits."},{"name":"sympy.integrate","library":"SymPy","note":"Symbolic integration over infinite intervals, using sympy.oo."}]},"C2.5":{"spoken":[{"line":0,"text":"A equals the integral from a to b of the quantity f of x minus g of x, d x."},{"line":1,"text":"f of x is greater than or equal to g of x on the interval a to b."}],"terms":[{"term":"A","meaning":"The area of the region between the two curves.","function":false},{"term":"∫_a^b","meaning":"The definite integral from a to b, summing the vertical strip heights times their widths.","function":true},{"term":"a, b","meaning":"The left and right x-values bounding the region, often where the curves intersect.","function":false},{"term":"f(x)","meaning":"The top curve: a function whose graph lies above or on g over the interval.","function":true},{"term":"g(x)","meaning":"The bottom curve: a function whose graph lies below or on f over the interval.","function":true},{"term":"dx","meaning":"The width of each thin vertical strip whose height is f(x) minus g(x).","function":false},{"term":"[a, b]","meaning":"The closed interval of x-values from a to b over which the area is computed.","function":false}],"explanation":"The area between two curves is the integral of the top function minus the bottom function over the interval where one stays above the other. Each thin vertical strip has height f(x) − g(x), and the integral sums the strips. If the curves cross, split the interval at the intersection points; for curves better described as functions of y, integrate right minus left instead.","origin":"","implementations":[{"name":"scipy.integrate.quad","library":"SciPy","note":"Numerically integrates f − g over an interval."},{"name":"sympy.integrate","library":"SymPy","note":"Symbolic definite integral of the difference of two functions."},{"name":"sympy.solve","library":"SymPy","note":"Finds intersection points to set the integration limits."}]},"C2.6":{"spoken":[{"line":0,"text":"Disk: V equals pi times the integral from a to b of R of x squared, d x."},{"line":1,"text":"Washer: V equals pi times the integral from a to b of the quantity R squared minus r squared, d x."},{"line":2,"text":"Shell: V equals 2 pi times the integral from a to b of x times h of x, d x."}],"terms":[{"term":"V","meaning":"The volume of the solid formed by revolving a region about an axis.","function":false},{"term":"π","meaning":"Pi; appears because each cross-section is a circle of area pi times radius squared.","function":false},{"term":"∫_a^b","meaning":"The definite integral from a to b, summing thin disks, washers or shells.","function":true},{"term":"R(x)","meaning":"The outer radius function: the distance from the axis of rotation to the outer edge at x.","function":true},{"term":"dx","meaning":"The thickness of each disk or washer, or of each shell.","function":false},{"term":"r","meaning":"The inner radius of the washer, the distance from the axis to the inner edge (the hole).","function":true},{"term":"x","meaning":"In the shell method, the radius of a shell: its distance from the axis of rotation (the y-axis).","function":false},{"term":"h(x)","meaning":"The height function of a cylindrical shell at radius x.","function":true}],"explanation":"Volumes of revolution are found by slicing a solid generated by rotating a region around an axis. Disks slice perpendicular to the axis, each a circle of area πR²; washers subtract an inner hole, giving π(R² − r²). Shells slice parallel to the axis, each a thin cylinder with lateral area 2πxh(x). The choice depends on which gives simpler integrals.","origin":"","implementations":[{"name":"scipy.integrate.quad","library":"SciPy","note":"Numerically evaluates the disk, washer, or shell integral."},{"name":"sympy.integrate","library":"SymPy","note":"Symbolic evaluation of volume integrals."}]},"C2.7":{"spoken":[{"line":0,"text":"L equals the integral from a to b of the square root of the quantity 1 plus f prime of x squared, d x."},{"line":1,"text":"L equals the integral from alpha to beta of the square root of the quantity d x d t squared plus d y d t squared, d t."}],"terms":[{"term":"L","meaning":"The arc length of the curve, the total distance measured along it.","function":false},{"term":"∫_a^b","meaning":"The definite integral over x from a to b, adding up tiny pieces of arc length.","function":true},{"term":"√","meaning":"The square root; the arc length element comes from the Pythagorean theorem on tiny right triangles.","function":true},{"term":"f′(x)","meaning":"The derivative of f, the slope of the curve y = f(x) at x.","function":true},{"term":"dx","meaning":"A small change in x along the curve.","function":false},{"term":"α, β","meaning":"Alpha and beta: the starting and ending values of the parameter t.","function":false},{"term":"dx/dt, dy/dt","meaning":"Derivatives of the parametric coordinate functions x(t) and y(t), the velocity components.","function":true},{"term":"dt","meaning":"The differential of the parameter t, the variable of integration for a parametric curve.","function":false}],"explanation":"Arc length measures the distance along a curve. Approximating the curve by tiny straight segments and applying the Pythagorean theorem to each gives √(dx² + dy²), which integrates to the formulas shown: one for a graph y = f(x), one for a parametric curve. The integrals often lack elementary antiderivatives, so they are frequently evaluated numerically.","origin":"","implementations":[{"name":"scipy.integrate.quad","library":"SciPy","note":"Numerically integrates the arc-length integrand."},{"name":"sympy.integrate","library":"SymPy","note":"Symbolic arc-length integral when an antiderivative exists."},{"name":"ArcLength","library":"Mathematica","note":"Computes the length of a curve or region."}]},"C2.8":{"spoken":[{"line":0,"text":"f average equals 1 over the quantity b minus a, times the integral from a to b of f of x, d x."},{"line":1,"text":"There exists c such that f of c equals f average."}],"terms":[{"term":"f_avg","meaning":"The average value of the function f over the interval from a to b.","function":false},{"term":"a, b","meaning":"The endpoints of the interval; b − a is its length.","function":false},{"term":"∫_a^b","meaning":"The definite integral, giving the total accumulated value of f over the interval.","function":true},{"term":"f(x)","meaning":"A continuous function whose average value is computed.","function":true},{"term":"dx","meaning":"The differential indicating integration with respect to x.","function":false},{"term":"∃","meaning":"There exists: asserts at least one value with the stated property, from the Mean Value Theorem for integrals.","function":false},{"term":"c","meaning":"A point in the interval where f takes exactly its average value.","function":false},{"term":"f(c)","meaning":"The value of f at the point c.","function":true}],"explanation":"The average value of a continuous function on [a, b] is its integral divided by the interval's length, the continuous analogue of summing values and dividing by their count. The Mean Value Theorem for integrals guarantees that a continuous function actually attains this average at some point c in the interval, so a rectangle of height f(c) has the same area as the region under the curve.","origin":"","implementations":[{"name":"scipy.integrate.quad","library":"SciPy","note":"Numerically integrates; divide by b − a for the average."},{"name":"numpy.mean","library":"NumPy","note":"Averages sampled values, approximating the continuous average."}]},"C2.9":{"spoken":[{"line":0,"text":"The limit as n approaches infinity of a sub n equals L."},{"line":1,"text":"r to the n approaches 0 if the absolute value of r is less than 1."},{"line":2,"text":"Bounded plus monotone implies convergent."}],"terms":[{"term":"lim","meaning":"The limit operator: takes the sequence a_n and returns the value its terms approach as n grows without bound.","function":true},{"term":"n","meaning":"The index of the sequence, a positive integer going to infinity.","function":false},{"term":"a_n","meaning":"The n-th term of the sequence; a function from positive integers to real numbers.","function":true},{"term":"L","meaning":"The limit of the sequence; the sequence converges to L.","function":false},{"term":"r^n","meaning":"A geometric sequence: r raised to the n-th power.","function":false},{"term":"r","meaning":"The common ratio of the geometric sequence r to the n, a fixed real number.","function":false},{"term":"|r|","meaning":"The absolute value of r; if less than 1, the powers of r shrink to zero.","function":true},{"term":"→","meaning":"Approaches: the terms get arbitrarily close to the given value.","function":false},{"term":"⇒","meaning":"Implies: the conditions on the left guarantee the conclusion on the right.","function":false},{"term":"bounded, monotone","meaning":"Bounded: all terms lie within fixed limits; monotone: the terms only increase or only decrease. Together they guarantee convergence.","function":false}],"explanation":"A sequence converges to L when its terms eventually stay arbitrarily close to L. Geometric sequences rⁿ shrink to zero when |r| < 1. The Monotone Convergence Theorem says any bounded, monotone sequence converges, which establishes limits without computing them. Comparing growth rates of logs, powers, exponentials, and factorials quickly settles limits of ratios.","origin":"","implementations":[{"name":"sympy.limit_seq","library":"SymPy","note":"Computes the limit of a sequence as n tends to infinity."},{"name":"sympy.limit","library":"SymPy","note":"Symbolic limit of an expression."}]},"C2.10":{"spoken":[{"line":0,"text":"S equals the sum from n equals 1 to infinity of a sub n, which equals the limit as capital N approaches infinity of S sub N."},{"line":1,"text":"The limit of a sub n not equal to 0 implies diverges."},{"line":2,"text":"The sum of 1 over n to the p converges if and only if p is greater than 1."},{"line":3,"text":"The sum from n equals 0 to infinity of a r to the n equals a over the quantity 1 minus r, when the absolute value of r is less than 1."}],"terms":[{"term":"S","meaning":"The sum of the infinite series, defined as the limit of its partial sums.","function":false},{"term":"Σ","meaning":"Summation: adds the terms a_n for every index n in the given range, here infinitely many.","function":true},{"term":"a_n","meaning":"The n-th term of the series, the quantity being added at index n.","function":false},{"term":"lim","meaning":"The limit operator, applied to partial sums S_N or to the terms a_n.","function":true},{"term":"N","meaning":"The number of terms in a partial sum.","function":false},{"term":"S_N","meaning":"The N-th partial sum, the sum of the first N terms of the series.","function":false},{"term":"≠","meaning":"Not equal; if the terms do not approach 0, the series diverges (the divergence test).","function":false},{"term":"1/n^p","meaning":"The general term of a p-series: one over n raised to the power p.","function":false},{"term":"p","meaning":"The exponent of the p-series; the series converges exactly when p is greater than 1.","function":false},{"term":"⟺","meaning":"If and only if: each condition implies the other.","function":false},{"term":"a","meaning":"The first term of the geometric series (in the last formula).","function":false},{"term":"r","meaning":"The common ratio of the geometric series; it converges when its absolute value is less than 1.","function":false},{"term":"|r|","meaning":"The absolute value of the ratio r: takes r and returns its size; must be less than 1 for convergence.","function":true}],"explanation":"An infinite series is defined as the limit of its partial sums S_N. If the terms do not tend to zero, the series diverges (the divergence test), though terms tending to zero alone do not guarantee convergence. Two benchmark families anchor comparisons: p-series converge exactly when p > 1, and geometric series converge to a/(1 − r) when |r| < 1.","origin":"Nicole Oresme proved the divergence of the harmonic series around 1350.","implementations":[{"name":"sympy.summation","library":"SymPy","note":"Symbolic evaluation of finite and infinite sums."},{"name":"sympy.Sum.is_convergent","library":"SymPy","note":"Tests whether an infinite series converges."},{"name":"mpmath.nsum","library":"mpmath","note":"Numerically sums infinite series with convergence acceleration."}]},"C2.11":{"spoken":[{"line":0,"text":"L equals the limit of the absolute value of a sub n plus 1 over a sub n, or the limit of the n-th root of the absolute value of a sub n."},{"line":1,"text":"L less than 1, converges. L greater than 1, diverges. L equals 1, inconclusive."},{"line":2,"text":"The sum of negative 1 to the n times b sub n: b sub n decreasing to 0 implies converges."},{"line":3,"text":"The absolute value of S minus S sub N is less than or equal to b sub N plus 1."}],"terms":[{"term":"L","meaning":"The limiting value computed by the ratio or root test, compared with 1 to decide convergence.","function":false},{"term":"lim","meaning":"The limit as n approaches infinity of the ratio or root expression.","function":true},{"term":"a_n, a_{n+1}","meaning":"Consecutive terms of the series; their ratio is used in the ratio test.","function":false},{"term":"|…|","meaning":"Absolute value, so the tests detect absolute convergence.","function":true},{"term":"ⁿ√","meaning":"The n-th root: in the root test, it takes the absolute value of a_n and returns its n-th root.","function":true},{"term":"conv., div.","meaning":"Abbreviations for converges and diverges; L = 1 gives no conclusion, shown by the question mark.","function":false},{"term":"Σ(−1)ⁿ b_n","meaning":"An alternating series, whose terms switch sign because of the factor negative one to the n.","function":true},{"term":"b_n","meaning":"The positive magnitudes of the alternating series' terms.","function":false},{"term":"↓ 0","meaning":"Decreases to zero: the terms b_n are decreasing and their limit is 0.","function":false},{"term":"S","meaning":"The true sum of the convergent alternating series.","function":false},{"term":"S_N","meaning":"The N-th partial sum, used to approximate S.","function":false},{"term":"b_{N+1}","meaning":"The first omitted term; it bounds the error of the partial sum S_N.","function":false}],"explanation":"The ratio and root tests compare a series to a geometric series by examining the limit L of |aₙ₊₁/aₙ| or the nth root of |aₙ|: L < 1 gives absolute convergence, L > 1 divergence, and L = 1 is inconclusive. The alternating series test states that terms of alternating sign shrinking monotonically to zero converge, with error after N terms bounded by the next term.","origin":"D'Alembert published the ratio test in 1768, Cauchy the root test in 1821, and Leibniz the alternating series test in the 1680s–90s.","implementations":[{"name":"sympy.Sum.is_convergent","library":"SymPy","note":"Tests series convergence using ratio, root, and other tests."}]},"C2.12":{"spoken":[{"line":0,"text":"The sum from n equals 0 to infinity of c sub n times the quantity x minus a to the n."},{"line":1,"text":"Converges for the absolute value of x minus a less than R."},{"line":2,"text":"R equals the limit of the absolute value of c sub n over c sub n plus 1."},{"line":3,"text":"1 over the quantity 1 minus x equals the sum from n equals 0 to infinity of x to the n, for the absolute value of x less than 1."}],"terms":[{"term":"Σ","meaning":"Summation over n from 0 to infinity, building the power series as a function of x.","function":true},{"term":"c_n","meaning":"The coefficients of the power series, one for each power of (x − a).","function":false},{"term":"x","meaning":"The variable of the power series; the series defines a function of x where it converges.","function":false},{"term":"a","meaning":"The center of the power series, the point around which it is expanded.","function":false},{"term":"(x − a)ⁿ","meaning":"The n-th power of the distance from the center, the basis terms of the power series.","function":false},{"term":"|x − a|","meaning":"The distance from x to the center a.","function":true},{"term":"R","meaning":"The radius of convergence: the series converges when x is within distance R of the center.","function":false},{"term":"lim","meaning":"The limit as n approaches infinity of the coefficient ratio, which gives R.","function":true},{"term":"c_{n+1}","meaning":"The next coefficient after c_n, used in the ratio formula for R.","function":false},{"term":"1/(1 − x)","meaning":"The function represented by the geometric series in x, valid for absolute value of x less than 1.","function":true},{"term":"xⁿ","meaning":"The n-th power of x, the terms of the geometric series.","function":false}],"explanation":"A power series is an infinite polynomial in (x − a). It converges absolutely inside an interval of radius R around its center and diverges outside it; the endpoints must be checked separately. The radius can be found with the ratio test, giving R as the limit of |cₙ/cₙ₊₁|. The geometric series 1/(1 − x) is the prototype, from which many other series are derived.","origin":"Cauchy gave the root-based radius formula in 1821, and Hadamard rediscovered and popularized it in 1888 (the Cauchy–Hadamard theorem).","implementations":[{"name":"sympy.series","library":"SymPy","note":"Power series expansion of an expression about a point."},{"name":"sympy.fps","library":"SymPy","note":"Computes a formal power series with a general term."},{"name":"numpy.polynomial.Polynomial","library":"NumPy","note":"Represents truncated power series as polynomial coefficient arrays."}]},"C2.13":{"spoken":[{"line":0,"text":"f of x equals the sum from n equals 0 to infinity of the n-th derivative of f at a, over n factorial, times the quantity x minus a to the n."},{"line":1,"text":"e to the x equals the sum of x to the n over n factorial; sine x equals the sum of negative 1 to the n times x to the 2 n plus 1, all over the quantity 2 n plus 1 factorial."},{"line":2,"text":"The absolute value of R sub n is less than or equal to M times the absolute value of x minus a to the n plus 1, all over the quantity n plus 1 factorial."}],"terms":[{"term":"f(x)","meaning":"The function being represented by its Taylor series.","function":true},{"term":"Σ","meaning":"Summation over n, adding infinitely many polynomial terms.","function":true},{"term":"f⁽ⁿ⁾(a)","meaning":"The n-th derivative of f evaluated at the center a, giving the coefficients of the series.","function":true},{"term":"a","meaning":"The center of the Taylor series; a Maclaurin series has a = 0.","function":false},{"term":"n!","meaning":"n factorial, the product 1 times 2 times up to n; divides each coefficient.","function":true},{"term":"(x − a)ⁿ","meaning":"The n-th power of the distance from the center.","function":false},{"term":"eˣ","meaning":"The exponential function: its Maclaurin series uses all powers of x divided by n factorial.","function":true},{"term":"sin x","meaning":"The sine function: its Maclaurin series uses only odd powers with alternating signs.","function":true},{"term":"(−1)ⁿ","meaning":"Negative one to the n, which makes the signs of the sine series alternate.","function":false},{"term":"R_n","meaning":"The remainder: the error between f(x) and its n-th degree Taylor polynomial.","function":true},{"term":"M","meaning":"An upper bound on the absolute value of the (n + 1)-th derivative of f between a and x.","function":false}],"explanation":"A Taylor series represents a smooth function as a power series built from its derivatives at a point a; a Maclaurin series is the special case a = 0. Truncating after n terms gives a polynomial approximation, and Taylor's remainder bound limits the error using a bound M on the next derivative. The expansions of eˣ, sin x, and cos x are the most frequently used examples.","origin":"Brook Taylor published the general series in 1715 and Colin Maclaurin popularized the a = 0 case in 1742; Madhava and James Gregory found special cases earlier.","implementations":[{"name":"sympy.series","library":"SymPy","note":"Taylor expansion of an expression to a given order."},{"name":"scipy.interpolate.approximate_taylor_polynomial","library":"SciPy","note":"Numerically estimates a Taylor polynomial of a function."},{"name":"taylor","library":"MATLAB Symbolic Math Toolbox","note":"Taylor series expansion of a symbolic expression."},{"name":"Series","library":"Mathematica","note":"Power series expansion about a point."}]},"C2.14":{"spoken":[{"line":0,"text":"x equals f of t, y equals g of t."},{"line":1,"text":"d y d x equals d y d t over d x d t."},{"line":2,"text":"The second derivative of y with respect to x equals d d t of d y d x, all over d x d t."}],"terms":[{"term":"x, y","meaning":"The coordinates of a point on the curve, each given as a function of the parameter t.","function":false},{"term":"f(t)","meaning":"The function giving the x-coordinate in terms of t.","function":true},{"term":"g(t)","meaning":"The function giving the y-coordinate in terms of t.","function":true},{"term":"t","meaning":"The parameter, often thought of as time, that traces out the curve.","function":false},{"term":"dy/dx","meaning":"The slope of the parametric curve, the ratio of the rates of change of y and x.","function":true},{"term":"dy/dt, dx/dt","meaning":"Derivatives of y and x with respect to the parameter t.","function":true},{"term":"d²y/dx²","meaning":"The second derivative of y with respect to x, describing concavity of the parametric curve.","function":true},{"term":"d/dt","meaning":"The derivative operator with respect to t, here applied to the slope dy/dx.","function":true}],"explanation":"Parametric equations describe a curve by giving x and y as functions of a parameter t, which can represent motion over time and trace curves that are not graphs of functions. The slope dy/dx is the ratio of the rates dy/dt and dx/dt, by the chain rule. The second derivative differentiates that slope with respect to t and divides again by dx/dt.","origin":"","implementations":[{"name":"sympy.diff","library":"SymPy","note":"Differentiates x(t) and y(t) to form dy/dx."},{"name":"matplotlib.pyplot.plot","library":"Matplotlib","note":"Plots parametric curves from arrays of x(t), y(t)."}]},"C2.15":{"spoken":[{"line":0,"text":"A equals one half times the integral from alpha to beta of r squared, d theta."},{"line":1,"text":"d y d x equals the quantity d r d theta sine theta plus r cosine theta, all over the quantity d r d theta cosine theta minus r sine theta."}],"terms":[{"term":"A","meaning":"The area enclosed by the polar curve between the angles alpha and beta.","function":false},{"term":"∫_α^β","meaning":"The definite integral over the angle θ from alpha to beta, summing thin pizza-slice sectors.","function":true},{"term":"α, β","meaning":"Alpha and beta: the starting and ending angles of the region.","function":false},{"term":"r","meaning":"The polar radius, a function r(θ) giving distance from the origin at angle θ.","function":true},{"term":"dθ","meaning":"The small angle of each thin pizza-slice sector being summed in the area integral.","function":false},{"term":"θ","meaning":"The polar angle, measured from the positive x-axis, that serves as the curve's parameter.","function":false},{"term":"dy/dx","meaning":"The slope of the tangent line to the polar curve in Cartesian terms.","function":true},{"term":"dr/dθ","meaning":"The derivative of the radius with respect to the angle.","function":true},{"term":"sin θ, cos θ","meaning":"Sine and cosine of the angle, from x = r cos θ and y = r sin θ.","function":true}],"explanation":"In polar coordinates a region swept by r = f(θ) is filled with thin circular sectors, each with area ½r² dθ, so the total area is half the integral of r². For slopes, write x = r cos θ and y = r sin θ and treat θ as a parameter; the parametric derivative formula then gives dy/dx in terms of r and dr/dθ.","origin":"","implementations":[{"name":"scipy.integrate.quad","library":"SciPy","note":"Numerically integrates ½r(θ)² over an angle interval."},{"name":"sympy.integrate","library":"SymPy","note":"Symbolic polar area integral."},{"name":"matplotlib.pyplot.polar","library":"Matplotlib","note":"Plots curves in polar coordinates."}]},"C2.16":{"spoken":[{"line":0,"text":"d y d x equals g of x times h of y, implies the integral of d y over h of y equals the integral of g of x, d x."},{"line":1,"text":"d y d t equals k y, implies y equals y sub 0 times e to the k t."},{"line":2,"text":"d P d t equals r P times the quantity 1 minus P over K, implies P equals K over the quantity 1 plus A e to the negative r t."}],"terms":[{"term":"dy/dx","meaning":"The derivative of the unknown function y with respect to x, given by the differential equation.","function":true},{"term":"g(x)","meaning":"The factor of the right side depending only on x.","function":true},{"term":"h(y)","meaning":"The factor of the right side depending only on y; separation divides it to the dy side.","function":true},{"term":"⇒","meaning":"Implies: the differential equation leads to the integrated form or solution.","function":false},{"term":"∫","meaning":"Integration, applied to both sides after separating variables.","function":true},{"term":"dy/dt","meaning":"The rate of change of y with respect to time t.","function":true},{"term":"k","meaning":"The growth (k > 0) or decay (k < 0) rate constant.","function":false},{"term":"y","meaning":"The unknown quantity that is growing or decaying, a function of time t.","function":true},{"term":"y₀","meaning":"The initial value of y at time t = 0.","function":false},{"term":"e^{kt}","meaning":"The exponential function of kt, solving exponential growth or decay.","function":true},{"term":"P","meaning":"The population, a function of time t in the logistic model.","function":true},{"term":"dP/dt","meaning":"The rate of change of the population P with respect to time t.","function":true},{"term":"r","meaning":"The intrinsic growth rate of the population when it is small compared with K.","function":false},{"term":"K","meaning":"The carrying capacity, the limiting population size that P approaches over time.","function":false},{"term":"A","meaning":"A constant determined by the initial population, equal to K minus P sub 0, over P sub 0.","function":false},{"term":"e^{−rt}","meaning":"A decaying exponential that shrinks to zero, so P approaches K over time.","function":true}],"explanation":"A separable differential equation has the form dy/dx = g(x)h(y), so the variables can be moved to opposite sides and each side integrated. Exponential growth dy/dt = ky, where the rate is proportional to the amount, gives y = y₀eᵏᵗ. The logistic equation adds a carrying capacity K that slows growth as P approaches K, producing an S-shaped curve.","origin":"Malthus described exponential population growth in 1798; Pierre-François Verhulst introduced the logistic equation in 1838.","implementations":[{"name":"sympy.dsolve","library":"SymPy","note":"Symbolically solves ordinary differential equations."},{"name":"scipy.integrate.solve_ivp","library":"SciPy","note":"Numerically solves initial value problems for ODEs."},{"name":"DSolve","library":"Mathematica","note":"Symbolically solves differential equations."}]},"C2.17":{"spoken":[{"line":0,"text":"y sub n plus 1 equals y sub n plus h times f of t sub n comma y sub n."},{"line":1,"text":"t sub n plus 1 equals t sub n plus h."},{"line":2,"text":"Global error big O of h."}],"terms":[{"term":"y_{n+1}","meaning":"The next approximate solution value after one Euler step.","function":false},{"term":"y_n","meaning":"The current approximate solution value at step n.","function":false},{"term":"h","meaning":"The step size: how far t advances in each Euler step.","function":false},{"term":"f(t, y)","meaning":"The slope function of the differential equation dy/dt = f(t, y); takes a time and value and returns the slope.","function":true},{"term":"t_n","meaning":"The current time value at step n of Euler's method.","function":false},{"term":"t_{n+1}","meaning":"The next time value, one step of size h later.","function":false},{"term":"O(h)","meaning":"Big O of h: the global error shrinks proportionally to the step size h (first order).","function":true}],"explanation":"Euler's method numerically solves an initial value problem y′ = f(t, y) by stepping along tangent lines. Each step uses the current slope f(tₙ, yₙ) to advance the solution by a step size h. It is simple but only first-order accurate: halving h roughly halves the global error. More accurate methods such as Runge–Kutta refine the same idea.","origin":"Leonhard Euler described the method in his Institutionum calculi integralis (1768).","implementations":[{"name":"scipy.integrate.solve_ivp","library":"SciPy","note":"ODE solver; uses higher-order Runge–Kutta methods by default."},{"name":"ode45","library":"MATLAB","note":"Runge–Kutta ODE solver, a refinement of Euler-style stepping."}]},"C2.18":{"spoken":[{"line":0,"text":"T equals h over 2 times the quantity f sub 0 plus 2 f sub 1 plus dot dot dot plus 2 f sub n minus 1 plus f sub n."},{"line":1,"text":"S equals h over 3 times the quantity f sub 0 plus 4 f sub 1 plus 2 f sub 2 plus dot dot dot plus 4 f sub n minus 1 plus f sub n."},{"line":2,"text":"Errors big O of h squared, big O of h to the fourth."}],"terms":[{"term":"T","meaning":"The trapezoid rule approximation of the definite integral.","function":false},{"term":"h","meaning":"The width of each subinterval, the step size (b − a)/n.","function":false},{"term":"f_i","meaning":"Shorthand for f(x_i), the function value at the i-th equally spaced grid point; f_0 and f_n are the endpoints.","function":false},{"term":"⋯","meaning":"Ellipsis: the pattern of weighted terms continues through the interior points.","function":false},{"term":"n","meaning":"The number of subintervals; it must be even for Simpson's rule.","function":false},{"term":"S","meaning":"The Simpson's rule approximation, using parabolas with weights 1, 4, 2, 4, ..., 4, 1.","function":false},{"term":"O(h²), O(h⁴)","meaning":"Big O error orders: the trapezoid error shrinks like h squared, Simpson's like h to the fourth.","function":true}],"explanation":"The trapezoid and Simpson's rules approximate a definite integral from sampled values with spacing h. The trapezoid rule connects samples with straight lines; Simpson's rule fits parabolas through consecutive triples of points, giving the 1, 4, 2, 4, …, 4, 1 weights and requiring an even number of intervals. Simpson's error shrinks like h⁴, much faster than the trapezoid's h².","origin":"Named for Thomas Simpson (1743), though the parabolic rule was known earlier to Cavalieri and James Gregory.","implementations":[{"name":"scipy.integrate.trapezoid","library":"SciPy","note":"Integrates sampled data using the composite trapezoid rule."},{"name":"scipy.integrate.simpson","library":"SciPy","note":"Integrates sampled data using composite Simpson's rule."},{"name":"numpy.trapezoid","library":"NumPy","note":"Composite trapezoid rule on sampled data (NumPy 2.0+)."},{"name":"trapz","library":"MATLAB","note":"Trapezoidal numerical integration of sampled data."}]},"C1.1":{"spoken":[{"line":0,"text":"The limit as x approaches a of f of x equals L."},{"line":1,"text":"The limit of the quantity f plus or minus g equals the limit of f plus or minus the limit of g; the limit of f over g equals the limit of f over the limit of g."},{"line":2,"text":"The limit as x approaches a of f exists if and only if the limit as x approaches a from the left of f equals the limit as x approaches a from the right of f."}],"terms":[{"term":"lim","meaning":"The limit operator: takes a function and a point a, and returns the value f(x) approaches as x gets close to a.","function":true},{"term":"x","meaning":"The input variable of f, which approaches the point a.","function":false},{"term":"a","meaning":"The point that x approaches; f need not be defined there.","function":false},{"term":"f(x)","meaning":"The function whose limiting behavior is being studied.","function":true},{"term":"L","meaning":"The limit value: the number that f(x) gets arbitrarily close to as x approaches a.","function":false},{"term":"f, g","meaning":"Two functions with limits at a; the limit laws combine their limits (the quotient law needs lim g nonzero).","function":true},{"term":"±","meaning":"Plus or minus: the law holds for both sum and difference.","function":false},{"term":"⟺","meaning":"If and only if: the two-sided limit exists exactly when the one-sided limits agree.","function":false},{"term":"x → a⁻","meaning":"x approaches a from the left, through values less than a: the left-hand limit.","function":false},{"term":"x → a⁺","meaning":"x approaches a from the right, through values greater than a: the right-hand limit.","function":false}],"explanation":"The limit of f(x) as x approaches a is the value L that f(x) gets arbitrarily close to as x nears a, regardless of f's value at a itself. The limit laws let limits of sums, products, and quotients be computed from limits of the pieces, provided they exist and denominators are nonzero. A two-sided limit exists exactly when both one-sided limits exist and agree.","origin":"Cauchy put limits at the foundation of calculus in 1821; Weierstrass gave the modern epsilon–delta definition in the mid-1800s.","implementations":[{"name":"sympy.limit","library":"SymPy","note":"Symbolic limit, optionally one-sided via the dir argument."},{"name":"Limit","library":"Mathematica","note":"Computes limits of expressions symbolically."},{"name":"limit","library":"MATLAB Symbolic Math Toolbox","note":"Symbolic limit of an expression."}]},"C1.2":{"spoken":[{"line":0,"text":"The limit as x approaches 0 of sine x over x equals 1; the limit as x approaches 0 of the quantity e to the x minus 1, all over x, equals 1."},{"line":1,"text":"The limit as n approaches infinity of the quantity 1 plus 1 over n, to the n, equals e; the limit as n approaches infinity of the quantity 1 plus r over n, to the n, equals e to the r."}],"terms":[{"term":"lim","meaning":"The limit operator, returning the value an expression approaches as x goes to 0 or n goes to infinity.","function":true},{"term":"x","meaning":"A real variable approaching 0 in the two special limits.","function":false},{"term":"sin x","meaning":"The sine function of x, measured in radians.","function":true},{"term":"eˣ","meaning":"The natural exponential function: takes x and returns e raised to x.","function":true},{"term":"n","meaning":"A variable growing without bound, such as the number of compounding periods.","function":false},{"term":"e","meaning":"Euler's number, about 2.71828, the base of the natural exponential.","function":false},{"term":"r","meaning":"A fixed real number, such as an interest rate compounded continuously.","function":false},{"term":"eʳ","meaning":"e raised to the r, the limit of compound growth at rate r.","function":true}],"explanation":"These standard limits underpin derivative rules. The limit of sin x / x equals 1, which gives the derivative of sine; the limit of (eˣ − 1)/x equals 1, which makes eˣ its own derivative. The compound-interest limit (1 + 1/n)ⁿ defines e, and more generally (1 + r/n)ⁿ tends to eʳ, describing continuous compounding.","origin":"Jacob Bernoulli studied the compound-interest limit in 1683; Euler named the constant e and computed it in the 1730s–40s.","implementations":[{"name":"sympy.limit","library":"SymPy","note":"Evaluates these limits symbolically."},{"name":"math.e","library":"Python standard library","note":"The constant e as a float."},{"name":"numpy.sinc","library":"NumPy","note":"Normalized sinc function sin(πx)/(πx), equal to 1 at 0."}]},"C1.3":{"spoken":[{"line":0,"text":"f continuous at a if and only if the limit as x approaches a of f of x equals f of a."},{"line":1,"text":"IVT: N between f of a and f of b implies there exists c such that f of c equals N."}],"terms":[{"term":"f","meaning":"A function; in the IVT it is continuous on the closed interval from a to b.","function":true},{"term":"a","meaning":"The point at which continuity is tested; in the IVT, the left endpoint of the interval.","function":false},{"term":"⟺","meaning":"If and only if: continuity is equivalent to the limit equaling the function value.","function":false},{"term":"lim","meaning":"The limit of f(x) as x approaches a.","function":true},{"term":"f(a)","meaning":"The value of the function at a, which must exist and equal the limit.","function":true},{"term":"IVT","meaning":"The Intermediate Value Theorem: a continuous function takes every value between f(a) and f(b).","function":false},{"term":"N","meaning":"Any intermediate value lying between f(a) and f(b).","function":false},{"term":"b","meaning":"The right endpoint of the interval on which f is continuous.","function":false},{"term":"∃","meaning":"There exists: guarantees at least one such c.","function":false},{"term":"c","meaning":"A point between a and b where f takes the value N.","function":false}],"explanation":"A function is continuous at a point when its limit there exists and equals its value, so its graph has no break. The Intermediate Value Theorem states that a function continuous on [a, b] takes every value N between f(a) and f(b) somewhere in the interval. This guarantees roots exist when f changes sign, which is the basis of the bisection method.","origin":"Bernard Bolzano proved the Intermediate Value Theorem in 1817.","implementations":[{"name":"scipy.optimize.bisect","library":"SciPy","note":"Finds a root on a sign-changing interval by bisection."},{"name":"scipy.optimize.brentq","library":"SciPy","note":"Fast bracketed root finding on a sign-changing interval."},{"name":"sympy.calculus.util.continuous_domain","library":"SymPy","note":"Finds the domain where an expression is continuous."}]},"C1.4":{"spoken":[{"line":0,"text":"f prime of x equals the limit as h approaches 0 of the quantity f of x plus h minus f of x, all over h."},{"line":1,"text":"d y d x."}],"terms":[{"term":"f′(x)","meaning":"The derivative of f: takes the function and returns the instantaneous rate of change, the slope of the tangent at x.","function":true},{"term":"f","meaning":"The function being differentiated; it takes an input x and returns f(x).","function":true},{"term":"lim","meaning":"The limit as h approaches 0 of the difference quotient.","function":true},{"term":"h","meaning":"A small change in x, the width of the secant line that shrinks to 0.","function":false},{"term":"x","meaning":"The input point at which the derivative is computed.","function":false},{"term":"dy/dx","meaning":"Leibniz notation for the derivative of y = f(x) with respect to x.","function":true}],"explanation":"The derivative of f at x is the limit of the difference quotient, the slope of secant lines through nearby points, as the gap h shrinks to zero. Geometrically it is the slope of the tangent line; physically it is an instantaneous rate of change, such as velocity. Leibniz's notation dy/dx expresses the same idea as a ratio of infinitesimal changes.","origin":"Newton and Leibniz developed the derivative independently in the 1660s–1680s; Leibniz introduced dy/dx and Lagrange the prime notation.","implementations":[{"name":"sympy.diff","library":"SymPy","note":"Symbolic derivative of an expression."},{"name":"numpy.gradient","library":"NumPy","note":"Finite-difference derivative of sampled data."},{"name":"jax.grad","library":"JAX","note":"Exact derivative via automatic differentiation."}]},"C1.5":{"spoken":[{"line":0,"text":"d d x of c equals 0; d d x of x to the n equals n x to the n minus 1."},{"line":1,"text":"The quantity c f, prime, equals c f prime; the quantity f plus or minus g, prime, equals f prime plus or minus g prime."}],"terms":[{"term":"d/dx","meaning":"The derivative operator: takes a function of x and returns its derivative with respect to x.","function":true},{"term":"c","meaning":"A constant; its derivative is 0, and it factors out of a derivative.","function":false},{"term":"xⁿ","meaning":"x raised to the power n, differentiated by the power rule.","function":true},{"term":"n","meaning":"A real exponent; the power rule brings it down and lowers the power by one.","function":false},{"term":"f, g","meaning":"Differentiable functions of x to which the constant multiple and sum rules apply.","function":true},{"term":"′","meaning":"Prime: denotes the derivative of the function or expression it is attached to.","function":true},{"term":"±","meaning":"Plus or minus: the derivative of a sum or difference is the sum or difference of derivatives.","function":false}],"explanation":"These are the basic differentiation rules. A constant has derivative zero, and the power rule says the derivative of xⁿ is n xⁿ⁻¹, valid for any real exponent. Differentiation is linear: constants factor out and derivatives of sums or differences are sums or differences of derivatives. Together these rules differentiate any polynomial term by term.","origin":"","implementations":[{"name":"sympy.diff","library":"SymPy","note":"Symbolic derivative applying these rules."},{"name":"numpy.polyder","library":"NumPy","note":"Derivative of a polynomial given by its coefficients."},{"name":"numpy.polynomial.Polynomial.deriv","library":"NumPy","note":"Derivative of a polynomial object."}]},"C1.6":{"spoken":[{"line":0,"text":"The quantity f g, prime, equals f prime g plus f g prime."},{"line":1,"text":"The quantity f over g, prime, equals the quantity f prime g minus f g prime, all over g squared."}],"terms":[{"term":"f, g","meaning":"Differentiable functions of x being multiplied or divided.","function":true},{"term":"′","meaning":"Prime: denotes taking the derivative of the expression it is attached to.","function":true},{"term":"f′, g′","meaning":"The derivatives of f and g, their rates of change with respect to x.","function":true},{"term":"f/g","meaning":"The quotient of f and g, defined where g is nonzero.","function":true},{"term":"g²","meaning":"g squared, the denominator in the quotient rule.","function":false}],"explanation":"The product rule differentiates a product as the first factor's derivative times the second plus the first times the second's derivative. The quotient rule handles f/g, giving (f′g − fg′)/g² wherever g is nonzero; the order in the numerator matters. Both follow from the limit definition, and the quotient rule can also be derived from the product and chain rules.","origin":"Leibniz stated the product rule in the 1670s.","implementations":[{"name":"sympy.diff","library":"SymPy","note":"Symbolic derivative applying the product and quotient rules."}]},"C1.7":{"spoken":[{"line":0,"text":"d d x of f of g of x equals f prime of g of x times g prime of x."},{"line":1,"text":"d y d x equals d y d u times d u d x."}],"terms":[{"term":"d/dx","meaning":"The derivative operator: takes a function of x and returns its derivative with respect to x.","function":true},{"term":"f","meaning":"The outer function, applied to the output of g.","function":true},{"term":"g(x)","meaning":"The inner function, whose output is fed into f.","function":true},{"term":"f′(g(x))","meaning":"The derivative of the outer function, evaluated at the inner function.","function":true},{"term":"g′(x)","meaning":"The derivative of the inner function g, the derivative of the inside.","function":true},{"term":"dy/dx","meaning":"The derivative of y with respect to x through the intermediate variable u.","function":true},{"term":"dy/du","meaning":"The derivative of y with respect to the intermediate variable u (outer derivative).","function":true},{"term":"du/dx","meaning":"The derivative of u = g(x) with respect to x (inner derivative).","function":true}],"explanation":"The chain rule differentiates a composition f(g(x)): take the outer function's derivative evaluated at the inner function, then multiply by the inner function's derivative. In Leibniz notation it reads as a cancellation of du terms. It is one of the most frequently used rules in calculus and the core of backpropagation in machine learning.","origin":"Leibniz used the chain rule in the 1670s.","implementations":[{"name":"sympy.diff","library":"SymPy","note":"Symbolic derivative of composite expressions."},{"name":"jax.grad","library":"JAX","note":"Autodiff that applies the chain rule through compositions."},{"name":"torch.autograd.grad","library":"PyTorch","note":"Reverse-mode autodiff through composed operations."}]},"C1.8":{"spoken":[{"line":0,"text":"The derivative of sine x equals cosine x; the derivative of cosine x equals negative sine x; the derivative of tangent x equals secant squared x."},{"line":1,"text":"The derivative of e to the x equals e to the x; the derivative of a to the x equals a to the x times the natural log of a; the derivative of the natural log of x equals 1 over x."},{"line":2,"text":"The derivative of arctangent x equals 1 over the quantity 1 plus x squared."}],"terms":[{"term":"sin x","meaning":"The sine function; its derivative is cos x.","function":true},{"term":"′","meaning":"Prime: takes the function in parentheses and returns its derivative with respect to x.","function":true},{"term":"cos x","meaning":"The cosine function; its derivative is negative sin x.","function":true},{"term":"tan x","meaning":"The tangent function, sin x over cos x; its derivative is sec squared x.","function":true},{"term":"sec²x","meaning":"The square of the secant function, 1 over cos squared x.","function":true},{"term":"eˣ","meaning":"The natural exponential function, which is its own derivative.","function":true},{"term":"aˣ","meaning":"An exponential function with positive base a; its derivative is a to the x times ln a.","function":true},{"term":"a","meaning":"A positive constant base, not equal to 1.","function":false},{"term":"ln","meaning":"The natural logarithm, log base e; its derivative is 1 over x.","function":true},{"term":"arctan x","meaning":"The inverse tangent function: takes x and returns the angle whose tangent is x.","function":true}],"explanation":"These are the derivatives of the standard transcendental functions. Sine and cosine differentiate into each other with a sign change, and tangent gives sec² x. The exponential eˣ is its own derivative, aˣ picks up a factor ln a, and ln x has derivative 1/x. The arctangent derivative 1/(1 + x²) shows inverse trig functions can have algebraic derivatives.","origin":"","implementations":[{"name":"sympy.diff","library":"SymPy","note":"Symbolic derivatives of elementary functions."},{"name":"D","library":"Mathematica","note":"Symbolic differentiation of expressions."}]},"C1.9":{"spoken":[{"line":0,"text":"d d x of y to the n equals n y to the n minus 1 times d y d x."},{"line":1,"text":"Differentiate both sides, solve for d y d x."}],"terms":[{"term":"d/dx","meaning":"The derivative operator with respect to x, applied to both sides of the equation.","function":true},{"term":"y","meaning":"A function of x defined implicitly by an equation, not solved explicitly.","function":true},{"term":"n","meaning":"The exponent on y, a real constant brought down by the power rule.","function":false},{"term":"yⁿ","meaning":"y raised to the power n; differentiated by the power rule with the chain rule.","function":true},{"term":"dy/dx","meaning":"The derivative of y with respect to x; the chain rule factor and the quantity solved for.","function":true}],"explanation":"Implicit differentiation finds dy/dx when y is defined by an equation relating x and y rather than given explicitly. Differentiate both sides with respect to x, treating y as a function of x, so the chain rule attaches a dy/dx factor to every y term. Then solve the resulting equation algebraically for dy/dx.","origin":"","implementations":[{"name":"sympy.idiff","library":"SymPy","note":"Computes dy/dx implicitly from an equation equal to zero."}]},"C1.10":{"spoken":[{"line":0,"text":"d d t of the relation."},{"line":1,"text":"For example, A equals pi r squared, implies d A d t equals 2 pi r d r d t."}],"terms":[{"term":"d/dt","meaning":"The derivative operator with respect to time, applied to both sides of an equation relating quantities.","function":true},{"term":"relation","meaning":"An equation linking the changing quantities, such as an area formula.","function":false},{"term":"A","meaning":"The area of a circle, changing with time.","function":true},{"term":"π","meaning":"Pi, the constant ratio of circumference to diameter.","function":false},{"term":"r","meaning":"The radius of the circle, a function of time.","function":true},{"term":"⇒","meaning":"Implies: differentiating the relation gives the related rates equation.","function":false},{"term":"dA/dt","meaning":"The rate at which the area changes with time.","function":true},{"term":"dr/dt","meaning":"The rate at which the radius changes with time.","function":true}],"explanation":"Related rates problems connect the rates of change of quantities linked by an equation. Write the relation among the variables, differentiate both sides with respect to time using the chain rule, then substitute known values to find the unknown rate. For example, a circle's area changes at 2πr times the rate the radius changes. Substitute numerical values only after differentiating.","origin":"","implementations":[{"name":"sympy.diff","library":"SymPy","note":"Differentiates a relation with respect to time t."},{"name":"sympy.solve","library":"SymPy","note":"Solves the differentiated equation for the unknown rate."}]},"C1.11":{"spoken":[{"line":0,"text":"y minus f of a equals f prime of a times the quantity x minus a."},{"line":1,"text":"f of x is approximately f of a plus f prime of a times the quantity x minus a."}],"terms":[{"term":"y","meaning":"The y-coordinate of a point on the tangent line.","function":false},{"term":"f(a)","meaning":"The value of f at the point of tangency a.","function":true},{"term":"f′(a)","meaning":"The derivative of f at a, the slope of the tangent line.","function":true},{"term":"x","meaning":"The input variable; a point near a for the approximation.","function":false},{"term":"a","meaning":"The point of tangency, where the linear approximation is centered.","function":false},{"term":"f(x)","meaning":"The true function value at x, being approximated near the point a.","function":true},{"term":"≈","meaning":"Approximately equal: the tangent line approximates f near a.","function":false}],"explanation":"The tangent line at x = a passes through (a, f(a)) with slope f′(a), written here in point-slope form. Near a, the curve and its tangent are almost indistinguishable, so the tangent line serves as a linear approximation of f. This underlies estimates like √4.1 ≈ 2.025 and is the first-order case of a Taylor polynomial and the basis of Newton's method.","origin":"","implementations":[{"name":"sympy.series","library":"SymPy","note":"Order-one series expansion gives the linear approximation."},{"name":"jax.jvp","library":"JAX","note":"Jacobian–vector product: the linearization of a function at a point."}]},"C1.12":{"spoken":[{"line":0,"text":"f prime of c equals 0 or undefined."},{"line":1,"text":"f double prime of c greater than 0 implies min; f double prime of c less than 0 implies max."},{"line":2,"text":"f double prime changes sign implies inflection."}],"terms":[{"term":"f′(c)","meaning":"The first derivative at c; a critical point is where it is zero or undefined.","function":true},{"term":"c","meaning":"A critical point in the domain of f.","function":false},{"term":"f″(c)","meaning":"The second derivative at c; its sign gives concavity and classifies the critical point.","function":true},{"term":"⇒","meaning":"Implies: the sign condition guarantees the stated classification of the point.","function":false},{"term":"min, max","meaning":"Local minimum (concave up) and local maximum (concave down) at the critical point.","function":false},{"term":"f″","meaning":"The second derivative function of f, measuring concavity.","function":true},{"term":"inflection","meaning":"An inflection point: where the concavity of f changes.","function":false}],"explanation":"Critical points are where the derivative is zero or undefined, the only interior candidates for local extrema. The second derivative test classifies them: positive curvature (concave up) means a local minimum, negative means a local maximum. Points where the second derivative changes sign are inflection points, where concavity switches. On a closed interval, endpoints must also be checked.","origin":"Fermat's method for locating maxima and minima, from the 1630s, anticipated the condition f′(c) = 0.","implementations":[{"name":"sympy.calculus.util.stationary_points","library":"SymPy","note":"Finds points where the derivative is zero."},{"name":"sympy.calculus.util.minimum","library":"SymPy","note":"Finds the minimum of a function over a domain."},{"name":"scipy.optimize.minimize_scalar","library":"SciPy","note":"Numerically finds a local minimum of a one-variable function."}]},"C1.13":{"spoken":[{"line":0,"text":"f prime of x star equals 0."},{"line":1,"text":"x sub k plus 1 equals x sub k minus eta times f prime of x sub k."},{"line":2,"text":"Theta gets theta minus eta times the gradient of L of theta."}],"terms":[{"term":"f′","meaning":"The derivative of the objective function f; it is zero at an optimum and gives the descent direction.","function":true},{"term":"x*","meaning":"x star: the optimal point, where f′ equals 0.","function":false},{"term":"x_k","meaning":"The current iterate of gradient descent at step k.","function":false},{"term":"x_{k+1}","meaning":"The next iterate after one gradient descent step.","function":false},{"term":"η","meaning":"Eta: the learning rate, a small positive step size controlling how far each update moves.","function":false},{"term":"θ","meaning":"Theta: the vector of model parameters being updated.","function":false},{"term":"←","meaning":"Assignment arrow: replace theta with the updated value on the right.","function":false},{"term":"∇L(θ)","meaning":"The gradient of the loss function L at theta; points uphill, so we step opposite to it.","function":true},{"term":"L","meaning":"The loss function: takes parameters theta and returns a number measuring error to minimize.","function":true}],"explanation":"Optimization seeks inputs where a function is smallest or largest; at an interior optimum the derivative is zero. When solving f′(x) = 0 directly is impractical, gradient descent repeatedly steps opposite the derivative, scaled by a learning rate η. The vector version updates parameters θ against the gradient of a loss L, which is how most machine learning models are trained.","origin":"Augustin-Louis Cauchy proposed the gradient descent method in 1847.","implementations":[{"name":"scipy.optimize.minimize","library":"SciPy","note":"General-purpose minimization, including gradient-based methods."},{"name":"torch.optim.SGD","library":"PyTorch","note":"Stochastic gradient descent optimizer for model parameters."},{"name":"tf.keras.optimizers.SGD","library":"TensorFlow","note":"Gradient descent optimizer for Keras models."},{"name":"fminunc","library":"MATLAB Optimization Toolbox","note":"Finds a minimum of an unconstrained multivariable function."}]},"C1.14":{"spoken":[{"line":0,"text":"f prime of c equals the quantity f of b minus f of a, all over the quantity b minus a."},{"line":1,"text":"Rolle: f of a equals f of b implies f prime of c equals 0."}],"terms":[{"term":"f′(c)","meaning":"The derivative of f at c, the instantaneous slope equal to the average slope.","function":true},{"term":"c","meaning":"A point strictly between a and b guaranteed by the theorem.","function":false},{"term":"f(a), f(b)","meaning":"Function values at the endpoints of the interval.","function":true},{"term":"a, b","meaning":"Endpoints of the interval; f is continuous on [a, b] and differentiable on (a, b).","function":false},{"term":"Rolle","meaning":"Rolle's theorem: the special case with equal endpoint values, giving a horizontal tangent.","function":false},{"term":"⇒","meaning":"Implies: equal endpoint values guarantee a point c where the derivative is zero.","function":false}],"explanation":"The Mean Value Theorem states that if f is continuous on [a, b] and differentiable inside, some point c has instantaneous slope equal to the average slope over the interval. Rolle's theorem is the special case where f(a) = f(b), forcing a horizontal tangent. The theorem connects local derivative information to global behavior, for instance proving that a zero derivative implies a constant function.","origin":"Michel Rolle proved his theorem for polynomials in 1691; Lagrange stated the general Mean Value Theorem in 1797.","implementations":[]},"C1.15":{"spoken":[{"line":0,"text":"If the limit of f equals the limit of g equals 0 or plus or minus infinity:"},{"line":1,"text":"The limit as x approaches a of f of x over g of x equals the limit as x approaches a of f prime of x over g prime of x."}],"terms":[{"term":"lim","meaning":"The limit operator: takes a function and returns the value it approaches as x approaches a.","function":true},{"term":"f, g","meaning":"The numerator and denominator functions, both tending to 0 or both to infinity (an indeterminate form).","function":true},{"term":"±∞","meaning":"Plus or minus infinity: the second indeterminate case, where both functions grow without bound.","function":false},{"term":"x","meaning":"The input variable of f and g, approaching the point a.","function":false},{"term":"a","meaning":"The point being approached (it may be infinity).","function":false},{"term":"f′(x), g′(x)","meaning":"Derivatives of the numerator and denominator, taken separately.","function":true}],"explanation":"L'Hôpital's rule evaluates limits of quotients that take the indeterminate form 0/0 or ∞/∞. In that case the limit of f/g equals the limit of f′/g′, provided the latter exists. Numerator and denominator are differentiated separately, and the rule may be repeated. Other indeterminate forms, such as 0·∞ or 1^∞, can be rewritten as quotients first.","origin":"Published by Guillaume de l'Hôpital in his 1696 textbook, but discovered by Johann Bernoulli, who taught him calculus.","implementations":[{"name":"sympy.limit","library":"SymPy","note":"Symbolic limits, including indeterminate forms (via the Gruntz algorithm)."},{"name":"Limit","library":"Mathematica","note":"Computes limits including indeterminate forms."}]},"C1.16":{"spoken":[{"line":0,"text":"The integral of x to the n, d x, equals x to the n plus 1 over n plus 1, plus C, for n not equal to negative 1."},{"line":1,"text":"The integral of 1 over x, d x, equals the natural log of the absolute value of x plus C; the integral of e to the x, d x, equals e to the x plus C."},{"line":2,"text":"The integral of sine x, d x, equals negative cosine x plus C; the integral of cosine x, d x, equals sine x plus C."}],"terms":[{"term":"∫","meaning":"The indefinite integral: takes a function and returns its family of antiderivatives.","function":true},{"term":"xⁿ","meaning":"x to the n, integrated by the reverse power rule.","function":true},{"term":"dx","meaning":"Indicates that the integration is with respect to the variable x.","function":false},{"term":"n","meaning":"The exponent; the power rule fails for n = −1.","function":false},{"term":"C","meaning":"The arbitrary constant of integration, representing the whole family of antiderivatives.","function":false},{"term":"ln|x|","meaning":"The natural log of the absolute value of x, the antiderivative of 1 over x.","function":true},{"term":"eˣ","meaning":"The natural exponential function: takes x and returns e to the x; it is its own antiderivative.","function":true},{"term":"sin x, cos x","meaning":"Sine and cosine functions; each integrates to the other, up to sign.","function":true}],"explanation":"An antiderivative of f is a function whose derivative is f; the family of all antiderivatives differs by a constant C. These basic formulas reverse the derivative rules: the power rule for n ≠ −1, the logarithm for 1/x, and the self-reproducing exponential, along with sine and cosine. They are the building blocks for evaluating definite integrals via the Fundamental Theorem.","origin":"","implementations":[{"name":"sympy.integrate","library":"SymPy","note":"Symbolic antiderivative of an expression."},{"name":"numpy.polyint","library":"NumPy","note":"Antiderivative of a polynomial given by its coefficients."},{"name":"Integrate","library":"Mathematica","note":"Symbolic indefinite and definite integration."}]},"C1.17":{"spoken":[{"line":0,"text":"The integral from a to b of f of x, d x, equals the limit as n approaches infinity of the sum from i equals 1 to n of f of x sub i star, delta x."},{"line":1,"text":"Delta x equals the quantity b minus a, all over n."}],"terms":[{"term":"∫_a^b","meaning":"The definite integral: takes f and an interval, returns the signed area under the curve.","function":true},{"term":"f(x)","meaning":"The function being integrated; it takes x and returns the height of the curve.","function":true},{"term":"a, b","meaning":"The lower and upper limits of integration, the ends of the interval.","function":false},{"term":"dx","meaning":"Indicates integration with respect to x; the limit of the rectangle widths Δx.","function":false},{"term":"lim","meaning":"The limit as the number of rectangles n grows without bound.","function":true},{"term":"Σ","meaning":"Summation from i = 1 to n, adding the areas of the rectangles.","function":true},{"term":"n","meaning":"The number of equal subintervals, or rectangles, in the Riemann sum.","function":false},{"term":"i","meaning":"The summation index labeling each subinterval from 1 to n.","function":false},{"term":"x_i*","meaning":"A sample point chosen in the i-th subinterval.","function":false},{"term":"Δx","meaning":"Delta x: the width of each of the n equal subintervals.","function":false}],"explanation":"A Riemann sum approximates the area under a curve by adding the areas of n rectangles of width Δx = (b − a)/n, each with height f at a sample point in its subinterval. The definite integral is the limit of these sums as the rectangles become infinitely thin. Left, right, and midpoint sums differ only in where each rectangle's height is sampled.","origin":"Bernhard Riemann gave the rigorous definition in his 1854 habilitation thesis, published in 1868.","implementations":[{"name":"sympy.Integral.as_sum","library":"SymPy","note":"Approximates an integral as a left, right, or midpoint Riemann sum."},{"name":"scipy.integrate.quad","library":"SciPy","note":"Numerically computes a definite integral."},{"name":"numpy.sum","library":"NumPy","note":"Sums sampled rectangle areas f(xᵢ)Δx."}]},"C1.18":{"spoken":[{"line":0,"text":"d d x of the integral from a to x of f of t, d t, equals f of x."},{"line":1,"text":"The integral from a to b of f of x, d x, equals F of b minus F of a."}],"terms":[{"term":"d/dx","meaning":"The derivative with respect to x, here of an accumulation function.","function":true},{"term":"∫_a^x","meaning":"The integral with variable upper limit x, an accumulation function of x.","function":true},{"term":"a","meaning":"A fixed lower limit of integration, the starting point of accumulation.","function":false},{"term":"x","meaning":"The variable upper limit; the derivative is taken with respect to it.","function":false},{"term":"f(t)","meaning":"The integrand, written in the dummy variable t.","function":true},{"term":"dt","meaning":"Indicates integration with respect to the dummy variable t.","function":false},{"term":"b","meaning":"The upper limit of the definite integral in the evaluation part of the theorem.","function":false},{"term":"F","meaning":"An antiderivative of f, meaning F′ = f; its change from a to b gives the integral.","function":true}],"explanation":"The Fundamental Theorem of Calculus links differentiation and integration as inverse processes. Part one says that differentiating an accumulation integral of f with variable upper limit returns f. Part two says a definite integral can be evaluated by finding any antiderivative F and subtracting its values at the endpoints, replacing limits of Riemann sums with simple arithmetic.","origin":"Developed by Newton and Leibniz in the 1660s–1680s, building on earlier geometric work by Isaac Barrow.","implementations":[{"name":"sympy.integrate","library":"SymPy","note":"Definite integrals via antiderivatives where possible."},{"name":"scipy.integrate.quad","library":"SciPy","note":"Numerical definite integration."}]},"C1.19":{"spoken":[{"line":0,"text":"The integral of f of g of x times g prime of x, d x, equals the integral of f of u, d u."},{"line":1,"text":"u equals g of x, d u equals g prime of x, d x."}],"terms":[{"term":"∫","meaning":"The integral operator: takes an integrand and returns its antiderivative; substitution rewrites it in terms of u.","function":true},{"term":"f","meaning":"The outer function in the composite integrand, evaluated at g(x) or at u.","function":true},{"term":"g(x)","meaning":"The inner function, replaced by the new variable u.","function":true},{"term":"g′(x)","meaning":"The derivative of the inner function, which must appear as a factor.","function":true},{"term":"dx","meaning":"Indicates the original integration is with respect to x.","function":false},{"term":"u","meaning":"The substitution variable, defined as u equals g(x), the inside function.","function":false},{"term":"du","meaning":"The differential of u, equal to g′(x) dx.","function":false}],"explanation":"U-substitution is the chain rule run backward. When an integrand contains a composite function f(g(x)) multiplied by the inner function's derivative g′(x), setting u = g(x) and du = g′(x) dx turns it into the simpler integral of f(u). For definite integrals, either change the limits to u-values or substitute back before evaluating.","origin":"","implementations":[{"name":"sympy.integrate","library":"SymPy","note":"Symbolic integration that applies substitution automatically."},{"name":"sympy.Integral.transform","library":"SymPy","note":"Performs an explicit change of variables in an integral."}]},"C1.20":{"spoken":[{"line":0,"text":"x sub n plus 1 equals x sub n minus f of x sub n over f prime of x sub n."},{"line":1,"text":"Fails if f prime of x sub n is approximately 0."}],"terms":[{"term":"x_n","meaning":"The current approximation to the root at step n.","function":false},{"term":"x_{n+1}","meaning":"The next approximation, where the tangent line at x_n crosses the x-axis.","function":false},{"term":"f","meaning":"The function whose root is sought; it takes x and returns f(x), which should equal zero.","function":true},{"term":"f′","meaning":"The derivative of f: takes x and returns the slope of the tangent line used at each step.","function":true},{"term":"≈","meaning":"Approximately equal; a near-zero slope makes the step huge and the method unreliable.","function":false}],"explanation":"Newton's method finds roots of f by repeatedly following the tangent line at the current guess to where it crosses the x-axis. Each update subtracts f(xₙ)/f′(xₙ). Near a simple root it converges quadratically, roughly doubling the correct digits per step, but it can fail or jump away when the derivative is near zero or the initial guess is poor.","origin":"Newton described the method around 1669, Joseph Raphson published a simplified version in 1690, and Thomas Simpson generalized it in 1740.","implementations":[{"name":"scipy.optimize.newton","library":"SciPy","note":"Newton–Raphson root finding given the derivative (secant method otherwise)."},{"name":"sympy.nsolve","library":"SymPy","note":"Numerical root finding from an initial guess."},{"name":"FindRoot","library":"Mathematica","note":"Numerical root finding, using Newton's method by default."}]},"S.1":{"spoken":[{"line":0,"text":"x bar equals one over n times the sum from i equals 1 to n of x sub i. Mu equals one over capital N times the sum from i equals 1 to capital N of x sub i."},{"line":1,"text":"x bar sub w equals the sum of w sub i x sub i, all over the sum of w sub i."}],"terms":[{"term":"x̄","meaning":"The sample mean: the arithmetic average of the n observed data values in a sample.","function":false},{"term":"n","meaning":"The sample size, the number of observations in the sample being averaged.","function":false},{"term":"Σ","meaning":"Summation operator: takes the indexed terms that follow and adds them up over the stated range of the index, producing their total.","function":true},{"term":"i","meaning":"The summation index, running over the data points from 1 up to n (or N).","function":false},{"term":"xᵢ","meaning":"The i-th data value in the sample or population.","function":false},{"term":"μ","meaning":"The population mean: the average of all N values in the entire population.","function":false},{"term":"N","meaning":"The population size, the total number of values in the whole population.","function":false},{"term":"x̄_w","meaning":"The weighted mean: an average in which each value counts in proportion to its weight.","function":false},{"term":"wᵢ","meaning":"The weight attached to the i-th value, saying how much that value counts toward the weighted mean.","function":false}],"explanation":"Measures of center summarize where a dataset sits with a single typical value. The mean adds every value and divides by the count (x̄ for a sample of n, μ for a population of N); the weighted mean lets some observations count more. The median is the middle value of the sorted data and resists outliers, while the mode is the most frequent value and also works for categorical data.","origin":"","implementations":[{"name":"statistics.mean","library":"Python standard library","note":"Arithmetic mean of a sequence."},{"name":"numpy.average","library":"NumPy","note":"Mean with optional weights, giving the weighted mean."},{"name":"statistics.median","library":"Python standard library","note":"Middle value of the data."},{"name":"statistics.mode","library":"Python standard library","note":"Most common data value."}]},"S.2":{"spoken":[{"line":0,"text":"Sigma squared equals one over capital N times the sum of the quantity x sub i minus mu, squared."},{"line":1,"text":"s squared equals one over the quantity n minus 1, times the sum of the quantity x sub i minus x bar, squared."},{"line":2,"text":"Sigma equals the square root of sigma squared, s equals the square root of s squared."}],"terms":[{"term":"σ²","meaning":"The population variance: the average squared deviation of the population values from the population mean μ.","function":false},{"term":"N","meaning":"The population size, the number of values in the whole population.","function":false},{"term":"Σ","meaning":"Summation operator: adds up the squared deviations over all data values to give a total sum of squares.","function":true},{"term":"xᵢ","meaning":"The i-th data value, whose deviation from the mean is squared and summed.","function":false},{"term":"μ","meaning":"The population mean, the center from which population deviations are measured.","function":false},{"term":"s²","meaning":"The sample variance: the sum of squared deviations from the sample mean divided by n minus 1, an unbiased estimate of σ².","function":false},{"term":"n","meaning":"The sample size, the number of observations in the sample.","function":false},{"term":"n − 1","meaning":"The degrees of freedom used as the divisor for sample variance, correcting the bias from estimating the mean with x̄.","function":false},{"term":"x̄","meaning":"The sample mean, the center from which sample deviations are measured.","function":false},{"term":"σ","meaning":"The population standard deviation, the square root of the population variance, in the same units as the data.","function":false},{"term":"√","meaning":"Square root: takes a nonnegative number and returns the nonnegative number whose square equals it; here it turns a variance into a standard deviation.","function":true},{"term":"s","meaning":"The sample standard deviation, the square root of the sample variance s².","function":false}],"explanation":"Variance measures spread as the average squared distance from the mean, and the standard deviation is its square root, back in the original units. The population version divides by N, while the sample version divides by n − 1 (Bessel's correction) because deviations are measured from x̄ rather than the true mean, which would otherwise make the estimate too small.","origin":"Karl Pearson introduced the term standard deviation in 1894; Ronald Fisher introduced the term variance in 1918.","implementations":[{"name":"statistics.stdev","library":"Python standard library","note":"Sample standard deviation using n − 1."},{"name":"statistics.pstdev","library":"Python standard library","note":"Population standard deviation using N."},{"name":"numpy.var","library":"NumPy","note":"Variance; ddof=1 gives the sample version."},{"name":"=STDEV.S()","library":"Excel","note":"Sample standard deviation of a range."}]},"S.3":{"spoken":[{"line":0,"text":"I Q R equals Q sub 3 minus Q sub 1."},{"line":1,"text":"Outlier: x is less than Q sub 1 minus 1.5 times I Q R"},{"line":2,"text":"or x is greater than Q sub 3 plus 1.5 times I Q R"},{"line":3,"text":"min, Q sub 1, med, Q sub 3, max"}],"terms":[{"term":"IQR","meaning":"The interquartile range: the spread of the middle 50 percent of the data, the third quartile minus the first quartile.","function":false},{"term":"Q₃","meaning":"The third quartile: the value below which about 75 percent of the data fall.","function":false},{"term":"Q₁","meaning":"The first quartile: the value below which about 25 percent of the data fall.","function":false},{"term":"x","meaning":"A single data value being checked against the outlier fences.","function":false},{"term":"1.5 IQR","meaning":"The fence distance used by the 1.5 times IQR rule: values more than this far beyond a quartile are flagged as outliers.","function":false},{"term":"min","meaning":"The minimum, the smallest data value; the first number of the five-number summary.","function":false},{"term":"med","meaning":"The median, the middle value of the sorted data, also called the second quartile.","function":false},{"term":"max","meaning":"The maximum, the largest data value; the last number of the five-number summary.","function":false}],"explanation":"Quartiles split sorted data into four equal parts, and the interquartile range Q3 − Q1 measures the spread of the middle half. Points more than 1.5 IQR below Q1 or above Q3 are flagged as possible outliers. The five-number summary (min, Q1, median, Q3, max) is what a box plot draws, giving a robust picture of center, spread and skew.","origin":"John Tukey popularized the box plot and the 1.5 × IQR outlier rule in his 1977 book Exploratory Data Analysis.","implementations":[{"name":"numpy.percentile","library":"NumPy","note":"Percentiles of data, e.g. 25th and 75th for quartiles."},{"name":"scipy.stats.iqr","library":"SciPy","note":"Interquartile range of data."},{"name":"=QUARTILE.INC()","library":"Excel","note":"Returns a quartile of a data range."},{"name":"matplotlib.pyplot.boxplot","library":"Matplotlib","note":"Draws a box plot with 1.5 × IQR whiskers."}]},"S.4":{"spoken":[{"line":0,"text":"z equals the quantity x minus mu, all over sigma. z equals the quantity x minus x bar, all over s."},{"line":1,"text":"x equals mu plus z sigma."}],"terms":[{"term":"z","meaning":"The z-score: how many standard deviations a value lies above (positive) or below (negative) the mean.","function":false},{"term":"x","meaning":"The raw data value being standardized, or recovered from a z-score.","function":false},{"term":"μ","meaning":"The population mean, subtracted to center the value.","function":false},{"term":"σ","meaning":"The population standard deviation, divided by to express the distance in standard-deviation units.","function":false},{"term":"x̄","meaning":"The sample mean, used in place of μ when standardizing with sample statistics.","function":false},{"term":"s","meaning":"The sample standard deviation, used in place of σ when standardizing with sample statistics.","function":false}],"explanation":"A z-score says how many standard deviations a value lies above or below the mean, found by subtracting the mean and dividing by the standard deviation. This puts values from different scales on a common, unitless footing and links raw data to the standard normal table. Rearranging gives x = μ + zσ, which converts a z-score back into the original units.","origin":"","implementations":[{"name":"scipy.stats.zscore","library":"SciPy","note":"Standardizes an array to z-scores."},{"name":"sklearn.preprocessing.StandardScaler","library":"scikit-learn","note":"Rescales features to mean 0 and unit variance."},{"name":"=STANDARDIZE()","library":"Excel","note":"Z-score from a value, mean and standard deviation."}]},"S.5":{"spoken":[{"line":0,"text":"Zero is less than or equal to the probability of A, which is less than or equal to 1. The probability of A complement equals 1 minus the probability of A."},{"line":1,"text":"The probability of A union B equals the probability of A plus the probability of B minus the probability of A intersect B."},{"line":2,"text":"Disjoint: the probability of A union B equals the probability of A plus the probability of B."}],"terms":[{"term":"P(·)","meaning":"Probability function: takes an event and returns a number between 0 and 1 giving how likely that event is to occur.","function":true},{"term":"A","meaning":"An event, a set of possible outcomes of the random experiment.","function":false},{"term":"Aᶜ","meaning":"The complement of A: the event that A does not occur, consisting of all outcomes not in A.","function":false},{"term":"B","meaning":"A second event in the same sample space as A.","function":false},{"term":"∪","meaning":"Union: A ∪ B is the event that A or B (or both) occurs.","function":true},{"term":"∩","meaning":"Intersection: A ∩ B is the event that both A and B occur; it is the overlap subtracted to avoid double counting.","function":true}],"explanation":"These rules are the basic bookkeeping of probability. Every probability lies between 0 and 1, and the complement rule says the chance an event does not happen is 1 minus the chance it does. The addition rule finds the probability of A or B by adding the two and subtracting the overlap, which would otherwise be counted twice; for disjoint events the overlap is zero.","origin":"Andrey Kolmogorov set out the axioms that underlie these rules in 1933.","implementations":[]},"S.6":{"spoken":[{"line":0,"text":"The probability of A given B equals the probability of A intersect B over the probability of B."},{"line":1,"text":"The probability of A intersect B equals the probability of A given B times the probability of B."},{"line":2,"text":"Independent if and only if the probability of A intersect B equals the probability of A times the probability of B."}],"terms":[{"term":"P(A | B)","meaning":"Conditional probability: the probability that A occurs given that B is known to have occurred, defined when P(B) is positive.","function":true},{"term":"A","meaning":"The event whose probability is being found, possibly restricted to outcomes where B occurs.","function":false},{"term":"B","meaning":"The conditioning event, known to have happened; it becomes the reduced sample space.","function":false},{"term":"P(·)","meaning":"Probability function: takes an event and returns its probability, a number from 0 to 1.","function":true},{"term":"∩","meaning":"Intersection: A ∩ B is the event that both A and B occur.","function":true},{"term":"⟺","meaning":"If and only if: the statements on each side are logically equivalent, each implying the other.","function":false}],"explanation":"Conditional probability P(A | B) is the chance of A once we know B has happened: restrict attention to B and ask what fraction of it also lies in A. Rearranging gives the multiplication rule for the probability of both events. Two events are independent when knowing one tells you nothing about the other, which is equivalent to their joint probability equalling the product of their separate probabilities.","origin":"","implementations":[]},"S.7":{"spoken":[{"line":0,"text":"The probability of A given B equals the probability of B given A times the probability of A, all over the probability of B."},{"line":1,"text":"The probability of B equals the sum over i of the probability of B given A sub i times the probability of A sub i."}],"terms":[{"term":"P(A | B)","meaning":"The posterior: the updated probability of A after observing evidence B.","function":true},{"term":"A","meaning":"The hypothesis or event whose probability is being updated.","function":false},{"term":"B","meaning":"The observed evidence or data used to update the probability of A.","function":false},{"term":"P(B | A)","meaning":"The likelihood: the probability of observing evidence B if A is true.","function":true},{"term":"P(A)","meaning":"The prior: the probability of A before the evidence B is taken into account.","function":true},{"term":"P(B)","meaning":"The total (marginal) probability of the evidence B, the normalizing constant in Bayes' theorem.","function":true},{"term":"Σ","meaning":"Summation operator: adds the terms P(B | Aᵢ)P(Aᵢ) over every event Aᵢ in the partition, giving the law of total probability.","function":true},{"term":"i","meaning":"The index labeling the events of the partition.","function":false},{"term":"Aᵢ","meaning":"The i-th event in a partition of the sample space: mutually exclusive events that together cover every outcome.","function":false}],"explanation":"Bayes' theorem reverses a conditional probability, turning P(B | A) into P(A | B). It updates a prior belief P(A) with the likelihood of observed evidence B to give a posterior. The denominator P(B) comes from the law of total probability, summing over every possible cause Aᵢ, and acts as a normalizing constant. It underlies medical test interpretation, spam filters and all of Bayesian statistics.","origin":"Thomas Bayes's result was published posthumously in 1763; Pierre-Simon Laplace developed it independently in 1774.","implementations":[{"name":"sklearn.naive_bayes.GaussianNB","library":"scikit-learn","note":"Classifier applying Bayes' theorem with Gaussian likelihoods."}]},"S.8":{"spoken":[{"line":0,"text":"n factorial equals n times the quantity n minus 1, and so on down to 1."},{"line":1,"text":"n P r equals n factorial over the quantity n minus r factorial."},{"line":2,"text":"n choose r equals n C r equals n factorial over r factorial times the quantity n minus r factorial."}],"terms":[{"term":"n","meaning":"The total number of distinct objects available to choose from.","function":false},{"term":"n!","meaning":"n factorial: takes a nonnegative integer n and returns the product n(n − 1)⋯1, the number of ways to arrange n objects in order; 0! = 1.","function":true},{"term":"⋯","meaning":"The continuation of the pattern: keep multiplying by successively smaller integers down to 1.","function":false},{"term":"ₙPᵣ","meaning":"Permutations: the number of ordered arrangements of r objects chosen from n, where position matters.","function":true},{"term":"r","meaning":"The number of objects being selected or arranged out of the n available.","function":false},{"term":"(n − r)!","meaning":"The factorial of the number of objects not chosen, divided out to remove arrangements of the leftovers.","function":true},{"term":"(n choose r)","meaning":"Binomial coefficient, n choose r: takes n and r and returns the number of unordered subsets of size r from n objects.","function":true},{"term":"ₙCᵣ","meaning":"Combinations: another notation for n choose r, the number of ways to choose r objects from n when order does not matter.","function":true},{"term":"r!","meaning":"r factorial, divided out to remove the orderings within each selected group of r.","function":true}],"explanation":"Counting formulas give the number of ways to choose items. The factorial n! counts orderings of n distinct objects. Permutations nPr count ordered selections of r from n, dividing out the arrangements of the unused items. Combinations nCr count unordered selections, additionally dividing by r! because each group of r appears in r! orders. These counts feed directly into probability calculations such as the binomial distribution.","origin":"","implementations":[{"name":"math.comb","library":"Python standard library","note":"Number of combinations n choose k."},{"name":"math.perm","library":"Python standard library","note":"Number of ordered arrangements of k from n."},{"name":"math.factorial","library":"Python standard library","note":"Factorial of a non-negative integer."},{"name":"itertools.combinations","library":"Python standard library","note":"Generates all r-length combinations of an iterable."}]},"S.9":{"spoken":[{"line":0,"text":"The expected value of X equals the sum of x times p of x. The expected value of X equals the integral of x times f of x d x."},{"line":1,"text":"The variance of X equals the expected value of X squared minus the quantity the expected value of X, squared."},{"line":2,"text":"The expected value of the quantity a X plus b equals a times the expected value of X plus b."},{"line":3,"text":"The variance of the quantity a X plus b equals a squared times the variance of X."}],"terms":[{"term":"E[·]","meaning":"Expected value operator: takes a random variable and returns its long-run probability-weighted average, the mean of its distribution.","function":true},{"term":"X","meaning":"A random variable, a numerical outcome of a random process.","function":false},{"term":"Σ","meaning":"Summation operator: adds x times p(x) over every possible value x of a discrete random variable.","function":true},{"term":"x","meaning":"A particular possible value that X can take.","function":false},{"term":"p(x)","meaning":"The probability mass function: for a discrete X, takes a value x and returns P(X = x).","function":true},{"term":"∫ … dx","meaning":"Integral: for a continuous X, accumulates x times f(x) over all real x, the continuous analogue of the sum; dx marks x as the integration variable.","function":true},{"term":"f(x)","meaning":"The probability density function of a continuous X: takes x and returns the density, whose area over an interval is a probability.","function":true},{"term":"Var(·)","meaning":"Variance operator: takes a random variable and returns the expected squared deviation from its mean, measuring spread.","function":true},{"term":"E[X²]","meaning":"The expected value of X squared, the second moment of X.","function":false},{"term":"a","meaning":"A constant multiplier that scales X; it scales the mean by a and the variance by a squared.","function":false},{"term":"b","meaning":"A constant added to X; it shifts the mean by b but does not change the variance.","function":false}],"explanation":"The expected value is the long-run average of a random variable, a probability-weighted sum for discrete variables or an integral against the density for continuous ones. Variance measures spread and is most easily computed as the mean of the square minus the square of the mean. Expectation is linear, so shifting by b moves the mean, while scaling by a multiplies variance by a² and leaves shifts out entirely.","origin":"Christiaan Huygens introduced the idea of expected value in his 1657 treatise on games of chance.","implementations":[{"name":"numpy.average","library":"NumPy","note":"Weighted average; with probabilities as weights gives E[X]."},{"name":"scipy.stats.rv_discrete","library":"SciPy","note":"Custom discrete distribution with mean, var and expect methods."}]},"S.10":{"spoken":[{"line":0,"text":"The probability that X equals k equals n choose k times p to the k times the quantity 1 minus p to the n minus k."},{"line":1,"text":"Mu equals n p. Sigma squared equals n p times the quantity 1 minus p."}],"terms":[{"term":"P(X = k)","meaning":"The probability that the binomial random variable X takes exactly the value k.","function":true},{"term":"X","meaning":"A binomial random variable: the number of successes in n independent trials.","function":false},{"term":"k","meaning":"A specific number of successes, from 0 to n.","function":false},{"term":"(n choose k)","meaning":"Binomial coefficient: takes n and k and returns the number of ways to place the k successes among the n trials.","function":true},{"term":"n","meaning":"The fixed number of independent trials performed in the binomial experiment.","function":false},{"term":"p","meaning":"The probability of success on each trial, the same for every trial.","function":false},{"term":"1 − p","meaning":"The probability of failure on each trial, the complement of the success probability p.","function":false},{"term":"μ","meaning":"The mean of the binomial distribution, the expected number of successes, n p.","function":false},{"term":"σ²","meaning":"The variance of the binomial distribution, n p (1 − p).","function":false}],"explanation":"The binomial distribution counts the number of successes k in n independent trials, each with the same success probability p. The binomial coefficient counts which trials succeed, and pᵏ(1 − p)ⁿ⁻ᵏ is the probability of any one such pattern. Because the count is a sum of n independent Bernoulli variables, its mean is np and its variance is np(1 − p).","origin":"Jacob Bernoulli studied it in Ars Conjectandi, published posthumously in 1713.","implementations":[{"name":"scipy.stats.binom","library":"SciPy","note":"Binomial distribution with pmf, cdf and sampling."},{"name":"numpy.random.binomial","library":"NumPy","note":"Draws samples from a binomial distribution."},{"name":"=BINOM.DIST()","library":"Excel","note":"Binomial probability or cumulative probability."}]},"S.11":{"spoken":[{"line":0,"text":"The probability that X equals k equals lambda to the k times e to the negative lambda, all over k factorial."},{"line":1,"text":"Mu equals sigma squared equals lambda."}],"terms":[{"term":"P(X = k)","meaning":"The probability that the Poisson count X equals exactly k.","function":true},{"term":"X","meaning":"A Poisson random variable: the number of events occurring in a fixed interval of time or space.","function":false},{"term":"k","meaning":"A specific count of events, a nonnegative integer 0, 1, 2, and so on.","function":false},{"term":"λ","meaning":"The rate parameter: the average number of events per interval; it is both the mean and the variance.","function":false},{"term":"e","meaning":"Euler's number, about 2.71828, the base of the natural exponential.","function":false},{"term":"k!","meaning":"k factorial, the product of the integers from 1 to k, with 0! equal to 1.","function":true},{"term":"μ","meaning":"The mean of the Poisson distribution, equal to λ.","function":false},{"term":"σ²","meaning":"The variance of the Poisson distribution, also equal to λ.","function":false}],"explanation":"The Poisson distribution models the number of events occurring in a fixed interval of time or space when events happen independently at a constant average rate λ. The formula gives the probability of exactly k events. It arises as the limit of the binomial when n is large and p is small with np = λ, and its defining feature is that the mean and variance both equal λ.","origin":"Siméon Denis Poisson published the distribution in 1837.","implementations":[{"name":"scipy.stats.poisson","library":"SciPy","note":"Poisson distribution with pmf, cdf and sampling."},{"name":"numpy.random.poisson","library":"NumPy","note":"Draws samples from a Poisson distribution."},{"name":"=POISSON.DIST()","library":"Excel","note":"Poisson probability or cumulative probability."}]},"S.12":{"spoken":[{"line":0,"text":"f of x equals one over sigma times the square root of 2 pi, times e to the negative the quantity x minus mu squared, all over 2 sigma squared."},{"line":1,"text":"The probability that a is less than or equal to X, which is less than or equal to b, equals capital Phi of z sub b minus capital Phi of z sub a."},{"line":2,"text":"68 percent, 95 percent, 99.7 percent."}],"terms":[{"term":"f(x)","meaning":"The normal probability density function: takes a value x and returns the height of the bell curve there.","function":true},{"term":"x","meaning":"A value on the horizontal axis of the normal distribution.","function":false},{"term":"σ","meaning":"The standard deviation, controlling the width of the bell curve.","function":false},{"term":"√","meaning":"Square root: here it gives the square root of 2π, part of the normalizing constant so the total area is 1.","function":true},{"term":"π","meaning":"Pi, about 3.14159, appearing in the normalizing constant of the normal density.","function":false},{"term":"e","meaning":"Euler's number, about 2.71828, the base of the exponential that gives the bell shape.","function":false},{"term":"μ","meaning":"The mean, the center and peak of the bell curve.","function":false},{"term":"σ²","meaning":"The variance, the square of the standard deviation.","function":false},{"term":"P(a ≤ X ≤ b)","meaning":"The probability that the normal random variable X falls between a and b, the area under the curve over that interval.","function":true},{"term":"a","meaning":"The lower endpoint of the interval whose probability is being computed.","function":false},{"term":"X","meaning":"A normally distributed random variable with mean μ and standard deviation σ.","function":false},{"term":"b","meaning":"The upper endpoint of the interval whose probability is being computed.","function":false},{"term":"Φ","meaning":"The standard normal CDF: takes a z-score and returns the probability that a standard normal variable is at most that value.","function":true},{"term":"z_b","meaning":"The z-score of the upper endpoint, (b − μ)/σ.","function":false},{"term":"z_a","meaning":"The z-score of the lower endpoint, (a − μ)/σ.","function":false},{"term":"%","meaning":"Percent; here the approximate shares of a normal distribution within 1, 2, and 3 standard deviations of the mean.","function":false}],"explanation":"The normal distribution is the symmetric bell curve with mean μ and standard deviation σ, given by the density f(x). Probabilities are areas under the curve, found by standardizing the endpoints to z-scores and subtracting values of the standard normal CDF Φ. The empirical rule summarizes its shape: about 68%, 95% and 99.7% of values lie within one, two and three standard deviations of the mean.","origin":"Abraham de Moivre derived it in 1733 as an approximation to the binomial; Carl Friedrich Gauss used it for errors of measurement in 1809.","implementations":[{"name":"scipy.stats.norm","library":"SciPy","note":"Normal distribution with pdf, cdf, ppf and sampling."},{"name":"statistics.NormalDist","library":"Python standard library","note":"Normal distribution object with pdf, cdf and inv_cdf."},{"name":"=NORM.DIST()","library":"Excel","note":"Normal density or cumulative probability."},{"name":"numpy.random.normal","library":"NumPy","note":"Draws samples from a normal distribution."}]},"S.13":{"spoken":[{"line":0,"text":"X bar is approximately normal with mean mu and variance sigma squared over n."},{"line":1,"text":"S E sub x bar equals sigma over the square root of n. S E sub p hat equals the square root of the quantity p times the quantity 1 minus p, all over n."},{"line":2,"text":"z equals the quantity x bar minus mu, all over sigma over the square root of n."}],"terms":[{"term":"X̄","meaning":"The sample mean viewed as a random variable, which varies from sample to sample.","function":false},{"term":"≈","meaning":"Is approximately distributed as: for large n the sampling distribution of X̄ is close to the stated normal distribution.","function":false},{"term":"N(μ, σ²/n)","meaning":"The normal distribution with mean μ and variance σ²/n, the approximate sampling distribution of X̄ given by the central limit theorem.","function":true},{"term":"μ","meaning":"The population mean, the center of the sampling distribution of the sample mean.","function":false},{"term":"σ²","meaning":"The population variance, the spread of individual values in the population being sampled.","function":false},{"term":"n","meaning":"The sample size; larger n shrinks the standard error by a factor of the square root of n.","function":false},{"term":"SE_x̄","meaning":"The standard error of the sample mean: the standard deviation of x̄ across repeated samples, σ over the square root of n.","function":false},{"term":"σ","meaning":"The population standard deviation of individual values, the numerator of the standard error.","function":false},{"term":"√","meaning":"Square root: takes a nonnegative quantity and returns its nonnegative square root; it produces the root-n scaling of standard errors.","function":true},{"term":"SE_p̂","meaning":"The standard error of the sample proportion: the standard deviation of p̂ across repeated samples.","function":false},{"term":"p̂","meaning":"The sample proportion, the fraction of successes observed in the sample.","function":false},{"term":"p","meaning":"The true population proportion of successes, used in the standard error of p̂.","function":false},{"term":"z","meaning":"The test or standardized statistic: how many standard errors the sample mean lies from μ.","function":false},{"term":"x̄","meaning":"The observed sample mean, the value being standardized in the z statistic.","function":false}],"explanation":"The central limit theorem says that the mean of a large random sample is approximately normally distributed, whatever the shape of the population, with mean μ and variance σ²/n. The standard error, σ/√n for a mean or √(p(1 − p)/n) for a proportion, measures how much a sample statistic varies between samples. Dividing by it yields a z-statistic, the basis of many tests and intervals.","origin":"Abraham de Moivre proved a special case for coin tosses in 1733; Pierre-Simon Laplace extended it around 1810, and Aleksandr Lyapunov gave a rigorous general proof in 1901.","implementations":[{"name":"scipy.stats.sem","library":"SciPy","note":"Standard error of the mean of a sample."}]},"S.14":{"spoken":[{"line":0,"text":"x bar plus or minus z star times sigma over the square root of n. x bar plus or minus t star times s over the square root of n."},{"line":1,"text":"p hat plus or minus z star times the square root of the quantity p hat times the quantity 1 minus p hat, all over n."},{"line":2,"text":"n equals the quantity z star sigma over E, squared."}],"terms":[{"term":"x̄","meaning":"The sample mean, the point estimate at the center of the interval for μ.","function":false},{"term":"±","meaning":"Plus or minus: marks the interval from the estimate minus the margin of error to the estimate plus the margin of error.","function":false},{"term":"z*","meaning":"The critical value from the standard normal distribution for the chosen confidence level, such as 1.96 for 95 percent.","function":false},{"term":"σ","meaning":"The known population standard deviation, used with z* to build the margin of error.","function":false},{"term":"√","meaning":"Square root: takes a nonnegative quantity and returns its nonnegative square root, used here to form standard errors.","function":true},{"term":"n","meaning":"The sample size; in the last formula, the sample size needed to achieve margin of error E.","function":false},{"term":"t*","meaning":"The critical value from the t distribution with n − 1 degrees of freedom, used when σ is unknown.","function":false},{"term":"s","meaning":"The sample standard deviation, used in place of an unknown σ.","function":false},{"term":"p̂","meaning":"The sample proportion, the point estimate at the center of the interval for a population proportion.","function":false},{"term":"E","meaning":"The desired margin of error, the half-width of the confidence interval.","function":false}],"explanation":"A confidence interval gives a range of plausible values for a parameter: the point estimate plus or minus a critical value times the standard error. Use z* when σ is known or for proportions, and t* with the sample standard deviation when σ is unknown. Solving the margin-of-error formula for n tells you how large a sample is needed to achieve a desired margin E.","origin":"Jerzy Neyman introduced the confidence interval in 1937.","implementations":[{"name":"scipy.stats.t.interval","library":"SciPy","note":"Central interval of a t distribution for given confidence."},{"name":"statsmodels.stats.proportion.proportion_confint","library":"statsmodels","note":"Confidence interval for a binomial proportion."},{"name":"=CONFIDENCE.T()","library":"Excel","note":"Margin of error for a mean using the t distribution."},{"name":"=CONFIDENCE.NORM()","library":"Excel","note":"Margin of error for a mean using the normal distribution."}]},"S.15":{"spoken":[{"line":0,"text":"H sub 0 versus H sub a. z equals the quantity x bar minus mu sub 0, all over sigma over the square root of n."},{"line":1,"text":"Reject H sub 0 if p is less than alpha."},{"line":2,"text":"Alpha equals the probability of Type I. Beta equals the probability of Type II."},{"line":3,"text":"Power equals 1 minus beta."}],"terms":[{"term":"H₀","meaning":"The null hypothesis: the default claim of no effect, here that the population mean equals μ₀.","function":false},{"term":"Hₐ","meaning":"The alternative hypothesis: the claim the test seeks evidence for, that the mean differs from (or exceeds, or falls below) μ₀.","function":false},{"term":"z","meaning":"The test statistic: how many standard errors the sample mean lies from the hypothesized mean μ₀.","function":false},{"term":"x̄","meaning":"The observed sample mean computed from the data being tested.","function":false},{"term":"μ₀","meaning":"The hypothesized value of the population mean under the null hypothesis.","function":false},{"term":"σ","meaning":"The known population standard deviation, used to compute the standard error of the mean.","function":false},{"term":"√","meaning":"Square root: here the square root of n, which turns σ into the standard error σ/√n.","function":true},{"term":"n","meaning":"The sample size, the number of observations used to compute x̄.","function":false},{"term":"p","meaning":"The p-value: the probability, assuming H₀ is true, of a test statistic at least as extreme as the one observed.","function":false},{"term":"α","meaning":"The significance level: the chosen threshold, which is also the probability of a Type I error (rejecting a true null).","function":false},{"term":"P(·)","meaning":"Probability function: takes an event, here making a Type I or Type II error, and returns its probability.","function":true},{"term":"Type I","meaning":"A Type I error: rejecting the null hypothesis when it is actually true, a false alarm.","function":false},{"term":"β","meaning":"The probability of a Type II error: failing to reject the null when the alternative is true.","function":false},{"term":"Type II","meaning":"A Type II error: failing to reject a false null hypothesis, a missed detection.","function":false},{"term":"power","meaning":"The probability that the test correctly rejects a false null hypothesis, equal to 1 − β.","function":false}],"explanation":"A hypothesis test asks whether data are consistent with a null hypothesis H₀. A test statistic such as z measures how far the estimate falls from the null value in standard errors, and the p-value is the probability of a result at least that extreme if H₀ is true. Reject H₀ when p < α; α is the Type I error rate, β the Type II rate, and power is 1 − β.","origin":"Ronald Fisher popularized significance testing and p-values in 1925; Jerzy Neyman and Egon Pearson introduced Type I and Type II errors and power in 1928–1933.","implementations":[{"name":"statsmodels.stats.weightstats.ztest","library":"statsmodels","note":"One- or two-sample z-test returning statistic and p-value."},{"name":"statsmodels.stats.power.TTestPower","library":"statsmodels","note":"Power and sample-size calculations for t-tests."}]},"S.16":{"spoken":[{"line":0,"text":"t equals the quantity x bar minus mu sub 0, all over s over the square root of n, d f equals n minus 1."},{"line":1,"text":"t equals the quantity x bar sub 1 minus x bar sub 2, all over the square root of the quantity s sub 1 squared over n sub 1 plus s sub 2 squared over n sub 2. Welch."},{"line":2,"text":"Paired: one-sample t on differences."}],"terms":[{"term":"t","meaning":"The t test statistic: the difference between estimate and hypothesized value measured in estimated standard errors.","function":false},{"term":"x̄","meaning":"The sample mean of the single sample being tested against μ₀.","function":false},{"term":"μ₀","meaning":"The hypothesized population mean under the null hypothesis.","function":false},{"term":"s","meaning":"The sample standard deviation, estimating the unknown σ.","function":false},{"term":"√","meaning":"Square root: takes a nonnegative quantity and returns its square root, used to form the standard error in the denominator.","function":true},{"term":"n","meaning":"The sample size of the one-sample test, which sets df = n − 1.","function":false},{"term":"df","meaning":"Degrees of freedom: the parameter of the t distribution used to find critical values and p-values, n − 1 for a one-sample test.","function":false},{"term":"x̄₁, x̄₂","meaning":"The sample means of the first and second independent groups.","function":false},{"term":"s₁², s₂²","meaning":"The sample variances of the first and second groups, not assumed equal in Welch's test.","function":false},{"term":"n₁, n₂","meaning":"The sample sizes of the first and second groups.","function":false}],"explanation":"The t-test compares means when the population standard deviation is unknown and must be estimated by s, so the statistic follows a t distribution with heavier tails than the normal. The one-sample test uses n − 1 degrees of freedom. Welch's two-sample test divides the difference of means by a standard error that allows unequal variances, and a paired test is just a one-sample test on the differences.","origin":"William Sealy Gosset published the t-test under the pseudonym Student in 1908; Bernard Welch introduced the unequal-variance version in 1947.","implementations":[{"name":"scipy.stats.ttest_1samp","library":"SciPy","note":"One-sample t-test against a hypothesized mean."},{"name":"scipy.stats.ttest_ind","library":"SciPy","note":"Two-sample t-test; equal_var=False gives Welch's test."},{"name":"scipy.stats.ttest_rel","library":"SciPy","note":"Paired t-test on related samples."},{"name":"=T.TEST()","library":"Excel","note":"p-value for paired or two-sample t-tests."}]},"S.17":{"spoken":[{"line":0,"text":"Chi squared equals the sum of the quantity O minus E squared, all over E."},{"line":1,"text":"G O F: d f equals k minus 1."},{"line":2,"text":"E equals row times col, over total."},{"line":3,"text":"Indep.: d f equals the quantity r minus 1 times the quantity c minus 1."}],"terms":[{"term":"χ²","meaning":"The chi-square test statistic, measuring the total discrepancy between observed and expected counts.","function":false},{"term":"Σ","meaning":"Summation operator: adds the contribution (O − E)²/E over every category or table cell.","function":true},{"term":"O","meaning":"The observed count in a category or cell.","function":false},{"term":"E","meaning":"The expected count in a category or cell if the null hypothesis is true.","function":false},{"term":"GOF","meaning":"Goodness of fit: the chi-square test of whether one categorical variable follows a specified distribution.","function":false},{"term":"df","meaning":"Degrees of freedom of the chi-square distribution used to find the p-value.","function":false},{"term":"k","meaning":"The number of categories in a goodness-of-fit test.","function":false},{"term":"row","meaning":"The row total for the cell's row in a two-way table.","function":false},{"term":"col","meaning":"The column total for the cell's column in a two-way table.","function":false},{"term":"total","meaning":"The grand total of all counts in the two-way table.","function":false},{"term":"indep.","meaning":"The chi-square test of independence between two categorical variables in a two-way table.","function":false},{"term":"r","meaning":"The number of rows in the two-way table.","function":false},{"term":"c","meaning":"The number of columns in the two-way table.","function":false}],"explanation":"The chi-square statistic sums the squared gaps between observed and expected counts, each scaled by the expected count, to measure how badly data fit a model. In a goodness-of-fit test the expected counts come from a hypothesized distribution over k categories, with k − 1 degrees of freedom. In a test of independence on a contingency table, each expected count is row total times column total over the grand total, with (r − 1)(c − 1) degrees of freedom.","origin":"Karl Pearson introduced the chi-square test in 1900; Ronald Fisher corrected the degrees of freedom for contingency tables in 1922.","implementations":[{"name":"scipy.stats.chisquare","library":"SciPy","note":"Chi-square goodness-of-fit test."},{"name":"scipy.stats.chi2_contingency","library":"SciPy","note":"Chi-square test of independence for a contingency table."},{"name":"=CHISQ.TEST()","library":"Excel","note":"p-value of a chi-square test from observed and expected ranges."}]},"S.18":{"spoken":[{"line":0,"text":"The covariance of X and Y equals the sum of the quantity x sub i minus x bar times the quantity y sub i minus y bar, all over n minus 1."},{"line":1,"text":"r equals the covariance of X and Y over s sub x times s sub y."},{"line":2,"text":"Negative 1 is less than or equal to r, which is less than or equal to 1."}],"terms":[{"term":"Cov(·,·)","meaning":"Sample covariance: takes two paired variables and returns the average product of their deviations, positive when they move together.","function":true},{"term":"X, Y","meaning":"The two quantitative variables measured on the same individuals.","function":false},{"term":"Σ","meaning":"Summation operator: adds the products of paired deviations over all n data points.","function":true},{"term":"xᵢ, yᵢ","meaning":"The i-th paired observations of X and Y.","function":false},{"term":"x̄, ȳ","meaning":"The sample means of X and Y, from which each deviation is measured.","function":false},{"term":"n","meaning":"The number of paired observations; n − 1 is the divisor for sample covariance.","function":false},{"term":"r","meaning":"The correlation coefficient: covariance rescaled by both standard deviations, a unitless measure of linear association between −1 and 1.","function":false},{"term":"s_x, s_y","meaning":"The sample standard deviations of X and Y.","function":false}],"explanation":"Covariance measures whether two variables move together, averaging the products of their deviations from their means; its sign shows direction but its size depends on units. Dividing by both standard deviations gives Pearson's correlation r, a unitless measure of linear association that always lies between −1 and 1. A strong correlation shows association only, not that one variable causes the other.","origin":"Francis Galton developed the idea of correlation in 1888; Karl Pearson gave the product-moment formula in 1896.","implementations":[{"name":"numpy.cov","library":"NumPy","note":"Covariance matrix of variables."},{"name":"numpy.corrcoef","library":"NumPy","note":"Pearson correlation coefficient matrix."},{"name":"scipy.stats.pearsonr","library":"SciPy","note":"Pearson's r with a p-value."},{"name":"=CORREL()","library":"Excel","note":"Correlation coefficient of two ranges."}]},"S.19":{"spoken":[{"line":0,"text":"y hat equals b sub 0 plus b sub 1 x."},{"line":1,"text":"b sub 1 equals r times s sub y over s sub x. b sub 0 equals y bar minus b sub 1 x bar."},{"line":2,"text":"R squared equals 1 minus S S sub res over S S sub tot."},{"line":3,"text":"Vector beta hat equals the quantity matrix X transpose X, inverse, times X transpose times vector y."}],"terms":[{"term":"ŷ","meaning":"The predicted (fitted) value of the response y from the regression line.","function":false},{"term":"b₀","meaning":"The intercept: the predicted y when x equals 0.","function":false},{"term":"b₁","meaning":"The slope: the predicted change in y for each one-unit increase in x.","function":false},{"term":"x","meaning":"The explanatory (predictor) variable whose value is plugged in to predict y.","function":false},{"term":"r","meaning":"The correlation coefficient between x and y, which sets the sign and strength of the slope.","function":false},{"term":"s_y, s_x","meaning":"The sample standard deviations of y and x.","function":false},{"term":"ȳ, x̄","meaning":"The sample means of y and x; the line passes through the point (x̄, ȳ).","function":false},{"term":"R²","meaning":"The coefficient of determination: the fraction of the variation in y explained by the regression.","function":false},{"term":"SS_res","meaning":"The residual sum of squares: the sum of squared differences between observed and predicted y values.","function":false},{"term":"SS_tot","meaning":"The total sum of squares: the sum of squared differences between observed y values and their mean.","function":false},{"term":"β̂","meaning":"The vector of least-squares coefficient estimates in multiple regression.","function":false},{"term":"X","meaning":"The design matrix: one row per observation, one column per predictor, usually with a column of ones for the intercept.","function":false},{"term":"Xᵀ","meaning":"The transpose of the design matrix, with rows and columns swapped.","function":true},{"term":"(XᵀX)⁻¹","meaning":"The inverse of the matrix XᵀX, which exists when the columns of X are linearly independent.","function":true},{"term":"y","meaning":"The vector of observed response values, one entry per observation in the data set.","function":false}],"explanation":"Least-squares regression fits the line ŷ = b₀ + b₁x that minimizes the sum of squared residuals. The slope is the correlation scaled by the ratio of standard deviations, and the intercept forces the line through the point of means. R² is the fraction of variance in y explained by the model. With many predictors the same idea is written in matrix form as the normal-equation solution β̂ = (XᵀX)⁻¹Xᵀy.","origin":"Adrien-Marie Legendre published least squares in 1805 and Carl Friedrich Gauss in 1809; Francis Galton coined the term regression in the 1880s.","implementations":[{"name":"scipy.stats.linregress","library":"SciPy","note":"Simple linear regression with slope, intercept and r."},{"name":"sklearn.linear_model.LinearRegression","library":"scikit-learn","note":"Ordinary least squares regression estimator."},{"name":"statsmodels.api.OLS","library":"statsmodels","note":"OLS regression with full statistical summary."},{"name":"numpy.linalg.lstsq","library":"NumPy","note":"Least-squares solution to a linear system."}]},"S.20":{"spoken":[{"line":0,"text":"Uniform: f equals one over the quantity b minus a."},{"line":1,"text":"Mu equals the quantity a plus b over 2, sigma squared equals the quantity b minus a squared, over 12."},{"line":2,"text":"Exp.: f equals lambda e to the negative lambda x, F equals 1 minus e to the negative lambda x."},{"line":3,"text":"Mu equals one over lambda, sigma squared equals one over lambda squared."}],"terms":[{"term":"f","meaning":"The probability density function; constant 1/(b − a) for the uniform, λe^(−λx) for x ≥ 0 for the exponential.","function":true},{"term":"a","meaning":"The lower endpoint of the interval on which the uniform distribution lives.","function":false},{"term":"b","meaning":"The upper endpoint of the uniform distribution's interval.","function":false},{"term":"μ","meaning":"The mean of the distribution: the midpoint (a + b)/2 for uniform, 1/λ for exponential.","function":false},{"term":"σ²","meaning":"The variance of the distribution: (b − a)²/12 for uniform, 1/λ² for exponential.","function":false},{"term":"λ","meaning":"The exponential rate parameter: the average number of events per unit time; the mean waiting time is 1/λ.","function":false},{"term":"e","meaning":"Euler's number, about 2.71828, the base of the exponential function.","function":false},{"term":"x","meaning":"A value of the random variable, here a waiting time, x ≥ 0 for the exponential.","function":false},{"term":"F","meaning":"The cumulative distribution function: takes x and returns P(X ≤ x), here 1 − e^(−λx) for the exponential.","function":true}],"explanation":"The continuous uniform distribution gives every value in [a, b] equal density 1/(b − a), so its mean is the midpoint and its variance is (b − a)²/12. The exponential distribution models waiting times between events of a Poisson process with rate λ; its CDF 1 − e^(−λx) gives the chance of waiting at most x. It has mean 1/λ and is memoryless: past waiting does not change future waiting.","origin":"","implementations":[{"name":"scipy.stats.uniform","library":"SciPy","note":"Continuous uniform distribution on [loc, loc + scale]."},{"name":"scipy.stats.expon","library":"SciPy","note":"Exponential distribution with pdf, cdf and sampling."},{"name":"numpy.random.exponential","library":"NumPy","note":"Draws samples from an exponential distribution."},{"name":"=EXPON.DIST()","library":"Excel","note":"Exponential density or cumulative probability."}]},"S.21":{"spoken":[{"line":0,"text":"L of theta equals the product from i equals 1 to n of f of x sub i given theta."},{"line":1,"text":"Little ell of theta equals the sum of the natural log of f of x sub i given theta."},{"line":2,"text":"Theta hat: d ell d theta equals 0."}],"terms":[{"term":"L(θ)","meaning":"The likelihood function: takes a parameter value θ and returns the joint probability or density of the observed data under that θ.","function":true},{"term":"θ","meaning":"The unknown parameter (or parameters) of the model being estimated.","function":false},{"term":"∏","meaning":"Product operator: multiplies the indexed terms together over the stated range, here the densities of the n independent observations.","function":true},{"term":"i","meaning":"The index running over the observations from 1 to n.","function":false},{"term":"n","meaning":"The number of independent observations in the sample, the number of factors in the product.","function":false},{"term":"f(xᵢ | θ)","meaning":"The probability mass or density of observation xᵢ when the parameter equals θ.","function":true},{"term":"xᵢ","meaning":"The i-th observed data value, assumed independent of the other observations.","function":false},{"term":"ℓ(θ)","meaning":"The log-likelihood, ln L(θ): turns the product into a sum and has the same maximizer as L.","function":true},{"term":"Σ","meaning":"Summation operator: adds the log densities over all n observations.","function":true},{"term":"ln","meaning":"Natural logarithm: takes a positive number and returns its logarithm base e, turning products into sums.","function":true},{"term":"θ̂","meaning":"The maximum likelihood estimate: the parameter value that maximizes the likelihood of the observed data.","function":false},{"term":"dℓ/dθ","meaning":"The derivative of the log-likelihood with respect to θ (the score); setting it to zero locates the maximum.","function":true}],"explanation":"Maximum likelihood estimation chooses the parameter value θ̂ that makes the observed data most probable. For independent observations the likelihood is a product of densities; taking logs turns it into a sum, which is easier to differentiate and has the same maximizer. Setting the derivative of the log-likelihood to zero, or maximizing it numerically, gives the estimate, which is consistent and asymptotically efficient under mild conditions.","origin":"Ronald Fisher developed and named maximum likelihood between 1912 and 1922.","implementations":[{"name":"scipy.stats.rv_continuous.fit","library":"SciPy","note":"Fits distribution parameters to data by maximum likelihood."},{"name":"scipy.optimize.minimize","library":"SciPy","note":"Minimizes a function, e.g. a negative log-likelihood."},{"name":"statsmodels.base.model.GenericLikelihoodModel","library":"statsmodels","note":"Framework for custom maximum likelihood models."}]},"LA.1":{"spoken":[{"line":0,"text":"Vector v equals c sub 1 vector v sub 1 plus c sub 2 vector v sub 2 plus and so on plus c sub k vector v sub k."},{"line":1,"text":"Vector u plus vector v equals the vector u sub 1 plus v sub 1, and so on. c times vector v equals the vector c v sub 1, and so on."}],"terms":[{"term":"v","meaning":"The vector formed as a linear combination of the vectors v₁ through v_k.","function":false},{"term":"c₁, c₂, …, c_k","meaning":"Scalar coefficients (weights) multiplying each vector in the linear combination.","function":false},{"term":"v₁, v₂, …, v_k","meaning":"The given vectors being scaled and added together.","function":false},{"term":"k","meaning":"The number of vectors in the linear combination.","function":false},{"term":"⋯","meaning":"Continuation: the same pattern of scaled vectors continues up to the k-th term.","function":false},{"term":"u","meaning":"A vector added to v component by component.","function":false},{"term":"u₁, v₁","meaning":"The first components of vectors u and v.","function":false},{"term":"…","meaning":"The remaining components, handled the same way as the first.","function":false},{"term":"c","meaning":"A scalar multiplying every component of v, stretching, shrinking, or flipping it.","function":false}],"explanation":"A linear combination multiplies vectors by scalars and adds the results, the basic operation of linear algebra. Vector addition and scalar multiplication act component by component: adding places vectors tip to tail, and scaling stretches a vector, flipping it if the scalar is negative. Every question about span, independence and solving Ax = b is ultimately a question about which linear combinations are possible.","origin":"Hermann Grassmann developed the algebra of linear combinations of vectors in his 1844 Ausdehnungslehre.","implementations":[{"name":"numpy.add","library":"NumPy","note":"Element-wise addition of arrays."},{"name":"numpy.multiply","library":"NumPy","note":"Element-wise multiplication, including scalar times vector."},{"name":"numpy.matmul","library":"NumPy","note":"Matrix times coefficient vector gives a linear combination of columns."}]},"LA.2":{"spoken":[{"line":0,"text":"c sub 1 vector v sub 1 plus and so on plus c sub k vector v sub k equals zero implies all c sub i equal zero."},{"line":1,"text":"Basis equals independent plus spanning."},{"line":2,"text":"Dim equals the number of basis vectors."}],"terms":[{"term":"c₁, …, c_k","meaning":"Scalar coefficients in a linear combination set equal to the zero vector.","function":false},{"term":"v₁, …, v_k","meaning":"The vectors being tested for linear independence; none can be built from the others.","function":false},{"term":"k","meaning":"The number of vectors in the set being tested for independence.","function":false},{"term":"0","meaning":"The zero vector, the target of the linear combination in the independence test.","function":false},{"term":"⇒","meaning":"Implies: if the left side holds, the right side must hold; here it defines linear independence.","function":false},{"term":"cᵢ","meaning":"Any one of the coefficients; all must be zero for the vectors to be independent.","function":false},{"term":"basis","meaning":"A set of vectors that is linearly independent and spans the space.","function":false},{"term":"dim","meaning":"Dimension: takes a vector space and returns the number of vectors in any basis for it.","function":true},{"term":"#","meaning":"Number of: the count of vectors in a basis.","function":false}],"explanation":"The span of a set of vectors is everything reachable by linear combinations of them. The vectors are linearly independent if the only combination giving the zero vector uses all zero coefficients, meaning none is redundant. A basis is a set that is both independent and spanning, and every basis of a space has the same number of vectors, called its dimension.","origin":"Hermann Grassmann developed these ideas in 1844; Giuseppe Peano gave the first axiomatic definition of a vector space in 1888.","implementations":[{"name":"numpy.linalg.matrix_rank","library":"NumPy","note":"Rank, i.e. number of independent columns."},{"name":"scipy.linalg.orth","library":"SciPy","note":"Orthonormal basis for the range of a matrix."},{"name":"sympy.Matrix.columnspace","library":"SymPy","note":"Basis vectors for the column space."}]},"LA.3":{"spoken":[{"line":0,"text":"Vector v equals P times the coordinate vector of v with respect to B. The coordinate vector of v with respect to B equals P inverse times vector v."},{"line":1,"text":"P equals the matrix with columns vector b sub 1, vector b sub 2, and so on."},{"line":2,"text":"The matrix of A with respect to B equals P inverse A P."}],"terms":[{"term":"v","meaning":"A vector written in standard coordinates, the same vector whatever basis describes it.","function":false},{"term":"P","meaning":"The change-of-basis matrix whose columns are the basis vectors of B; it converts B-coordinates to standard coordinates.","function":false},{"term":"[v]_B","meaning":"The coordinate vector of v relative to basis B: the weights that combine the B basis vectors to give v.","function":false},{"term":"B","meaning":"A new basis for the space, consisting of the vectors b₁, b₂, and so on.","function":false},{"term":"P⁻¹","meaning":"The inverse of P: converts standard coordinates into B-coordinates.","function":true},{"term":"b₁, b₂, …","meaning":"The vectors of the basis B, placed as the columns of P.","function":false},{"term":"A","meaning":"A matrix representing a linear transformation in standard coordinates.","function":false},{"term":"[A]_B","meaning":"The matrix of the same linear transformation expressed in B-coordinates, similar to A.","function":false}],"explanation":"A change of basis re-expresses the same vector in different coordinates. The matrix P whose columns are the new basis vectors converts B-coordinates into standard coordinates, and P⁻¹ converts back. A linear map represented by A in the standard basis is represented by P⁻¹AP in the new basis, a similar matrix describing the same transformation, which is the idea behind diagonalization.","origin":"","implementations":[{"name":"numpy.linalg.solve","library":"NumPy","note":"Solves P c = v to find coordinates in a new basis."},{"name":"numpy.linalg.inv","library":"NumPy","note":"Inverse of the change-of-basis matrix."}]},"LA.4":{"spoken":[{"line":0,"text":"T of the quantity a vector u plus b vector v equals a T of vector u plus b T of vector v."},{"line":1,"text":"A equals the matrix with columns T of vector e sub 1 through T of vector e sub n."},{"line":2,"text":"T of vector x equals matrix A vector x."}],"terms":[{"term":"T","meaning":"A linear transformation: takes a vector as input and returns a vector, preserving addition and scalar multiplication.","function":true},{"term":"a, b","meaning":"Arbitrary scalars multiplying the input vectors in the linearity condition.","function":false},{"term":"u, v","meaning":"Arbitrary input vectors in the domain of the transformation T.","function":false},{"term":"A","meaning":"The standard matrix of T, whose j-th column is T applied to the j-th standard basis vector.","function":false},{"term":"e₁, …, e_n","meaning":"The standard basis vectors: eⱼ has a 1 in position j and 0 elsewhere.","function":false},{"term":"n","meaning":"The dimension of the input space, the number of columns of A.","function":false},{"term":"x","meaning":"An input vector, transformed by multiplying by A.","function":false}],"explanation":"A linear transformation preserves addition and scalar multiplication, so it is completely determined by where it sends the basis vectors. Placing the images T(e₁), …, T(eₙ) as columns gives the standard matrix A, and then applying T to any vector is just the product Ax. Composition of transformations corresponds to matrix multiplication.","origin":"Arthur Cayley's 1858 memoir on the theory of matrices developed matrices as representations of linear transformations.","implementations":[{"name":"numpy.matmul","library":"NumPy","note":"Applies a matrix to a vector or composes matrices."},{"name":"scipy.sparse.linalg.LinearOperator","library":"SciPy","note":"Represents a linear map by its action on vectors."}]},"LA.5":{"spoken":[{"line":0,"text":"The augmented matrix A, with b as an extra column goes to row echelon form."}],"terms":[{"term":"[A | b]","meaning":"The augmented matrix: the coefficient matrix A with the right-hand-side vector b attached as an extra column.","function":false},{"term":"A","meaning":"The coefficient matrix of the linear system A x = b.","function":false},{"term":"b","meaning":"The vector of constants on the right-hand side of the system.","function":false},{"term":"→","meaning":"Row-reduces to: applying elementary row operations transforms the matrix into the stated form.","function":false},{"term":"row echelon form","meaning":"A staircase form where each pivot lies to the right of the pivot above and rows of zeros are at the bottom.","function":false}],"explanation":"Gaussian elimination solves a linear system by applying row operations to the augmented matrix [A | b]: swapping rows, scaling a row and adding a multiple of one row to another. These operations do not change the solution set, and they reduce the matrix to row echelon form, from which back-substitution gives the answer. The pivot pattern reveals whether there is a unique solution, none, or infinitely many.","origin":"The method appears in the ancient Chinese text The Nine Chapters on the Mathematical Art; it is named after Carl Friedrich Gauss, who used it in the early 1800s.","implementations":[{"name":"numpy.linalg.solve","library":"NumPy","note":"Solves a square linear system via LU factorization."},{"name":"scipy.linalg.lu","library":"SciPy","note":"LU decomposition with partial pivoting."},{"name":"sympy.Matrix.rref","library":"SymPy","note":"Reduced row echelon form and pivot columns."}]},"LA.6":{"spoken":[{"line":0,"text":"The rank of A equals the dimension of the column space of A."},{"line":1,"text":"The null space of A equals the set of vectors x such that matrix A vector x equals zero."},{"line":2,"text":"The rank of A plus the nullity of A equals n."}],"terms":[{"term":"rank","meaning":"Rank: takes a matrix and returns the number of linearly independent columns, equal to the number of pivots.","function":true},{"term":"A","meaning":"An m by n matrix whose rank, column space and null space are described.","function":false},{"term":"dim","meaning":"Dimension: takes a subspace and returns the number of vectors in a basis for it.","function":true},{"term":"Col A","meaning":"The column space of A: the set of all linear combinations of A's columns, the outputs A x.","function":true},{"term":"Null A","meaning":"The null space of A: the set of all vectors x that A sends to the zero vector.","function":true},{"term":"x","meaning":"A vector in the input space of A.","function":false},{"term":"{ : }","meaning":"Set-builder notation: the set of all x satisfying the condition after the colon.","function":false},{"term":"0","meaning":"The zero vector in the output space of A, which defines the null space.","function":false},{"term":"nullity","meaning":"Nullity: takes a matrix and returns the dimension of its null space, the number of free variables.","function":true},{"term":"n","meaning":"The number of columns of A, the dimension of its input space.","function":false}],"explanation":"The column space of A is the set of all outputs Ax, and its dimension is the rank. The null space is the set of inputs sent to zero. The rank–nullity theorem says these trade off exactly: for an m × n matrix, rank plus nullity equals n, the number of columns, because each column is either a pivot column or corresponds to a free variable.","origin":"","implementations":[{"name":"numpy.linalg.matrix_rank","library":"NumPy","note":"Rank of a matrix via SVD."},{"name":"scipy.linalg.null_space","library":"SciPy","note":"Orthonormal basis for the null space."},{"name":"scipy.linalg.orth","library":"SciPy","note":"Orthonormal basis for the column space."},{"name":"sympy.Matrix.nullspace","library":"SymPy","note":"Exact basis vectors for the null space."}]},"LA.7":{"spoken":[{"line":0,"text":"Vector u is perpendicular to vector v if and only if u dot v equals zero."},{"line":1,"text":"Vector b hat equals A times the quantity A transpose A, inverse, times A transpose times vector b."},{"line":2,"text":"A transpose A times vector x hat equals A transpose times vector b."},{"line":3,"text":"Q transpose Q equals I."}],"terms":[{"term":"u, v","meaning":"Two vectors in the same space, tested for perpendicularity by their dot product.","function":false},{"term":"⟂","meaning":"Is orthogonal (perpendicular) to: the two vectors meet at a right angle.","function":false},{"term":"⟺","meaning":"If and only if: the two statements are equivalent.","function":false},{"term":"·","meaning":"The dot product: takes two vectors and returns the sum of products of their components, a scalar.","function":true},{"term":"b̂","meaning":"The orthogonal projection of b onto the column space of A, the closest point to b in that space.","function":false},{"term":"A","meaning":"A matrix with linearly independent columns whose column space is projected onto.","function":false},{"term":"Aᵀ","meaning":"The transpose of A, rows and columns swapped.","function":true},{"term":"(AᵀA)⁻¹","meaning":"The inverse of the Gram matrix AᵀA, which exists when A has independent columns.","function":true},{"term":"b","meaning":"The target vector being projected onto the column space or approximated by least squares.","function":false},{"term":"x̂","meaning":"The least-squares solution: the coefficients that minimize the length of b − A x.","function":false},{"term":"Q","meaning":"A matrix with orthonormal columns: each column has length 1 and is perpendicular to the others.","function":false},{"term":"Qᵀ","meaning":"The transpose of Q, which acts as a left inverse of Q because its columns are orthonormal.","function":true},{"term":"I","meaning":"The identity matrix, with ones on the diagonal and zeros elsewhere.","function":false}],"explanation":"Two vectors are orthogonal when their dot product is zero. Projecting b onto the column space of A gives the closest point b̂, and the residual b − Ab̂ is perpendicular to every column. That orthogonality condition yields the normal equations AᵀAx̂ = Aᵀb, whose solution is the least-squares fit when Ax = b has no exact solution. Matrices with orthonormal columns satisfy QᵀQ = I, which simplifies projection.","origin":"Adrien-Marie Legendre published the method of least squares in 1805; Carl Friedrich Gauss published his version in 1809.","implementations":[{"name":"numpy.linalg.lstsq","library":"NumPy","note":"Least-squares solution to Ax = b."},{"name":"scipy.linalg.lstsq","library":"SciPy","note":"Least-squares solution with selectable LAPACK driver."},{"name":"numpy.linalg.qr","library":"NumPy","note":"QR factorization, a stable route to least squares."}]},"LA.8":{"spoken":[{"line":0,"text":"Vector u sub 1 equals vector v sub 1."},{"line":1,"text":"Vector u sub k equals vector v sub k minus the sum over j less than k of the projection onto vector u sub j of vector v sub k."},{"line":2,"text":"Vector q sub k equals vector u sub k over the norm of vector u sub k. A equals Q R."}],"terms":[{"term":"u₁","meaning":"The first orthogonal vector, taken to be v₁ itself.","function":false},{"term":"v₁","meaning":"The first of the original linearly independent vectors.","function":false},{"term":"u_k","meaning":"The k-th orthogonal vector: v_k with its components along all earlier u's removed.","function":false},{"term":"v_k","meaning":"The k-th original vector being orthogonalized against the earlier orthogonal vectors.","function":false},{"term":"Σ","meaning":"Summation operator: adds the projections of v_k onto each earlier vector uⱼ for j less than k.","function":true},{"term":"j","meaning":"The index over earlier vectors, j less than k.","function":false},{"term":"proj_uⱼ","meaning":"Projection onto uⱼ: takes a vector and returns its component along uⱼ, (v·uⱼ)/(uⱼ·uⱼ) times uⱼ.","function":true},{"term":"q_k","meaning":"The k-th orthonormal vector: u_k scaled to unit length.","function":false},{"term":"‖·‖","meaning":"Euclidean norm: takes a vector and returns its length, the square root of the sum of squared components.","function":true},{"term":"A","meaning":"The matrix whose columns are the original vectors v₁, v₂, and so on.","function":false},{"term":"Q","meaning":"The matrix whose columns are the orthonormal vectors q₁, q₂, and so on.","function":false},{"term":"R","meaning":"An upper triangular matrix holding the coefficients that rebuild A's columns from Q's columns.","function":false}],"explanation":"Gram–Schmidt turns a set of independent vectors into an orthonormal set spanning the same space. Each new vector has its projections onto the earlier ones subtracted, leaving only the perpendicular part, and is then divided by its length. Recording the coefficients gives the QR factorization A = QR, with Q orthonormal and R upper triangular, used for least squares and eigenvalue algorithms.","origin":"Jørgen Pedersen Gram published the procedure in 1883 and Erhard Schmidt in 1907.","implementations":[{"name":"numpy.linalg.qr","library":"NumPy","note":"QR factorization of a matrix."},{"name":"scipy.linalg.qr","library":"SciPy","note":"QR factorization with optional pivoting."}]},"LA.9":{"spoken":[{"line":0,"text":"Matrix A vector v equals lambda vector v, vector v is not equal to zero."},{"line":1,"text":"The determinant of the quantity A minus lambda I equals zero."},{"line":2,"text":"The trace of A equals the sum of lambda sub i. The determinant of A equals the product of lambda sub i."}],"terms":[{"term":"A","meaning":"A square n by n matrix whose eigenvalues and eigenvectors are sought.","function":false},{"term":"v","meaning":"An eigenvector: a nonzero vector whose direction is unchanged by A, only scaled.","function":false},{"term":"λ","meaning":"An eigenvalue: the scalar factor by which A stretches its eigenvector.","function":false},{"term":"0","meaning":"The zero vector (or the number zero in the characteristic equation).","function":false},{"term":"det","meaning":"Determinant: takes a square matrix and returns a scalar; det(A − λI) = 0 is the characteristic equation for eigenvalues.","function":true},{"term":"I","meaning":"The identity matrix of the same size as A.","function":false},{"term":"tr","meaning":"Trace: takes a square matrix and returns the sum of its diagonal entries, which equals the sum of eigenvalues.","function":true},{"term":"Σ","meaning":"Summation operator: adds all the eigenvalues, counted with multiplicity.","function":true},{"term":"λᵢ","meaning":"The i-th eigenvalue of A, counted with algebraic multiplicity and possibly complex.","function":false},{"term":"∏","meaning":"Product operator: multiplies all the eigenvalues together, counted with multiplicity.","function":true}],"explanation":"An eigenvector of A is a nonzero vector whose direction is unchanged by A, only scaled by the eigenvalue λ. Rewriting Av = λv as (A − λI)v = 0 shows a nonzero solution exists only when A − λI is singular, so the eigenvalues are roots of the characteristic equation det(A − λI) = 0. The eigenvalues sum to the trace and multiply to the determinant.","origin":"Augustin-Louis Cauchy studied characteristic equations in 1829; David Hilbert introduced the German prefix eigen in this sense around 1904.","implementations":[{"name":"numpy.linalg.eig","library":"NumPy","note":"Eigenvalues and right eigenvectors of a square matrix."},{"name":"numpy.linalg.eigh","library":"NumPy","note":"Eigen-decomposition for symmetric or Hermitian matrices."},{"name":"numpy.linalg.eigvals","library":"NumPy","note":"Eigenvalues only of a square matrix."},{"name":"scipy.linalg.eig","library":"SciPy","note":"General or generalized eigenvalue problem."}]},"LA.10":{"spoken":[{"line":0,"text":"A equals P D P inverse."},{"line":1,"text":"A to the k equals P D to the k P inverse."},{"line":2,"text":"Symmetric: A equals Q capital Lambda Q transpose."}],"terms":[{"term":"A","meaning":"A diagonalizable square matrix, one with a full set of linearly independent eigenvectors.","function":false},{"term":"P","meaning":"The matrix whose columns are eigenvectors of A.","function":false},{"term":"D","meaning":"The diagonal matrix of A's eigenvalues, in the same order as the eigenvector columns of P.","function":false},{"term":"P⁻¹","meaning":"The inverse of P, converting standard coordinates into eigenvector coordinates.","function":true},{"term":"Aᵏ","meaning":"A raised to the k-th power, A multiplied by itself k times.","function":false},{"term":"k","meaning":"A positive integer exponent giving how many times A is multiplied by itself.","function":false},{"term":"Dᵏ","meaning":"The k-th power of D, found by raising each diagonal eigenvalue to the k-th power.","function":false},{"term":"Q","meaning":"An orthogonal matrix whose columns are orthonormal eigenvectors of the symmetric matrix A.","function":false},{"term":"Λ","meaning":"The diagonal matrix of eigenvalues of the symmetric matrix A, all real.","function":false},{"term":"Qᵀ","meaning":"The transpose of Q, which equals its inverse.","function":true}],"explanation":"A matrix with n independent eigenvectors can be written A = PDP⁻¹, with the eigenvectors as columns of P and eigenvalues on the diagonal of D. In that eigenbasis the matrix just scales each axis, so powers collapse to Aᵏ = PDᵏP⁻¹, where Dᵏ raises each eigenvalue to the k-th power. Real symmetric matrices can always be diagonalized by an orthogonal Q, the spectral theorem.","origin":"","implementations":[{"name":"numpy.linalg.eig","library":"NumPy","note":"Eigenvalues and eigenvectors for forming P and D."},{"name":"numpy.linalg.matrix_power","library":"NumPy","note":"Raises a square matrix to an integer power."},{"name":"numpy.linalg.eigh","library":"NumPy","note":"Orthogonal eigen-decomposition of a symmetric matrix."},{"name":"sympy.Matrix.diagonalize","library":"SymPy","note":"Returns P and D with A = PDP⁻¹."}]},"LA.11":{"spoken":[{"line":0,"text":"Vector x transpose A vector x is greater than zero for all vector x not equal to zero."},{"line":1,"text":"If and only if all lambda sub i are greater than zero."},{"line":2,"text":"If and only if the leading principal minors are greater than zero."}],"terms":[{"term":"xᵀ","meaning":"The transpose of the vector x, a row vector.","function":true},{"term":"A","meaning":"A symmetric matrix being tested for positive definiteness.","function":false},{"term":"x","meaning":"Any nonzero vector plugged into the quadratic form to test the sign.","function":false},{"term":"xᵀAx","meaning":"The quadratic form of A: takes a vector x and returns a scalar.","function":true},{"term":"∀","meaning":"For all: the inequality must hold for every nonzero vector x.","function":false},{"term":"0","meaning":"The zero vector (on the right) or the number zero (in the inequalities).","function":false},{"term":"⟺","meaning":"If and only if: each condition is equivalent to positive definiteness.","function":false},{"term":"λᵢ","meaning":"The eigenvalues of A; all positive exactly when A is positive definite.","function":false},{"term":"leading principal minors","meaning":"The determinants of the upper-left 1 by 1, 2 by 2, up to n by n submatrices of A (Sylvester's criterion).","function":false}],"explanation":"A symmetric matrix A is positive definite when the quadratic form xᵀAx is positive for every nonzero x, so its graph is an upward bowl with a unique minimum. Equivalent tests are that all eigenvalues are positive or that all leading principal minors are positive. Such matrices appear as covariance matrices and Hessians at minima, and they admit a Cholesky factorization.","origin":"The leading-minor test is known as Sylvester's criterion, after James Joseph Sylvester.","implementations":[{"name":"numpy.linalg.cholesky","library":"NumPy","note":"Cholesky factor; fails if the matrix is not positive definite."},{"name":"numpy.linalg.eigvalsh","library":"NumPy","note":"Eigenvalues of a symmetric matrix, to check signs."},{"name":"scipy.linalg.cholesky","library":"SciPy","note":"Cholesky decomposition of a positive definite matrix."}]},"LA.12":{"spoken":[{"line":0,"text":"A equals U capital Sigma V transpose."},{"line":1,"text":"Sigma sub i equals the square root of lambda sub i of A transpose A."},{"line":2,"text":"A sub k equals the sum from i equals 1 to k of sigma sub i vector u sub i vector v sub i transpose. Best rank k."}],"terms":[{"term":"A","meaning":"Any m by n matrix being factored; every real matrix has an SVD.","function":false},{"term":"U","meaning":"An orthogonal matrix whose columns are the left singular vectors of A.","function":false},{"term":"Σ","meaning":"Here a matrix, not a sum: the m by n diagonal matrix of nonnegative singular values in decreasing order.","function":false},{"term":"Vᵀ","meaning":"The transpose of the orthogonal matrix V whose columns are the right singular vectors of A.","function":true},{"term":"σᵢ","meaning":"The i-th singular value of A, the stretch factor along the i-th singular direction.","function":false},{"term":"√","meaning":"Square root: takes a nonnegative eigenvalue of AᵀA and returns the corresponding singular value.","function":true},{"term":"λᵢ(AᵀA)","meaning":"The i-th eigenvalue of the matrix AᵀA, which is symmetric with nonnegative eigenvalues.","function":true},{"term":"Aᵀ","meaning":"The transpose of A, used to form the symmetric matrix AᵀA.","function":true},{"term":"A_k","meaning":"The truncated SVD: the best rank-k approximation of A in the 2-norm and Frobenius norm.","function":false},{"term":"∑","meaning":"Summation operator: adds the first k rank-one pieces σᵢuᵢvᵢᵀ.","function":true},{"term":"i","meaning":"The index over singular values from 1 to k.","function":false},{"term":"k","meaning":"The number of singular values kept, the rank of the approximation.","function":false},{"term":"uᵢ","meaning":"The i-th left singular vector, the i-th column of U.","function":false},{"term":"vᵢᵀ","meaning":"The transpose of the i-th right singular vector, making uᵢvᵢᵀ a rank-one matrix.","function":false}],"explanation":"The singular value decomposition factors any matrix as A = UΣVᵀ: a rotation, a scaling along axes, and another rotation. The singular values on Σ's diagonal are the square roots of the eigenvalues of AᵀA. Keeping only the k largest terms of the sum of rank-one pieces σᵢuᵢvᵢᵀ gives the best rank-k approximation, the basis of PCA, compression and noise reduction.","origin":"Eugenio Beltrami (1873) and Camille Jordan (1874) discovered it independently; Carl Eckart and Gale Young proved the best low-rank approximation result in 1936.","implementations":[{"name":"numpy.linalg.svd","library":"NumPy","note":"Singular value decomposition of a matrix."},{"name":"scipy.linalg.svd","library":"SciPy","note":"SVD with selectable LAPACK driver."},{"name":"scipy.sparse.linalg.svds","library":"SciPy","note":"Largest k singular values of a sparse matrix."},{"name":"sklearn.decomposition.TruncatedSVD","library":"scikit-learn","note":"Rank-k approximation for dimensionality reduction."}]},"LA.13":{"spoken":[{"line":0,"text":"The 1-norm of vector x equals the sum of the absolute value of x sub i. The 2-norm of vector x equals the square root of the sum of x sub i squared. The infinity norm of vector x equals the max of the absolute value of x sub i."},{"line":1,"text":"The Frobenius norm of A equals the square root of the sum of a sub i j squared, equals the square root of the trace of A transpose A."},{"line":2,"text":"Kappa of A equals sigma max over sigma min."}],"terms":[{"term":"‖x‖₁","meaning":"The 1-norm: takes a vector and returns the sum of the absolute values of its components.","function":true},{"term":"x","meaning":"A vector whose size is being measured by different norms.","function":false},{"term":"Σ","meaning":"Summation operator: adds the indicated quantity over all components or entries.","function":true},{"term":"|·|","meaning":"Absolute value: takes a number and returns its distance from zero.","function":true},{"term":"xᵢ","meaning":"The i-th component of the vector x, a real number.","function":false},{"term":"‖x‖₂","meaning":"The 2-norm (Euclidean norm): takes a vector and returns its ordinary length.","function":true},{"term":"√","meaning":"Square root: takes a nonnegative number and returns its nonnegative square root.","function":true},{"term":"‖x‖∞","meaning":"The infinity norm: takes a vector and returns the largest absolute value among its components.","function":true},{"term":"max","meaning":"Maximum: takes a set of numbers and returns the largest.","function":true},{"term":"‖A‖_F","meaning":"The Frobenius norm: takes a matrix and returns the square root of the sum of squares of all its entries.","function":true},{"term":"A","meaning":"A matrix whose size is measured by the Frobenius norm and whose sensitivity is measured by κ.","function":false},{"term":"aᵢⱼ","meaning":"The entry of A in row i, column j.","function":false},{"term":"tr","meaning":"Trace: takes a square matrix and returns the sum of its diagonal entries.","function":true},{"term":"Aᵀ","meaning":"The transpose of A, used to form AᵀA whose trace is the sum of squared entries.","function":true},{"term":"κ(A)","meaning":"The condition number: takes a matrix and returns the ratio of its largest to smallest singular value, measuring sensitivity to errors.","function":true},{"term":"σ_max","meaning":"The largest singular value of A, the maximum stretch factor of A.","function":false},{"term":"σ_min","meaning":"The smallest singular value of A; near zero means A is nearly singular.","function":false}],"explanation":"Norms measure size: the 1-norm sums absolute values, the 2-norm is Euclidean length, and the ∞-norm takes the largest entry. The Frobenius norm treats a matrix as one long vector and equals the square root of tr(AᵀA). The condition number, the ratio of largest to smallest singular value, measures how much errors in the data can be amplified when solving Ax = b.","origin":"Alan Turing introduced the term condition number in 1948.","implementations":[{"name":"numpy.linalg.norm","library":"NumPy","note":"Vector or matrix norm; ord selects 1, 2, inf or 'fro'."},{"name":"numpy.linalg.cond","library":"NumPy","note":"Condition number of a matrix."},{"name":"numpy.trace","library":"NumPy","note":"Sum of the diagonal entries."}]},"LA.14":{"spoken":[{"line":0,"text":"A I equals I A equals A. A B is not equal to B A, in general."},{"line":1,"text":"The quantity A B, transpose, equals B transpose A transpose. The quantity A B, inverse, equals B inverse A inverse."},{"line":2,"text":"The determinant of A B equals the determinant of A times the determinant of B."},{"line":3,"text":"The trace of A B equals the trace of B A."}],"terms":[{"term":"A, B","meaning":"Matrices of compatible sizes for the products shown; square and invertible where inverses or determinants appear.","function":false},{"term":"I","meaning":"The identity matrix, which leaves any matrix unchanged under multiplication.","function":false},{"term":"≠","meaning":"Not equal: matrix multiplication is generally not commutative.","function":false},{"term":"ᵀ","meaning":"Transpose: takes a matrix and returns it with rows and columns swapped; a product's transpose reverses the order.","function":true},{"term":"⁻¹","meaning":"Inverse: takes an invertible square matrix and returns the matrix that multiplies with it to give I; a product's inverse reverses the order.","function":true},{"term":"det","meaning":"Determinant: takes a square matrix and returns a scalar; the determinant of a product is the product of determinants.","function":true},{"term":"tr","meaning":"Trace: takes a square matrix and returns the sum of its diagonal entries; it is unchanged by cyclically swapping a product.","function":true}],"explanation":"These identities are the working rules of matrix algebra. The identity matrix acts like 1, but multiplication is generally not commutative. Transposes and inverses of a product reverse the order of the factors, since the last operation applied must be undone first. Determinants multiply across products, and the trace is unchanged by cyclically swapping factors, so tr(AB) = tr(BA) even though AB ≠ BA.","origin":"Arthur Cayley set out the algebra of matrices, including non-commutative multiplication, in his 1858 memoir.","implementations":[{"name":"numpy.linalg.inv","library":"NumPy","note":"Inverse of a square matrix."},{"name":"numpy.linalg.det","library":"NumPy","note":"Determinant of a square matrix."},{"name":"numpy.transpose","library":"NumPy","note":"Transpose of an array."},{"name":"numpy.trace","library":"NumPy","note":"Trace of a matrix."}]},"LA.15":{"spoken":[{"line":0,"text":"Diagonal, triangular, symmetric: A equals A transpose."},{"line":1,"text":"Orthogonal: Q transpose Q equals I, Q inverse equals Q transpose."},{"line":2,"text":"Idempotent: P squared equals P. Nilpotent: N to the k equals zero."}],"terms":[{"term":"A","meaning":"A square matrix; it is symmetric when it equals its own transpose.","function":false},{"term":"Aᵀ","meaning":"The transpose of A, its rows and columns swapped.","function":true},{"term":"Q","meaning":"An orthogonal matrix: a square matrix whose columns are orthonormal, representing a rotation or reflection.","function":false},{"term":"Qᵀ","meaning":"The transpose of Q, which equals its inverse.","function":true},{"term":"I","meaning":"The identity matrix, with ones on the diagonal and zeros elsewhere.","function":false},{"term":"Q⁻¹","meaning":"The inverse of Q, which for an orthogonal matrix is simply its transpose.","function":true},{"term":"P","meaning":"An idempotent matrix, such as a projection: applying it twice is the same as applying it once.","function":false},{"term":"N","meaning":"A nilpotent matrix: some power of it is the zero matrix.","function":false},{"term":"k","meaning":"A positive integer power at which N becomes zero.","function":false},{"term":"0","meaning":"The zero matrix, every entry equal to zero.","function":false}],"explanation":"Certain matrix structures recur because they make computation easy. Diagonal and triangular matrices are solved by simple substitution; symmetric matrices equal their transpose and have real eigenvalues. Orthogonal matrices preserve lengths and angles, so their inverse is just the transpose. Idempotent matrices such as projections satisfy P² = P, and nilpotent matrices become zero after enough powers.","origin":"","implementations":[{"name":"numpy.diag","library":"NumPy","note":"Builds a diagonal matrix or extracts a diagonal."},{"name":"numpy.triu","library":"NumPy","note":"Upper-triangular part of a matrix."},{"name":"numpy.tril","library":"NumPy","note":"Lower-triangular part of a matrix."},{"name":"scipy.linalg.solve_triangular","library":"SciPy","note":"Solves a triangular system by substitution."}]},"LA.16":{"spoken":[{"line":0,"text":"Vector u transpose vector v, scalar. Vector u vector v transpose, rank-1 matrix."},{"line":1,"text":"The i j entry of A Hadamard B equals a sub i j times b sub i j."},{"line":2,"text":"A Kronecker B equals the block matrix with blocks a sub i j times B."},{"line":3,"text":"Matrix A vector x equals the sum over j of x sub j vector a sub j."}],"terms":[{"term":"uᵀv","meaning":"The inner product: a row vector times a column vector of the same length, giving a single scalar.","function":true},{"term":"u, v","meaning":"Column vectors; equal lengths for the inner product, any lengths for the outer product.","function":false},{"term":"uvᵀ","meaning":"The outer product: a column vector times a row vector, giving a rank-one matrix.","function":true},{"term":"⊙","meaning":"Hadamard product: takes two matrices of the same size and returns the matrix of entrywise products.","function":true},{"term":"A, B","meaning":"Matrices being combined; the same size for the Hadamard product, any sizes for the Kronecker product.","function":false},{"term":"i, j","meaning":"Row and column indices of an entry; in the last line j indexes the columns of A.","function":false},{"term":"aᵢⱼ, bᵢⱼ","meaning":"The entries of A and B in row i, column j.","function":false},{"term":"⊗","meaning":"Kronecker product: takes matrices A and B and returns the block matrix whose (i, j) block is aᵢⱼ times B.","function":true},{"term":"x","meaning":"A vector multiplying A, whose components weight the columns of A.","function":false},{"term":"Σ","meaning":"Summation operator: adds xⱼ times the j-th column of A over all columns.","function":true},{"term":"xⱼ","meaning":"The j-th component of x, the weight on the j-th column.","function":false},{"term":"aⱼ","meaning":"The j-th column of A, weighted by xⱼ in the column view of A x.","function":false}],"explanation":"These are the main ways to multiply vectors and matrices. The inner product uᵀv collapses two vectors to a scalar, while the outer product uvᵀ expands them into a rank-one matrix. The Hadamard product multiplies entries position by position, and the Kronecker product replaces each entry of A with a scaled copy of B. Writing Ax as a sum of columns weighted by xⱼ is the column view of multiplication.","origin":"","implementations":[{"name":"numpy.inner","library":"NumPy","note":"Inner product of two arrays."},{"name":"numpy.outer","library":"NumPy","note":"Outer product of two vectors."},{"name":"numpy.kron","library":"NumPy","note":"Kronecker product of two arrays."},{"name":"numpy.block","library":"NumPy","note":"Assembles a matrix from blocks."}]},"LA.17":{"spoken":[{"line":0,"text":"The gradient with respect to vector x of vector a transpose vector x equals vector a."},{"line":1,"text":"The gradient with respect to vector x of vector x transpose A vector x equals the quantity A plus A transpose, times vector x."},{"line":2,"text":"The gradient with respect to beta of the norm of vector y minus X beta, squared, equals negative 2 X transpose times the quantity vector y minus X beta."},{"line":3,"text":"The partial of the natural log of the determinant of X, with respect to X, equals X inverse transpose."}],"terms":[{"term":"∇ₓ","meaning":"Gradient with respect to x: takes a scalar function of a vector and returns the vector of its partial derivatives.","function":true},{"term":"a","meaning":"A constant vector that does not depend on x.","function":false},{"term":"aᵀ","meaning":"The transpose of a, so aᵀx is a scalar dot product.","function":true},{"term":"x","meaning":"The vector variable with respect to which the gradient is taken.","function":false},{"term":"A","meaning":"A constant square matrix in the quadratic form xᵀAx.","function":false},{"term":"Aᵀ","meaning":"The transpose of A; if A is symmetric the gradient simplifies to 2Ax.","function":true},{"term":"∇_β","meaning":"Gradient with respect to the coefficient vector β.","function":true},{"term":"‖·‖²","meaning":"Squared Euclidean norm: takes a vector and returns the sum of squares of its components, here the residual sum of squares.","function":true},{"term":"y","meaning":"The vector of observed responses in the least-squares regression problem.","function":false},{"term":"X","meaning":"In line 3, the design matrix of predictors; in line 4, an invertible square matrix variable.","function":false},{"term":"β","meaning":"The vector of regression coefficients, the variable of differentiation in least squares.","function":false},{"term":"Xᵀ","meaning":"The transpose of the design matrix, which carries the residual back into coefficient space.","function":true},{"term":"∂/∂X","meaning":"Matrix derivative: differentiates a scalar function with respect to each entry of X, giving a matrix of the same shape.","function":true},{"term":"ln","meaning":"Natural logarithm, applied here to the determinant of X.","function":true},{"term":"det","meaning":"Determinant: takes a square matrix and returns a scalar.","function":true},{"term":"X⁻ᵀ","meaning":"The inverse transpose of X, equal to (X⁻¹)ᵀ.","function":true}],"explanation":"Matrix calculus extends derivatives to vector and matrix variables, with results that mirror scalar rules. The gradient of a linear function aᵀx is a, and the gradient of a quadratic form is (A + Aᵀ)x, or 2Ax when A is symmetric. Applying these to the squared error ‖y − Xβ‖² and setting the gradient to zero yields the normal equations; the log-determinant identity appears in Gaussian likelihoods.","origin":"","implementations":[{"name":"jax.grad","library":"JAX","note":"Automatic gradient of a scalar function."},{"name":"torch.autograd.grad","library":"PyTorch","note":"Computes gradients of outputs with respect to inputs."}]},"LA.18":{"spoken":[{"line":0,"text":"A plus equals the quantity A transpose A, inverse, times A transpose. Full column rank."},{"line":1,"text":"A plus equals V capital Sigma plus U transpose."},{"line":2,"text":"The quantity A plus vector u vector v transpose, inverse, equals A inverse minus A inverse vector u vector v transpose A inverse, all over 1 plus vector v transpose A inverse vector u."}],"terms":[{"term":"A⁺","meaning":"The Moore–Penrose pseudoinverse of A: generalizes the inverse to nonsquare or singular matrices and gives least-squares solutions.","function":true},{"term":"A","meaning":"A matrix; in line 1 with full column rank, in line 3 square and invertible.","function":false},{"term":"Aᵀ","meaning":"The transpose of A, its rows and columns swapped.","function":true},{"term":"(AᵀA)⁻¹","meaning":"The inverse of AᵀA, which exists when A has full column rank.","function":true},{"term":"V","meaning":"The orthogonal matrix of right singular vectors from the SVD of A.","function":false},{"term":"Σ⁺","meaning":"The pseudoinverse of the singular-value matrix: transpose it and replace each nonzero singular value by its reciprocal.","function":true},{"term":"Uᵀ","meaning":"The transpose of the orthogonal matrix of left singular vectors of A.","function":true},{"term":"u, v","meaning":"Column vectors whose outer product uvᵀ is the rank-one update to A.","function":false},{"term":"vᵀ","meaning":"The transpose of v, a row vector used in the outer product and denominator.","function":true},{"term":"A⁻¹","meaning":"The inverse of A, assumed already known so the update is cheap.","function":true},{"term":"(A + uvᵀ)⁻¹","meaning":"The inverse of the rank-one-updated matrix, given by the Sherman–Morrison formula when the denominator is nonzero.","function":true}],"explanation":"The Moore–Penrose pseudoinverse A⁺ generalizes the inverse to non-square or singular matrices, giving the minimum-norm least-squares solution of Ax = b. For full column rank it equals (AᵀA)⁻¹Aᵀ, and in general it comes from the SVD by inverting the nonzero singular values. The Sherman–Morrison formula updates a known inverse after a rank-one change in O(n²) time instead of recomputing it.","origin":"E. H. Moore described the pseudoinverse in 1920 and Roger Penrose in 1955; Jack Sherman and Winifred Morrison published their update formula around 1950.","implementations":[{"name":"numpy.linalg.pinv","library":"NumPy","note":"Moore–Penrose pseudoinverse via SVD."},{"name":"scipy.linalg.pinv","library":"SciPy","note":"Moore–Penrose pseudoinverse of a matrix."}]},"ML.1":{"spoken":[{"line":0,"text":"theta hat equals the arg min over theta of one over n times the sum from i equals 1 to n of L of y sub i comma f sub theta of vector x sub i"},{"line":1,"text":"plus lambda R of theta"},{"line":2,"text":"supervised: vector x comma y"},{"line":3,"text":"unsupervised: vector x only"}],"terms":[{"term":"θ̂","meaning":"The fitted parameter vector: the value of theta that minimizes the average training loss plus the regularization penalty.","function":false},{"term":"arg min","meaning":"Operator that takes an objective as a function of theta and returns the parameter value at which that objective is smallest, not the minimum value itself.","function":true},{"term":"θ","meaning":"The model parameters (weights) being searched over during training.","function":false},{"term":"n","meaning":"The number of training examples in the dataset.","function":false},{"term":"Σ","meaning":"Summation operator: adds up the loss over every training example from i equals 1 to n.","function":true},{"term":"i","meaning":"Index that runs over the training examples, from 1 to n.","function":false},{"term":"L","meaning":"The loss function: takes a true label and a prediction and outputs a nonnegative number measuring how bad the prediction is.","function":true},{"term":"yᵢ","meaning":"The true target value or label for the i-th training example.","function":false},{"term":"f_θ","meaning":"The model: a function with parameters theta that maps an input feature vector to a prediction.","function":true},{"term":"𝐱ᵢ","meaning":"The feature vector (input) of the i-th training example.","function":false},{"term":"λ","meaning":"Regularization strength: a nonnegative tuning constant controlling how heavily the penalty R(θ) is weighted against the data fit.","function":false},{"term":"R","meaning":"The regularizer: a function of the parameters theta that outputs a penalty for complexity, such as the squared or absolute size of the weights.","function":true},{"term":"𝐱","meaning":"A feature vector (input); in unsupervised learning it is the only data available.","function":false},{"term":"y","meaning":"The label or target paired with each input in supervised learning.","function":false}],"explanation":"Learning is framed as choosing parameters θ that minimize the average loss L between true labels yᵢ and predictions f_θ(xᵢ) over the n training examples, the empirical risk. Adding a penalty λR(θ) discourages overly complex models so the fit generalizes beyond the sample. Supervised learning has labeled pairs (x, y); unsupervised learning sees only x and must find structure on its own.","origin":"Vladimir Vapnik and Alexey Chervonenkis formalized empirical risk minimization in statistical learning theory from the late 1960s onward.","implementations":[{"name":"sklearn.linear_model.SGDClassifier","library":"scikit-learn","note":"Minimizes regularized empirical loss for linear classifiers via SGD."},{"name":"sklearn.linear_model.SGDRegressor","library":"scikit-learn","note":"Minimizes regularized empirical loss for linear regression via SGD."}]},"ML.2":{"spoken":[{"line":0,"text":"MSE equals one over n times the sum of the quantity y minus y hat, squared"},{"line":1,"text":"MAE equals one over n times the sum of the absolute value of y minus y hat"},{"line":2,"text":"log-loss equals negative the quantity y times the natural log of p plus the quantity 1 minus y times the natural log of the quantity 1 minus p"},{"line":3,"text":"hinge equals the max of 0 and 1 minus y times f of vector x"}],"terms":[{"term":"MSE","meaning":"Mean squared error: the average of squared differences between true and predicted values; minimized by predicting the mean.","function":false},{"term":"n","meaning":"The number of observations whose errors are being averaged in MSE and MAE.","function":false},{"term":"Σ","meaning":"Summation operator: adds the per-observation errors over all n observations.","function":true},{"term":"y","meaning":"The true target value; in log-loss it is the 0 or 1 class label, in hinge loss it is the plus or minus 1 label.","function":false},{"term":"ŷ","meaning":"The model's predicted value for an observation, compared against the true value y.","function":false},{"term":"MAE","meaning":"Mean absolute error: the average of absolute differences between true and predicted values; minimized by predicting the median.","function":false},{"term":"| |","meaning":"Absolute value: takes a number and returns its size without sign, so over- and under-predictions count equally.","function":true},{"term":"log-loss","meaning":"Binary cross-entropy loss: penalizes a predicted probability by how little probability it gave to the true class.","function":false},{"term":"ln","meaning":"Natural logarithm: takes a positive number and returns its log base e; here applied to predicted probabilities.","function":true},{"term":"p","meaning":"The model's predicted probability that the label is 1.","function":false},{"term":"hinge","meaning":"Hinge loss used by support vector machines: zero when a point is correctly classified with margin at least 1, growing linearly otherwise.","function":false},{"term":"max","meaning":"Takes two numbers and returns the larger; here it clips the hinge loss at zero.","function":true},{"term":"f","meaning":"The classifier's real-valued score function; its sign gives the predicted class.","function":true},{"term":"𝐱","meaning":"The input feature vector of the observation being scored by the classifier f.","function":false}],"explanation":"A loss function scores how wrong a single prediction is, and training minimizes its average. MSE squares errors, so its optimal constant prediction is the mean; MAE uses absolute errors, giving the median and more robustness to outliers. Log-loss penalizes confident wrong probabilities for binary labels, and hinge loss, used by SVMs, is zero once a point is on the correct side with margin at least 1.","origin":"Adrien-Marie Legendre published least squares in 1805, with Gauss providing its probabilistic justification; hinge loss became standard with support vector machines in the 1990s.","implementations":[{"name":"sklearn.metrics.mean_squared_error","library":"scikit-learn","note":"Mean squared error between targets and predictions."},{"name":"sklearn.metrics.log_loss","library":"scikit-learn","note":"Binary or multiclass cross-entropy (log-loss) of predicted probabilities."},{"name":"sklearn.metrics.hinge_loss","library":"scikit-learn","note":"Average hinge loss for margin-based classifiers."},{"name":"torch.nn.MSELoss","library":"PyTorch","note":"Mean squared error loss module for training."}]},"ML.3":{"spoken":[{"line":0,"text":"H of p equals negative the sum over k of p sub k times log p sub k"},{"line":1,"text":"H of p comma q equals negative the sum over k of p sub k times log q sub k"},{"line":2,"text":"D sub KL of p parallel q equals the sum over k of p sub k times log of p sub k over q sub k, which is greater than or equal to 0"},{"line":3,"text":"H of p comma q equals H of p plus D sub KL"}],"terms":[{"term":"H(p)","meaning":"Entropy: a function taking a probability distribution p and returning its average surprise, the expected value of negative log p.","function":true},{"term":"p","meaning":"The true (or reference) probability distribution over the outcomes k.","function":false},{"term":"Σ","meaning":"Summation operator: adds the terms over all possible outcomes k.","function":true},{"term":"k","meaning":"Index running over the possible outcomes or classes of the distributions p and q.","function":false},{"term":"pₖ","meaning":"The probability that distribution p assigns to outcome k.","function":false},{"term":"log","meaning":"Logarithm (base 2 for bits or base e for nats): turns probabilities into information content.","function":true},{"term":"H(p, q)","meaning":"Cross-entropy: a function of two distributions giving the expected negative log of q's probabilities when outcomes are actually drawn from p.","function":true},{"term":"q","meaning":"The approximating or model distribution being compared against p.","function":false},{"term":"qₖ","meaning":"The probability that distribution q assigns to outcome k.","function":false},{"term":"D_KL","meaning":"Kullback-Leibler divergence: takes two distributions p and q and returns a nonnegative measure of how much q differs from p; zero only when they are equal.","function":true},{"term":"‖","meaning":"Separator inside the KL divergence indicating the first distribution is measured relative to the second; order matters.","function":false}],"explanation":"Entropy H(p) measures the average surprise, or information, in a distribution p. Cross-entropy H(p, q) is the average cost of encoding outcomes from p using a code built for q, and the KL divergence is the extra cost, always nonnegative and zero only when p = q. Hence H(p, q) = H(p) + D_KL(p‖q), so minimizing cross-entropy against fixed data minimizes KL. KL is asymmetric, so it is not a true distance.","origin":"Claude Shannon defined entropy in 1948; Solomon Kullback and Richard Leibler introduced their divergence in 1951.","implementations":[{"name":"scipy.stats.entropy","library":"SciPy","note":"Shannon entropy, or KL divergence when a second distribution is given."},{"name":"scipy.special.rel_entr","library":"SciPy","note":"Elementwise relative entropy terms p·log(p/q)."},{"name":"torch.nn.functional.kl_div","library":"PyTorch","note":"KL divergence loss between log-probabilities and target probabilities."},{"name":"torch.nn.KLDivLoss","library":"PyTorch","note":"Module form of the KL divergence loss."}]},"ML.4":{"spoken":[{"line":0,"text":"the expected value of the quantity y minus f hat, squared, equals Bias squared plus Var plus sigma squared"},{"line":1,"text":"Bias equals the expected value of f hat minus f"},{"line":2,"text":"underfit, double arrow, overfit"}],"terms":[{"term":"E","meaning":"Expectation operator: takes a random quantity and returns its average over random training sets and noise.","function":true},{"term":"y","meaning":"A new observed target value, equal to the true function plus random noise.","function":false},{"term":"f̂","meaning":"The fitted model's prediction, which varies depending on the training set drawn.","function":false},{"term":"Bias","meaning":"Systematic error: how far the average prediction across training sets is from the true function.","function":false},{"term":"Var","meaning":"Variance of the prediction: how much f hat fluctuates from one training set to another.","function":false},{"term":"σ²","meaning":"Irreducible error: the variance of the noise in y, which no model can remove.","function":false},{"term":"f","meaning":"The true underlying function that generates the data.","function":false},{"term":"↔","meaning":"Indicates the trade-off spectrum running from underfitting (high bias) to overfitting (high variance).","function":false}],"explanation":"The expected squared prediction error splits into three parts: squared bias, how far the average fitted model lies from the true function; variance, how much the fit changes across training sets; and irreducible noise σ². Simple models have high bias and underfit, while flexible models have high variance and overfit. Good model choice balances the two, since σ² cannot be reduced by any model.","origin":"Stuart Geman, Elie Bienenstock and René Doursat popularized the decomposition in machine learning in 1992.","implementations":[{"name":"mlxtend.evaluate.bias_variance_decomp","library":"mlxtend","note":"Estimates bias and variance of a model by bootstrap resampling."}]},"ML.5":{"spoken":[{"line":0,"text":"Ridge: min of the norm of vector y minus X beta, squared, plus lambda times the 2-norm of beta, squared"},{"line":1,"text":"beta hat equals the quantity X transpose X plus lambda I, inverse, times X transpose vector y"},{"line":2,"text":"Lasso: min of the norm of vector y minus X beta, squared, plus lambda times the 1-norm of beta"}],"terms":[{"term":"min","meaning":"Minimize: choose the coefficient vector beta that makes the penalized objective as small as possible.","function":true},{"term":"‖ ‖","meaning":"Norm: takes a vector and returns its length; squared it gives the residual sum of squares.","function":true},{"term":"𝐲","meaning":"The vector of observed responses for all n observations.","function":false},{"term":"X","meaning":"The design matrix whose rows are observations and columns are features.","function":false},{"term":"β","meaning":"The vector of regression coefficients being estimated, one per feature column of X.","function":false},{"term":"λ","meaning":"Regularization strength: a nonnegative constant setting how strongly coefficients are penalized.","function":false},{"term":"‖β‖₂²","meaning":"Squared L2 norm of the coefficients, the sum of squared coefficients; the ridge penalty that shrinks coefficients smoothly.","function":false},{"term":"β̂","meaning":"The ridge estimate of the coefficients, given in closed form.","function":false},{"term":"⊤","meaning":"Transpose: flips a matrix so rows become columns.","function":true},{"term":"I","meaning":"The identity matrix, with ones on the diagonal, added so the matrix is always invertible.","function":false},{"term":"⁻¹","meaning":"Matrix inverse: takes a square invertible matrix and returns the matrix that undoes it.","function":true},{"term":"‖β‖₁","meaning":"L1 norm of the coefficients, the sum of their absolute values; the lasso penalty that can set coefficients exactly to zero.","function":false}],"explanation":"Regularized regression adds a coefficient penalty to the least-squares objective. Ridge uses the squared L2 norm, which shrinks all coefficients toward zero and has the closed form β̂ = (XᵀX + λI)⁻¹Xᵀy, stabilizing ill-conditioned problems. Lasso uses the L1 norm, whose corners set some coefficients exactly to zero, performing variable selection. Elastic net mixes both penalties; λ controls strength and is usually tuned by cross-validation.","origin":"Arthur Hoerl and Robert Kennard introduced ridge regression in 1970, Robert Tibshirani the lasso in 1996, and Hui Zou and Trevor Hastie the elastic net in 2005.","implementations":[{"name":"sklearn.linear_model.Ridge","library":"scikit-learn","note":"Linear regression with L2 penalty."},{"name":"sklearn.linear_model.Lasso","library":"scikit-learn","note":"Linear regression with L1 penalty via coordinate descent."},{"name":"sklearn.linear_model.ElasticNet","library":"scikit-learn","note":"Linear regression with combined L1 and L2 penalties."},{"name":"glmnet","library":"glmnet (R)","note":"Fits lasso, ridge and elastic-net regularization paths."}]},"ML.6":{"spoken":[{"line":0,"text":"CV sub k equals one over k times the sum from j equals 1 to k of Err sub j"},{"line":1,"text":"each fold: train on the quantity k minus 1 over k, times n, test on n over k"},{"line":2,"text":"LOOCV: k equals n"}],"terms":[{"term":"CV₍ₖ₎","meaning":"The k-fold cross-validation estimate of test error: the average of the k held-out fold errors.","function":false},{"term":"k","meaning":"The number of folds the data are split into.","function":false},{"term":"Σ","meaning":"Summation operator: adds the error from each of the k folds.","function":true},{"term":"j","meaning":"Index over the folds, from 1 to k.","function":false},{"term":"Errⱼ","meaning":"The error measured on fold j when the model is trained on the other k minus 1 folds.","function":false},{"term":"n","meaning":"The total number of observations in the dataset.","function":false},{"term":"LOOCV","meaning":"Leave-one-out cross-validation: the special case with one fold per observation, so each test set is a single point.","function":false}],"explanation":"k-fold cross-validation estimates out-of-sample error by splitting the data into k folds, training on k − 1 of them and testing on the held-out fold, then averaging the k fold errors. Every observation is used for testing exactly once. Leave-one-out (k = n) is nearly unbiased but costly and high-variance; k = 5 or 10 is the usual compromise for model selection and hyperparameter tuning.","origin":"Mervyn Stone and Seymour Geisser formalized cross-validation for model assessment in the mid-1970s.","implementations":[{"name":"sklearn.model_selection.cross_val_score","library":"scikit-learn","note":"Scores an estimator by k-fold cross-validation."},{"name":"sklearn.model_selection.KFold","library":"scikit-learn","note":"Generates train/test index splits for k folds."},{"name":"sklearn.model_selection.LeaveOneOut","library":"scikit-learn","note":"Leave-one-out cross-validation splitter."},{"name":"sklearn.model_selection.GridSearchCV","library":"scikit-learn","note":"Tunes hyperparameters using cross-validated scores."}]},"ML.7":{"spoken":[{"line":0,"text":"p equals sigma of the quantity beta sub 0 plus beta transpose vector x, which equals 1 over 1 plus e to the negative quantity beta sub 0 plus beta transpose vector x"},{"line":1,"text":"the natural log of p over 1 minus p equals beta sub 0 plus beta transpose vector x"},{"line":2,"text":"odds ratio equals e to the beta sub j"}],"terms":[{"term":"p","meaning":"The predicted probability that the outcome belongs to the positive class.","function":false},{"term":"σ","meaning":"Logistic sigmoid function: takes any real number and squashes it into a probability between 0 and 1.","function":true},{"term":"β₀","meaning":"The intercept: the log-odds when all features are zero.","function":false},{"term":"β","meaning":"The vector of feature coefficients; each is the change in log-odds per unit change in its feature.","function":false},{"term":"⊤","meaning":"Transpose, so beta transpose x is the dot product of coefficients and features.","function":true},{"term":"𝐱","meaning":"The feature vector of an observation whose class probability is being predicted.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential.","function":false},{"term":"ln","meaning":"Natural logarithm; applied to the odds p over 1 minus p it gives the log-odds, or logit.","function":true},{"term":"odds ratio","meaning":"The multiplicative change in the odds of the positive class for a one-unit increase in a feature.","function":false},{"term":"βⱼ","meaning":"The coefficient of feature j; exponentiating it gives that feature's odds ratio.","function":false}],"explanation":"Logistic regression models the probability of a binary outcome by passing a linear score β₀ + βᵀx through the sigmoid, which maps any real number into (0, 1). Inverting the sigmoid shows the model is linear in the log-odds, so each coefficient βⱼ is the change in log-odds per unit of xⱼ, and e^βⱼ is the corresponding odds ratio. Coefficients are fit by maximizing likelihood, equivalently minimizing log-loss.","origin":"David Cox popularized logistic regression for binary outcomes in 1958, building on the logistic function of Pierre-François Verhulst.","implementations":[{"name":"sklearn.linear_model.LogisticRegression","library":"scikit-learn","note":"Regularized logistic regression classifier."},{"name":"statsmodels.api.Logit","library":"statsmodels","note":"Maximum-likelihood logit model with inference statistics."},{"name":"glm","library":"R stats","note":"Fits logistic regression with family = binomial."}]},"ML.8":{"spoken":[{"line":0,"text":"Prec equals T P over the quantity T P plus F P. Rec equals T P over the quantity T P plus F N"},{"line":1,"text":"F sub 1 equals 2 P R over the quantity P plus R"},{"line":2,"text":"Acc equals the quantity T P plus T N over N. Spec equals T N over the quantity T N plus F P"}],"terms":[{"term":"Prec","meaning":"Precision: of the cases predicted positive, the fraction that are actually positive.","function":false},{"term":"TP","meaning":"True positives: positive cases the classifier correctly flagged as positive.","function":false},{"term":"FP","meaning":"False positives: negative cases the classifier wrongly flagged as positive.","function":false},{"term":"Rec","meaning":"Recall (sensitivity, true positive rate): of the actual positives, the fraction the classifier caught.","function":false},{"term":"FN","meaning":"False negatives: positive cases the classifier missed by predicting negative.","function":false},{"term":"F₁","meaning":"The F1 score: the harmonic mean of precision and recall, high only when both are high.","function":false},{"term":"P","meaning":"Precision, written as P inside the F1 score formula.","function":false},{"term":"R","meaning":"Recall, written as R inside the F1 score formula.","function":false},{"term":"Acc","meaning":"Accuracy: the fraction of all cases classified correctly.","function":false},{"term":"TN","meaning":"True negatives: negative cases correctly predicted as negative.","function":false},{"term":"N","meaning":"The total number of cases evaluated, so N equals TP plus TN plus FP plus FN.","function":false},{"term":"Spec","meaning":"Specificity (true negative rate): of the actual negatives, the fraction correctly predicted negative.","function":false}],"explanation":"These metrics summarize a confusion matrix of true/false positives and negatives. Precision is the share of flagged cases that are truly positive; recall (sensitivity) is the share of actual positives caught. F1 is their harmonic mean, which stays low if either is low. Accuracy counts all correct predictions over N and can mislead with imbalanced classes, while specificity is the share of actual negatives correctly cleared.","origin":"Precision and recall come from information retrieval research; C. J. van Rijsbergen introduced the effectiveness measure underlying the F-score in 1979.","implementations":[{"name":"sklearn.metrics.precision_score","library":"scikit-learn","note":"Precision of predicted labels."},{"name":"sklearn.metrics.recall_score","library":"scikit-learn","note":"Recall (sensitivity) of predicted labels."},{"name":"sklearn.metrics.f1_score","library":"scikit-learn","note":"Harmonic mean of precision and recall."},{"name":"sklearn.metrics.classification_report","library":"scikit-learn","note":"Text summary of precision, recall, F1 per class."}]},"ML.9":{"spoken":[{"line":0,"text":"d sub 2 equals the square root of the sum of the quantity x sub j minus z sub j, squared. d sub 1 equals the sum of the absolute value of x sub j minus z sub j"},{"line":1,"text":"cosine theta equals vector x dot vector z over the norm of vector x times the norm of vector z"},{"line":2,"text":"y hat equals majority or mean of k nearest"}],"terms":[{"term":"d₂","meaning":"Euclidean distance: the straight-line distance between points x and z.","function":false},{"term":"√","meaning":"Square root: takes a nonnegative number and returns the value whose square is that number.","function":true},{"term":"Σ","meaning":"Summation operator: adds the per-feature contributions over all features j.","function":true},{"term":"xⱼ","meaning":"The j-th feature (coordinate) of point x, such as the query point.","function":false},{"term":"zⱼ","meaning":"The j-th feature (coordinate) of point z, such as a training point.","function":false},{"term":"d₁","meaning":"Manhattan (L1) distance: the sum of absolute coordinate differences between x and z.","function":false},{"term":"| |","meaning":"Absolute value: returns the size of each coordinate difference without sign.","function":true},{"term":"cos","meaning":"Cosine function; here cos theta is cosine similarity, measuring the angle between two vectors regardless of their length.","function":true},{"term":"θ","meaning":"The angle between vectors x and z; a smaller angle means more similar directions.","function":false},{"term":"𝐱","meaning":"A feature vector, such as the query point.","function":false},{"term":"𝐳","meaning":"Another feature vector, such as a training point being compared.","function":false},{"term":"·","meaning":"Dot product: multiplies matching components and sums them.","function":true},{"term":"‖ ‖","meaning":"Euclidean norm: takes a vector and returns its length.","function":true},{"term":"ŷ","meaning":"The k-NN prediction: majority class vote for classification or average value for regression among the neighbors.","function":false},{"term":"k","meaning":"The number of nearest neighbors consulted when making the k-NN prediction.","function":false}],"explanation":"k-nearest neighbors predicts a point's label from the k closest training points: a majority vote for classification or the mean for regression. Closeness depends on the metric: Euclidean distance d₂, Manhattan distance d₁, or cosine similarity, which compares direction and ignores magnitude. There is no training phase, so feature scaling and the choice of k matter greatly; small k overfits, large k oversmooths.","origin":"Evelyn Fix and Joseph Hodges introduced the nearest-neighbor rule in 1951, and Thomas Cover and Peter Hart analyzed it in 1967.","implementations":[{"name":"sklearn.neighbors.KNeighborsClassifier","library":"scikit-learn","note":"k-NN classification by neighbor vote."},{"name":"sklearn.neighbors.KNeighborsRegressor","library":"scikit-learn","note":"k-NN regression by averaging neighbor targets."},{"name":"scipy.spatial.distance.cdist","library":"SciPy","note":"Pairwise distances between two point sets, many metrics."},{"name":"sklearn.metrics.pairwise.cosine_similarity","library":"scikit-learn","note":"Cosine similarity between rows of two matrices."}]},"ML.10":{"spoken":[{"line":0,"text":"y hat equals the arg max over y of P of y times the product over j of P of x sub j given y"},{"line":1,"text":"Laplace: P hat of x sub j given y equals the quantity n sub j y plus 1 over the quantity n sub y plus V"}],"terms":[{"term":"ŷ","meaning":"The predicted class: the one with the highest unnormalized posterior.","function":false},{"term":"arg max","meaning":"Operator that returns the class y giving the largest value of the expression, rather than the value itself.","function":true},{"term":"y","meaning":"A candidate class label being scored; the arg max ranges over all classes.","function":false},{"term":"P","meaning":"Probability function: P(y) is the prior probability of class y; P(xⱼ ∣ y) is the likelihood of feature value xⱼ within class y.","function":true},{"term":"∏","meaning":"Product operator: multiplies the per-feature likelihoods, valid under the naive assumption that features are independent given the class.","function":true},{"term":"xⱼ","meaning":"The value of the j-th feature of the input.","function":false},{"term":"∣","meaning":"Conditioning bar, read given: the probability is computed within class y.","function":false},{"term":"P̂","meaning":"An estimated probability computed from smoothed training counts rather than known exactly.","function":false},{"term":"n_jy","meaning":"Count of training examples in class y that have feature value xⱼ.","function":false},{"term":"n_y","meaning":"Total count of training examples (or feature occurrences) in class y.","function":false},{"term":"V","meaning":"The number of possible values (vocabulary size) of the feature, added so smoothed probabilities sum to 1.","function":false}],"explanation":"Naive Bayes applies Bayes' theorem and assumes features are conditionally independent given the class, so the likelihood factors into a product of per-feature terms. The predicted class maximizes prior P(y) times that product. Laplace (add-one) smoothing adds 1 to each count and V to the denominator, where V is the number of possible feature values, so unseen values never zero out the product. It is fast and strong for text classification.","origin":"It rests on Bayes' theorem, published posthumously for Thomas Bayes in 1763; add-one smoothing follows Laplace's rule of succession.","implementations":[{"name":"sklearn.naive_bayes.MultinomialNB","library":"scikit-learn","note":"Naive Bayes for count features with additive smoothing alpha."},{"name":"sklearn.naive_bayes.GaussianNB","library":"scikit-learn","note":"Naive Bayes with Gaussian per-feature likelihoods."},{"name":"sklearn.naive_bayes.BernoulliNB","library":"scikit-learn","note":"Naive Bayes for binary features."}]},"ML.11":{"spoken":[{"line":0,"text":"Gini equals 1 minus the sum over k of p sub k squared"},{"line":1,"text":"H equals negative the sum over k of p sub k times log base 2 of p sub k"},{"line":2,"text":"I G equals H of parent minus the sum over c of n sub c over n times H of c"}],"terms":[{"term":"Gini","meaning":"Gini impurity of a node: the chance two randomly drawn points have different classes; 0 for a pure node.","function":false},{"term":"Σ","meaning":"Summation operator: adds over classes k, or over child nodes c.","function":true},{"term":"k","meaning":"Index running over the classes present in the node being evaluated.","function":false},{"term":"pₖ","meaning":"The fraction of points in the node that belong to class k.","function":false},{"term":"H","meaning":"Entropy function: takes a node and returns the impurity of its class mix, in bits.","function":true},{"term":"log₂","meaning":"Logarithm base 2, so entropy is measured in bits.","function":true},{"term":"IG","meaning":"Information gain: the drop in entropy achieved by a split; the tree picks the split with the largest gain.","function":false},{"term":"parent","meaning":"The node before the split, whose entropy is compared with its children's weighted entropy.","function":false},{"term":"c","meaning":"Index over the child nodes produced by the split.","function":false},{"term":"n_c","meaning":"The number of points that go to child c.","function":false},{"term":"n","meaning":"The number of points in the parent node.","function":false}],"explanation":"Decision trees split data recursively, choosing at each node the split that makes child nodes purest. Gini impurity is the chance of mislabeling a random point drawn and labeled by the node's class proportions; entropy measures the node's uncertainty in bits. Information gain is the parent's entropy minus the size-weighted average entropy of the children, and the split with the largest gain (or Gini decrease) is chosen.","origin":"Gini-based trees come from the CART method of Breiman, Friedman, Olshen and Stone (1984); information-gain trees from Ross Quinlan's ID3 (1986).","implementations":[{"name":"sklearn.tree.DecisionTreeClassifier","library":"scikit-learn","note":"CART classifier; criterion 'gini' or 'entropy'."},{"name":"sklearn.tree.DecisionTreeRegressor","library":"scikit-learn","note":"CART regression tree."},{"name":"rpart","library":"rpart (R)","note":"Recursive partitioning trees in R."}]},"ML.12":{"spoken":[{"line":0,"text":"Var of f bar equals rho sigma squared plus the quantity 1 minus rho over B, times sigma squared"},{"line":1,"text":"F sub m of vector x equals F sub m minus 1 of vector x plus nu times h sub m of vector x"},{"line":2,"text":"alpha sub m equals one half times the natural log of the quantity 1 minus epsilon sub m over epsilon sub m"}],"terms":[{"term":"Var","meaning":"Variance operator: returns how much the averaged ensemble prediction fluctuates across training sets.","function":true},{"term":"f̄","meaning":"The bagged ensemble prediction: the average of the B individual models' predictions.","function":false},{"term":"ρ","meaning":"The pairwise correlation between the individual models' predictions; random forests lower it by subsampling features.","function":false},{"term":"σ²","meaning":"The variance of a single model's prediction before any averaging is applied.","function":false},{"term":"B","meaning":"The number of models (bootstrap samples or trees) averaged.","function":false},{"term":"F_m","meaning":"The boosted model after m rounds, a function mapping inputs to predictions.","function":true},{"term":"𝐱","meaning":"The input feature vector at which the boosted model makes a prediction.","function":false},{"term":"F_{m−1}","meaning":"The boosted model from the previous round, before adding the new learner.","function":true},{"term":"ν","meaning":"The learning rate (shrinkage), between 0 and 1, scaling each new learner's contribution.","function":false},{"term":"h_m","meaning":"The weak learner fitted at round m, typically a small tree fit to the current residuals or gradients.","function":true},{"term":"α_m","meaning":"The AdaBoost weight (vote) given to learner m; larger for more accurate learners.","function":false},{"term":"ln","meaning":"Natural logarithm, applied to the odds of learner m being correct.","function":true},{"term":"ε_m","meaning":"The weighted training error rate of learner m.","function":false}],"explanation":"Ensembles combine many models. Averaging B models with variance σ² and pairwise correlation ρ gives variance ρσ² + (1 − ρ)σ²/B, so bagging reduces variance, and random forests decorrelate trees by sampling features at each split. Boosting instead builds models sequentially: each new learner hₘ corrects the current ensemble, added with learning rate ν. In AdaBoost, a learner's weight αₘ grows as its weighted error εₘ shrinks.","origin":"Leo Breiman introduced bagging in 1996 and random forests in 2001; Yoav Freund and Robert Schapire introduced AdaBoost in the mid-1990s, and Jerome Friedman gradient boosting in 2001.","implementations":[{"name":"sklearn.ensemble.RandomForestClassifier","library":"scikit-learn","note":"Bagged decision trees with random feature subsets."},{"name":"sklearn.ensemble.GradientBoostingClassifier","library":"scikit-learn","note":"Gradient-boosted decision trees."},{"name":"sklearn.ensemble.AdaBoostClassifier","library":"scikit-learn","note":"AdaBoost ensemble of weak learners."},{"name":"xgboost.XGBClassifier","library":"XGBoost","note":"Regularized gradient boosting of trees."}]},"ML.13":{"spoken":[{"line":0,"text":"min of one half the norm of vector w squared plus C times the sum of xi sub i"},{"line":1,"text":"such that y sub i times the quantity vector w transpose vector x sub i plus b is greater than or equal to 1 minus xi sub i"},{"line":2,"text":"margin equals 2 over the norm of vector w"},{"line":3,"text":"K of vector x comma vector z equals e to the negative gamma times the norm of vector x minus vector z, squared"}],"terms":[{"term":"min","meaning":"Minimize the objective over the weight vector w, offset b and slacks xi.","function":true},{"term":"𝐰","meaning":"The weight vector normal to the separating hyperplane.","function":false},{"term":"‖ ‖","meaning":"Euclidean norm: returns the length of a vector.","function":true},{"term":"C","meaning":"Penalty constant trading off a wide margin against margin violations; larger C tolerates fewer violations.","function":false},{"term":"Σ","meaning":"Summation operator: adds up slack over all training points.","function":true},{"term":"ξᵢ","meaning":"Slack variable for point i: how far it falls inside the margin or on the wrong side.","function":false},{"term":"s.t.","meaning":"Such that: introduces the constraints the minimization must satisfy.","function":false},{"term":"yᵢ","meaning":"The class label of point i, coded as plus 1 or minus 1.","function":false},{"term":"⊤","meaning":"Transpose, so w transpose x is the dot product of w and x.","function":true},{"term":"𝐱ᵢ","meaning":"The feature vector of training point i in the support vector machine problem.","function":false},{"term":"b","meaning":"The bias (offset) of the separating hyperplane, shifting it away from the origin.","function":false},{"term":"margin","meaning":"The width of the street between the two classes' supporting hyperplanes.","function":false},{"term":"K","meaning":"Kernel function: takes two input vectors and returns their similarity, equal to an inner product in an implicit feature space; here the RBF kernel.","function":true},{"term":"𝐱, 𝐳","meaning":"Two input points being compared by the kernel.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential function used here.","function":false},{"term":"γ","meaning":"Kernel width parameter: larger gamma makes similarity fall off faster with distance.","function":false}],"explanation":"A support vector machine finds the separating hyperplane wᵀx + b = 0 with the widest margin, 2/‖w‖, so minimizing ‖w‖²/2 maximizes it. Slack variables ξᵢ let some points violate the margin, with C trading margin width against violations. Only points on or inside the margin, the support vectors, determine the solution. Kernels such as the RBF kernel replace dot products to produce nonlinear boundaries without explicit feature maps.","origin":"Boser, Guyon and Vapnik introduced the kernel trick for SVMs in 1992, and Corinna Cortes and Vladimir Vapnik the soft-margin formulation in 1995.","implementations":[{"name":"sklearn.svm.SVC","library":"scikit-learn","note":"Kernel SVM classifier built on libsvm."},{"name":"sklearn.svm.LinearSVC","library":"scikit-learn","note":"Linear SVM classifier built on liblinear."},{"name":"sklearn.metrics.pairwise.rbf_kernel","library":"scikit-learn","note":"Computes the RBF kernel matrix exp(−γ‖x−z‖²)."}]},"ML.14":{"spoken":[{"line":0,"text":"vector a superscript l equals phi of W superscript l times vector a superscript l minus 1 plus vector b superscript l"},{"line":1,"text":"ReLU of z equals the max of 0 and z. sigma prime equals sigma times the quantity 1 minus sigma"},{"line":2,"text":"delta superscript l equals the quantity W superscript l plus 1 transpose times delta superscript l plus 1, Hadamard product, phi prime of vector z superscript l"}],"terms":[{"term":"𝐚⁽ˡ⁾","meaning":"The activation vector output by layer l, fed as input to the next layer.","function":false},{"term":"l","meaning":"Layer index; superscript l marks quantities belonging to layer l.","function":false},{"term":"ϕ","meaning":"Activation function: applied elementwise to pre-activations to add nonlinearity.","function":true},{"term":"W⁽ˡ⁾","meaning":"The weight matrix connecting layer l minus 1 to layer l.","function":false},{"term":"𝐛⁽ˡ⁾","meaning":"The bias vector of layer l, added to the weighted inputs before activation.","function":false},{"term":"ReLU","meaning":"Rectified linear unit: takes a number and returns it if positive, otherwise 0.","function":true},{"term":"z","meaning":"A pre-activation value fed into the activation function.","function":false},{"term":"max","meaning":"Takes two numbers and returns the larger; in ReLU it compares 0 with z.","function":true},{"term":"σ","meaning":"Logistic sigmoid activation, mapping a real number to (0, 1).","function":true},{"term":"σ′","meaning":"The derivative of the sigmoid, which can be written in terms of the sigmoid itself.","function":true},{"term":"δ⁽ˡ⁾","meaning":"The error signal at layer l: the gradient of the loss with respect to that layer's pre-activations.","function":false},{"term":"⊤","meaning":"Transpose of the weight matrix, sending errors backward through the layer.","function":true},{"term":"⊙","meaning":"Hadamard product: multiplies two vectors element by element.","function":true},{"term":"ϕ′","meaning":"Derivative of the activation function, evaluated elementwise at the layer's pre-activations.","function":true},{"term":"𝐳⁽ˡ⁾","meaning":"The pre-activation vector of layer l, W times previous activations plus bias.","function":false}],"explanation":"A feedforward network computes each layer's activations by applying an affine map W a + b to the previous layer and then a nonlinearity φ such as ReLU or the sigmoid. Backpropagation applies the chain rule backward: each layer's error signal δ is the next layer's δ pulled back through Wᵀ and multiplied elementwise by φ′. These δ values give every weight's gradient for gradient descent in one backward pass.","origin":"Rumelhart, Hinton and Williams popularized backpropagation for neural networks in 1986, building on earlier work by Seppo Linnainmaa (1970) and Paul Werbos (1974).","implementations":[{"name":"torch.nn.Linear","library":"PyTorch","note":"Affine layer Wx + b."},{"name":"torch.Tensor.backward","library":"PyTorch","note":"Runs backpropagation to compute gradients."},{"name":"tf.keras.layers.Dense","library":"TensorFlow","note":"Fully connected layer with optional activation."},{"name":"sklearn.neural_network.MLPClassifier","library":"scikit-learn","note":"Multilayer perceptron trained by backpropagation."}]},"ML.15":{"spoken":[{"line":0,"text":"softmax of vector z, sub k, equals e to the z sub k over the sum over j of e to the z sub j"},{"line":1,"text":"L equals negative the sum over k of y sub k times the natural log of p hat sub k"},{"line":2,"text":"the partial derivative of L with respect to vector z equals vector p hat minus vector y"}],"terms":[{"term":"softmax","meaning":"Takes a vector of real scores and returns a probability vector: each entry exponentiated and divided by the total.","function":true},{"term":"𝐳","meaning":"The vector of raw class scores (logits) produced by the network before softmax.","function":false},{"term":"k","meaning":"Index of a particular class among the possible output classes.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential function used here.","function":false},{"term":"z_k","meaning":"The logit (raw score) for class k, entry k of the vector z.","function":false},{"term":"Σ","meaning":"Summation operator: adds over all classes, normalizing the softmax or totaling the loss.","function":true},{"term":"j","meaning":"Index running over all classes in the normalizing sum.","function":false},{"term":"L","meaning":"The cross-entropy loss for one example, comparing predicted probabilities with the true label.","function":false},{"term":"y_k","meaning":"The true label indicator for class k: 1 for the correct class, 0 otherwise.","function":false},{"term":"ln","meaning":"Natural logarithm, applied to the predicted probability of each class in the loss.","function":true},{"term":"p̂_k","meaning":"The predicted probability of class k, the softmax output.","function":false},{"term":"∂","meaning":"Partial derivative: the rate of change of the loss with respect to each logit.","function":true},{"term":"𝐩̂","meaning":"The vector of predicted class probabilities output by the softmax.","function":false},{"term":"𝐲","meaning":"The one-hot vector of true labels, with a 1 in the correct class.","function":false}],"explanation":"Softmax turns a vector of scores z into probabilities by exponentiating and normalizing, so outputs are positive and sum to one. Cross-entropy loss then takes the negative log probability of the true class (y one-hot). Combined, the gradient with respect to the scores is simply p̂ − y, prediction minus truth, which makes training multiclass classifiers clean and numerically stable when computed together.","origin":"Softmax mirrors the Boltzmann distribution of statistical mechanics; John Bridle coined the name 'softmax' around 1990.","implementations":[{"name":"torch.nn.CrossEntropyLoss","library":"PyTorch","note":"Combined log-softmax and negative log-likelihood on raw logits."},{"name":"torch.nn.functional.softmax","library":"PyTorch","note":"Softmax along a given dimension."},{"name":"scipy.special.softmax","library":"SciPy","note":"Softmax of an array along an axis."},{"name":"tf.nn.softmax","library":"TensorFlow","note":"Softmax activation on logits."}]},"ML.16":{"spoken":[{"line":0,"text":"theta gets theta minus eta times the gradient of L sub batch"},{"line":1,"text":"vector v gets beta vector v plus the gradient of L, theta gets theta minus eta vector v"},{"line":2,"text":"Adam: vector m hat equals vector m over 1 minus beta sub 1 to the t, vector v hat equals vector v over 1 minus beta sub 2 to the t"},{"line":3,"text":"theta gets theta minus eta times vector m hat over the quantity square root of vector v hat plus epsilon"}],"terms":[{"term":"θ","meaning":"The model parameters being updated by each optimization step.","function":false},{"term":"←","meaning":"Assignment: replace the left side with the value computed on the right.","function":false},{"term":"η","meaning":"Learning rate: the step size of each update.","function":false},{"term":"∇","meaning":"Gradient operator: takes the loss and returns the vector of partial derivatives with respect to the parameters.","function":true},{"term":"L_batch","meaning":"The loss computed on the current mini-batch, giving a noisy estimate of the full loss.","function":true},{"term":"𝐯","meaning":"In momentum, the velocity: a running accumulation of past gradients; in Adam, the running average of squared gradients.","function":false},{"term":"β","meaning":"The momentum decay factor, controlling how much past velocity is kept.","function":false},{"term":"L","meaning":"The loss function being minimized; its gradient drives the momentum update.","function":true},{"term":"𝐦","meaning":"Adam's running exponential moving average of the gradients, the momentum term.","function":false},{"term":"𝐦̂","meaning":"Bias-corrected first moment estimate, compensating for m starting at zero.","function":false},{"term":"β₁","meaning":"Decay rate for the gradient moving average, typically 0.9.","function":false},{"term":"t","meaning":"The step (iteration) count, used for bias correction.","function":false},{"term":"𝐯̂","meaning":"Bias-corrected second moment estimate, compensating for v starting at zero.","function":false},{"term":"β₂","meaning":"Decay rate for the squared-gradient moving average, typically 0.999.","function":false},{"term":"√","meaning":"Elementwise square root, giving per-parameter scale of recent gradients.","function":true},{"term":"ϵ","meaning":"A tiny constant, such as ten to the negative eighth, preventing division by zero.","function":false}],"explanation":"Stochastic gradient descent updates parameters against the gradient of the loss on a mini-batch, scaled by learning rate η. Momentum keeps a running velocity v of past gradients, smoothing noise and accelerating along consistent directions. Adam tracks both a first-moment average m and a second-moment average v of gradients, corrects their startup bias by dividing by 1 − βᵗ, and divides the step by √v̂, giving each parameter its own adaptive step size.","origin":"Herbert Robbins and Sutton Monro introduced stochastic approximation in 1951, Boris Polyak the momentum method in 1964, and Diederik Kingma and Jimmy Ba Adam in 2014.","implementations":[{"name":"torch.optim.SGD","library":"PyTorch","note":"SGD with optional momentum and Nesterov."},{"name":"torch.optim.Adam","library":"PyTorch","note":"Adam optimizer."},{"name":"tf.keras.optimizers.Adam","library":"TensorFlow","note":"Adam optimizer for Keras models."},{"name":"optax.adam","library":"Optax (JAX)","note":"Adam gradient transformation."}]},"ML.17":{"spoken":[{"line":0,"text":"J equals the sum from k equals 1 to K of the sum over vector x sub i in C sub k of the norm of vector x sub i minus mu sub k, squared"},{"line":1,"text":"assign to nearest mu sub k; mu sub k equals 1 over the size of C sub k times the sum over C sub k of vector x sub i"}],"terms":[{"term":"J","meaning":"The k-means objective: total within-cluster sum of squared distances.","function":false},{"term":"Σ","meaning":"Summation operator: adds over clusters and over points within each cluster.","function":true},{"term":"k","meaning":"Index of a cluster, running from 1 to K in the objective.","function":false},{"term":"K","meaning":"The number of clusters, chosen by the user before running k-means.","function":false},{"term":"𝐱ᵢ","meaning":"The i-th data point, assigned to exactly one cluster at a time.","function":false},{"term":"∈","meaning":"Set membership: the point belongs to that cluster.","function":false},{"term":"C_k","meaning":"The set of points currently assigned to cluster k.","function":false},{"term":"‖ ‖","meaning":"Euclidean norm, the distance from point to centroid.","function":true},{"term":"μ_k","meaning":"The centroid (mean position) of cluster k, recomputed at each update step.","function":false},{"term":"|C_k|","meaning":"The number of points in cluster k, the size (cardinality) of the set C_k.","function":false}],"explanation":"k-means partitions data into K clusters by minimizing J, the total squared distance from each point to its cluster centroid. Lloyd's algorithm alternates two steps: assign each point to its nearest centroid, then move each centroid to the mean of its assigned points. Each step cannot increase J, so it converges, though only to a local optimum; multiple restarts and k-means++ initialization help.","origin":"Stuart Lloyd proposed the algorithm in 1957 (published 1982), and James MacQueen coined the term 'k-means' in 1967.","implementations":[{"name":"sklearn.cluster.KMeans","library":"scikit-learn","note":"k-means with k-means++ initialization."},{"name":"sklearn.cluster.MiniBatchKMeans","library":"scikit-learn","note":"k-means on mini-batches for large data."},{"name":"scipy.cluster.vq.kmeans2","library":"SciPy","note":"k-means returning centroids and labels."},{"name":"kmeans","library":"R stats","note":"k-means clustering in base R."}]},"ML.18":{"spoken":[{"line":0,"text":"s of i equals the quantity b of i minus a of i over the max of a of i and b of i"},{"line":1,"text":"single: min d"},{"line":2,"text":"complete: max d"},{"line":3,"text":"average: mean d"}],"terms":[{"term":"s(i)","meaning":"The silhouette of point i, from negative 1 to 1; near 1 means well clustered.","function":false},{"term":"i","meaning":"A particular data point whose silhouette score is being computed.","function":false},{"term":"b(i)","meaning":"Average distance from point i to points in the nearest other cluster.","function":false},{"term":"a(i)","meaning":"Average distance from point i to the other points in its own cluster.","function":false},{"term":"max","meaning":"Returns the larger of its arguments; here used to normalize the silhouette, and in complete linkage the largest pairwise distance.","function":true},{"term":"min","meaning":"Returns the smallest value; single linkage uses the closest pair of points between clusters.","function":true},{"term":"d","meaning":"Distance between a point in one cluster and a point in another.","function":false},{"term":"mean","meaning":"Returns the average; average linkage uses the mean of all between-cluster pairwise distances.","function":true}],"explanation":"Agglomerative hierarchical clustering starts with each point as its own cluster and repeatedly merges the closest pair, producing a dendrogram. The linkage defines cluster distance: single uses the closest pair of points, complete the farthest pair, and average the mean pairwise distance. The silhouette s(i) compares a point's mean distance to its own cluster, a(i), with that to the nearest other cluster, b(i); values near 1 mean good clustering.","origin":"Peter Rousseeuw introduced the silhouette coefficient in 1987.","implementations":[{"name":"scipy.cluster.hierarchy.linkage","library":"SciPy","note":"Hierarchical clustering with single, complete, average and other linkages."},{"name":"sklearn.cluster.AgglomerativeClustering","library":"scikit-learn","note":"Bottom-up hierarchical clustering."},{"name":"sklearn.metrics.silhouette_score","library":"scikit-learn","note":"Mean silhouette coefficient over all samples."},{"name":"hclust","library":"R stats","note":"Hierarchical clustering in base R."}]},"ML.19":{"spoken":[{"line":0,"text":"S equals 1 over n minus 1 times X sub c transpose X sub c"},{"line":1,"text":"S vector v sub k equals lambda sub k vector v sub k"},{"line":2,"text":"explained ratio equals lambda sub k over the sum over j of lambda sub j"},{"line":3,"text":"vector z equals V sub k transpose times the quantity vector x minus vector x bar"}],"terms":[{"term":"S","meaning":"The sample covariance matrix of the features, whose eigenvectors give the principal components.","function":false},{"term":"n","meaning":"The number of observations (rows) in the data matrix.","function":false},{"term":"X_c","meaning":"The centered data matrix, each column with its mean subtracted.","function":false},{"term":"⊤","meaning":"Transpose operator: takes a matrix and flips its rows and columns.","function":true},{"term":"𝐯_k","meaning":"The k-th eigenvector of S: the direction of the k-th principal component.","function":false},{"term":"λ_k","meaning":"The k-th eigenvalue of S: the variance of the data along component k.","function":false},{"term":"Σ","meaning":"Summation operator: adds all eigenvalues, the total variance.","function":true},{"term":"j","meaning":"Index running over all principal components in the total variance sum.","function":false},{"term":"explained ratio","meaning":"The fraction of total variance captured by component k.","function":false},{"term":"𝐳","meaning":"The projected scores: the point's coordinates in the reduced principal component space.","function":false},{"term":"V_k","meaning":"Matrix whose columns are the top k eigenvectors.","function":false},{"term":"𝐱","meaning":"An original data point in the full feature space, to be projected.","function":false},{"term":"𝐱̄","meaning":"The mean vector of the data, subtracted to center the point before projection.","function":false}],"explanation":"PCA finds orthogonal directions of maximum variance. Center the data, form the sample covariance matrix S, and take its eigenvectors vₖ; the eigenvalues λₖ are the variances along them. Each component's explained variance ratio is λₖ divided by the total. Projecting centered data onto the top k eigenvectors gives low-dimensional scores z, useful for compression, visualization and decorrelating features.","origin":"Karl Pearson introduced the method in 1901, and Harold Hotelling developed and named it in 1933.","implementations":[{"name":"sklearn.decomposition.PCA","library":"scikit-learn","note":"PCA via SVD with explained_variance_ratio_."},{"name":"numpy.linalg.eigh","library":"NumPy","note":"Eigen-decomposition of a symmetric matrix such as S."},{"name":"numpy.linalg.svd","library":"NumPy","note":"Singular value decomposition of centered data."},{"name":"prcomp","library":"R stats","note":"Principal components analysis in base R."}]},"ML.20":{"spoken":[{"line":0,"text":"p of x equals the sum over k of pi sub k times N of x given mu sub k comma sigma sub k squared"},{"line":1,"text":"E: gamma sub i k equals pi sub k N of x sub i given mu sub k comma sigma sub k squared over the sum over j of pi sub j N of x sub i given mu sub j comma sigma sub j squared"},{"line":2,"text":"M: mu sub k equals the sum over i of gamma sub i k x sub i over the sum over i of gamma sub i k, pi sub k equals N sub k over n"}],"terms":[{"term":"p(x)","meaning":"The mixture density: a function giving the probability density of x as a weighted sum of Gaussians.","function":true},{"term":"x","meaning":"A data value whose density is described by the Gaussian mixture.","function":false},{"term":"Σ","meaning":"Summation operator: adds over components or over data points.","function":true},{"term":"k","meaning":"Index of a mixture component, one of the Gaussians in the mixture.","function":false},{"term":"π_k","meaning":"The mixing weight of component k; weights are nonnegative and sum to 1.","function":false},{"term":"N","meaning":"Normal density function: takes x, a mean and a variance and returns the Gaussian density at x.","function":true},{"term":"∣","meaning":"Conditioning bar, read given: the density uses those parameters.","function":false},{"term":"μ_k","meaning":"The mean of Gaussian component k, re-estimated in the M-step.","function":false},{"term":"σ_k²","meaning":"The variance of Gaussian component k, describing that component's spread.","function":false},{"term":"γ_ik","meaning":"The responsibility: posterior probability that point i came from component k.","function":false},{"term":"xᵢ","meaning":"The i-th data point in the sample being clustered.","function":false},{"term":"j","meaning":"Index over all components in the normalizing sum.","function":false},{"term":"i","meaning":"Index running over the data points in the sample.","function":false},{"term":"N_k","meaning":"Effective number of points in component k, the sum of its responsibilities.","function":false},{"term":"n","meaning":"The total number of data points in the sample used to fit the mixture.","function":false}],"explanation":"A Gaussian mixture models a density as a weighted sum of K Gaussians with mixing weights πₖ. The EM algorithm fits it by alternating: the E-step computes each point's responsibility γᵢₖ, the posterior probability it came from component k; the M-step re-estimates each mean, variance and weight using those responsibilities as soft counts, with Nₖ = Σᵢ γᵢₖ. Each iteration never decreases the likelihood.","origin":"Arthur Dempster, Nan Laird and Donald Rubin formalized the EM algorithm in 1977.","implementations":[{"name":"sklearn.mixture.GaussianMixture","library":"scikit-learn","note":"Gaussian mixture model fitted by EM."},{"name":"sklearn.mixture.BayesianGaussianMixture","library":"scikit-learn","note":"Variational Bayesian Gaussian mixture."}]},"ML.21":{"spoken":[{"line":1,"text":"AUC equals the probability that s sub plus is greater than s sub minus"},{"line":3,"text":"PR baseline equals prevalence"}],"terms":[{"term":"AUC","meaning":"Area under the ROC curve; equals the chance a random positive scores above a random negative.","function":false},{"term":"P","meaning":"Probability function: returns the probability of the event inside the parentheses.","function":true},{"term":"s₊","meaning":"The score the model gives a randomly chosen positive example.","function":false},{"term":"s₋","meaning":"The score the model gives a randomly chosen negative example.","function":false},{"term":"PR baseline","meaning":"The precision-recall curve of a random classifier, a flat line.","function":false},{"term":"prevalence","meaning":"The fraction of examples that are actually positive.","function":false}],"explanation":"A classifier's scores become labels only after choosing a threshold. The ROC curve traces true positive rate against false positive rate across all thresholds, and its area, AUC, equals the probability that a random positive scores higher than a random negative. The precision–recall curve plots precision against recall and is more informative for rare positives; a random classifier's precision equals the prevalence, its baseline.","origin":"ROC analysis comes from signal detection theory developed for radar during World War II, later adopted in psychology and medicine.","implementations":[{"name":"sklearn.metrics.roc_curve","library":"scikit-learn","note":"False and true positive rates across thresholds."},{"name":"sklearn.metrics.roc_auc_score","library":"scikit-learn","note":"Area under the ROC curve."},{"name":"sklearn.metrics.precision_recall_curve","library":"scikit-learn","note":"Precision and recall across thresholds."},{"name":"sklearn.metrics.average_precision_score","library":"scikit-learn","note":"Summary area under the precision–recall curve."}]},"ML.22":{"spoken":[{"line":0,"text":"RMSE equals the square root of one over n times the sum of the quantity y minus y hat, squared. MAE equals one over n times the sum of the absolute value of y minus y hat"},{"line":1,"text":"MAPE equals 100 percent over n times the sum of the absolute value of the quantity y minus y hat over y"},{"line":2,"text":"R sub adj squared equals 1 minus the quantity 1 minus R squared, times the quantity n minus 1 over the quantity n minus p minus 1"}],"terms":[{"term":"RMSE","meaning":"Root mean squared error: the square root of the average squared error, in units of y.","function":false},{"term":"√","meaning":"Square root, returning error to the original units.","function":true},{"term":"n","meaning":"The number of observations over which the errors are averaged.","function":false},{"term":"Σ","meaning":"Summation operator: adds the per-observation error terms over all observations.","function":true},{"term":"y","meaning":"The actual observed value of the target for an observation.","function":false},{"term":"ŷ","meaning":"The model's predicted value of the target for an observation.","function":false},{"term":"MAE","meaning":"Mean absolute error: the average size of the errors.","function":false},{"term":"| |","meaning":"Absolute value: the size of an error, ignoring sign.","function":true},{"term":"MAPE","meaning":"Mean absolute percentage error: average error as a percent of the actual value.","function":false},{"term":"R²_adj","meaning":"Adjusted R squared: R squared penalized for the number of predictors.","function":false},{"term":"R²","meaning":"Coefficient of determination: fraction of variance in y explained by the model.","function":false},{"term":"p","meaning":"The number of predictors (features) in the regression model, excluding the intercept.","function":false}],"explanation":"RMSE is the square root of mean squared error, so large misses dominate; MAE averages absolute errors equally; both are in the units of y. MAPE expresses error as an average percentage of the true values, which breaks down when y is near zero. Adjusted R² corrects R² for the number of predictors p, penalizing features that do not improve fit enough to justify themselves.","origin":"","implementations":[{"name":"sklearn.metrics.root_mean_squared_error","library":"scikit-learn","note":"Root mean squared error (scikit-learn 1.4+)."},{"name":"sklearn.metrics.mean_absolute_error","library":"scikit-learn","note":"Mean absolute error."},{"name":"sklearn.metrics.mean_absolute_percentage_error","library":"scikit-learn","note":"MAPE, returned as a fraction rather than percent."},{"name":"sklearn.metrics.r2_score","library":"scikit-learn","note":"Coefficient of determination R²."}]},"ML.23":{"spoken":[{"line":1,"text":"R squared: 0 equals mean baseline, 1 perfect"},{"line":2,"text":"log-loss: the natural log of 2 is approximately 0.693 coin flip, 0 perfect"}],"terms":[{"term":"R²","meaning":"Coefficient of determination: 0 means no better than predicting the mean, 1 means perfect.","function":false},{"term":"ln","meaning":"Natural logarithm; ln 2 is the log-loss of always predicting probability one half.","function":true},{"term":"≈","meaning":"Approximately equal to; ln 2 is roughly 0.693 when rounded.","function":false},{"term":"log-loss","meaning":"Binary cross-entropy loss; 0 is perfect, and about 0.693 matches a coin flip.","function":false}],"explanation":"Metric values only make sense against reference points. AUC of 0.5 is what random scoring achieves and 1 is perfect ranking. R² of 0 means no better than predicting the mean, and 1 is a perfect fit; it can even go negative. Binary log-loss of ln 2 ≈ 0.693 matches always predicting 0.5, and 0 is perfect. Always compare a model to a trivial baseline.","origin":"","implementations":[{"name":"sklearn.dummy.DummyClassifier","library":"scikit-learn","note":"Trivial baseline classifier (prior, most frequent, uniform)."},{"name":"sklearn.dummy.DummyRegressor","library":"scikit-learn","note":"Trivial baseline regressor predicting mean or median."}]},"F.1":{"spoken":[{"line":1,"text":"y equals m x plus b"},{"line":2,"text":"slope m, intercept b"}],"terms":[{"term":"y","meaning":"The output value of the line at input x.","function":false},{"term":"m","meaning":"The slope: change in y per unit increase in x.","function":false},{"term":"x","meaning":"The input (independent) variable of the linear function.","function":false},{"term":"b","meaning":"The y-intercept: the value of y when x is 0.","function":false}],"explanation":"A linear function y = mx + b graphs as a straight line. The slope m is the constant rate of change, the rise in y per unit increase in x, and the intercept b is the value of y where the line crosses the y-axis at x = 0. Linear models are the foundation of regression and of local approximations to any smooth function.","origin":"","implementations":[{"name":"numpy.polyfit","library":"NumPy","note":"Least-squares polynomial fit; degree 1 gives slope and intercept."},{"name":"scipy.stats.linregress","library":"SciPy","note":"Simple linear regression with slope, intercept and r."},{"name":"sklearn.linear_model.LinearRegression","library":"scikit-learn","note":"Ordinary least squares linear model."}]},"F.2":{"spoken":[{"line":1,"text":"y equals a x squared plus b x plus c"},{"line":2,"text":"parabola; vertex at x equals negative b over 2 a"}],"terms":[{"term":"y","meaning":"The output of the quadratic function at input x.","function":false},{"term":"a","meaning":"The leading coefficient; its sign sets whether the parabola opens up or down.","function":false},{"term":"x","meaning":"The input (independent) variable of the quadratic function.","function":false},{"term":"b","meaning":"The linear coefficient, which shifts the vertex horizontally.","function":false},{"term":"c","meaning":"The constant term, which is the y-intercept of the parabola.","function":false}],"explanation":"A quadratic y = ax² + bx + c graphs as a parabola that opens up when a > 0 and down when a < 0. Its axis of symmetry and vertex sit at x = −b/(2a), where the function reaches its minimum or maximum. The roots come from the quadratic formula, and the discriminant b² − 4ac determines whether there are two, one or no real roots.","origin":"","implementations":[{"name":"numpy.roots","library":"NumPy","note":"Roots of a polynomial from its coefficients."},{"name":"numpy.polyval","library":"NumPy","note":"Evaluates a polynomial at given points."},{"name":"numpy.polynomial.Polynomial","library":"NumPy","note":"Polynomial class with evaluation, roots and fitting."}]},"F.3":{"spoken":[{"line":1,"text":"y equals a x cubed plus b x squared plus c x plus d"}],"terms":[{"term":"y","meaning":"The output of the cubic function at input x.","function":false},{"term":"a","meaning":"The leading coefficient, nonzero; its sign sets end behavior.","function":false},{"term":"x","meaning":"The input (independent) variable of the cubic function.","function":false},{"term":"b","meaning":"The coefficient of the x squared term in the cubic.","function":false},{"term":"c","meaning":"The coefficient of the linear x term in the cubic.","function":false},{"term":"d","meaning":"The constant term, which is the y-intercept of the cubic curve.","function":false}],"explanation":"A cubic y = ax³ + bx² + cx + d has odd end behavior: the two ends of its graph head in opposite directions, so it always has at least one real root. Its derivative is a quadratic, so the graph has at most two turning points, a local maximum and a local minimum, and it always has one inflection point where curvature changes sign.","origin":"Gerolamo Cardano published the general solution of the cubic equation in Ars Magna in 1545, building on work by del Ferro and Tartaglia.","implementations":[{"name":"numpy.roots","library":"NumPy","note":"Roots of a polynomial from its coefficients."},{"name":"numpy.polyval","library":"NumPy","note":"Evaluates a polynomial at given points."},{"name":"numpy.polynomial.Polynomial","library":"NumPy","note":"Polynomial class with evaluation, roots and fitting."}]},"F.4":{"spoken":[{"line":1,"text":"y equals the absolute value of x"},{"line":2,"text":"V shape, vertex at 0 comma 0"}],"terms":[{"term":"y","meaning":"The output value, which is never negative for the absolute value function.","function":false},{"term":"| |","meaning":"Absolute value: takes a number and returns its distance from zero.","function":true},{"term":"x","meaning":"The input variable of the absolute value function, any real number.","function":false}],"explanation":"The absolute value |x| returns the distance of x from zero, equal to x when x ≥ 0 and −x when x < 0. Its graph is a V with vertex at the origin, and it is continuous everywhere but not differentiable at 0, where the slope jumps from −1 to 1. It underlies MAE, the L1 norm and distance on the number line.","origin":"Karl Weierstrass introduced the |x| notation in 1841.","implementations":[{"name":"numpy.abs","library":"NumPy","note":"Elementwise absolute value."},{"name":"abs","library":"Python built-in","note":"Absolute value of a number."},{"name":"torch.abs","library":"PyTorch","note":"Elementwise absolute value of a tensor."}]},"F.5":{"spoken":[{"line":1,"text":"y equals the square root of x"},{"line":2,"text":"domain x greater than or equal to 0"}],"terms":[{"term":"y","meaning":"The output value, the nonnegative square root of x.","function":false},{"term":"√","meaning":"Square root: takes a nonnegative number and returns its nonnegative root.","function":true},{"term":"x","meaning":"The input, which must be nonnegative for a real square root.","function":false}],"explanation":"The square root function y = √x returns the nonnegative number whose square is x. Over the reals it is defined only for x ≥ 0, starts at the origin and increases ever more slowly, since its slope 1/(2√x) shrinks as x grows. It is the inverse of y = x² restricted to x ≥ 0, and appears in standard deviations and Euclidean distances.","origin":"","implementations":[{"name":"numpy.sqrt","library":"NumPy","note":"Elementwise nonnegative square root."},{"name":"math.sqrt","library":"Python standard library","note":"Square root of a nonnegative number."},{"name":"torch.sqrt","library":"PyTorch","note":"Elementwise square root of a tensor."}]},"F.6":{"spoken":[{"line":1,"text":"y equals 1 over x"},{"line":2,"text":"asymptotes x equals 0, y equals 0"}],"terms":[{"term":"y","meaning":"The output value, the reciprocal of x, which is never zero.","function":false},{"term":"x","meaning":"The input variable, which cannot be 0 because division by zero is undefined.","function":false}],"explanation":"The reciprocal function y = 1/x is undefined at x = 0 and its graph is a hyperbola with two branches in the first and third quadrants. As x approaches 0 the values blow up, giving a vertical asymptote x = 0, and as |x| grows the values approach 0, giving a horizontal asymptote y = 0. It is the basic model of inverse proportion.","origin":"","implementations":[{"name":"numpy.reciprocal","library":"NumPy","note":"Elementwise reciprocal 1/x."},{"name":"torch.reciprocal","library":"PyTorch","note":"Elementwise reciprocal of a tensor."}]},"F.7":{"spoken":[{"line":1,"text":"y equals e to the x, b to the x, with b greater than 1"},{"line":2,"text":"y-intercept 1; HA y equals 0"}],"terms":[{"term":"y","meaning":"The output value of the exponential growth function, always positive.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential function used here.","function":false},{"term":"x","meaning":"The exponent, which is the input variable of the exponential function.","function":false},{"term":"b","meaning":"A general base; growth requires b greater than 1.","function":false},{"term":"HA","meaning":"Horizontal asymptote: the line y equals 0 approached as x goes to negative infinity.","function":false}],"explanation":"Exponential growth y = eˣ, or more generally bˣ with b > 1, increases by a constant factor for each unit step in x, so growth accelerates. Every such curve passes through (0, 1), since b⁰ = 1, and approaches the horizontal asymptote y = 0 as x → −∞. The base e is special because eˣ is its own derivative, which is why it models compounding and unchecked population growth.","origin":"Leonhard Euler named the constant e and established the exponential function's central role in the 1730s–1740s.","implementations":[{"name":"numpy.exp","library":"NumPy","note":"Elementwise natural exponential eˣ."},{"name":"math.exp","library":"Python standard library","note":"Natural exponential of a number."},{"name":"numpy.power","library":"NumPy","note":"Elementwise powers, e.g. bˣ."},{"name":"torch.exp","library":"PyTorch","note":"Elementwise exponential of a tensor."}]},"F.8":{"spoken":[{"line":1,"text":"y equals e to the negative x, the quantity b to the x, 0 less than b less than 1"},{"line":2,"text":"half-life the natural log of 2 over k"}],"terms":[{"term":"y","meaning":"The output value of the exponential decay function, always positive.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential function used here.","function":false},{"term":"x","meaning":"The input variable, often representing elapsed time in decay problems.","function":false},{"term":"b","meaning":"A general base; decay requires b between 0 and 1.","function":false},{"term":"ln","meaning":"Natural logarithm function; ln 2, about 0.693, appears in the half-life formula.","function":true},{"term":"k","meaning":"The decay rate constant in e to the negative k x.","function":false}],"explanation":"Exponential decay y = e⁻ˣ, or bˣ with 0 < b < 1, shrinks by a constant factor per unit of x, falling quickly at first and then levelling off toward zero. For a decay rate k, as in y = e^(−kx), the half-life, the time for the quantity to halve, is ln 2 / k regardless of the starting amount. It models radioactive decay, cooling and drug clearance.","origin":"","implementations":[{"name":"numpy.exp","library":"NumPy","note":"Elementwise exponential; use a negative argument for decay."},{"name":"math.exp","library":"Python standard library","note":"Natural exponential of a number."},{"name":"torch.exp","library":"PyTorch","note":"Elementwise exponential of a tensor."}]},"F.9":{"spoken":[{"line":1,"text":"y equals the natural log of x"},{"line":2,"text":"domain x greater than 0; VA x equals 0; the natural log of 1 equals 0"}],"terms":[{"term":"y","meaning":"The output value of the natural logarithm at input x.","function":false},{"term":"ln","meaning":"Natural logarithm: takes a positive number and returns the power to which e must be raised to get it.","function":true},{"term":"x","meaning":"The input, which must be positive for the natural logarithm to be defined.","function":false},{"term":"VA","meaning":"Vertical asymptote: the line x equals 0, which the curve approaches but never touches.","function":false}],"explanation":"The natural logarithm ln x is the inverse of eˣ: it gives the power to which e must be raised to get x. It is defined only for x > 0, has a vertical asymptote at x = 0, passes through (1, 0), and grows without bound but very slowly. Logs turn products into sums, which is why log-likelihoods and log scales are so common.","origin":"John Napier introduced logarithms in 1614; the natural logarithm's link to e was developed later in the 17th and 18th centuries.","implementations":[{"name":"numpy.log","library":"NumPy","note":"Elementwise natural logarithm."},{"name":"math.log","library":"Python standard library","note":"Natural log, or log to a given base."},{"name":"numpy.log1p","library":"NumPy","note":"Accurate ln(1 + x) for small x."},{"name":"torch.log","library":"PyTorch","note":"Elementwise natural logarithm of a tensor."}]},"F.10":{"spoken":[{"line":1,"text":"y equals sine x"},{"line":2,"text":"period 2 pi; sine 0 equals 0"}],"terms":[{"term":"y","meaning":"The output value of the sine function, between negative 1 and 1.","function":false},{"term":"sin","meaning":"Sine function: takes an angle in radians and returns the vertical coordinate on the unit circle.","function":true},{"term":"x","meaning":"The input angle of the sine function, measured in radians.","function":false},{"term":"π","meaning":"Pi, about 3.14159; 2 pi is one full cycle.","function":false}],"explanation":"The sine function gives the y-coordinate of a point on the unit circle at angle x radians. It oscillates smoothly between −1 and 1, repeats every 2π, and is an odd function with sin 0 = 0. Sines model waves, oscillations and seasonal cycles, and by Fourier analysis sums of sines and cosines can represent very general periodic signals.","origin":"","implementations":[{"name":"numpy.sin","library":"NumPy","note":"Elementwise sine of angles in radians."},{"name":"math.sin","library":"Python standard library","note":"Sine of an angle in radians."},{"name":"torch.sin","library":"PyTorch","note":"Elementwise sine of a tensor."}]},"F.11":{"spoken":[{"line":1,"text":"y equals cosine x"},{"line":2,"text":"period 2 pi; cosine 0 equals 1"}],"terms":[{"term":"y","meaning":"The output value of the cosine function, between negative 1 and 1.","function":false},{"term":"cos","meaning":"Cosine function: takes an angle in radians and returns the horizontal coordinate on the unit circle.","function":true},{"term":"x","meaning":"The input angle of the cosine function, measured in radians.","function":false},{"term":"π","meaning":"Pi, about 3.14159; 2 pi is one full cycle.","function":false}],"explanation":"The cosine function gives the x-coordinate of a point on the unit circle at angle x radians. It oscillates between −1 and 1 with period 2π, is an even function, and starts at its maximum, cos 0 = 1. Its graph is the sine curve shifted left by π/2, and it is the basis of cosine similarity between vectors.","origin":"","implementations":[{"name":"numpy.cos","library":"NumPy","note":"Elementwise cosine of angles in radians."},{"name":"math.cos","library":"Python standard library","note":"Cosine of an angle in radians."},{"name":"torch.cos","library":"PyTorch","note":"Elementwise cosine of a tensor."}]},"F.12":{"spoken":[{"line":1,"text":"y equals tangent x equals sine x over cosine x"},{"line":2,"text":"period pi; VA at x equals plus or minus pi over 2"}],"terms":[{"term":"y","meaning":"The output value of the tangent function, any real number.","function":false},{"term":"tan","meaning":"Tangent function: takes an angle and returns sine over cosine, the slope of that angle.","function":true},{"term":"x","meaning":"The input angle of the tangent function, measured in radians.","function":false},{"term":"sin","meaning":"Sine function: takes an angle and returns its sine, the numerator of tangent.","function":true},{"term":"cos","meaning":"Cosine function, the denominator; where it is zero, tangent is undefined.","function":true},{"term":"π","meaning":"Pi, about 3.14159, the ratio of a circle's circumference to its diameter, appearing here as the period of tangent and in its asymptotes.","function":false},{"term":"VA","meaning":"Vertical asymptotes of tangent, located where cosine of x equals zero.","function":false},{"term":"±","meaning":"Plus or minus: indicates both the positive and the negative value.","function":false}],"explanation":"The tangent function is the ratio sin x / cos x, the slope of the line from the origin at angle x. It is undefined wherever cos x = 0, giving vertical asymptotes at x = ±π/2 and every π beyond. Between asymptotes it rises from −∞ to ∞, so its period is π, half that of sine and cosine. It is odd, with tan 0 = 0.","origin":"","implementations":[{"name":"numpy.tan","library":"NumPy","note":"Elementwise tangent of angles in radians."},{"name":"math.tan","library":"Python standard library","note":"Tangent of an angle in radians."},{"name":"torch.tan","library":"PyTorch","note":"Elementwise tangent of a tensor."}]},"F.13":{"spoken":[{"line":1,"text":"y equals arctangent x"},{"line":2,"text":"HA y equals plus or minus pi over 2"}],"terms":[{"term":"y","meaning":"The output angle in radians, between negative pi over 2 and pi over 2.","function":false},{"term":"arctan","meaning":"Inverse tangent: takes any real number and returns the angle whose tangent is that number.","function":true},{"term":"x","meaning":"The input, which can be any real number for arctangent.","function":false},{"term":"HA","meaning":"Horizontal asymptotes, approached as x goes to plus or minus infinity.","function":false},{"term":"±","meaning":"Plus or minus: indicates both the positive and the negative value.","function":false},{"term":"π","meaning":"Pi, about 3.14159, the ratio of a circle's circumference to its diameter, appearing here as pi over 2 in the asymptotes.","function":false}],"explanation":"Arctangent is the inverse of tangent restricted to (−π/2, π/2): it returns the angle whose tangent is x. Defined for all real x, it increases smoothly and levels off at horizontal asymptotes y = ±π/2, giving an S-shaped curve. It converts slopes to angles, and its two-argument form atan2(y, x) recovers the full angle of a point in the plane.","origin":"","implementations":[{"name":"numpy.arctan","library":"NumPy","note":"Elementwise inverse tangent in radians."},{"name":"numpy.arctan2","library":"NumPy","note":"Quadrant-aware angle of the point (x, y)."},{"name":"math.atan","library":"Python standard library","note":"Inverse tangent of a number."},{"name":"torch.atan","library":"PyTorch","note":"Elementwise inverse tangent of a tensor."}]},"F.14":{"spoken":[{"line":1,"text":"sigma of x equals 1 over 1 plus e to the negative x"},{"line":2,"text":"range 0 to 1, open interval; sigma of 0 equals one half"}],"terms":[{"term":"σ","meaning":"Logistic sigmoid: takes any real number and returns a value strictly between 0 and 1.","function":true},{"term":"x","meaning":"The input to the sigmoid, which can be any real number.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential function used here.","function":false}],"explanation":"The logistic sigmoid σ(x) = 1/(1 + e⁻ˣ) squashes any real number into (0, 1), with σ(0) = 1/2 and symmetric S-shaped tails. Its output reads naturally as a probability, which is why logistic regression and binary classifier outputs use it. Its derivative is σ(1 − σ), simple to compute, though it becomes tiny for large |x|, causing vanishing gradients in deep networks.","origin":"Pierre-François Verhulst introduced the logistic function between 1838 and 1845 to model population growth.","implementations":[{"name":"scipy.special.expit","library":"SciPy","note":"Numerically stable logistic sigmoid."},{"name":"torch.sigmoid","library":"PyTorch","note":"Elementwise sigmoid of a tensor."},{"name":"torch.nn.Sigmoid","library":"PyTorch","note":"Sigmoid activation module."},{"name":"tf.math.sigmoid","library":"TensorFlow","note":"Elementwise sigmoid."}]},"F.15":{"spoken":[{"line":1,"text":"hyperbolic tangent of x equals the quantity e to the x minus e to the negative x over the quantity e to the x plus e to the negative x"},{"line":2,"text":"range negative 1 to 1, open interval; odd"}],"terms":[{"term":"tanh","meaning":"Hyperbolic tangent: takes any real number and returns a value strictly between negative 1 and 1.","function":true},{"term":"x","meaning":"The input to the hyperbolic tangent, which can be any real number.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential function used here.","function":false}],"explanation":"The hyperbolic tangent is the ratio of sinh to cosh, written with exponentials as (eˣ − e⁻ˣ)/(eˣ + e⁻ˣ). It is an S-shaped curve with range (−1, 1), odd symmetry and tanh 0 = 0. It is a rescaled sigmoid, tanh x = 2σ(2x) − 1, and its zero-centered outputs made it a popular hidden-layer activation in neural networks.","origin":"Vincenzo Riccati introduced the hyperbolic functions in the 1760s, and Johann Heinrich Lambert developed them further.","implementations":[{"name":"numpy.tanh","library":"NumPy","note":"Elementwise hyperbolic tangent."},{"name":"torch.tanh","library":"PyTorch","note":"Elementwise tanh of a tensor."},{"name":"torch.nn.Tanh","library":"PyTorch","note":"Tanh activation module."},{"name":"math.tanh","library":"Python standard library","note":"Hyperbolic tangent of a number."}]},"F.16":{"spoken":[{"line":1,"text":"ReLU of x equals the max of 0 and x"}],"terms":[{"term":"ReLU","meaning":"Rectified linear unit: returns x when positive and 0 otherwise.","function":true},{"term":"x","meaning":"The input to ReLU, which can be any real number.","function":false},{"term":"max","meaning":"Takes two numbers and returns the larger; here it compares 0 with x.","function":true}],"explanation":"The rectified linear unit outputs x for positive inputs and 0 otherwise, so its graph is flat then a 45° line with a kink at 0. Its gradient is simply 1 or 0, which avoids the vanishing gradients of sigmoid and tanh and makes deep networks fast to train. Units stuck in the negative region can stop learning, which variants like leaky ReLU address.","origin":"Kunihiko Fukushima used rectifying units in 1969, and Vinod Nair and Geoffrey Hinton popularized ReLU for deep learning in 2010.","implementations":[{"name":"torch.nn.ReLU","library":"PyTorch","note":"ReLU activation module."},{"name":"torch.nn.functional.relu","library":"PyTorch","note":"Functional elementwise ReLU."},{"name":"tf.nn.relu","library":"TensorFlow","note":"Elementwise ReLU."},{"name":"numpy.maximum","library":"NumPy","note":"Elementwise maximum; numpy.maximum(0, x) gives ReLU."}]},"F.17":{"spoken":[{"line":1,"text":"y equals e to the negative x squared"},{"line":2,"text":"even; maximum 1 at x equals 0"}],"terms":[{"term":"y","meaning":"The output value of the Gaussian bell curve, between 0 and 1.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential function used here.","function":false},{"term":"x","meaning":"The input variable; it is squared, so the curve is symmetric about 0.","function":false}],"explanation":"The Gaussian function y = e^(−x²) is a symmetric bell curve with maximum 1 at x = 0, decaying faster than any exponential in both directions. It is even, and its total area is √π. Shifting, scaling and normalizing it gives the normal probability density, and the same shape appears in RBF kernels and Gaussian smoothing filters.","origin":"Abraham de Moivre derived the bell curve in 1733 as an approximation to the binomial, and Carl Friedrich Gauss used it for errors in 1809.","implementations":[{"name":"numpy.exp","library":"NumPy","note":"Compute numpy.exp(-x**2) elementwise."},{"name":"scipy.signal.windows.gaussian","library":"SciPy","note":"Gaussian window of given length and standard deviation."},{"name":"scipy.ndimage.gaussian_filter","library":"SciPy","note":"Smooths arrays with a Gaussian kernel."}]},"F.18":{"spoken":[{"line":1,"text":"y equals the floor of x"},{"line":2,"text":"greatest integer less than or equal to x"}],"terms":[{"term":"y","meaning":"The output of the floor function, which is always an integer.","function":false},{"term":"⌊ ⌋","meaning":"Floor function: takes a real number and returns the greatest integer less than or equal to it.","function":true},{"term":"x","meaning":"The input to the floor function, which can be any real number.","function":false}],"explanation":"The floor function ⌊x⌋ returns the greatest integer less than or equal to x, so ⌊2.7⌋ = 2 and ⌊−2.3⌋ = −3. Its graph is a staircase of horizontal steps, closed on the left and open on the right, with jump discontinuities at every integer. It is used for rounding down, binning and integer division.","origin":"Kenneth Iverson introduced the ⌊x⌋ notation in 1962.","implementations":[{"name":"math.floor","library":"Python standard library","note":"Largest integer ≤ x."},{"name":"numpy.floor","library":"NumPy","note":"Elementwise floor."},{"name":"torch.floor","library":"PyTorch","note":"Elementwise floor of a tensor."}]},"D.1":{"spoken":[{"line":1,"text":"the probability that X equals 1 equals p, the probability that X equals 0 equals 1 minus p"},{"line":2,"text":"mu equals p, sigma squared equals p times the quantity 1 minus p"}],"terms":[{"term":"P","meaning":"Probability function: returns the probability of the event inside the parentheses.","function":true},{"term":"X","meaning":"A Bernoulli random variable: 1 for success, 0 for failure.","function":false},{"term":"p","meaning":"The probability of success on the single trial.","function":false},{"term":"μ","meaning":"The mean (expected value) of the Bernoulli variable X, equal to p.","function":false},{"term":"σ²","meaning":"The variance of the Bernoulli variable X, largest when p equals one half.","function":false}],"explanation":"A Bernoulli random variable models a single trial with two outcomes: 1 (success) with probability p and 0 (failure) with probability 1 − p. Its mean is p, and its variance p(1 − p) is largest at p = 1/2 when the outcome is most uncertain. It is the building block of the binomial and geometric distributions and of logistic regression's likelihood.","origin":"It is named for Jacob Bernoulli, whose Ars Conjectandi was published posthumously in 1713.","implementations":[{"name":"scipy.stats.bernoulli","library":"SciPy","note":"Bernoulli distribution: pmf, cdf and random samples."},{"name":"torch.distributions.Bernoulli","library":"PyTorch","note":"Bernoulli distribution with sampling and log_prob."},{"name":"numpy.random.Generator.binomial","library":"NumPy","note":"Bernoulli draws when n = 1."}]},"D.2":{"spoken":[{"line":1,"text":"the probability that X equals k equals n choose k times p to the k times the quantity 1 minus p to the n minus k"},{"line":2,"text":"mu equals n p, sigma squared equals n p times the quantity 1 minus p"}],"terms":[{"term":"P","meaning":"Probability function: returns the probability of the event inside the parentheses.","function":true},{"term":"X","meaning":"The number of successes in n independent trials.","function":false},{"term":"k","meaning":"A particular count of successes, from 0 to n.","function":false},{"term":"(n k)","meaning":"Binomial coefficient, n choose k: the number of ways to choose which k of the n trials succeed.","function":true},{"term":"n","meaning":"The number of independent trials, each with the same success probability.","function":false},{"term":"p","meaning":"The probability of success on each individual trial.","function":false},{"term":"μ","meaning":"The mean (expected number of successes) of the binomial variable X.","function":false},{"term":"σ²","meaning":"The variance of the binomial count of successes X.","function":false}],"explanation":"The binomial distribution counts successes k in n independent Bernoulli trials with success probability p. The binomial coefficient (n choose k) counts the ways to place k successes, and p^k(1 − p)^(n−k) is the probability of any one arrangement. Because it sums n independent Bernoullis, its mean is np and its variance np(1 − p).","origin":"Jacob Bernoulli derived the binomial distribution in Ars Conjectandi, published in 1713.","implementations":[{"name":"scipy.stats.binom","library":"SciPy","note":"Binomial distribution: pmf, cdf and random samples."},{"name":"numpy.random.Generator.binomial","library":"NumPy","note":"Draws binomial samples."},{"name":"torch.distributions.Binomial","library":"PyTorch","note":"Binomial distribution with sampling and log_prob."},{"name":"dbinom","library":"R stats","note":"Binomial pmf; pbinom, qbinom, rbinom companions."}]},"D.3":{"spoken":[{"line":1,"text":"the probability that X equals k equals the quantity 1 minus p to the k minus 1, times p, k equals 1, 2, and so on"},{"line":2,"text":"trials to first success; mu equals 1 over p, sigma squared equals the quantity 1 minus p over p squared"}],"terms":[{"term":"P","meaning":"Probability function: returns the probability of the event inside the parentheses.","function":true},{"term":"X","meaning":"The trial number on which the first success occurs.","function":false},{"term":"k","meaning":"A possible value of X: 1, 2, 3, and so on.","function":false},{"term":"p","meaning":"The probability of success on each independent trial.","function":false},{"term":"…","meaning":"Ellipsis, meaning and so on: the possible values continue without end.","function":false},{"term":"μ","meaning":"The mean number of trials until the first success.","function":false},{"term":"σ²","meaning":"The variance of the number of trials until the first success.","function":false}],"explanation":"This geometric distribution counts the number of independent trials up to and including the first success. Getting the first success on trial k requires k − 1 failures followed by one success, giving (1 − p)^(k−1)p. The mean 1/p says rarer successes take longer on average. Like the exponential, it is memoryless: past failures do not change the wait ahead.","origin":"","implementations":[{"name":"scipy.stats.geom","library":"SciPy","note":"Geometric distribution on k = 1, 2, …: pmf, cdf, samples."},{"name":"numpy.random.Generator.geometric","library":"NumPy","note":"Draws trials-to-first-success samples (support 1, 2, …)."},{"name":"torch.distributions.Geometric","library":"PyTorch","note":"Geometric distribution counting failures (support 0, 1, …)."}]},"D.4":{"spoken":[{"line":1,"text":"the probability that X equals k equals lambda to the k times e to the negative lambda, over k factorial"},{"line":2,"text":"mu equals sigma squared equals lambda"}],"terms":[{"term":"P","meaning":"Probability function: returns the probability of the event inside the parentheses.","function":true},{"term":"X","meaning":"The count of events in a fixed interval.","function":false},{"term":"k","meaning":"A particular count, 0, 1, 2, and so on.","function":false},{"term":"λ","meaning":"The average rate: expected number of events per interval.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential function used here.","function":false},{"term":"!","meaning":"Factorial: k factorial is the product of integers from 1 to k.","function":true},{"term":"μ","meaning":"The mean (expected count) of the Poisson variable X, equal to lambda.","function":false},{"term":"σ²","meaning":"The variance of X, equal to its mean for a Poisson.","function":false}],"explanation":"The Poisson distribution gives the probability of k events in a fixed interval when events occur independently at a constant average rate λ. It arises as the limit of the binomial with many trials and small success probability, np = λ. A distinctive feature is that its mean and variance both equal λ, which is used to check count data for overdispersion.","origin":"Siméon Denis Poisson introduced the distribution in 1837.","implementations":[{"name":"scipy.stats.poisson","library":"SciPy","note":"Poisson distribution: pmf, cdf and random samples."},{"name":"numpy.random.Generator.poisson","library":"NumPy","note":"Draws Poisson samples."},{"name":"torch.distributions.Poisson","library":"PyTorch","note":"Poisson distribution with sampling and log_prob."},{"name":"dpois","library":"R stats","note":"Poisson pmf; ppois, qpois, rpois companions."}]},"D.5":{"spoken":[{"line":1,"text":"f of x equals 1 over the quantity b minus a, for a less than or equal to x less than or equal to b"},{"line":2,"text":"mu equals the quantity a plus b over 2, sigma squared equals the quantity b minus a squared over 12"}],"terms":[{"term":"f","meaning":"Probability density function: takes a value x and returns the density there, constant on the interval.","function":true},{"term":"x","meaning":"A value of the uniform random variable within the interval from a to b.","function":false},{"term":"a","meaning":"The lower endpoint of the interval on which the density is positive.","function":false},{"term":"b","meaning":"The upper endpoint of the interval on which the density is positive.","function":false},{"term":"μ","meaning":"The mean of the uniform distribution, the midpoint of the interval.","function":false},{"term":"σ²","meaning":"The variance of the uniform distribution, growing with the interval's width.","function":false}],"explanation":"The continuous uniform distribution gives every value in [a, b] equal density, so the density is the constant 1/(b − a) that makes total area one. Its mean is the midpoint (a + b)/2 and its variance (b − a)²/12. It models complete ignorance within bounds and is the basis of random number generation, since other distributions can be produced by transforming uniform draws.","origin":"","implementations":[{"name":"scipy.stats.uniform","library":"SciPy","note":"Uniform on [loc, loc + scale]: pdf, cdf, samples."},{"name":"numpy.random.Generator.uniform","library":"NumPy","note":"Draws uniform samples on [low, high)."},{"name":"torch.distributions.Uniform","library":"PyTorch","note":"Uniform distribution with sampling and log_prob."},{"name":"runif","library":"R stats","note":"Uniform random draws; dunif, punif, qunif companions."}]},"D.6":{"spoken":[{"line":1,"text":"f of x equals 1 over sigma times the square root of 2 pi, times e to the negative the quantity x minus mu squared over 2 sigma squared"}],"terms":[{"term":"f","meaning":"Probability density function: takes a value x and returns the normal density there.","function":true},{"term":"x","meaning":"A value of the normally distributed random variable.","function":false},{"term":"σ","meaning":"The standard deviation, controlling the width of the bell curve.","function":false},{"term":"√","meaning":"Square root function: takes a nonnegative number and returns its root; here the root of 2 pi.","function":true},{"term":"π","meaning":"Pi, about 3.14159, the ratio of a circle's circumference to its diameter, appearing here as part of the normalizing constant.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential function used here.","function":false},{"term":"μ","meaning":"The mean, which is the center and peak location of the bell curve.","function":false},{"term":"σ²","meaning":"The variance, the square of the standard deviation, in the exponent's denominator.","function":false}],"explanation":"The normal distribution is the symmetric bell curve with mean μ and standard deviation σ; the exponent penalizes squared distance from μ and the constant makes total area one. About 68%, 95% and 99.7% of values lie within one, two and three standard deviations of the mean. By the central limit theorem, sums and averages of many independent effects are approximately normal.","origin":"Abraham de Moivre derived it in 1733 as an approximation to the binomial; Gauss (1809) and Laplace developed it as the law of errors.","implementations":[{"name":"scipy.stats.norm","library":"SciPy","note":"Normal distribution: pdf, cdf, ppf and samples."},{"name":"numpy.random.Generator.normal","library":"NumPy","note":"Draws normal samples with given mean and scale."},{"name":"torch.distributions.Normal","library":"PyTorch","note":"Normal distribution with sampling and log_prob."},{"name":"dnorm","library":"R stats","note":"Normal pdf; pnorm, qnorm, rnorm companions."}]},"D.7":{"spoken":[{"line":0,"text":"Student's t, versus normal"},{"line":1,"text":"f of t is proportional to the quantity 1 plus t squared over nu, to the negative the quantity nu plus 1 over 2"},{"line":2,"text":"heavier tails; t approaches N of 0 comma 1 as nu approaches infinity"}],"terms":[{"term":"t","meaning":"The t-distributed random variable, or the value at which its density is evaluated.","function":false},{"term":"f","meaning":"Probability density function of the t distribution: takes a value t and returns its density.","function":true},{"term":"∝","meaning":"Proportional to: equal up to a normalizing constant.","function":false},{"term":"ν","meaning":"Degrees of freedom; smaller values give heavier tails.","function":false},{"term":"→","meaning":"Approaches: the t distribution converges to the standard normal as nu grows.","function":false},{"term":"N(0, 1)","meaning":"The standard normal distribution: mean 0, variance 1.","function":false},{"term":"∞","meaning":"Infinity: the degrees of freedom growing without bound.","function":false}],"explanation":"Student's t distribution describes a standardized sample mean when the population standard deviation is estimated from the data. It is bell-shaped and symmetric like the standard normal but has heavier tails, controlled by the degrees of freedom ν, reflecting extra uncertainty in small samples. As ν → ∞ it converges to N(0, 1). It underlies t-tests and confidence intervals for means.","origin":"William Sealy Gosset published it in 1908 under the pseudonym 'Student', and Ronald Fisher later extended its use.","implementations":[{"name":"scipy.stats.t","library":"SciPy","note":"Student's t distribution: pdf, cdf, ppf and samples."},{"name":"numpy.random.Generator.standard_t","library":"NumPy","note":"Draws standard t samples with df degrees of freedom."},{"name":"torch.distributions.StudentT","library":"PyTorch","note":"Student's t distribution with sampling and log_prob."},{"name":"scipy.stats.ttest_ind","library":"SciPy","note":"Two-sample t-test using the t distribution."}]},"D.8":{"spoken":[{"line":1,"text":"f of x equals lambda e to the negative lambda x, x greater than or equal to 0"},{"line":2,"text":"mu equals 1 over lambda; memoryless"}],"terms":[{"term":"f","meaning":"Probability density function: returns the density of waiting time x.","function":true},{"term":"x","meaning":"A waiting time until the next event, which must be nonnegative.","function":false},{"term":"λ","meaning":"The rate parameter: the average number of events per unit time.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential function used here.","function":false},{"term":"μ","meaning":"The mean waiting time of the exponential distribution, one over lambda.","function":false}],"explanation":"The exponential distribution models the waiting time until the next event in a Poisson process with rate λ. Its density λe^(−λx) starts at λ and decays, giving mean 1/λ. It is the only continuous memoryless distribution: the probability of waiting another t units is the same no matter how long you have already waited, which suits lifetimes with constant hazard.","origin":"","implementations":[{"name":"scipy.stats.expon","library":"SciPy","note":"Exponential distribution; scale = 1/λ."},{"name":"numpy.random.Generator.exponential","library":"NumPy","note":"Draws exponential samples; scale = 1/λ."},{"name":"torch.distributions.Exponential","library":"PyTorch","note":"Exponential distribution parameterized by rate."},{"name":"dexp","library":"R stats","note":"Exponential pdf; pexp, qexp, rexp companions."}]},"D.9":{"spoken":[{"line":1,"text":"f of x equals x to the k minus 1 times e to the negative x over theta, all over gamma of k times theta to the k"},{"line":2,"text":"mu equals k theta, sigma squared equals k theta squared"}],"terms":[{"term":"f","meaning":"Probability density function of the gamma distribution, for x greater than 0.","function":true},{"term":"x","meaning":"A positive value of the gamma random variable, such as a total waiting time.","function":false},{"term":"k","meaning":"The shape parameter of the gamma distribution, controlling its skewness.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential function used here.","function":false},{"term":"θ","meaning":"The scale parameter of the gamma distribution, stretching it horizontally.","function":false},{"term":"Γ","meaning":"Gamma function: takes a positive number and returns a generalized factorial, gamma of k equals k minus 1 factorial for integers; normalizes the density.","function":true},{"term":"μ","meaning":"The mean of the gamma distribution, shape times scale.","function":false},{"term":"σ²","meaning":"The variance of the gamma distribution, shape times scale squared.","function":false}],"explanation":"The gamma distribution, with shape k and scale θ, models positive continuous quantities such as waiting times; for integer k it is the time until the k-th event of a Poisson process, a sum of k exponentials. The gamma function Γ(k) normalizes the density. Its mean is kθ and variance kθ². Exponential and chi-square distributions are special cases, and it is a common Bayesian prior for rates.","origin":"Its normalizing constant is the gamma function, introduced by Leonhard Euler around 1729–1730.","implementations":[{"name":"scipy.stats.gamma","library":"SciPy","note":"Gamma distribution with shape a and scale."},{"name":"numpy.random.Generator.gamma","library":"NumPy","note":"Draws gamma samples with shape and scale."},{"name":"torch.distributions.Gamma","library":"PyTorch","note":"Gamma distribution parameterized by concentration and rate."},{"name":"dgamma","library":"R stats","note":"Gamma pdf; pgamma, qgamma, rgamma companions."}]},"D.10":{"spoken":[{"line":1,"text":"f of x equals x to the alpha minus 1 times the quantity 1 minus x to the beta minus 1, all over B of alpha comma beta, for 0 less than or equal to x less than or equal to 1"},{"line":2,"text":"mu equals alpha over the quantity alpha plus beta"}],"terms":[{"term":"f","meaning":"Probability density function of the beta distribution on 0 to 1.","function":true},{"term":"x","meaning":"A value between 0 and 1, often a probability or proportion.","function":false},{"term":"α","meaning":"The first shape parameter of the beta distribution; larger alpha pulls mass toward 1.","function":false},{"term":"β","meaning":"The second shape parameter of the beta distribution; larger beta pulls mass toward 0.","function":false},{"term":"B","meaning":"Beta function: takes alpha and beta and returns the constant making the density integrate to 1.","function":true},{"term":"μ","meaning":"The mean of the beta distribution, alpha over alpha plus beta.","function":false}],"explanation":"The beta distribution lives on [0, 1], making it a natural model for probabilities and proportions. Shape parameters α and β control where mass concentrates: α = β = 1 is uniform, larger α pushes toward 1, larger β toward 0. The beta function B(α, β) normalizes the density, and the mean is α/(α + β). It is the conjugate prior for a Bernoulli or binomial success probability.","origin":"","implementations":[{"name":"scipy.stats.beta","library":"SciPy","note":"Beta distribution: pdf, cdf, ppf and samples."},{"name":"numpy.random.Generator.beta","library":"NumPy","note":"Draws beta samples."},{"name":"torch.distributions.Beta","library":"PyTorch","note":"Beta distribution with sampling and log_prob."},{"name":"dbeta","library":"R stats","note":"Beta pdf; pbeta, qbeta, rbeta companions."}]},"D.11":{"spoken":[{"line":1,"text":"chi squared sub k equals the sum from i equals 1 to k of Z sub i squared"},{"line":2,"text":"mu equals k, sigma squared equals 2 k; right-skewed"}],"terms":[{"term":"χ²_k","meaning":"A chi-square random variable with k degrees of freedom.","function":false},{"term":"k","meaning":"Degrees of freedom: the number of squared standard normals summed.","function":false},{"term":"Σ","meaning":"Summation operator: adds the squared terms from i equals 1 to k.","function":true},{"term":"i","meaning":"Index running over the k independent standard normal variables.","function":false},{"term":"Zᵢ","meaning":"Independent standard normal random variables, each with mean 0 and variance 1.","function":false},{"term":"μ","meaning":"The mean of the chi-square distribution, equal to its degrees of freedom k.","function":false},{"term":"σ²","meaning":"The variance of the chi-square distribution, equal to twice the degrees of freedom.","function":false}],"explanation":"The chi-square distribution with k degrees of freedom is the distribution of a sum of k squared independent standard normal variables. It is nonnegative and right-skewed, with mean k and variance 2k, becoming more symmetric as k grows. It is the reference distribution for goodness-of-fit and independence tests and for confidence intervals on a normal variance; it is a gamma with shape k/2 and scale 2.","origin":"Friedrich Robert Helmert derived the distribution in 1876, and Karl Pearson introduced the chi-square test in 1900.","implementations":[{"name":"scipy.stats.chi2","library":"SciPy","note":"Chi-square distribution: pdf, cdf, ppf and samples."},{"name":"numpy.random.Generator.chisquare","library":"NumPy","note":"Draws chi-square samples."},{"name":"torch.distributions.Chi2","library":"PyTorch","note":"Chi-square distribution with sampling and log_prob."},{"name":"scipy.stats.chisquare","library":"SciPy","note":"Chi-square goodness-of-fit test."}]},"D.12":{"spoken":[{"line":1,"text":"the natural log of X is distributed as N of mu comma sigma squared"},{"line":2,"text":"f of x equals 1 over x sigma times the square root of 2 pi, times e to the negative the quantity natural log of x minus mu squared over 2 sigma squared"}],"terms":[{"term":"ln","meaning":"Natural logarithm; the log of a log-normal variable is normal.","function":true},{"term":"X","meaning":"A positive log-normal random variable whose logarithm is normally distributed.","function":false},{"term":"~","meaning":"Tilde, read is distributed as: names the distribution of the quantity on its left.","function":false},{"term":"N","meaning":"Normal distribution with the given mean and variance, here describing ln X.","function":true},{"term":"μ","meaning":"The mean of ln X, not of X.","function":false},{"term":"σ²","meaning":"The variance of ln X, not the variance of X itself.","function":false},{"term":"f","meaning":"Probability density function of X, for x greater than 0.","function":true},{"term":"x","meaning":"A positive value at which the log-normal density is evaluated.","function":false},{"term":"σ","meaning":"The standard deviation of ln X, appearing in the normalizing constant.","function":false},{"term":"√","meaning":"Square root function: takes a nonnegative number and returns its root; here the root of 2 pi.","function":true},{"term":"π","meaning":"Pi, about 3.14159, the ratio of a circle's circumference to its diameter, appearing here as part of the normalizing constant.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential function used here.","function":false}],"explanation":"A variable X is log-normal when its logarithm is normally distributed with mean μ and variance σ². It is positive and right-skewed, with the density obtained from the normal by substituting ln x and including a 1/x factor from the change of variables. It arises when many independent factors multiply rather than add, modelling incomes, stock prices and particle sizes.","origin":"Francis Galton and Donald McAlister described the log-normal distribution in 1879.","implementations":[{"name":"scipy.stats.lognorm","library":"SciPy","note":"Log-normal with shape s = σ and scale = e^μ."},{"name":"numpy.random.Generator.lognormal","library":"NumPy","note":"Draws log-normal samples given the underlying mean and sigma."},{"name":"torch.distributions.LogNormal","library":"PyTorch","note":"Log-normal distribution with sampling and log_prob."},{"name":"dlnorm","library":"R stats","note":"Log-normal pdf; plnorm, qlnorm, rlnorm companions."}]},"D.13":{"spoken":[{"line":1,"text":"f of x equals alpha x sub m to the alpha over x to the alpha plus 1, x greater than or equal to x sub m"},{"line":2,"text":"heavy tail; mean finite if and only if alpha greater than 1"}],"terms":[{"term":"f","meaning":"Probability density function of the Pareto distribution, defined for x at least x sub m.","function":true},{"term":"x","meaning":"A value of the random variable, at least x sub m.","function":false},{"term":"α","meaning":"Tail index (shape); smaller alpha means a heavier tail.","function":false},{"term":"x_m","meaning":"The minimum possible value (scale parameter) of the Pareto distribution.","function":false},{"term":"iff","meaning":"If and only if: the condition is both necessary and sufficient.","function":false}],"explanation":"The Pareto distribution is a power law for values at or above a minimum xₘ: the density falls off like x^(−(α+1)), much more slowly than exponentially, so extreme values are relatively common. The tail index α controls tail heaviness; the mean is finite only when α > 1 and the variance only when α > 2. It models wealth, city sizes and the 80/20 rule.","origin":"Vilfredo Pareto introduced it in the 1890s to describe the distribution of income and wealth.","implementations":[{"name":"scipy.stats.pareto","library":"SciPy","note":"Pareto with shape b = α and scale = xₘ."},{"name":"torch.distributions.Pareto","library":"PyTorch","note":"Pareto distribution with scale and alpha."},{"name":"numpy.random.Generator.pareto","library":"NumPy","note":"Draws Pareto II (Lomax) samples; add 1 and multiply by xₘ."}]},"O.1":{"spoken":[{"line":0,"text":"minimize over bold x, f of bold x"},{"line":1,"text":"subject to g sub i of bold x less than or equal to zero, h sub j of bold x equals zero"}],"terms":[{"term":"min","meaning":"Minimization operator: takes the objective function over all allowed choices of the decision vector and returns its smallest value; here it defines the goal of the problem.","function":true},{"term":"𝐱","meaning":"Decision vector: the bold x collecting all the variables the optimizer is free to choose, such as quantities, settings or allocations.","function":false},{"term":"f","meaning":"Objective function: maps a candidate decision vector x to a single number (cost, loss, time) that the problem seeks to make as small as possible.","function":true},{"term":"s.t.","meaning":"Abbreviation for subject to: introduces the constraints that any feasible decision vector must satisfy while the objective is being minimized.","function":false},{"term":"gᵢ","meaning":"Inequality constraint functions, indexed by i: each takes x and returns a number that must be less than or equal to zero for x to be feasible.","function":true},{"term":"i","meaning":"Index counting the inequality constraints, running from 1 to the number of inequality constraints in the problem.","function":false},{"term":"≤","meaning":"Less than or equal to: requires each inequality constraint value g sub i of x to be at most zero, defining a feasible region boundary.","function":false},{"term":"hⱼ","meaning":"Equality constraint functions, indexed by j: each takes x and returns a number that must equal exactly zero for x to be feasible.","function":true},{"term":"j","meaning":"Index counting the equality constraints, running from 1 to the number of equality constraints in the problem.","function":false}],"explanation":"Every optimization problem has decision variables x, an objective f(x) to minimize or maximize, and constraints: inequalities gᵢ(x) ≤ 0 and equalities hⱼ(x) = 0. The constraints define the feasible region, and the goal is the best feasible point. The problem's form decides how hard it is to solve and which solver to use: linear (LP), mixed-integer (MIP) or nonlinear (NLP).","origin":"","implementations":[{"name":"scipy.optimize.minimize","library":"SciPy","note":"General constrained and unconstrained nonlinear minimization."},{"name":"cvxpy.Problem","library":"CVXPY","note":"Models and solves convex problems written as objective plus constraints."},{"name":"pyomo.environ.ConcreteModel","library":"Pyomo","note":"Algebraic modeling of LP, MIP and NLP models for external solvers."}]},"O.2":{"spoken":[{"line":0,"text":"maximize over bold x, c transpose x"},{"line":1,"text":"subject to A x less than or equal to b, x greater than or equal to zero"}],"terms":[{"term":"max","meaning":"Maximization operator: searches over all feasible decision vectors x and returns the largest value of the linear objective c transpose x.","function":true},{"term":"𝐱","meaning":"Vector of decision variables, such as production quantities, that the linear program chooses; each component must be nonnegative.","function":false},{"term":"𝐜","meaning":"Cost or profit coefficient vector: entry c sub j gives how much the objective gains per unit of decision variable x sub j.","function":false},{"term":"⊤","meaning":"Transpose: turns the column vector c into a row so c transpose x is the dot product, the sum of c sub j times x sub j.","function":true},{"term":"s.t.","meaning":"Subject to: introduces the linear constraints that every feasible solution must satisfy.","function":false},{"term":"A","meaning":"Constraint coefficient matrix: row i lists how much of resource i each unit of every decision variable consumes.","function":false},{"term":"𝐛","meaning":"Right-hand-side vector: entry b sub i is the available amount, capacity or limit of resource i in constraint i.","function":false},{"term":"≤","meaning":"Componentwise less than or equal to: every row of A x must not exceed the matching entry of b.","function":false},{"term":"≥","meaning":"Componentwise greater than or equal to: here x greater than or equal to zero is the nonnegativity constraint on all decision variables.","function":false}],"explanation":"A linear program maximizes a linear objective cᵀx subject to linear inequalities Ax ≤ b and nonnegativity x ≥ 0. The feasible region is a convex polyhedron and the objective is linear, so if an optimum exists it occurs at a vertex. That is why solving an LP comes down to checking corner points efficiently. LPs model resource allocation, blending, scheduling and transportation.","origin":"Leonid Kantorovich formulated linear programming in 1939, and George Dantzig developed the simplex method for solving it in 1947.","implementations":[{"name":"scipy.optimize.linprog","library":"SciPy","note":"Solves linear programs (HiGHS solvers)."},{"name":"pulp.LpProblem","library":"PuLP","note":"Builds LP models and solves them with CBC or other solvers."},{"name":"Solver","library":"Excel","note":"Add-in that solves linear programs with the Simplex LP method."}]},"O.3":{"spoken":[{"line":0,"text":"Primal: maximize c transpose x, A x less than or equal to b, x greater than or equal to zero"},{"line":1,"text":"Dual: minimize b transpose y, A transpose y greater than or equal to c, y greater than or equal to zero"},{"line":2,"text":"c transpose x is less than or equal to b transpose y"},{"line":3,"text":"optimal: c transpose x star equals b transpose y star"}],"terms":[{"term":"max","meaning":"Maximization operator: in the primal problem it returns the largest achievable value of c transpose x over feasible x.","function":true},{"term":"𝐜","meaning":"Objective coefficient vector of the primal; it also appears as the right-hand side of the dual constraints.","function":false},{"term":"⊤","meaning":"Transpose: flips a vector or matrix so products like c transpose x become dot products and A transpose swaps rows and columns.","function":true},{"term":"𝐱","meaning":"Primal decision vector, the nonnegative quantities chosen to maximize c transpose x within the resource constraints.","function":false},{"term":"A","meaning":"Constraint matrix of the primal; its transpose A transpose defines the constraints of the dual problem.","function":false},{"term":"𝐛","meaning":"Primal resource limits vector; in the dual it becomes the objective coefficients being minimized.","function":false},{"term":"min","meaning":"Minimization operator: in the dual problem it returns the smallest value of b transpose y over feasible y.","function":true},{"term":"𝐲","meaning":"Dual variable vector, one entry per primal constraint, interpretable as shadow prices: the value of one more unit of each resource.","function":false},{"term":"≤","meaning":"Weak duality: any feasible primal objective value is at most any feasible dual objective value, so the dual bounds the primal.","function":false},{"term":"𝐱*","meaning":"Optimal primal solution: the feasible x that achieves the maximum primal objective.","function":false},{"term":"𝐲*","meaning":"Optimal dual solution: the feasible y achieving the minimum dual objective; at optimality the two objective values are equal (strong duality).","function":false}],"explanation":"The simplex method moves from vertex to adjacent vertex, improving the objective at each step until no neighbor is better. Every primal LP has a dual: each primal constraint becomes a dual variable y, and the max becomes a min. Weak duality, cᵀx ≤ bᵀy, means any dual solution bounds the primal. At the optimum the two values are equal (strong duality), and the dual variables act as shadow prices on the constraints.","origin":"George Dantzig introduced the simplex method in 1947. John von Neumann proposed LP duality the same year, and Gale, Kuhn and Tucker published a proof in 1951.","implementations":[{"name":"scipy.optimize.linprog","library":"SciPy","note":"LP solver; method 'highs-ds' is dual simplex and it returns constraint marginals."},{"name":"pulp.LpProblem","library":"PuLP","note":"LP modeling; constraint .pi gives dual values after solving."}]},"O.4":{"spoken":[{"line":0,"text":"maximize c transpose x, A x less than or equal to b"},{"line":1,"text":"x sub j is an element of the integers (some or all), x sub j is an element of the set zero, one"},{"line":3,"text":"big M: x is less than or equal to M y"}],"terms":[{"term":"max","meaning":"Maximization operator: returns the largest value of the linear objective over all feasible, integer-restricted decision vectors.","function":true},{"term":"𝐜","meaning":"Objective coefficient vector giving the profit or value per unit of each decision variable.","function":false},{"term":"⊤","meaning":"Transpose: makes c transpose x the dot product, the sum over j of c sub j times x sub j.","function":true},{"term":"𝐱","meaning":"Vector of decision variables; in a mixed-integer program some components must be integers while others may stay continuous.","function":false},{"term":"A","meaning":"Constraint matrix whose rows encode the linear resource or logical constraints of the program.","function":false},{"term":"𝐛","meaning":"Right-hand-side vector of constraint limits, giving the capacity or available amount for each linear constraint.","function":false},{"term":"xⱼ","meaning":"The j-th decision variable, which may be restricted to integer values or to the binary values zero and one.","function":false},{"term":"∈","meaning":"Is an element of: states which set a variable's values must come from.","function":false},{"term":"ℤ","meaning":"The set of all integers; requiring x sub j in this set forces whole-number decisions such as counts of trucks or machines.","function":false},{"term":"{0,1}","meaning":"The binary set: a variable restricted to it models a yes-or-no decision, such as whether to open a facility.","function":false},{"term":"M","meaning":"Big-M constant: a large number chosen at least as big as any realistic value of x, used to switch a constraint on or off.","function":false},{"term":"x","meaning":"A continuous or integer variable linked to a binary indicator, such as the amount produced at a site.","function":false},{"term":"y","meaning":"Binary indicator variable: when y equals 0 the constraint forces x to zero; when y equals 1 x may go up to M.","function":false}],"explanation":"A mixed-integer program is an LP in which some variables must be integers, often binary yes/no decisions. Integrality makes the problem NP-hard. Dropping it gives the LP relaxation, whose optimum bounds the MIP's best value, and branch-and-bound uses those bounds to prune its search. The big-M trick x ≤ My links a continuous quantity to a binary switch y, so x can be positive only when y = 1.","origin":"Ralph Gomory introduced cutting-plane methods in 1958, and Ailsa Land and Alison Doig introduced branch-and-bound in 1960.","implementations":[{"name":"scipy.optimize.milp","library":"SciPy","note":"Solves mixed-integer linear programs with HiGHS."},{"name":"pulp.LpProblem","library":"PuLP","note":"Models MIPs with integer or binary variables; solves with CBC by default."},{"name":"pywraplp.Solver","library":"OR-Tools","note":"Google's linear and mixed-integer solver wrapper (SCIP, CBC, etc.)."}]},"O.5":{"spoken":[{"line":0,"text":"maximize the sum of v sub i x sub i subject to the sum of w sub i x sub i less than or equal to W, x sub i is an element of the set zero, one"},{"line":1,"text":"V of i comma w equals the max of V of i minus 1 comma w, and v sub i plus V of i minus 1 comma w minus w sub i"},{"line":2,"text":"big O of n W"}],"terms":[{"term":"max","meaning":"Maximization operator: returns the largest total value achievable; in the recursion it picks the better of skipping or taking item i.","function":true},{"term":"∑","meaning":"Summation over items i: adds up the value or weight of every item, counting only those with x sub i equal to 1.","function":true},{"term":"vᵢ","meaning":"Value (benefit or profit) of item i, gained if the item is placed in the knapsack.","function":false},{"term":"xᵢ","meaning":"Binary decision variable: 1 if item i is packed, 0 if it is left out.","function":false},{"term":"s.t.","meaning":"Subject to: introduces the capacity and binary constraints.","function":false},{"term":"wᵢ","meaning":"Weight (or size) of item i, which counts against the knapsack's capacity if the item is chosen.","function":false},{"term":"W","meaning":"Total weight capacity of the knapsack; the summed weight of chosen items cannot exceed it.","function":false},{"term":"{0,1}","meaning":"Binary set: each item is either taken whole or not at all, making this the 0-1 knapsack problem.","function":false},{"term":"V(i, w)","meaning":"Dynamic programming value function: takes the number of items considered i and remaining capacity w, returns the best total value achievable using only the first i items.","function":true},{"term":"i","meaning":"Index of the current item; V of i uses items 1 through i.","function":false},{"term":"w","meaning":"Remaining capacity available in the subproblem, an integer between 0 and W.","function":false},{"term":"O(·)","meaning":"Big-O notation: takes a function of the input size and describes the algorithm's growth rate; O of n W is the dynamic programming table size and running time.","function":true},{"term":"n","meaning":"Number of items available to choose from; together with W it sets the size of the dynamic programming table.","function":false}],"explanation":"The 0/1 knapsack problem picks items with values vᵢ and weights wᵢ to maximize total value without exceeding capacity W. The recurrence V(i, w) builds the solution from smaller ones: the best value using the first i items at capacity w is the better of skipping item i or taking it and using the remaining capacity. Filling the table takes O(nW) time. That is pseudo-polynomial, because the problem itself is NP-hard.","origin":"","implementations":[{"name":"knapsack_solver.KnapsackSolver","library":"OR-Tools","note":"Dedicated solver for 0/1 and multidimensional knapsack problems."},{"name":"scipy.optimize.milp","library":"SciPy","note":"Solves the knapsack written as a binary integer program."}]},"O.6":{"spoken":[{"line":0,"text":"minimize the sum over i not equal to j of c sub i j x sub i j"},{"line":1,"text":"the sum over j of x sub i j equals 1, the sum over i of x sub i j equals 1, x sub i j is an element of the set zero, one"},{"line":3,"text":"the quantity n minus 1 factorial, over 2, tours"}],"terms":[{"term":"min","meaning":"Minimization operator: returns the lowest total travel cost over all valid tours.","function":true},{"term":"∑","meaning":"Summation: adds terms over the indicated index; in the objective over all ordered city pairs, in the constraints over all departures or arrivals of a city.","function":true},{"term":"i","meaning":"Index of the city a leg departs from.","function":false},{"term":"j","meaning":"Index of the city a leg arrives at.","function":false},{"term":"≠","meaning":"Not equal: excludes pairs where a city would travel to itself.","function":false},{"term":"cᵢⱼ","meaning":"Cost, distance or travel time of going directly from city i to city j.","function":false},{"term":"xᵢⱼ","meaning":"Binary decision variable equal to 1 if the tour travels directly from city i to city j, and 0 otherwise.","function":false},{"term":"{0,1}","meaning":"Binary set: each possible leg is either used in the tour or not.","function":false},{"term":"n","meaning":"Number of cities that the salesman must visit exactly once before returning home.","function":false},{"term":"!","meaning":"Factorial: takes a whole number and returns the product of all positive integers up to it; it counts orderings of the cities.","function":true}],"explanation":"The traveling salesman problem seeks the cheapest tour that visits every city exactly once and returns to the start. In the integer program, xᵢⱼ = 1 if the tour goes from i to j, and the degree constraints force exactly one arrival and one departure per city. Subtour-elimination constraints rule out disconnected small loops. Brute force must check (n − 1)!/2 tours, so practical methods use cutting planes, branch-and-bound or heuristics.","origin":"Dantzig, Fulkerson and Johnson solved a 49-city instance in 1954 using LP relaxation with cutting planes.","implementations":[{"name":"networkx.algorithms.approximation.traveling_salesman_problem","library":"NetworkX","note":"Approximate TSP tours (Christofides, simulated annealing, etc.)."},{"name":"pywrapcp.RoutingModel","library":"OR-Tools","note":"Routing solver for TSP and vehicle routing problems."},{"name":"Concorde","library":"Concorde TSP Solver","note":"Exact branch-and-cut solver for symmetric TSP."}]},"O.7":{"spoken":[{"line":0,"text":"d of v equals the minimum over u of the quantity d of u plus w of u comma v"},{"line":1,"text":"Dijkstra: w greater than or equal to zero; Bellman–Ford: any w"},{"line":2,"text":"max flow equals min cut"}],"terms":[{"term":"d(v)","meaning":"Shortest-path distance function: takes a node v and returns the length of the shortest path from the source node to v.","function":true},{"term":"v","meaning":"The node whose shortest distance is being computed.","function":false},{"term":"min","meaning":"Minimization operator: over all predecessor nodes u with an edge into v, returns the smallest candidate distance.","function":true},{"term":"u","meaning":"A neighbor node with an edge leading into v, a possible last stop before reaching v.","function":false},{"term":"w(u, v)","meaning":"Edge weight function: takes the edge from u to v and returns its length, cost or travel time.","function":true},{"term":"w","meaning":"Edge weights in general; Dijkstra requires all to be nonnegative, while Bellman-Ford tolerates negative weights without negative cycles.","function":false},{"term":"max flow","meaning":"The largest total amount that can be sent from source to sink without exceeding any edge's capacity.","function":false},{"term":"min cut","meaning":"The smallest total capacity of edges whose removal separates the source from the sink; it equals the maximum flow.","function":false}],"explanation":"Shortest-path algorithms apply the Bellman recurrence d(v) = minᵤ[d(u) + w(u, v)]: the best distance to v comes through its best predecessor. Dijkstra's algorithm settles nodes greedily and needs nonnegative weights. Bellman–Ford relaxes every edge repeatedly, so it handles negative weights and detects negative cycles. In network flow, the max-flow min-cut theorem says the largest flow from source to sink equals the smallest total capacity of edges whose removal separates them.","origin":"Edsger Dijkstra devised his algorithm in 1956 (published 1959). Bellman and Ford published their method in the late 1950s, and Ford and Fulkerson proved max-flow min-cut in 1956.","implementations":[{"name":"networkx.shortest_path","library":"NetworkX","note":"Shortest path; uses Dijkstra when weighted."},{"name":"networkx.bellman_ford_path","library":"NetworkX","note":"Shortest path allowing negative edge weights."},{"name":"networkx.maximum_flow","library":"NetworkX","note":"Computes maximum flow value and flow on each edge."},{"name":"scipy.sparse.csgraph.dijkstra","library":"SciPy","note":"Dijkstra shortest paths on sparse graph matrices."}]},"O.8":{"spoken":[{"line":0,"text":"f of the quantity lambda x plus the quantity 1 minus lambda, y, is less than or equal to lambda f of x plus the quantity 1 minus lambda, f of y"},{"line":1,"text":"f double prime of x greater than or equal to zero, or del squared f is positive semidefinite"},{"line":2,"text":"convex implies local min equals global min"}],"terms":[{"term":"f","meaning":"The function being tested for convexity; it maps points to real values and is convex if its graph lies below every chord.","function":true},{"term":"λ","meaning":"Lambda, a mixing weight between 0 and 1 that selects a point on the line segment between x and y.","function":false},{"term":"x","meaning":"A first point in the function's domain, one endpoint of the segment used to test convexity.","function":false},{"term":"y","meaning":"A second point in the function's domain; the segment between x and y must lie in the convex set.","function":false},{"term":"f″","meaning":"Second derivative of a one-variable f: takes x and returns the curvature; nonnegative everywhere means f is convex.","function":true},{"term":"∇²","meaning":"Hessian operator: takes a multivariable function and returns its matrix of second partial derivatives, measuring curvature in every direction.","function":true},{"term":"⪰","meaning":"Positive semidefinite: the matrix has no negative eigenvalues, so the function curves upward or stays flat in every direction.","function":false},{"term":"⇒","meaning":"Implies: if the function and feasible set are convex, the stated conclusion follows.","function":false}],"explanation":"A function is convex if the chord between any two points on its graph lies on or above the graph, which is what the λ-inequality says. For twice-differentiable functions this is the same as a nonnegative second derivative, or a positive semidefinite Hessian in many dimensions. Convexity matters because any local minimum of a convex function over a convex set is a global minimum. That makes convex problems reliably solvable.","origin":"The chord inequality is closely tied to Jensen's inequality, published by Johan Jensen in 1906.","implementations":[{"name":"cvxpy.Problem","library":"CVXPY","note":"Solves convex problems; checks convexity with disciplined convex programming rules."},{"name":"cvxpy.Problem.is_dcp","library":"CVXPY","note":"Checks whether a problem satisfies the DCP convexity rules."}]},"O.9":{"spoken":[{"line":0,"text":"the gradient of f at x star equals zero, the Hessian of f at x star is positive definite"},{"line":1,"text":"x sub k plus 1 equals x sub k minus f prime of x sub k over f double prime of x sub k"},{"line":2,"text":"bold x sub k plus 1 equals bold x sub k minus the inverse of the Hessian of f, times the gradient of f"}],"terms":[{"term":"∇","meaning":"Gradient operator: takes a scalar function and returns the vector of its partial derivatives, pointing in the direction of steepest increase.","function":true},{"term":"f","meaning":"The smooth nonlinear objective function being minimized; it takes the decision vector and returns a real-valued cost.","function":true},{"term":"𝐱*","meaning":"A candidate local minimizer where the first- and second-order optimality conditions hold.","function":false},{"term":"∇²","meaning":"Hessian operator: returns the matrix of second partial derivatives of f, describing its local curvature.","function":true},{"term":"≻","meaning":"Positive definite: all eigenvalues of the Hessian are strictly positive, so f curves upward in every direction and x star is a strict local minimum.","function":false},{"term":"xₖ","meaning":"The current iterate of Newton's method at step k.","function":false},{"term":"xₖ₊₁","meaning":"The next iterate, obtained by jumping to the minimum of the local quadratic approximation.","function":false},{"term":"k","meaning":"Iteration counter of Newton's method, increasing by one with each update step.","function":false},{"term":"f′","meaning":"First derivative of f: gives the slope at the current iterate; Newton's method drives it to zero.","function":true},{"term":"f″","meaning":"Second derivative of f: gives the curvature at the current iterate and scales the step size.","function":true},{"term":"[·]⁻¹","meaning":"Matrix inverse: takes the Hessian and returns the matrix that undoes it, so the step solves the Newton linear system.","function":true}],"explanation":"For unconstrained nonlinear problems, a local minimum needs a zero gradient (the first-order condition) and a positive definite Hessian (the second-order check). Newton's method finds such points by fitting a quadratic at the current iterate and jumping to its minimum. In one dimension the step is f′/f″, and in many dimensions it is the inverse Hessian times the gradient. Close to the solution it converges quadratically, roughly doubling the correct digits each step.","origin":"Isaac Newton described the method around 1669, and Joseph Raphson published a simplified version in 1690.","implementations":[{"name":"scipy.optimize.minimize","library":"SciPy","note":"Supports Newton-type methods such as 'Newton-CG' and 'trust-exact'."},{"name":"scipy.optimize.newton","library":"SciPy","note":"Newton–Raphson root finding; apply to f′ to locate stationary points."}]},"O.10":{"spoken":[{"line":0,"text":"script L of x comma lambda equals f of x minus lambda times the quantity g of x minus c"},{"line":1,"text":"the gradient of f equals lambda times the gradient of g, g of x equals c"},{"line":2,"text":"lambda equals the partial derivative of f star with respect to c"}],"terms":[{"term":"ℒ","meaning":"The Lagrangian function: takes the decision vector x and multiplier lambda and returns the objective minus the weighted constraint violation; its stationary points solve the constrained problem.","function":true},{"term":"𝐱","meaning":"Decision vector being optimized subject to the equality constraint.","function":false},{"term":"λ","meaning":"Lagrange multiplier: the weight on the constraint, equal at the optimum to the shadow price, the change in optimal objective per unit change in c.","function":false},{"term":"f","meaning":"Objective function to be maximized or minimized; it takes the decision vector and returns the value being optimized.","function":true},{"term":"g","meaning":"Constraint function of x whose value must equal the constant c.","function":true},{"term":"c","meaning":"Constant level the constraint function must equal, such as a budget or resource limit.","function":false},{"term":"∇","meaning":"Gradient operator: returns the vector of partial derivatives; at the optimum the gradients of f and g are parallel.","function":true},{"term":"∂","meaning":"Partial derivative: measures how the optimal value f star changes when only c is varied.","function":true},{"term":"f*","meaning":"The optimal value of the objective, viewed as a function of the constraint level c.","function":true}],"explanation":"Lagrange multipliers turn an equality-constrained optimization into a stationarity problem. At a constrained optimum, the gradient of f is parallel to the gradient of the constraint g, so ∇f = λ∇g, and the constraint g(x) = c still holds. Setting the gradient of the Lagrangian ℒ to zero gives both conditions together. The multiplier λ measures how fast the optimal value changes as the constraint level c is relaxed, so it works as a shadow price.","origin":"Joseph-Louis Lagrange introduced the method in his Mécanique analytique (1788).","implementations":[{"name":"scipy.optimize.minimize","library":"SciPy","note":"Method 'SLSQP' or 'trust-constr' handles equality-constrained problems."},{"name":"sympy.solve","library":"SymPy","note":"Solves the Lagrangian stationarity equations symbolically."}]},"O.11":{"spoken":[{"line":0,"text":"minimize f subject to g sub i less than or equal to zero"},{"line":1,"text":"the gradient of f plus the sum of mu sub i times the gradient of g sub i equals zero"},{"line":2,"text":"g sub i less than or equal to zero, mu sub i greater than or equal to zero, mu sub i g sub i equals zero"}],"terms":[{"term":"min","meaning":"Minimization operator: returns the lowest objective value among points satisfying all inequality constraints.","function":true},{"term":"f","meaning":"Objective function of the decision vector to be minimized.","function":true},{"term":"s.t.","meaning":"Subject to: introduces the inequality constraints that every feasible point must satisfy.","function":false},{"term":"gᵢ","meaning":"Inequality constraint functions; feasible points must have each g sub i less than or equal to zero.","function":true},{"term":"∇","meaning":"Gradient operator: returns the vector of partial derivatives; stationarity requires the weighted gradients to cancel.","function":true},{"term":"∑","meaning":"Summation over all constraints i of the multiplier times the constraint gradient.","function":true},{"term":"μᵢ","meaning":"KKT multiplier for constraint i: nonnegative, and zero whenever the constraint is not binding (complementary slackness).","function":false},{"term":"i","meaning":"Index over the inequality constraints, each with its own multiplier mu sub i.","function":false}],"explanation":"The Karush–Kuhn–Tucker conditions extend Lagrange multipliers to inequality constraints. At an optimum, the gradient of f plus a nonnegative combination of the active constraint gradients is zero (stationarity). Every constraint must hold (primal feasibility), and the multipliers μᵢ are nonnegative (dual feasibility). Complementary slackness, μᵢgᵢ = 0, means each constraint is either tight or has a zero multiplier. For convex problems that satisfy a regularity condition, these conditions are both necessary and sufficient.","origin":"William Karush derived the conditions in his 1939 master's thesis, and Harold Kuhn and Albert Tucker published them independently in 1951.","implementations":[{"name":"scipy.optimize.minimize","library":"SciPy","note":"SLSQP and trust-constr solve inequality-constrained problems satisfying KKT."},{"name":"cvxpy.Problem","library":"CVXPY","note":"Solves convex problems; constraint .dual_value gives the KKT multipliers."}]},"O.12":{"spoken":[{"line":0,"text":"V of s equals the max over a of the quantity r of s comma a plus gamma V of s prime"},{"line":3,"text":"the sum from t equals 0 to infinity of gamma to the t times r equals r over the quantity 1 minus gamma"}],"terms":[{"term":"V(s)","meaning":"Value function: takes a state s and returns the best total discounted reward obtainable starting from that state.","function":true},{"term":"s","meaning":"The current state of the system, such as inventory level or position.","function":false},{"term":"max","meaning":"Maximization operator: over all available actions a, returns the largest immediate-plus-future value.","function":true},{"term":"a","meaning":"An action or decision available in state s.","function":false},{"term":"r(s, a)","meaning":"Reward function: takes a state and action and returns the immediate payoff of taking action a in state s.","function":true},{"term":"γ","meaning":"Gamma, the discount factor between 0 and 1 that shrinks future rewards relative to immediate ones.","function":false},{"term":"s′","meaning":"s prime, the next state reached after taking action a in state s.","function":false},{"term":"∑","meaning":"Summation from t equals 0 to infinity: adds the discounted reward of every future period.","function":true},{"term":"t","meaning":"Time step index, counting periods from 0 up to infinity in the discounted sum.","function":false},{"term":"∞","meaning":"Infinity: the sum runs over an unending horizon.","function":false},{"term":"r","meaning":"A constant reward received every period; its discounted infinite sum is r over 1 minus gamma.","function":false}],"explanation":"Dynamic programming solves a problem by breaking it into subproblems, solving each once and storing the answer. It works when there is optimal substructure (optimal solutions are built from optimal sub-solutions) and the subproblems overlap. The Bellman equation states this for sequential decisions: the value of a state is the best immediate reward plus the discounted value of the next state. The geometric series shows that a discount γ < 1 keeps infinite-horizon totals finite.","origin":"Richard Bellman developed dynamic programming and the Bellman equation in the 1950s.","implementations":[{"name":"functools.lru_cache","library":"Python standard library","note":"Memoizes a recursive function so each subproblem is computed once."},{"name":"mdptoolbox.mdp.ValueIteration","library":"pymdptoolbox","note":"Solves Markov decision processes by iterating the Bellman equation."}]},"O.13":{"spoken":[{"line":0,"text":"P of accept worse equals e to the negative delta over T"},{"line":1,"text":"T sub k equals T sub 0 times alpha to the k"}],"terms":[{"term":"P(·)","meaning":"Probability: takes an event, here accepting a worse candidate solution, and returns its likelihood between 0 and 1.","function":true},{"term":"e","meaning":"Euler's number, about 2.718, the base of the natural exponential in the Metropolis acceptance rule.","function":false},{"term":"Δ","meaning":"Delta, the increase in cost (worsening of the objective) caused by moving to the candidate solution.","function":false},{"term":"T","meaning":"Temperature parameter: high values accept worse moves often, low values make the search nearly greedy.","function":false},{"term":"Tₖ","meaning":"Temperature at iteration k of the cooling schedule.","function":false},{"term":"T₀","meaning":"Initial temperature at the start of the annealing run.","function":false},{"term":"α","meaning":"Alpha, the cooling rate between 0 and 1 (often 0.9 to 0.99) by which temperature is multiplied each step.","function":false},{"term":"k","meaning":"Iteration or cooling-step counter; temperature is multiplied by alpha once per step.","function":false}],"explanation":"Simulated annealing is a heuristic for hard combinatorial or nonconvex problems. It always accepts improving moves and accepts worsening moves with probability e^(−Δ/T). At high temperature T it explores widely and can escape local optima. As T cools geometrically (Tₖ = T₀αᵏ) it settles into a good solution. Related heuristics include greedy construction, local search, 2-opt edge swaps for routing, and genetic algorithms.","origin":"Kirkpatrick, Gelatt and Vecchi introduced simulated annealing in 1983, adapting the Metropolis acceptance rule from 1953.","implementations":[{"name":"scipy.optimize.dual_annealing","library":"SciPy","note":"Generalized simulated annealing for global optimization."},{"name":"scipy.optimize.basinhopping","library":"SciPy","note":"Global optimizer that uses Metropolis-style acceptance of local minima."}]},"O.14":{"spoken":[{"line":0,"text":"theta hat equals 1 over N times the sum from i equals 1 to N of f of X sub i, which approaches the expected value of f of X"},{"line":1,"text":"the integral from a to b of f d x is approximately the quantity b minus a, over N, times the sum of f of U sub i"},{"line":2,"text":"S E equals sigma over the square root of N"}],"terms":[{"term":"θ̂","meaning":"Theta hat, the Monte Carlo estimate: the sample average of simulated function values.","function":false},{"term":"N","meaning":"Number of random samples or simulation runs; more samples shrink the estimation error.","function":false},{"term":"∑","meaning":"Summation over samples i from 1 to N, adding the simulated function values.","function":true},{"term":"f","meaning":"The function of the random input whose mean or integral is being estimated.","function":true},{"term":"Xᵢ","meaning":"The i-th independent random draw from the distribution of X.","function":false},{"term":"→","meaning":"Converges to: by the law of large numbers the estimate approaches the true mean as N grows.","function":false},{"term":"E[·]","meaning":"Expected value: takes a random quantity and returns its probability-weighted average, the true target of the estimate.","function":true},{"term":"X","meaning":"The random variable being sampled, whose function values are averaged in the estimate.","function":false},{"term":"∫","meaning":"Integral from a to b: the area under f that Monte Carlo approximates by averaging random evaluations.","function":true},{"term":"a","meaning":"Lower limit of the integration interval from which uniform points are drawn.","function":false},{"term":"b","meaning":"Upper limit of the integration interval from which uniform points are drawn.","function":false},{"term":"dx","meaning":"Differential of x, marking x as the integration variable.","function":false},{"term":"Uᵢ","meaning":"The i-th uniform random point drawn between a and b.","function":false},{"term":"SE","meaning":"Standard error of the Monte Carlo estimate, shrinking like 1 over the square root of N.","function":false},{"term":"σ","meaning":"Sigma, the standard deviation of the individual sampled values f of X.","function":false},{"term":"√","meaning":"Square root: takes a nonnegative number and returns the value whose square equals it; here applied to N.","function":true}],"explanation":"Monte Carlo estimation approximates an expectation by averaging f over N random samples. By the law of large numbers this average converges to E[f(X)]. An integral over [a, b] can be estimated the same way: average f at uniform points and multiply by the interval length. The standard error is σ/√N in any dimension, so the method scales well to high-dimensional problems but converges slowly.","origin":"Stanislaw Ulam and John von Neumann developed the Monte Carlo method at Los Alamos in the 1940s. Nicholas Metropolis suggested the name.","implementations":[{"name":"numpy.random.default_rng","library":"NumPy","note":"Creates a random generator for drawing Monte Carlo samples."},{"name":"scipy.stats.qmc.Sobol","library":"SciPy","note":"Low-discrepancy sequences for quasi-Monte Carlo integration."}]},"O.15":{"spoken":[{"line":0,"text":"X equals F inverse of U, U is distributed uniform on zero to one"},{"line":1,"text":"exponential: X equals negative natural log of the quantity 1 minus U, over lambda"},{"line":2,"text":"rejection: accept if U is less than or equal to f of x over M g of x"},{"line":3,"text":"the expected value under p of h equals the expected value under q of h times p over q"}],"terms":[{"term":"X","meaning":"The generated random variable with the desired target distribution.","function":false},{"term":"F⁻¹","meaning":"Inverse cumulative distribution function (quantile function): takes a probability in 0 to 1 and returns the value x with F of x equal to that probability.","function":true},{"term":"U","meaning":"A uniform random number between 0 and 1, the raw input to all these sampling methods.","function":false},{"term":"~","meaning":"Is distributed as: states the probability distribution a random variable follows.","function":false},{"term":"Unif(0,1)","meaning":"Continuous uniform distribution on the interval 0 to 1, where every value is equally likely.","function":true},{"term":"ln","meaning":"Natural logarithm: takes a positive number and returns its log base e; used to invert the exponential CDF.","function":true},{"term":"λ","meaning":"Lambda, the rate parameter of the exponential distribution; its mean is 1 over lambda.","function":false},{"term":"f(x)","meaning":"Target probability density we want to sample from in rejection sampling.","function":true},{"term":"M","meaning":"Envelope constant chosen so that M times g of x is at least f of x everywhere.","function":false},{"term":"g(x)","meaning":"Proposal density that is easy to sample from and, scaled by M, covers the target density.","function":true},{"term":"x","meaning":"A candidate value drawn from the proposal distribution g.","function":false},{"term":"Eₚ[·]","meaning":"Expected value under distribution p: returns the average of the bracketed quantity when samples come from p.","function":true},{"term":"h","meaning":"The function whose expectation under the target distribution p is being estimated by importance sampling.","function":true},{"term":"E_q[·]","meaning":"Expected value under the proposal distribution q, from which importance samples are actually drawn.","function":true},{"term":"p","meaning":"Target density in importance sampling: the distribution under which we want the expectation of h.","function":true},{"term":"q","meaning":"Proposal (importance) density; the ratio p over q is the importance weight correcting for sampling from q.","function":true}],"explanation":"Inverse-transform sampling turns a uniform random number U into a draw from any distribution by applying the inverse CDF. For the exponential distribution this gives X = −ln(1 − U)/λ. Rejection sampling draws from an easy proposal g and accepts with probability f(x)/(Mg(x)), where Mg must lie above the target f. Importance sampling instead draws from q and reweights each sample by p/q to estimate expectations under p.","origin":"John von Neumann described rejection sampling in 1951.","implementations":[{"name":"scipy.stats.rv_continuous.ppf","library":"SciPy","note":"Inverse CDF (percent point function) for inverse-transform sampling."},{"name":"numpy.random.Generator.exponential","library":"NumPy","note":"Draws exponential random variates directly."},{"name":"scipy.stats.rv_continuous.rvs","library":"SciPy","note":"Draws random variates from any SciPy distribution."}]},"O.16":{"spoken":[{"line":0,"text":"alpha equals the min of 1 and p of x prime times q of x given x prime, over p of x times q of x prime given x"},{"line":1,"text":"symmetric q:"},{"line":2,"text":"alpha equals the min of 1 and p of x prime over p of x"}],"terms":[{"term":"α","meaning":"Alpha, the acceptance probability of the proposed move in Metropolis-Hastings.","function":false},{"term":"min","meaning":"Minimum operator: returns the smaller of 1 and the ratio, so the acceptance probability never exceeds 1.","function":true},{"term":"p","meaning":"Target density (possibly unnormalized) that the Markov chain should sample from, such as a posterior.","function":true},{"term":"x′","meaning":"x prime, the proposed next state of the chain.","function":false},{"term":"q(· ∣ ·)","meaning":"Proposal density: q of x prime given x is the probability of proposing x prime when the chain is at x.","function":true},{"term":"x","meaning":"Current state of the Markov chain, from which the next move x prime is proposed.","function":false},{"term":"∣","meaning":"Given: conditions the proposal probability on the state it is proposed from.","function":false}],"explanation":"Metropolis–Hastings builds a Markov chain whose long-run distribution is the target p, which only needs to be known up to a constant. From the current state x, it proposes x′ from q and accepts with probability α. The α ratio corrects for asymmetry in the proposal so that detailed balance holds. With a symmetric proposal the q terms cancel, giving the original Metropolis rule: always move toward higher probability, and sometimes move toward lower.","origin":"Metropolis, the Rosenbluths and the Tellers introduced the algorithm in 1953, and W. K. Hastings generalized it to asymmetric proposals in 1970.","implementations":[{"name":"pymc.Metropolis","library":"PyMC","note":"Metropolis–Hastings step method for MCMC sampling."},{"name":"pymc.sample","library":"PyMC","note":"Draws posterior samples using the chosen MCMC step methods."}]},"O.17":{"spoken":[{"line":0,"text":"f of n equals big O of g of n if and only if f is less than or equal to c g for large n"},{"line":1,"text":"big O of 1 is less than big O of log n, is less than big O of n, is less than big O of n log n, is less than big O of n squared, is less than big O of 2 to the n, is less than big O of n factorial"}],"terms":[{"term":"f(n)","meaning":"The running time or memory use of an algorithm as a function of input size n.","function":true},{"term":"n","meaning":"Input size, such as the number of items, nodes or records.","function":false},{"term":"O(·)","meaning":"Big-O notation: takes a function and denotes the set of functions growing no faster than it, up to a constant factor, for large inputs.","function":true},{"term":"g(n)","meaning":"A simple reference function used as an upper bound on the growth of f.","function":true},{"term":"⟺","meaning":"If and only if: the two statements are equivalent definitions.","function":false},{"term":"c","meaning":"A positive constant multiplier allowed in the upper bound.","function":false},{"term":"log","meaning":"Logarithm: takes n and returns the power needed to reach n; log n grows very slowly, as in binary search.","function":true},{"term":"!","meaning":"Factorial: n factorial is the product of 1 through n, the growth of brute-force enumeration of orderings.","function":true}],"explanation":"Big-O notation describes how an algorithm's running time or memory grows with input size n, ignoring constant factors and lower-order terms. f(n) = O(g(n)) means f is eventually bounded by a constant multiple of g. The hierarchy runs from constant time through logarithmic, linear, n log n (efficient sorting) and quadratic, up to exponential and factorial. Those last two are why brute force on problems like the TSP is hopeless.","origin":"Paul Bachmann introduced O-notation in 1894 and Edmund Landau popularized it. Donald Knuth established its use in computer science in the 1970s.","implementations":[]},"FN.1":{"spoken":[{"line":0,"text":"I equals P r t (simple)"},{"line":1,"text":"A equals P times the quantity 1 plus r over n, raised to the n t"},{"line":2,"text":"A equals P e to the r t (continuous)"}],"terms":[{"term":"I","meaning":"Simple interest earned in dollars, computed only on the original principal.","function":false},{"term":"P","meaning":"Principal: the initial amount deposited or borrowed, in dollars.","function":false},{"term":"r","meaning":"Annual nominal interest rate expressed as a decimal, for example 0.05 for 5 percent.","function":false},{"term":"t","meaning":"Time the money is invested or borrowed, measured in years.","function":false},{"term":"A","meaning":"Accumulated amount: the future balance including principal plus all interest earned.","function":false},{"term":"n","meaning":"Number of compounding periods per year, such as 12 for monthly or 365 for daily.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the limit of compounding infinitely often; used for continuous compounding.","function":false}],"explanation":"Simple interest pays only on the original principal, so it grows linearly: I = Prt. Compound interest adds interest to the balance n times a year, so later interest is earned on earlier interest and growth is exponential. As n increases without bound, (1 + r/n)ⁿᵗ approaches eʳᵗ, which is continuous compounding, the upper limit for a given nominal rate.","origin":"Jacob Bernoulli discovered the constant e in 1683 while studying the limit of continuously compounded interest.","implementations":[{"name":"numpy_financial.fv","library":"numpy-financial","note":"Future value of an investment with periodic compounding."},{"name":"=FV()","library":"Excel","note":"Future value given rate, number of periods and payments."}]},"FN.2":{"spoken":[{"line":0,"text":"EAR equals the quantity 1 plus APR over n, to the n, minus 1"},{"line":1,"text":"continuous: EAR equals e to the r minus 1"}],"terms":[{"term":"EAR","meaning":"Effective annual rate: the true one-year growth rate after accounting for compounding, as a decimal.","function":false},{"term":"APR","meaning":"Annual percentage rate: the stated nominal yearly rate before compounding, as a decimal.","function":false},{"term":"n","meaning":"Number of compounding periods per year, such as 12 for monthly compounding.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base used for continuously compounded growth.","function":false},{"term":"r","meaning":"Continuously compounded nominal annual rate, as a decimal.","function":false}],"explanation":"The APR is a nominal annual rate that ignores compounding within the year. The effective annual rate (EAR) is the true one-year growth once compounding n times a year is counted, (1 + APR/n)ⁿ − 1. Under continuous compounding it becomes eʳ − 1. Converting rates to EAR makes loans or accounts with different compounding frequencies directly comparable.","origin":"The U.S. Truth in Lending Act of 1968 made APR disclosure standard for consumer loans.","implementations":[{"name":"=EFFECT()","library":"Excel","note":"Converts a nominal rate and compounding frequency to the effective annual rate."},{"name":"=NOMINAL()","library":"Excel","note":"Converts an effective annual rate back to a nominal rate."}]},"FN.3":{"spoken":[{"line":0,"text":"t sub double equals the natural log of 2 over the natural log of the quantity 1 plus r"},{"line":1,"text":"t is approximately 72 over r in percent"}],"terms":[{"term":"t_double","meaning":"Doubling time: the number of compounding periods, usually years, for an investment to grow to twice its value.","function":false},{"term":"ln","meaning":"Natural logarithm: takes a positive number and returns its log base e; it converts growth multiples into time.","function":true},{"term":"r","meaning":"Interest or growth rate per period; a decimal in the exact formula, a whole percent in the Rule of 72.","function":false},{"term":"t","meaning":"Approximate doubling time in years from the Rule of 72.","function":false},{"term":"%","meaning":"Percent: the rate is entered as a whole number, so 6 percent is written 6, not 0.06.","function":false}],"explanation":"Doubling time is how long compound growth takes to double a quantity: solve (1 + r)ᵗ = 2, which gives t = ln 2 / ln(1 + r). For small rates ln(1 + r) ≈ r, so t ≈ 69.3/r(%). The Rule of 72 rounds this up because 72 is more accurate at typical rates of 6–10% and divides evenly by many numbers. It works for investments, inflation, populations or any constant-rate growth.","origin":"The Rule of 72 appears in Luca Pacioli's Summa de arithmetica (1494).","implementations":[{"name":"numpy_financial.nper","library":"numpy-financial","note":"Number of periods needed to reach a target value."},{"name":"=NPER()","library":"Excel","note":"Number of periods for an investment at a given rate."}]},"FN.4":{"spoken":[{"line":0,"text":"P V equals F V over the quantity 1 plus r, to the t"},{"line":1,"text":"F V equals P V times the quantity 1 plus r, to the t"},{"line":2,"text":"discount factor equals 1 over the quantity 1 plus r, to the t"}],"terms":[{"term":"PV","meaning":"Present value: what a future amount is worth in today's dollars.","function":false},{"term":"FV","meaning":"Future value: the dollar amount received or accumulated at time t.","function":false},{"term":"r","meaning":"Discount rate or interest rate per period, as a decimal, reflecting the time value of money.","function":false},{"term":"t","meaning":"Number of periods, usually years, between today and the future cash flow.","function":false},{"term":"discount factor","meaning":"The multiplier that converts one dollar at time t into its present value; always below 1 for positive r.","function":false}],"explanation":"Discounting reverses compounding. A future cash flow FV received in t periods is worth FV/(1 + r)ᵗ today, because money available now could be invested at rate r. The discount factor 1/(1 + r)ᵗ converts any future amount into present terms. That lets you compare cash flows at different dates, and it is the basis of NPV, bond pricing and valuation.","origin":"","implementations":[{"name":"numpy_financial.pv","library":"numpy-financial","note":"Present value of future payments at a given rate."},{"name":"=PV()","library":"Excel","note":"Present value of an investment or loan."}]},"FN.5":{"spoken":[{"line":0,"text":"N P V equals the sum from t equals 0 to T of C F sub t over the quantity 1 plus r, to the t"},{"line":1,"text":"IRR: the sum of C F sub t over the quantity 1 plus IRR, to the t, equals 0"},{"line":2,"text":"accept if NPV is greater than 0 (IRR greater than r)"}],"terms":[{"term":"NPV","meaning":"Net present value: the sum of all discounted cash flows of a project, including the initial outlay, in today's dollars.","function":false},{"term":"∑","meaning":"Summation over periods t: adds up the discounted cash flow of every period from 0 to T.","function":true},{"term":"t","meaning":"Period index, with t equals 0 for the initial investment.","function":false},{"term":"T","meaning":"Final period of the project's life, the last period whose cash flow is included.","function":false},{"term":"CFₜ","meaning":"Cash flow at period t: negative for investments, positive for inflows.","function":false},{"term":"r","meaning":"Discount rate or required rate of return (cost of capital) per period.","function":false},{"term":"IRR","meaning":"Internal rate of return: the discount rate that makes the project's NPV exactly zero.","function":false}],"explanation":"Net present value discounts each period's cash flow at the required rate r and sums the results. A positive NPV means the project adds value beyond what it costs. The internal rate of return is the discount rate that makes NPV exactly zero, and accepting when IRR > r usually agrees with NPV > 0. IRR can mislead when cash-flow signs change more than once or when ranking projects of different sizes, so NPV is the more reliable test.","origin":"","implementations":[{"name":"numpy_financial.npv","library":"numpy-financial","note":"NPV of a cash-flow series; the first value is at t = 0."},{"name":"numpy_financial.irr","library":"numpy-financial","note":"Internal rate of return of a cash-flow series."},{"name":"=NPV()","library":"Excel","note":"NPV; discounts the first value one period, so add t = 0 separately."},{"name":"=IRR()","library":"Excel","note":"Internal rate of return for periodic cash flows."}]},"FN.6":{"spoken":[{"line":0,"text":"P V sub ann equals C times the quantity 1 minus the quantity 1 plus r to the negative n, all over r"},{"line":1,"text":"F V sub ann equals C times the quantity, the quantity 1 plus r to the n, minus 1, all over r"},{"line":2,"text":"P V sub perp equals C over r; P V sub growing equals C sub 1 over the quantity r minus g"}],"terms":[{"term":"PV_ann","meaning":"Present value of an ordinary annuity: today's worth of n equal payments made at the end of each period.","function":false},{"term":"C","meaning":"Fixed cash payment received or paid each period, in dollars.","function":false},{"term":"r","meaning":"Interest or discount rate per period, as a decimal.","function":false},{"term":"n","meaning":"Number of payments, or periods, in the annuity.","function":false},{"term":"FV_ann","meaning":"Future value of an annuity: the accumulated balance after n periodic payments earn compound interest.","function":false},{"term":"PV_perp","meaning":"Present value of a perpetuity: today's worth of an equal payment C received every period forever.","function":false},{"term":"PV_growing","meaning":"Present value of a growing perpetuity whose payments rise at rate g forever.","function":false},{"term":"C₁","meaning":"The first payment of the growing perpetuity, received one period from now.","function":false},{"term":"g","meaning":"Constant growth rate of payments per period; must be less than r for the value to be finite.","function":false}],"explanation":"An annuity pays a fixed amount C each period for n periods. Its present value is C times a geometric-series sum, C·[1 − (1 + r)⁻ⁿ]/r, and its future value compounds each payment forward. A perpetuity pays forever, so the (1 + r)⁻ⁿ term vanishes and PV = C/r. If payments grow at rate g < r, the growing perpetuity is worth C/(r − g). These formulas price loans, pensions, leases and dividend streams.","origin":"","implementations":[{"name":"numpy_financial.pv","library":"numpy-financial","note":"Present value of an annuity of fixed payments."},{"name":"numpy_financial.fv","library":"numpy-financial","note":"Future value of an annuity of fixed payments."},{"name":"=PV()","library":"Excel","note":"Present value of a series of equal payments."}]},"FN.7":{"spoken":[{"line":0,"text":"M equals P times i times the quantity 1 plus i to the n, all over the quantity 1 plus i to the n, minus 1"},{"line":1,"text":"i equals APR over 12, n equals 12 times years"}],"terms":[{"term":"M","meaning":"Fixed monthly loan or mortgage payment, in dollars, covering interest and principal.","function":false},{"term":"P","meaning":"Principal: the amount borrowed at the start of the loan, in dollars.","function":false},{"term":"i","meaning":"Periodic (monthly) interest rate as a decimal, the annual rate divided by 12.","function":false},{"term":"n","meaning":"Total number of monthly payments over the life of the loan.","function":false},{"term":"APR","meaning":"Annual percentage rate: the stated yearly interest rate of the loan, as a decimal.","function":false},{"term":"years","meaning":"Loan term in years, such as 30 for a typical fixed-rate mortgage.","function":false}],"explanation":"A fully amortizing loan is repaid with equal payments M that cover each period's interest and gradually pay down principal. The payment formula comes from setting the loan amount P equal to the present value of an annuity of M payments. For a mortgage, the periodic rate is i = APR/12 and the number of payments is n = 12 × years. Early payments are mostly interest because interest is charged on a balance that is still large.","origin":"","implementations":[{"name":"numpy_financial.pmt","library":"numpy-financial","note":"Fixed periodic payment for a loan."},{"name":"numpy_financial.ipmt","library":"numpy-financial","note":"Interest portion of a given payment."},{"name":"numpy_financial.ppmt","library":"numpy-financial","note":"Principal portion of a given payment."},{"name":"=PMT()","library":"Excel","note":"Periodic loan payment for constant rate and payments."}]},"FN.8":{"spoken":[{"line":0,"text":"the quantity 1 plus i sub nom equals the quantity 1 plus r sub real times the quantity 1 plus pi"},{"line":1,"text":"r sub real is approximately i sub nom minus pi"},{"line":2,"text":"purchasing power equals 1 over the quantity 1 plus pi, to the t"}],"terms":[{"term":"i_nom","meaning":"Nominal interest rate or return: the stated rate in money terms, before adjusting for inflation.","function":false},{"term":"r_real","meaning":"Real interest rate or return: growth in actual purchasing power after removing inflation.","function":false},{"term":"π","meaning":"Pi here means the inflation rate per period, as a decimal, not the circle constant.","function":false},{"term":"purchasing power","meaning":"What one dollar today will buy after t periods of inflation, measured in today's dollars.","function":false},{"term":"t","meaning":"Number of periods, usually years, over which inflation erodes purchasing power.","function":false}],"explanation":"The Fisher relation links nominal and real returns: growth in money terms equals real growth in purchasing power compounded with inflation π. Solving gives the exact real rate (1 + i)/(1 + π) − 1. For small rates this is approximately the nominal rate minus inflation. Purchasing power falls by the factor 1/(1 + π)ᵗ, so even modest inflation erodes value substantially over decades.","origin":"The relation is named after economist Irving Fisher, who developed it in the late 1890s and in The Theory of Interest (1930).","implementations":[]},"FN.9":{"spoken":[{"line":0,"text":"R equals P sub 1 minus P sub 0, over P sub 0; r equals the natural log of P sub 1 over P sub 0"},{"line":1,"text":"CAGR equals the quantity V sub T over V sub 0, to the 1 over T, minus 1"},{"line":2,"text":"geometric is less than or equal to arithmetic mean"}],"terms":[{"term":"R","meaning":"Simple (arithmetic) return over the period, as a decimal: the percentage price change.","function":false},{"term":"P₁","meaning":"Price or value of the asset at the end of the period.","function":false},{"term":"P₀","meaning":"Price or value of the asset at the start of the period.","function":false},{"term":"r","meaning":"Log (continuously compounded) return, which adds across periods.","function":false},{"term":"ln","meaning":"Natural logarithm: takes the price ratio and returns the continuously compounded return.","function":true},{"term":"CAGR","meaning":"Compound annual growth rate: the constant yearly rate that would grow the starting value to the ending value.","function":false},{"term":"V_T","meaning":"Ending value of the investment after T years.","function":false},{"term":"V₀","meaning":"Starting value of the investment at the beginning of the holding period.","function":false},{"term":"T","meaning":"Number of years in the holding period; the 1 over T power annualizes growth.","function":false},{"term":"≤","meaning":"Less than or equal: the geometric mean return never exceeds the arithmetic mean, with equality only when returns are constant.","function":false}],"explanation":"The simple return R is the percentage change in price, and the log return r = ln(P₁/P₀) is its continuously compounded counterpart. Log returns add across time periods, and simple returns combine linearly across the assets in a portfolio. CAGR is the constant annual rate that turns V₀ into V_T over T years, which is a geometric mean. The geometric mean never exceeds the arithmetic mean, so volatility drags down compounded growth.","origin":"","implementations":[{"name":"pandas.Series.pct_change","library":"pandas","note":"Computes simple period-over-period returns."},{"name":"numpy.log","library":"NumPy","note":"Natural log for computing log returns from price ratios."},{"name":"scipy.stats.gmean","library":"SciPy","note":"Geometric mean, e.g. of gross returns 1 + R."},{"name":"=RRI()","library":"Excel","note":"Equivalent compound growth rate (CAGR) from start and end values."}]},"FN.10":{"spoken":[{"line":0,"text":"sigma equals the square root of 1 over the quantity n minus 1, times the sum of the quantity r sub t minus r bar, squared"},{"line":1,"text":"sigma sub annual equals sigma sub daily times the square root of 252"},{"line":2,"text":"sigma sub T equals sigma times the square root of T"}],"terms":[{"term":"σ","meaning":"Sigma, the volatility: the sample standard deviation of returns, measuring how widely they vary.","function":false},{"term":"√","meaning":"Square root: takes a nonnegative number and returns its principal root; used to turn variance into standard deviation and to scale over time.","function":true},{"term":"n","meaning":"Number of return observations in the sample; dividing by n minus 1 gives an unbiased variance.","function":false},{"term":"∑","meaning":"Summation over all observations t of the squared deviation from the mean return.","function":true},{"term":"rₜ","meaning":"Return of the asset in period t, one observation in the sample.","function":false},{"term":"r̄","meaning":"r bar, the average (mean) return over the sample.","function":false},{"term":"σ_annual","meaning":"Annualized volatility, the standard deviation of yearly returns.","function":false},{"term":"σ_daily","meaning":"Standard deviation of daily returns, scaled up by the square root of 252.","function":false},{"term":"252","meaning":"Approximate number of trading days in a year, used to scale daily volatility.","function":false},{"term":"σ_T","meaning":"Volatility over a horizon of T periods, which grows with the square root of time.","function":false},{"term":"T","meaning":"Length of the horizon in the same time units as sigma.","function":false}],"explanation":"Volatility is the sample standard deviation of returns, with n − 1 in the denominator for an unbiased variance. If returns are independent across periods, variances add over time, so volatility scales with the square root of time. Annualizing daily volatility therefore multiplies by √252, the approximate number of trading days in a year. Expected return grows linearly with time while risk grows only as √T, which is why risk per unit of return falls over longer horizons.","origin":"Square-root-of-time scaling comes from random-walk models of prices that go back to Louis Bachelier's 1900 thesis.","implementations":[{"name":"pandas.Series.std","library":"pandas","note":"Sample standard deviation (ddof=1 by default)."},{"name":"numpy.std","library":"NumPy","note":"Standard deviation; pass ddof=1 for the sample version."},{"name":"pandas.Series.rolling","library":"pandas","note":"Rolling windows for computing moving volatility."}]},"FN.11":{"spoken":[{"line":0,"text":"the expected value of R sub p equals the sum of w sub i times the expected value of R sub i"},{"line":1,"text":"sigma sub p squared equals w transpose Sigma w"},{"line":2,"text":"sigma sub p squared equals w sub 1 squared sigma sub 1 squared plus w sub 2 squared sigma sub 2 squared plus 2 w sub 1 w sub 2 rho sigma sub 1 sigma sub 2"}],"terms":[{"term":"E[·]","meaning":"Expected value: takes a random return and returns its probability-weighted average, the expected return.","function":true},{"term":"R_p","meaning":"Portfolio return, a random variable equal to the weighted combination of asset returns.","function":false},{"term":"∑","meaning":"Summation over assets i of weight times expected return.","function":true},{"term":"wᵢ","meaning":"Portfolio weight of asset i: the fraction of total wealth invested in it; weights sum to 1.","function":false},{"term":"Rᵢ","meaning":"Return of individual asset i in the portfolio, a random variable.","function":false},{"term":"σ_p²","meaning":"Portfolio variance: the squared volatility of the portfolio's return.","function":false},{"term":"𝐰","meaning":"Column vector of all portfolio weights, one entry per asset.","function":false},{"term":"⊤","meaning":"Transpose: turns w into a row vector so w transpose Sigma w is a single number, a quadratic form.","function":true},{"term":"Σ","meaning":"Capital Sigma here is the covariance matrix of asset returns, with variances on the diagonal and covariances off it.","function":false},{"term":"σ₁, σ₂","meaning":"Standard deviations (volatilities) of the returns of asset 1 and asset 2.","function":false},{"term":"w₁, w₂","meaning":"Weights of asset 1 and asset 2 in a two-asset portfolio.","function":false},{"term":"ρ","meaning":"Rho, the correlation between the two assets' returns, from negative 1 to 1; lower rho means more diversification benefit.","function":false}],"explanation":"A portfolio's expected return is the weighted average of its assets' expected returns. Its variance is the quadratic form wᵀΣw in the covariance matrix Σ. The two-asset expansion shows the cross term 2w₁w₂ρσ₁σ₂: when correlation ρ is below 1, portfolio volatility is less than the weighted average of the individual volatilities. That reduction is diversification, and it underlies mean-variance optimization and the efficient frontier.","origin":"Harry Markowitz introduced mean-variance portfolio theory in 1952.","implementations":[{"name":"numpy.cov","library":"NumPy","note":"Estimates the covariance matrix of asset returns."},{"name":"pypfopt.EfficientFrontier","library":"PyPortfolioOpt","note":"Mean-variance optimization over portfolio weights."}]},"FN.12":{"spoken":[{"line":0,"text":"S equals R sub p minus R sub f, over sigma sub p"},{"line":1,"text":"Sortino equals R sub p minus R sub f, over sigma sub down"},{"line":2,"text":"S sub annual equals S sub daily times the square root of 252"}],"terms":[{"term":"S","meaning":"Sharpe ratio: excess return earned per unit of total volatility.","function":false},{"term":"R_p","meaning":"Portfolio return, typically average or expected, over the measurement period.","function":false},{"term":"R_f","meaning":"Risk-free rate of return, such as a Treasury bill yield, over the same period.","function":false},{"term":"σ_p","meaning":"Standard deviation (volatility) of the portfolio's returns, measuring total risk.","function":false},{"term":"Sortino","meaning":"Sortino ratio: excess return per unit of downside volatility only, ignoring upside variation.","function":false},{"term":"σ_down","meaning":"Downside deviation: the standard deviation of returns below a target or zero.","function":false},{"term":"S_annual","meaning":"Sharpe ratio expressed on an annual basis, scaled up from the daily ratio.","function":false},{"term":"S_daily","meaning":"Sharpe ratio computed from daily excess returns and daily volatility.","function":false},{"term":"√","meaning":"Square root: scales the daily ratio to annual because mean grows with time while volatility grows with its square root.","function":true},{"term":"252","meaning":"Approximate number of trading days per year, used to annualize daily figures.","function":false}],"explanation":"The Sharpe ratio divides a portfolio's excess return over the risk-free rate by its volatility, giving return per unit of total risk. The Sortino ratio replaces σ with downside deviation, so only harmful volatility is penalized. Because mean excess return scales with time and volatility with √time, a daily Sharpe ratio is annualized by multiplying by √252. Very high values often signal overfitting, short samples or hidden tail risk.","origin":"William Sharpe introduced the ratio in 1966, and the Sortino ratio is named after Frank Sortino, who promoted it in the 1980s.","implementations":[{"name":"empyrical.sharpe_ratio","library":"empyrical","note":"Annualized Sharpe ratio from a return series."},{"name":"empyrical.sortino_ratio","library":"empyrical","note":"Annualized Sortino ratio using downside deviation."},{"name":"quantstats.stats.sharpe","library":"QuantStats","note":"Sharpe ratio of a return series."}]},"FN.13":{"spoken":[{"line":0,"text":"the expected value of R sub i equals R sub f plus beta sub i times the quantity the expected value of R sub m minus R sub f"},{"line":1,"text":"beta sub i equals the covariance of R sub i and R sub m, over the variance of R sub m"}],"terms":[{"term":"E[·]","meaning":"Expected value: takes a random return and returns its average; here the required or expected return.","function":true},{"term":"Rᵢ","meaning":"Return on asset i, whose expected value CAPM predicts from its beta.","function":false},{"term":"R_f","meaning":"Risk-free rate of return, such as a short-term Treasury bill yield.","function":false},{"term":"βᵢ","meaning":"Beta of asset i: sensitivity of its return to market movements; 1 means it moves with the market.","function":false},{"term":"R_m","meaning":"Return on the market portfolio, such as a broad stock index.","function":false},{"term":"Cov(·,·)","meaning":"Covariance: takes two random returns and returns how much they move together.","function":true},{"term":"Var(·)","meaning":"Variance: takes a random return and returns the expected squared deviation from its mean.","function":true}],"explanation":"The Capital Asset Pricing Model says an asset's expected return is the risk-free rate plus beta times the market risk premium. Only systematic, market-related risk is rewarded, because idiosyncratic risk can be diversified away. Beta is the covariance of the asset with the market divided by market variance, which is the slope of a regression of the asset's returns on market returns. β > 1 amplifies market moves and β < 1 dampens them.","origin":"CAPM was developed independently by William Sharpe (1964), John Lintner (1965) and Jan Mossin (1966), building on work by Jack Treynor.","implementations":[{"name":"scipy.stats.linregress","library":"SciPy","note":"Regression slope of asset on market returns gives beta."},{"name":"statsmodels.api.OLS","library":"statsmodels","note":"Regression for beta and alpha with standard errors."},{"name":"=SLOPE()","library":"Excel","note":"Slope of asset returns against market returns (beta)."}]},"FN.14":{"spoken":[{"line":0,"text":"P equals the sum from t equals 1 to n of C over the quantity 1 plus y, to the t, plus F over the quantity 1 plus y, to the n"},{"line":1,"text":"y up implies P down"},{"line":2,"text":"zero: P equals F over the quantity 1 plus y, to the n"}],"terms":[{"term":"P","meaning":"Bond price: the present value of all its coupon and principal payments.","function":false},{"term":"∑","meaning":"Summation over coupon periods t from 1 to n of each discounted coupon.","function":true},{"term":"t","meaning":"Coupon period index, running from 1 to n, marking when each coupon is paid.","function":false},{"term":"n","meaning":"Number of periods until maturity, when the final coupon and face value are paid.","function":false},{"term":"C","meaning":"Coupon payment per period, in dollars, paid to the bondholder each period.","function":false},{"term":"y","meaning":"Yield to maturity per period: the single discount rate that equates price with the bond's cash flows.","function":false},{"term":"F","meaning":"Face (par) value repaid at maturity, in dollars, discounted over n periods.","function":false},{"term":"↑ / ↓","meaning":"Arrows mean rises and falls: bond prices move inversely to yields.","function":false},{"term":"⇒","meaning":"Implies: a rise in yield leads to a fall in price.","function":false}],"explanation":"A bond's price is the present value of its coupons plus its face value at maturity, all discounted at the yield to maturity y. Higher yields shrink every discounted term, so price and yield move in opposite directions. When the coupon rate exceeds the yield the bond trades above face value (a premium), and below face when the coupon is lower (a discount). A zero-coupon bond is simply its face value discounted n periods.","origin":"","implementations":[{"name":"=PRICE()","library":"Excel","note":"Bond price per 100 face value from yield and coupon."},{"name":"=YIELD()","library":"Excel","note":"Yield to maturity from bond price."},{"name":"QuantLib.FixedRateBond","library":"QuantLib","note":"Models fixed-coupon bonds for pricing and yield calculations."}]},"FN.15":{"spoken":[{"line":0,"text":"D sub Mac equals 1 over P times the sum of t times C F sub t over the quantity 1 plus y, to the t"},{"line":1,"text":"D sub mod equals D sub Mac over the quantity 1 plus y"},{"line":2,"text":"delta P over P is approximately negative D sub mod delta y plus one half Cx times the quantity delta y, squared"}],"terms":[{"term":"D_Mac","meaning":"Macaulay duration: the present-value-weighted average time, in years or periods, until the bond's cash flows arrive.","function":false},{"term":"P","meaning":"Current bond price, the sum of discounted cash flows.","function":false},{"term":"∑","meaning":"Summation over periods t of time times discounted cash flow.","function":true},{"term":"t","meaning":"Time of each cash flow, in periods, used as the weight in the duration average.","function":false},{"term":"CFₜ","meaning":"Cash flow at time t: a coupon, plus principal at maturity.","function":false},{"term":"y","meaning":"Yield to maturity per period, the discount rate applied to every cash flow.","function":false},{"term":"D_mod","meaning":"Modified duration: the approximate percentage price change for a one-unit change in yield.","function":false},{"term":"Δ","meaning":"Delta, a small change in the quantity that follows.","function":false},{"term":"Cx","meaning":"Convexity: the curvature of the price-yield relationship, a second-order correction to the duration estimate.","function":false}],"explanation":"Macaulay duration is the present-value-weighted average time until a bond's cash flows arrive. Dividing by (1 + y) gives modified duration, the approximate percentage price change per unit change in yield. Because the price–yield curve bends, convexity adds a second-order term, ½·Cx·(Δy)², which improves the estimate for larger rate moves. Duration and convexity are the main tools for measuring and hedging interest-rate risk.","origin":"Frederick Macaulay introduced duration in 1938.","implementations":[{"name":"=DURATION()","library":"Excel","note":"Macaulay duration of a periodic-coupon bond."},{"name":"=MDURATION()","library":"Excel","note":"Modified duration of a periodic-coupon bond."},{"name":"QuantLib.BondFunctions.duration","library":"QuantLib","note":"Duration (Macaulay, modified or simple) of a bond."}]},"FN.16":{"spoken":[{"line":0,"text":"P sub 0 equals D sub 1 over the quantity r minus g (Gordon)"},{"line":1,"text":"P over E equals price over EPS"},{"line":2,"text":"EV equals market cap plus debt minus cash"}],"terms":[{"term":"P₀","meaning":"Intrinsic value of the stock today under the Gordon constant-growth model.","function":false},{"term":"D₁","meaning":"Dividend per share expected one year from now.","function":false},{"term":"r","meaning":"Required rate of return on equity (cost of equity).","function":false},{"term":"g","meaning":"Constant long-run growth rate of dividends; must be below r.","function":false},{"term":"P/E","meaning":"Price-to-earnings ratio: how many dollars investors pay per dollar of annual earnings.","function":false},{"term":"price","meaning":"Current market price per share of the company's stock.","function":false},{"term":"EPS","meaning":"Earnings per share: net income divided by shares outstanding.","function":false},{"term":"EV","meaning":"Enterprise value: the total value of the firm's operations to all capital providers.","function":false},{"term":"market cap","meaning":"Market capitalization: share price times shares outstanding, the equity value.","function":false},{"term":"debt","meaning":"Total interest-bearing debt of the company, added because acquirers assume it.","function":false},{"term":"cash","meaning":"Cash and cash equivalents, subtracted because they offset debt.","function":false}],"explanation":"The Gordon growth model values a stock as a growing perpetuity of dividends: next year's dividend divided by the discount rate minus the growth rate. Because g sits in the denominator, values blow up as g approaches r. Multiples such as P/E are shortcuts for comparing firms. Enterprise value, which is market cap plus debt minus cash, measures the value of the whole business regardless of how it is financed.","origin":"Myron Gordon published the growth model in 1959, building on the dividend discount model of John Burr Williams (1938).","implementations":[]},"FN.17":{"spoken":[{"line":0,"text":"call equals the max of S sub T minus K, and 0"},{"line":1,"text":"put equals the max of K minus S sub T, and 0"},{"line":2,"text":"C minus P equals S sub 0 minus K e to the negative r T"}],"terms":[{"term":"call","meaning":"Payoff at expiration of a call option, the right to buy at the strike price.","function":false},{"term":"max","meaning":"Maximum: takes two numbers and returns the larger; the option holder exercises only when it pays, so payoff never goes negative.","function":true},{"term":"S_T","meaning":"Price of the underlying asset at expiration time T.","function":false},{"term":"K","meaning":"Strike price: the fixed price at which the option can be exercised.","function":false},{"term":"put","meaning":"Payoff at expiration of a put option, the right to sell at the strike price.","function":false},{"term":"C","meaning":"Price today of a European call option on the underlying asset.","function":false},{"term":"P","meaning":"Price today of a European put option with the same strike and expiration.","function":false},{"term":"S₀","meaning":"Current price of the underlying asset at time zero.","function":false},{"term":"e","meaning":"Euler's number, used for continuous discounting of the strike.","function":false},{"term":"r","meaning":"Continuously compounded annual risk-free interest rate used to discount the strike.","function":false},{"term":"T","meaning":"Time to expiration of both options, measured in years.","function":false}],"explanation":"At expiry a call pays the amount by which the stock price exceeds the strike, and a put pays the amount by which the strike exceeds the price. Each is floored at zero, so the option holder never loses more than the premium. Put–call parity says a long call plus a short put equals holding the stock and borrowing the present value of the strike. Without it there would be a riskless arbitrage, so it links European call and put prices.","origin":"Hans Stoll formalized put–call parity in 1969.","implementations":[{"name":"numpy.maximum","library":"NumPy","note":"Elementwise max for computing option payoffs."},{"name":"QuantLib.PlainVanillaPayoff","library":"QuantLib","note":"Defines call or put payoffs for option pricing."}]},"FN.18":{"spoken":[{"line":0,"text":"C equals S sub 0 N of d sub 1 minus K e to the negative r T N of d sub 2"},{"line":1,"text":"d sub 1 equals the natural log of S sub 0 over K, plus the quantity r plus sigma squared over 2, times T, all over sigma times the square root of T"},{"line":2,"text":"d sub 2 equals d sub 1 minus sigma times the square root of T"}],"terms":[{"term":"C","meaning":"Black-Scholes price of a European call option on a non-dividend-paying stock.","function":false},{"term":"S₀","meaning":"Current price of the underlying stock at time zero.","function":false},{"term":"N(·)","meaning":"Standard normal cumulative distribution function: takes a number and returns the probability that a standard normal variable is below it.","function":true},{"term":"d₁","meaning":"Standardized moneyness term; N of d sub 1 is the call's delta.","function":false},{"term":"K","meaning":"Strike price of the option, the price paid if the call is exercised.","function":false},{"term":"e","meaning":"Euler's number, used to discount the strike continuously.","function":false},{"term":"r","meaning":"Continuously compounded annual risk-free interest rate over the option's life.","function":false},{"term":"T","meaning":"Time to expiration of the option, measured in years.","function":false},{"term":"d₂","meaning":"d sub 1 minus sigma root T; N of d sub 2 is the risk-neutral probability the call finishes in the money.","function":false},{"term":"ln","meaning":"Natural logarithm: takes the ratio of spot to strike and returns its log, measuring moneyness.","function":true},{"term":"σ","meaning":"Sigma, the annualized volatility of the underlying stock's returns.","function":false},{"term":"√","meaning":"Square root of time, scaling volatility to the option's life.","function":true}],"explanation":"The Black–Scholes formula prices a European call as the stock price weighted by N(d₁) minus the discounted strike weighted by N(d₂), where N is the standard normal CDF. It assumes the stock follows geometric Brownian motion with constant volatility σ and rate r. Under those assumptions continuous delta hedging makes the option riskless. N(d₂) is the risk-neutral probability of finishing in the money, and N(d₁) is the option's delta.","origin":"Fischer Black and Myron Scholes published the model in 1973, with Robert Merton extending it the same year. Scholes and Merton received the 1997 Nobel Prize in economics for it.","implementations":[{"name":"scipy.stats.norm.cdf","library":"SciPy","note":"Standard normal CDF for N(d₁) and N(d₂)."},{"name":"QuantLib.AnalyticEuropeanEngine","library":"QuantLib","note":"Closed-form Black–Scholes pricing of European options."},{"name":"py_vollib.black_scholes.black_scholes","library":"py_vollib","note":"Black–Scholes price of a European call or put."}]},"FN.19":{"spoken":[{"line":0,"text":"VaR sub alpha equals z sub alpha sigma times the square root of t times V"},{"line":1,"text":"ES equals the expected value of loss given loss is greater than VaR"},{"line":2,"text":"z sub 0.95 equals 1.645, z sub 0.99 equals 2.326"}],"terms":[{"term":"VaR_α","meaning":"Value at Risk at confidence level alpha: the loss, in dollars, not expected to be exceeded with probability alpha.","function":false},{"term":"α","meaning":"Alpha, the confidence level, such as 0.95 or 0.99.","function":false},{"term":"z_α","meaning":"Standard normal quantile at level alpha, the number of standard deviations to the loss threshold.","function":false},{"term":"σ","meaning":"Sigma, the volatility of portfolio returns per unit time.","function":false},{"term":"√","meaning":"Square root of the horizon, scaling one-period volatility to t periods.","function":true},{"term":"t","meaning":"Holding period or horizon, in the same units as sigma, such as days.","function":false},{"term":"V","meaning":"Current dollar value of the portfolio whose potential loss is being measured.","function":false},{"term":"ES","meaning":"Expected shortfall: the average loss in the worst cases beyond the VaR threshold.","function":false},{"term":"E[· ∣ ·]","meaning":"Conditional expectation: returns the average of the loss restricted to scenarios where the loss exceeds VaR.","function":true},{"term":"loss","meaning":"Portfolio loss over the horizon, a random variable.","function":false}],"explanation":"Value at Risk is the loss threshold that a portfolio exceeds only with a small probability over a given horizon. Under a normal model it is the z-score times volatility times √t times the portfolio value, with z = 1.645 at 95% and 2.326 at 99%. Expected shortfall is the average loss beyond VaR, so it captures how bad tail losses are. Unlike VaR, ES is a coherent risk measure.","origin":"J.P. Morgan's RiskMetrics system (1994) popularized VaR, and Artzner and coauthors' 1999 work on coherent risk measures motivated expected shortfall.","implementations":[{"name":"scipy.stats.norm.ppf","library":"SciPy","note":"Normal quantile z for parametric VaR."},{"name":"numpy.percentile","library":"NumPy","note":"Empirical quantile of returns for historical VaR."},{"name":"empyrical.value_at_risk","library":"empyrical","note":"Historical VaR from a return series."},{"name":"empyrical.conditional_value_at_risk","library":"empyrical","note":"Expected shortfall (CVaR) from a return series."}]},"FN.20":{"spoken":[{"line":0,"text":"ROE equals NI over equity, equals NI over sales, times sales over assets, times assets over equity"},{"line":1,"text":"current ratio equals CA over CL"},{"line":2,"text":"D over E equals debt over equity"}],"terms":[{"term":"ROE","meaning":"Return on equity: net income earned per dollar of shareholders' equity.","function":false},{"term":"NI","meaning":"Net income: the company's profit after all expenses, interest and taxes.","function":false},{"term":"equity","meaning":"Shareholders' equity: total assets minus total liabilities, the owners' stake in the firm.","function":false},{"term":"sales","meaning":"Revenue; NI over sales is profit margin, sales over assets is asset turnover.","function":false},{"term":"assets","meaning":"Total assets; assets over equity is the equity multiplier, a measure of leverage.","function":false},{"term":"·","meaning":"Multiplication: the three DuPont ratios multiply to give ROE.","function":false},{"term":"current ratio","meaning":"Liquidity ratio of short-term assets to short-term obligations.","function":false},{"term":"CA","meaning":"Current assets: cash, receivables and inventory convertible within a year.","function":false},{"term":"CL","meaning":"Current liabilities: obligations such as payables and short-term debt due within a year.","function":false},{"term":"D/E","meaning":"Debt-to-equity ratio, a leverage measure of how much debt finances the firm per dollar of equity.","function":false},{"term":"debt","meaning":"Total debt of the company, borrowed money owed to lenders.","function":false}],"explanation":"DuPont analysis breaks return on equity into three ratios multiplied together: profit margin (NI/sales), asset turnover (sales/assets) and leverage (assets/equity). The intermediate terms cancel, so the product is exactly NI/equity. This shows whether a high ROE comes from profitability, efficiency or debt. The current ratio measures short-term liquidity and debt-to-equity measures solvency, and both rest on the identity assets = liabilities + equity.","origin":"The decomposition was developed at the DuPont company by F. Donaldson Brown in the 1910s.","implementations":[]},"FN.21":{"spoken":[{"line":0,"text":"E V equals p W minus q L"},{"line":1,"text":"f star equals b p minus q, over b; q equals 1 minus p"}],"terms":[{"term":"EV","meaning":"Expected value of the bet: the average profit per bet if repeated many times.","function":false},{"term":"p","meaning":"Probability of winning the bet, a number between 0 and 1.","function":false},{"term":"W","meaning":"Amount won if the bet succeeds, in dollars or units of stake.","function":false},{"term":"q","meaning":"Probability of losing the bet, equal to 1 minus p.","function":false},{"term":"L","meaning":"Amount lost if the bet fails, in dollars or units of stake.","function":false},{"term":"f*","meaning":"Kelly fraction: the optimal fraction of current bankroll to wager to maximize long-run growth.","function":false},{"term":"b","meaning":"Net odds received on the bet: profit per dollar wagered if you win.","function":false}],"explanation":"The expected value of a bet weighs the win amount by its probability and subtracts the probability-weighted loss. A negative EV loses money on average. The Kelly criterion gives the fraction f* of wealth to stake at net odds b that maximizes the long-run growth rate of wealth, which is the expected log return. Betting more than Kelly raises risk and lowers growth. Many practitioners bet half Kelly to cut volatility and allow for errors in estimating p.","origin":"John L. Kelly Jr. introduced the criterion at Bell Labs in 1956.","implementations":[]},"FN.22":{"spoken":[{"line":0,"text":"d S equals mu S d t plus sigma S d W"},{"line":1,"text":"S sub T equals S sub 0 times the exponential of the quantity, mu minus sigma squared over 2, times T, plus sigma W sub T"},{"line":2,"text":"the expected value of S sub T equals S sub 0 e to the mu T"}],"terms":[{"term":"dS","meaning":"Infinitesimal change in the asset price over a tiny time interval.","function":false},{"term":"μ","meaning":"Mu, the drift: the expected continuously compounded rate of return per year.","function":false},{"term":"S","meaning":"Current asset price, so both drift and randomness scale with price.","function":false},{"term":"dt","meaning":"Infinitesimal time increment over which the price change dS occurs.","function":false},{"term":"σ","meaning":"Sigma, the annualized volatility of the asset's returns.","function":false},{"term":"dW","meaning":"Increment of a Wiener process (Brownian motion): random normal shock with mean 0 and variance dt.","function":false},{"term":"S_T","meaning":"Asset price at future time T, a lognormally distributed random variable.","function":false},{"term":"S₀","meaning":"Asset price at time zero, the known starting value.","function":false},{"term":"exp","meaning":"Exponential function: takes a number x and returns e to the x, making the price lognormal and always positive.","function":true},{"term":"T","meaning":"Time horizon from now to the future date, in years.","function":false},{"term":"W_T","meaning":"Value of the Brownian motion at time T, normally distributed with mean 0 and variance T.","function":false},{"term":"E[·]","meaning":"Expected value: takes the random future price and returns its average.","function":true},{"term":"e","meaning":"Euler's number, about 2.718, the base of continuous exponential growth.","function":false}],"explanation":"Geometric Brownian motion models a price whose percentage changes have constant drift μ and volatility σ, driven by a Wiener process W. Solving the stochastic differential equation with Itô's lemma gives a log-normal price, with a −σ²/2 drift correction in the exponent. The mean grows as S₀e^(μT), but the median S₀e^((μ−σ²/2)T) is lower, which reflects right skew. GBM is the price model behind Black–Scholes.","origin":"Paul Samuelson popularized geometric Brownian motion as a stock-price model in 1965, and it underlies the 1973 Black–Scholes model.","implementations":[{"name":"QuantLib.GeometricBrownianMotionProcess","library":"QuantLib","note":"Defines a GBM stochastic process for simulation and pricing."},{"name":"numpy.random.Generator.standard_normal","library":"NumPy","note":"Normal shocks for simulating GBM paths."}]},"P.1":{"spoken":[{"line":0,"text":"the dimensions of F equal kilograms times meters per second squared, equals newtons"},{"line":2,"text":"Buckingham pi: number of groups equals n minus k"}],"terms":[{"term":"[ ]","meaning":"Square brackets denote the dimensions or units of the enclosed quantity, here the units of force.","function":false},{"term":"F","meaning":"Force, the physical quantity whose SI units are being expressed in base units.","function":false},{"term":"kg","meaning":"Kilogram, the SI base unit of mass appearing in the unit of force.","function":false},{"term":"m/s²","meaning":"Meters per second squared, the SI unit of acceleration.","function":false},{"term":"N","meaning":"Newton, the SI unit of force, equal to one kilogram meter per second squared.","function":false},{"term":"π","meaning":"Pi here names a dimensionless group in the Buckingham pi theorem, not the number 3.14159.","function":false},{"term":"#","meaning":"Number of: counts the independent dimensionless groups that can be formed.","function":false},{"term":"n","meaning":"Number of physical variables in the problem being nondimensionalized.","function":false},{"term":"k","meaning":"Number of independent fundamental dimensions involved, such as mass, length and time.","function":false}],"explanation":"Dimensional analysis checks equations by making sure both sides have the same fundamental dimensions, such as mass, length and time. The newton, for example, breaks down into kg·m/s². A mismatch means an error, and the method can also predict how a quantity scales. The Buckingham π theorem says a relation among n variables with k independent dimensions can be rewritten using n − k dimensionless groups, which is how Reynolds and similar numbers arise.","origin":"Edgar Buckingham published the π theorem in 1914, building on earlier work by Lord Rayleigh and others.","implementations":[{"name":"pint.UnitRegistry","library":"Pint","note":"Attaches units to quantities and checks dimensional consistency."},{"name":"astropy.units","library":"Astropy","note":"Unit-aware quantities with conversion and dimension checking."},{"name":"sympy.physics.units","library":"SymPy","note":"Symbolic units and dimensional analysis."}]},"P.2":{"spoken":[{"line":0,"text":"v equals d x d t, a equals d v d t"},{"line":1,"text":"v equals v sub 0 plus a t"},{"line":2,"text":"x equals x sub 0 plus v sub 0 t plus one half a t squared"},{"line":3,"text":"v squared equals v sub 0 squared plus 2 a delta x"}],"terms":[{"term":"v","meaning":"Velocity of the object at time t, in meters per second.","function":false},{"term":"d/dt","meaning":"Time derivative operator: takes a quantity changing with time and returns its instantaneous rate of change.","function":true},{"term":"x","meaning":"Position of the object at time t, in meters.","function":false},{"term":"t","meaning":"Elapsed time since the start of motion, in seconds.","function":false},{"term":"a","meaning":"Constant acceleration of the object, in meters per second squared.","function":false},{"term":"v₀","meaning":"Initial velocity at time zero, in meters per second.","function":false},{"term":"x₀","meaning":"Initial position of the object at time zero, in meters.","function":false},{"term":"Δx","meaning":"Displacement: change in position, x minus x sub 0, in meters.","function":false}],"explanation":"Velocity is the time derivative of position and acceleration is the time derivative of velocity. With constant acceleration, integrating once gives v = v₀ + at, and integrating again gives the quadratic position formula. Eliminating time between the two gives v² = v₀² + 2aΔx, which helps when time is unknown. These equations describe free fall, braking cars and projectiles, treating each axis separately.","origin":"Galileo Galilei established the laws of uniformly accelerated motion in the early 1600s.","implementations":[]},"P.3":{"spoken":[{"line":0,"text":"the sum of the forces F equals m a"},{"line":1,"text":"W equals m g"},{"line":2,"text":"f sub k equals mu sub k N"},{"line":3,"text":"F sub A B equals negative F sub B A"}],"terms":[{"term":"∑","meaning":"Summation: adds all force vectors acting on the object to give the net force.","function":true},{"term":"𝐅","meaning":"Force vector, in newtons, acting on the object.","function":false},{"term":"m","meaning":"Mass of the object, in kilograms, resisting changes in its motion.","function":false},{"term":"𝐚","meaning":"Acceleration vector of the object, in meters per second squared.","function":false},{"term":"W","meaning":"Weight: the gravitational force on the object, in newtons.","function":false},{"term":"g","meaning":"Gravitational acceleration near Earth's surface, about 9.81 meters per second squared.","function":false},{"term":"f_k","meaning":"Kinetic friction force opposing sliding motion, in newtons.","function":false},{"term":"μ_k","meaning":"Mu sub k, the dimensionless coefficient of kinetic friction between the two surfaces.","function":false},{"term":"N","meaning":"Normal force: the perpendicular contact force from the surface, in newtons.","function":false},{"term":"𝐅_AB","meaning":"Force exerted by object A on object B; Newton's third law says it equals minus the force of B on A.","function":false},{"term":"𝐅_BA","meaning":"Force exerted by object B on object A, equal in size and opposite in direction.","function":false}],"explanation":"Newton's second law says the net force on a body equals its mass times its acceleration, so to solve a problem you sum every force from a free-body diagram. Weight near Earth's surface is mg. Kinetic friction opposes sliding with magnitude μₖ times the normal force. The third law says forces come in equal and opposite pairs acting on different bodies.","origin":"Isaac Newton stated the three laws in his Principia (1687). The friction law was formulated by Guillaume Amontons (1699) and Charles-Augustin de Coulomb (1785).","implementations":[]},"P.4":{"spoken":[{"line":0,"text":"W equals F d cosine theta"},{"line":1,"text":"K E equals one half m v squared; P E equals m g h"},{"line":2,"text":"K E sub 1 plus P E sub 1 equals K E sub 2 plus P E sub 2"},{"line":3,"text":"P equals W over t equals F v"}],"terms":[{"term":"W","meaning":"Work done by the force on the object, in joules.","function":false},{"term":"F","meaning":"Magnitude of the applied force, in newtons; in P equals F v the driving force.","function":false},{"term":"d","meaning":"Displacement distance through which the force acts, in meters.","function":false},{"term":"cos","meaning":"Cosine function: takes the angle between force and displacement and returns the fraction of the force along the motion.","function":true},{"term":"θ","meaning":"Theta, the angle between the force vector and the displacement direction.","function":false},{"term":"KE","meaning":"Kinetic energy: energy an object has due to its motion, in joules.","function":false},{"term":"m","meaning":"Mass of the moving or raised object, in kilograms.","function":false},{"term":"v","meaning":"Speed of the object, in meters per second.","function":false},{"term":"PE","meaning":"Gravitational potential energy relative to a reference height, in joules.","function":false},{"term":"g","meaning":"Gravitational acceleration, about 9.81 meters per second squared.","function":false},{"term":"h","meaning":"Height of the object above the chosen reference level, in meters.","function":false},{"term":"KE₁, PE₁","meaning":"Kinetic and potential energy at the initial state 1, in joules.","function":false},{"term":"KE₂, PE₂","meaning":"Kinetic and potential energy at the later state 2, in joules.","function":false},{"term":"P","meaning":"Power: rate of doing work, in watts (joules per second).","function":false},{"term":"t","meaning":"Time over which the work is done, in seconds.","function":false}],"explanation":"Work is the component of force along the displacement times the distance moved, Fd·cos θ. Kinetic energy ½mv² and gravitational potential energy mgh are two forms of mechanical energy. When only conservative forces act, their sum stays constant, so energy conservation relates speeds and heights without tracking forces in detail. Power is the rate of doing work, which also equals force times velocity.","origin":"Gaspard-Gustave Coriolis introduced the term 'work' and the ½mv² form of kinetic energy around 1829.","implementations":[]},"P.5":{"spoken":[{"line":0,"text":"p equals m v"},{"line":1,"text":"J equals F delta t equals delta p"},{"line":2,"text":"the sum of p before equals the sum of p after"}],"terms":[{"term":"𝐩","meaning":"Linear momentum vector, in kilogram meters per second.","function":false},{"term":"m","meaning":"Mass of the object, in kilograms, multiplying velocity to give momentum.","function":false},{"term":"𝐯","meaning":"Velocity vector of the object, in meters per second.","function":false},{"term":"𝐉","meaning":"Impulse: the force integrated over time, in newton seconds.","function":false},{"term":"𝐅","meaning":"Average force applied during the interaction, in newtons.","function":false},{"term":"Δt","meaning":"Duration of the force or collision, in seconds.","function":false},{"term":"Δ𝐩","meaning":"Change in momentum of the object, equal to the impulse.","function":false},{"term":"∑","meaning":"Summation over all objects in the system, adding their momentum vectors.","function":true},{"term":"𝐩_before, 𝐩_after","meaning":"Momenta of each object before and after a collision; total momentum is conserved in an isolated system.","function":false}],"explanation":"Momentum is mass times velocity. Impulse, which is force times the time it acts, equals the change in momentum, so spreading a collision over more time lowers the peak force. That is how airbags and padding work. With no external forces, total momentum is conserved, so the summed momenta before and after a collision or explosion are equal, whether or not kinetic energy is lost.","origin":"Isaac Newton's Principia (1687) states the second law in terms of change in the quantity of motion, that is, momentum.","implementations":[]},"P.6":{"spoken":[{"line":0,"text":"a sub c equals v squared over r equals omega squared r"},{"line":1,"text":"F equals G m sub 1 m sub 2 over r squared"},{"line":2,"text":"g equals G M over R squared; v sub orbit equals the square root of G M over r"}],"terms":[{"term":"a_c","meaning":"Centripetal acceleration directed toward the center of the circle, in meters per second squared.","function":false},{"term":"v","meaning":"Tangential speed along the circular path, in meters per second.","function":false},{"term":"r","meaning":"Radius of the circular path or distance between centers of masses, in meters.","function":false},{"term":"ω","meaning":"Omega, the angular velocity, in radians per second.","function":false},{"term":"F","meaning":"Magnitude of the gravitational attraction between two masses, in newtons.","function":false},{"term":"G","meaning":"Universal gravitational constant, about 6.674 times 10 to the negative 11 newton meters squared per kilogram squared.","function":false},{"term":"m₁, m₂","meaning":"The two attracting masses, in kilograms, whose product sets the gravitational force.","function":false},{"term":"g","meaning":"Surface gravitational acceleration of a planet, in meters per second squared.","function":false},{"term":"M","meaning":"Mass of the planet or central body, in kilograms.","function":false},{"term":"R","meaning":"Radius of the planet, the distance from its center to its surface, in meters.","function":false},{"term":"v_orbit","meaning":"Speed needed for a circular orbit at radius r, in meters per second.","function":false},{"term":"√","meaning":"Square root: takes G M over r and returns the orbital speed.","function":true}],"explanation":"An object moving in a circle accelerates toward the center at v²/r = ω²r, even at constant speed. Newton's law of gravitation gives an attractive force proportional to both masses and inversely proportional to distance squared. Applying it at a planet's surface gives g = GM/R². Setting gravity equal to the centripetal force gives the speed of a circular orbit, √(GM/r).","origin":"Isaac Newton published the law of universal gravitation in 1687. Christiaan Huygens derived the centripetal acceleration formula around 1659 and published it in 1673.","implementations":[{"name":"scipy.constants.G","library":"SciPy","note":"Newtonian constant of gravitation (CODATA value)."}]},"P.7":{"spoken":[{"line":0,"text":"x of t equals A cosine of the quantity omega t plus phi"},{"line":1,"text":"omega equals the square root of k over m, T equals 2 pi times the square root of m over k"},{"line":2,"text":"T sub pend equals 2 pi times the square root of L over g"}],"terms":[{"term":"x(t)","meaning":"Displacement from equilibrium as a function of time, in meters.","function":true},{"term":"A","meaning":"Amplitude: the maximum displacement from equilibrium, in meters.","function":false},{"term":"cos","meaning":"Cosine function: takes the phase angle and returns a value between negative 1 and 1, producing periodic motion.","function":true},{"term":"ω","meaning":"Omega, the angular frequency of oscillation, in radians per second.","function":false},{"term":"t","meaning":"Time elapsed since the reference moment, in seconds.","function":false},{"term":"ϕ","meaning":"Phi, the phase constant, in radians, set by the initial conditions.","function":false},{"term":"√","meaning":"Square root: takes a ratio of physical quantities and returns the factor setting frequency or period.","function":true},{"term":"k","meaning":"Spring constant (stiffness) of the spring, in newtons per meter.","function":false},{"term":"m","meaning":"Mass attached to the oscillating spring, in kilograms.","function":false},{"term":"T","meaning":"Period: time for one complete oscillation, in seconds.","function":false},{"term":"π","meaning":"Pi, about 3.14159; 2 pi radians make one full cycle.","function":false},{"term":"T_pend","meaning":"Period of a simple pendulum for small swings, in seconds.","function":false},{"term":"L","meaning":"Length of the pendulum from pivot to center of mass, in meters.","function":false},{"term":"g","meaning":"Gravitational acceleration, about 9.81 meters per second squared.","function":false}],"explanation":"Simple harmonic motion occurs when a restoring force is proportional to displacement, which gives sinusoidal motion with amplitude A, angular frequency ω and phase ϕ. For a mass on a spring, ω = √(k/m), so the period depends on mass and stiffness but not on amplitude. A simple pendulum at small angles has period 2π√(L/g), set only by its length and gravity.","origin":"Robert Hooke stated his spring law in 1678. Christiaan Huygens derived the pendulum period formula in 1673.","implementations":[]},"P.8":{"spoken":[{"line":0,"text":"P equals F over A"},{"line":1,"text":"P equals P sub 0 plus rho g h"},{"line":2,"text":"F sub B equals rho sub fluid g V sub disp"}],"terms":[{"term":"P","meaning":"Pressure: force per unit area, in pascals (newtons per square meter).","function":false},{"term":"F","meaning":"Normal force pushing on the surface, in newtons.","function":false},{"term":"A","meaning":"Area over which the force is spread, in square meters.","function":false},{"term":"P₀","meaning":"Pressure at the fluid surface, often atmospheric pressure, about 101,325 pascals.","function":false},{"term":"ρ","meaning":"Rho, the fluid density, in kilograms per cubic meter.","function":false},{"term":"g","meaning":"Gravitational acceleration, about 9.81 meters per second squared.","function":false},{"term":"h","meaning":"Depth below the fluid's free surface, in meters, where pressure is measured.","function":false},{"term":"F_B","meaning":"Buoyant force pushing upward on a submerged object, in newtons.","function":false},{"term":"ρ_fluid","meaning":"Density of the surrounding fluid, in kilograms per cubic meter.","function":false},{"term":"V_disp","meaning":"Volume of fluid displaced by the object, in cubic meters.","function":false}],"explanation":"Pressure is force per unit area. In a static fluid it increases linearly with depth, P = P₀ + ρgh, because each layer supports the weight of the fluid above it. Buoyancy is the net result of the higher pressure on an object's lower surface. Archimedes' principle states that the upward force equals the weight of the displaced fluid, which determines whether objects float or sink.","origin":"Archimedes stated the buoyancy principle around 250 BC. Blaise Pascal clarified hydrostatic pressure in the 1640s and 1650s.","implementations":[]},"P.9":{"spoken":[{"line":0,"text":"A sub 1 v sub 1 equals A sub 2 v sub 2 (Q equals A v)"},{"line":1,"text":"P plus one half rho v squared plus rho g h equals constant"},{"line":2,"text":"Torricelli: v equals the square root of 2 g h"}],"terms":[{"term":"A₁, A₂","meaning":"Cross-sectional areas of the pipe at sections 1 and 2, in square meters.","function":false},{"term":"v₁, v₂","meaning":"Average flow speeds at sections 1 and 2, in meters per second.","function":false},{"term":"Q","meaning":"Volumetric flow rate, in cubic meters per second, constant along the pipe.","function":false},{"term":"A","meaning":"Cross-sectional area of the flow, in square meters.","function":false},{"term":"v","meaning":"Flow speed, in meters per second; in Torricelli's law the outflow speed from a hole.","function":false},{"term":"P","meaning":"Static fluid pressure at a point along the streamline, in pascals.","function":false},{"term":"ρ","meaning":"Rho, the fluid density, in kilograms per cubic meter.","function":false},{"term":"g","meaning":"Gravitational acceleration, about 9.81 meters per second squared.","function":false},{"term":"h","meaning":"Elevation above a reference; in Torricelli's law the fluid depth above the hole, in meters.","function":false},{"term":"const","meaning":"A constant: the total mechanical energy per volume stays the same along a streamline.","function":false},{"term":"√","meaning":"Square root: takes 2 g h and returns the efflux speed.","function":true}],"explanation":"The continuity equation says that an incompressible fluid's volume flow rate Q = Av is the same everywhere along a pipe, so flow speeds up where the pipe narrows. Bernoulli's equation states energy conservation along a streamline for steady, inviscid flow: pressure, kinetic energy density and potential energy density sum to a constant. Faster flow therefore means lower pressure. Torricelli's law, v = √(2gh), follows for fluid draining from an opening at depth h.","origin":"Daniel Bernoulli published the principle in Hydrodynamica (1738), and Evangelista Torricelli found his efflux law in 1643.","implementations":[]},"P.10":{"spoken":[{"line":0,"text":"tau equals mu d u d y"},{"line":1,"text":"R e equals rho v L over mu equals v L over nu"},{"line":2,"text":"pipe: laminar less than 2300, turbulent greater than 4000"},{"line":3,"text":"Q equals pi r to the fourth delta P, over 8 mu L"}],"terms":[{"term":"τ","meaning":"Tau, the shear stress within the fluid, in pascals.","function":false},{"term":"μ","meaning":"Mu, the dynamic viscosity of the fluid, in pascal seconds.","function":false},{"term":"du/dy","meaning":"Velocity gradient: derivative of flow velocity u with respect to distance y across the flow, in inverse seconds.","function":true},{"term":"Re","meaning":"Reynolds number: dimensionless ratio of inertial to viscous forces that predicts laminar or turbulent flow.","function":false},{"term":"ρ","meaning":"Rho, the fluid density, in kilograms per cubic meter.","function":false},{"term":"v","meaning":"Characteristic flow velocity of the fluid, in meters per second.","function":false},{"term":"L","meaning":"Characteristic length, such as pipe diameter, in meters; in Poiseuille's law the pipe length.","function":false},{"term":"ν","meaning":"Nu, the kinematic viscosity, mu over rho, in square meters per second.","function":false},{"term":"Q","meaning":"Volumetric flow rate through the pipe, in cubic meters per second.","function":false},{"term":"π","meaning":"Pi, the circle constant about 3.14159, arising from the pipe's circular cross section.","function":false},{"term":"r","meaning":"Inner radius of the pipe, in meters; flow scales with its fourth power.","function":false},{"term":"ΔP","meaning":"Pressure drop along the pipe length, in pascals.","function":false}],"explanation":"Viscosity μ relates shear stress to the velocity gradient in a Newtonian fluid. The Reynolds number compares inertial and viscous forces. In pipes, flow stays laminar below about 2300 and becomes turbulent above about 4000. For laminar pipe flow, the Hagen–Poiseuille law gives the volume flow rate, which scales with the fourth power of the radius, so a small change in pipe size changes the flow dramatically.","origin":"Osborne Reynolds demonstrated the laminar-turbulent transition in 1883. Gotthilf Hagen and Jean Poiseuille independently found the pipe-flow law around 1839–1840.","implementations":[{"name":"fluids.core.Reynolds","library":"fluids","note":"Computes the Reynolds number from velocity, length and fluid properties."}]},"P.11":{"spoken":[{"line":0,"text":"F sub D equals one half rho C sub D A v squared"},{"line":1,"text":"v sub t equals the square root of 2 m g over rho C sub D A"},{"line":2,"text":"Stokes (R e much less than 1): F sub D equals 6 pi mu r v"}],"terms":[{"term":"F_D","meaning":"Drag force resisting motion through the fluid, in newtons.","function":false},{"term":"ρ","meaning":"Rho, the density of the fluid, in kilograms per cubic meter.","function":false},{"term":"C_D","meaning":"Drag coefficient: dimensionless number depending on the object's shape and Reynolds number.","function":false},{"term":"A","meaning":"Frontal (projected) area facing the flow, in square meters.","function":false},{"term":"v","meaning":"Speed of the object relative to the fluid, in meters per second.","function":false},{"term":"v_t","meaning":"Terminal velocity, where drag balances weight, in meters per second.","function":false},{"term":"√","meaning":"Square root: takes the ratio of weight to drag factor and returns terminal speed.","function":true},{"term":"m","meaning":"Mass of the falling object, in kilograms, setting its weight m g.","function":false},{"term":"g","meaning":"Gravitational acceleration, about 9.81 meters per second squared.","function":false},{"term":"Re","meaning":"Reynolds number; Stokes drag applies when it is much less than 1 (creeping flow).","function":false},{"term":"≪","meaning":"Much less than: Re is far below 1, so viscous forces dominate.","function":false},{"term":"π","meaning":"Pi, the circle constant about 3.14159, appearing in Stokes drag on a sphere.","function":false},{"term":"μ","meaning":"Mu, the dynamic viscosity of the fluid, in pascal seconds.","function":false},{"term":"r","meaning":"Radius of the small sphere moving through the viscous fluid, in meters.","function":false}],"explanation":"At ordinary speeds, aerodynamic drag grows with fluid density, a drag coefficient C_D, the frontal area and the square of the velocity. A falling object accelerates until drag equals its weight. Setting the two equal and solving gives the terminal velocity. At very low Reynolds number, such as tiny particles or droplets, drag is instead linear in velocity, which is Stokes' law, 6πμrv.","origin":"George Gabriel Stokes derived his law for drag on a small sphere in 1851.","implementations":[]},"P.12":{"spoken":[{"line":0,"text":"Q equals m c delta T"},{"line":1,"text":"Q equals m L"},{"line":2,"text":"T sub K equals T sub C plus 273.15"},{"line":3,"text":"T sub F equals nine fifths T sub C plus 32"}],"terms":[{"term":"Q","meaning":"Heat energy added to or removed from the substance, in joules.","function":false},{"term":"m","meaning":"Mass of the substance being heated or changing phase, in kilograms.","function":false},{"term":"c","meaning":"Specific heat capacity, in joules per kilogram kelvin.","function":false},{"term":"ΔT","meaning":"Change in temperature, in kelvins or degrees Celsius.","function":false},{"term":"L","meaning":"Latent heat of the phase change (fusion or vaporization), in joules per kilogram.","function":false},{"term":"T_K","meaning":"Temperature in kelvins, the absolute scale starting at absolute zero.","function":false},{"term":"T_C","meaning":"Temperature on the Celsius scale, in degrees Celsius.","function":false},{"term":"T_F","meaning":"Temperature on the Fahrenheit scale, in degrees Fahrenheit.","function":false}],"explanation":"Sensible heat Q = mcΔT changes a substance's temperature in proportion to its mass and specific heat c. Latent heat Q = mL changes its phase at constant temperature. Water's large specific heat and latent heat of fusion explain why melting ice absorbs so much energy. The conversion formulas relate the Celsius, Kelvin and Fahrenheit scales. Kelvin is an absolute scale and is required in thermodynamic formulas.","origin":"Joseph Black introduced the concepts of specific and latent heat around 1760. Lord Kelvin proposed the absolute temperature scale in 1848.","implementations":[{"name":"scipy.constants.convert_temperature","library":"SciPy","note":"Converts between Celsius, Kelvin, Fahrenheit and Rankine."}]},"P.13":{"spoken":[{"line":0,"text":"q equals negative k d T d x"},{"line":1,"text":"Q dot equals k A delta T over L"},{"line":2,"text":"R equals L over k A, Q dot equals delta T over R sub total"}],"terms":[{"term":"q","meaning":"Heat flux: heat flow per unit area, in watts per square meter.","function":false},{"term":"k","meaning":"Thermal conductivity of the material, in watts per meter kelvin.","function":false},{"term":"dT/dx","meaning":"Temperature gradient: derivative of temperature with respect to position, in kelvins per meter; heat flows down it.","function":true},{"term":"Q̇","meaning":"Q dot, the heat transfer rate through the wall, in watts.","function":false},{"term":"A","meaning":"Cross-sectional area perpendicular to heat flow, in square meters.","function":false},{"term":"ΔT","meaning":"Temperature difference across the wall or layer, in kelvins.","function":false},{"term":"L","meaning":"Thickness of the wall in the direction of heat flow, in meters.","function":false},{"term":"R","meaning":"Thermal resistance of a conducting layer, in kelvins per watt.","function":false},{"term":"R_total","meaning":"Sum of thermal resistances in series along the heat path, in kelvins per watt.","function":false}],"explanation":"Fourier's law says heat flux is proportional to the negative temperature gradient, with thermal conductivity k as the constant, so heat flows from hot to cold. Across a flat wall of thickness L and area A this gives a heat rate of kAΔT/L. Defining thermal resistance R = L/(kA) makes heat flow behave like Ohm's law. Resistances of layers in series or parallel combine like electrical resistors.","origin":"Joseph Fourier formulated the law in his Théorie analytique de la chaleur (1822).","implementations":[]},"P.14":{"spoken":[{"line":0,"text":"Q dot equals h A times the quantity T sub s minus T sub infinity"},{"line":1,"text":"T of t equals T sub infinity plus the quantity T sub 0 minus T sub infinity, times e to the negative t over tau"},{"line":2,"text":"tau equals rho V c over h A"}],"terms":[{"term":"Q̇","meaning":"Q dot, the convective heat transfer rate, in watts.","function":false},{"term":"h","meaning":"Convective heat transfer coefficient, in watts per square meter kelvin.","function":false},{"term":"A","meaning":"Surface area exposed to the fluid, in square meters.","function":false},{"term":"T_s","meaning":"Surface temperature of the object exchanging heat, in kelvins.","function":false},{"term":"T_∞","meaning":"T sub infinity, the ambient fluid temperature far from the surface, in kelvins.","function":false},{"term":"T(t)","meaning":"Object temperature as a function of time, in kelvins.","function":true},{"term":"T₀","meaning":"Initial temperature of the object at time zero.","function":false},{"term":"e","meaning":"Euler's number, about 2.718; the temperature difference decays exponentially.","function":false},{"term":"t","meaning":"Elapsed time since cooling or heating began, in seconds.","function":false},{"term":"τ","meaning":"Tau, the thermal time constant, in seconds: time for the difference to fall to about 37 percent.","function":false},{"term":"ρ","meaning":"Rho, the density of the object, in kilograms per cubic meter.","function":false},{"term":"V","meaning":"Volume of the object, in cubic meters, setting its heat storage.","function":false},{"term":"c","meaning":"Specific heat capacity of the object, in joules per kilogram kelvin.","function":false}],"explanation":"Newton's law of cooling says the convective heat-transfer rate is proportional to the temperature difference between a surface and the surrounding fluid, with heat-transfer coefficient h. If the object has a uniform internal temperature, the gap to ambient temperature decays exponentially. The time constant τ = ρVc/(hA) shows that large heat capacity slows cooling and large surface area speeds it up.","origin":"Isaac Newton published the cooling law anonymously in 1701.","implementations":[]},"P.15":{"spoken":[{"line":0,"text":"B i equals h L sub c over k, L sub c equals V over A sub s"},{"line":1,"text":"B i less than 0.1 implies uniform internal T"},{"line":2,"text":"F o equals alpha t over L sub c squared"}],"terms":[{"term":"Bi","meaning":"Biot number: dimensionless ratio of internal conduction resistance to surface convection resistance.","function":false},{"term":"h","meaning":"Convective heat transfer coefficient at the surface, in watts per square meter kelvin.","function":false},{"term":"L_c","meaning":"Characteristic length, volume over surface area, in meters.","function":false},{"term":"k","meaning":"Thermal conductivity of the solid, in watts per meter kelvin.","function":false},{"term":"V","meaning":"Volume of the solid body, in cubic meters.","function":false},{"term":"A_s","meaning":"Surface area of the body exposed to convection, in square meters.","function":false},{"term":"⇒","meaning":"Implies: a small Biot number justifies the lumped capacitance assumption.","function":false},{"term":"T","meaning":"Temperature inside the body, treated as spatially uniform.","function":false},{"term":"Fo","meaning":"Fourier number: dimensionless time comparing conduction rate to thermal storage.","function":false},{"term":"α","meaning":"Alpha, the thermal diffusivity of the solid, in square meters per second.","function":false},{"term":"t","meaning":"Elapsed time since the start of transient heating or cooling, in seconds.","function":false}],"explanation":"The Biot number compares internal conductive resistance with external convective resistance, using a characteristic length equal to volume over surface area. When Bi is below about 0.1, temperature inside the body stays nearly uniform. The body can then be treated as a single lumped capacitance with exponential cooling. The Fourier number is dimensionless time, and it measures how far heat has diffused relative to the body's size.","origin":"The Biot number is named after Jean-Baptiste Biot, who studied heat conduction in the early 1800s. The Fourier number honors Joseph Fourier.","implementations":[{"name":"fluids.core.Biot","library":"fluids","note":"Computes the Biot number from h, length and conductivity."}]},"P.16":{"spoken":[{"line":0,"text":"N u equals h L over k sub f; P r equals nu over alpha"},{"line":1,"text":"G r equals g beta delta T L cubed, over nu squared"},{"line":2,"text":"R a equals G r times P r equals g beta delta T L cubed, over nu alpha"},{"line":3,"text":"R a sub c is approximately 1708"}],"terms":[{"term":"Nu","meaning":"Nusselt number: dimensionless ratio of convective to conductive heat transfer across a fluid layer.","function":false},{"term":"h","meaning":"Convective heat transfer coefficient, in watts per square meter kelvin.","function":false},{"term":"L","meaning":"Characteristic length, such as plate height or layer thickness, in meters.","function":false},{"term":"k_f","meaning":"Thermal conductivity of the fluid, in watts per meter kelvin.","function":false},{"term":"Pr","meaning":"Prandtl number: dimensionless ratio of momentum diffusivity to thermal diffusivity.","function":false},{"term":"ν","meaning":"Nu, the kinematic viscosity of the fluid, in square meters per second.","function":false},{"term":"α","meaning":"Alpha, the thermal diffusivity of the fluid, in square meters per second.","function":false},{"term":"Gr","meaning":"Grashof number: dimensionless ratio of buoyancy to viscous forces.","function":false},{"term":"g","meaning":"Gravitational acceleration, about 9.81 meters per second squared.","function":false},{"term":"β","meaning":"Beta, the volumetric thermal expansion coefficient of the fluid, in inverse kelvins.","function":false},{"term":"ΔT","meaning":"Temperature difference between surface and fluid driving buoyancy, in kelvins.","function":false},{"term":"Ra","meaning":"Rayleigh number: product of Grashof and Prandtl numbers, governing onset of natural convection.","function":false},{"term":"Ra_c","meaning":"Critical Rayleigh number for convection onset between horizontal plates heated from below.","function":false}],"explanation":"Natural convection is fluid motion driven by buoyancy. The Nusselt number is the ratio of convective to conductive heat transfer, and the Prandtl number compares momentum and thermal diffusivity. The Grashof number compares buoyancy with viscous forces. Their product, the Rayleigh number, determines whether a fluid layer heated from below stays still or starts circulating. For a layer between two rigid plates, convection cells form above about 1708.","origin":"The groups are named after Wilhelm Nusselt, Ludwig Prandtl, Franz Grashof and Lord Rayleigh. Rayleigh analyzed the onset of convection in 1916, after Henri Bénard's experiments.","implementations":[{"name":"fluids.core.Rayleigh","library":"fluids","note":"Computes the Rayleigh number from Prandtl and Grashof numbers."},{"name":"fluids.core.Grashof","library":"fluids","note":"Computes the Grashof number for natural convection."},{"name":"fluids.core.Prandtl","library":"fluids","note":"Computes the Prandtl number from fluid properties."}]},"P.17":{"spoken":[{"line":0,"text":"P equals epsilon sigma A T to the fourth"},{"line":1,"text":"P sub net equals epsilon sigma A times the quantity T to the fourth minus T sub surr to the fourth"},{"line":2,"text":"lambda sub max T equals 2.898 times 10 to the negative 3 meter kelvins"}],"terms":[{"term":"P","meaning":"Radiated power emitted by the surface, in watts.","function":false},{"term":"ε","meaning":"Epsilon, the emissivity: dimensionless value from 0 to 1, with 1 a perfect blackbody.","function":false},{"term":"σ","meaning":"Sigma, the Stefan-Boltzmann constant, about 5.67 times 10 to the negative 8 watts per square meter kelvin to the fourth.","function":false},{"term":"A","meaning":"Radiating surface area of the object, in square meters.","function":false},{"term":"T","meaning":"Absolute temperature of the radiating surface, in kelvins.","function":false},{"term":"P_net","meaning":"Net radiative power exchanged with the surroundings, in watts.","function":false},{"term":"T_surr","meaning":"Absolute temperature of the surrounding environment, in kelvins.","function":false},{"term":"λ_max","meaning":"Lambda max, the wavelength of peak blackbody emission, in meters (Wien's law).","function":false},{"term":"m·K","meaning":"Meter kelvins, the units of Wien's displacement constant.","function":false}],"explanation":"The Stefan–Boltzmann law says a surface radiates power proportional to its emissivity, its area and the fourth power of its absolute temperature. Net exchange with surroundings depends on the difference of fourth powers. Temperatures must be in kelvin. Wien's displacement law gives the wavelength where emission peaks, which moves shorter as temperature rises. That is why hot objects glow red, then white.","origin":"Josef Stefan found the T⁴ law empirically in 1879 and Ludwig Boltzmann derived it in 1884. Wilhelm Wien published his displacement law in 1893.","implementations":[{"name":"scipy.constants.Stefan_Boltzmann","library":"SciPy","note":"Stefan–Boltzmann constant σ (CODATA value)."},{"name":"scipy.constants.Wien","library":"SciPy","note":"Wien wavelength displacement law constant."}]},"P.18":{"spoken":[{"line":0,"text":"P V equals n R T"},{"line":1,"text":"delta U equals Q minus W"},{"line":2,"text":"eta sub Carnot equals 1 minus T sub C over T sub H"}],"terms":[{"term":"P","meaning":"Absolute pressure of the ideal gas, in pascals.","function":false},{"term":"V","meaning":"Volume occupied by the gas, in cubic meters.","function":false},{"term":"n","meaning":"Amount of gas present in the container, measured in moles.","function":false},{"term":"R","meaning":"Universal gas constant, about 8.314 joules per mole kelvin.","function":false},{"term":"T","meaning":"Absolute temperature of the gas, measured in kelvins.","function":false},{"term":"ΔU","meaning":"Change in internal energy of the system, in joules.","function":false},{"term":"Q","meaning":"Net heat added to the system from its surroundings, in joules.","function":false},{"term":"W","meaning":"Work done by the system on its surroundings, in joules.","function":false},{"term":"η_Carnot","meaning":"Eta Carnot, the maximum possible efficiency of a heat engine between two reservoirs.","function":false},{"term":"T_C","meaning":"Absolute temperature of the cold reservoir, in kelvins.","function":false},{"term":"T_H","meaning":"Absolute temperature of the hot reservoir, in kelvins.","function":false}],"explanation":"The ideal gas law relates pressure, volume, amount of substance and absolute temperature. The first law of thermodynamics is energy conservation: the change in internal energy equals heat added minus work done by the system. The second law limits heat engines. No engine running between reservoirs at T_H and T_C can be more efficient than a Carnot engine, whose efficiency 1 − T_C/T_H depends only on the two temperatures.","origin":"Émile Clapeyron combined the gas laws into the ideal gas law in 1834. Sadi Carnot analyzed the efficiency limit in 1824, and Rudolf Clausius stated the first and second laws around 1850.","implementations":[{"name":"scipy.constants.R","library":"SciPy","note":"Molar gas constant R (CODATA value)."},{"name":"CoolProp.CoolProp.PropsSI","library":"CoolProp","note":"Thermodynamic properties of real fluids and gases."}]},"P.19":{"spoken":[{"line":0,"text":"J equals negative D d C d x"},{"line":1,"text":"the partial derivative of T with respect to t equals alpha times the second partial derivative of T with respect to x"},{"line":2,"text":"L sub diff is approximately the square root of 2 D t"}],"terms":[{"term":"J","meaning":"Diffusive flux: amount of substance crossing unit area per unit time, in moles per square meter second.","function":false},{"term":"D","meaning":"Diffusion coefficient (diffusivity), in square meters per second.","function":false},{"term":"dC/dx","meaning":"Concentration gradient: derivative of concentration with respect to position; substance flows down it.","function":true},{"term":"C","meaning":"Concentration of the diffusing substance, in moles per cubic meter.","function":false},{"term":"∂","meaning":"Partial derivative: rate of change with respect to one variable while holding the others fixed.","function":true},{"term":"T","meaning":"Temperature field as a function of position x and time t, in kelvins.","function":true},{"term":"t","meaning":"Time elapsed since diffusion or heating began, in seconds.","function":false},{"term":"α","meaning":"Alpha, the thermal diffusivity, in square meters per second.","function":false},{"term":"x","meaning":"Spatial position along the rod or medium, in meters.","function":false},{"term":"L_diff","meaning":"Diffusion length: typical distance spread in time t, in meters.","function":false},{"term":"√","meaning":"Square root: diffusion distance grows with the square root of time.","function":true}],"explanation":"Fick's first law says diffusive flux runs down the concentration gradient in proportion to diffusivity D, just as Fourier's law does for heat. Combining it with conservation gives the diffusion equation, or heat equation, in which a field's rate of change is proportional to its curvature. The characteristic spreading distance grows as √(Dt), so diffusion is fast over short distances and very slow over long ones.","origin":"Adolf Fick published his laws of diffusion in 1855, modeled on Joseph Fourier's 1822 heat equation.","implementations":[{"name":"fipy.DiffusionTerm","library":"FiPy","note":"Finite-volume diffusion term for solving heat and diffusion PDEs."}]},"P.20":{"spoken":[{"line":0,"text":"V equals I R; P equals I V equals I squared R equals V squared over R"},{"line":1,"text":"R sub series equals R sub 1 plus R sub 2"},{"line":2,"text":"1 over R sub par equals 1 over R sub 1 plus 1 over R sub 2"}],"terms":[{"term":"V","meaning":"Voltage (potential difference) across the element, in volts.","function":false},{"term":"I","meaning":"Electric current flowing through the circuit element, in amperes.","function":false},{"term":"R","meaning":"Electrical resistance of the circuit element, in ohms.","function":false},{"term":"P","meaning":"Electrical power dissipated by the element as heat, in watts.","function":false},{"term":"R_series","meaning":"Equivalent resistance of resistors connected in series, in ohms.","function":false},{"term":"R₁, R₂","meaning":"Resistances of the two individual resistors, in ohms.","function":false},{"term":"R_par","meaning":"Equivalent resistance of resistors connected in parallel, in ohms.","function":false}],"explanation":"Ohm's law states that the current through a resistor is proportional to the voltage across it, V = IR. Electrical power is P = IV, and substituting Ohm's law gives the I²R and V²/R forms. Resistances in series add because the same current flows through each. In parallel the reciprocals add because each branch shares the same voltage, so the combined resistance is less than the smallest branch.","origin":"Georg Ohm published his law in 1827.","implementations":[{"name":"ngspice","library":"ngspice","note":"Open-source SPICE circuit simulator for DC, AC and transient analysis."}]},"SY.1":{"spoken":[{"line":2,"text":"V equals I R, unit ohms."}],"terms":[{"term":"V","meaning":"Voltage across the resistor, measured in volts (V).","function":false},{"term":"I","meaning":"Current flowing through the resistor, measured in amperes (A).","function":false},{"term":"R","meaning":"Resistance of the resistor, the opposition to current flow, measured in ohms.","function":false},{"term":"Ω","meaning":"Ohm, the SI unit of resistance; one ohm passes one ampere when one volt is applied.","function":false}],"explanation":"A resistor opposes current flow, converting electrical energy into heat. Ohm's law V = IR links the voltage across it to the current through it, with resistance measured in ohms (Ω). Resistors set currents, divide voltages, bias transistors and limit current into parts such as LEDs. The schematic symbol is a zigzag line (US) or a plain rectangle (IEC).","origin":"Georg Ohm published the proportionality between voltage and current in 1827.","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Models resistors with the R element in netlists."}]},"SY.3":{"spoken":[{"line":2,"text":"Q equals C V, and i equals C d v d t."}],"terms":[{"term":"Q","meaning":"Electric charge stored on the capacitor plates, measured in coulombs (C).","function":false},{"term":"C","meaning":"Capacitance, the charge stored per volt across the plates, measured in farads (F).","function":false},{"term":"V","meaning":"Steady voltage across the capacitor, measured in volts.","function":false},{"term":"i","meaning":"Instantaneous current into the capacitor, measured in amperes; it flows only when the voltage changes.","function":false},{"term":"v","meaning":"Instantaneous, time-varying voltage across the capacitor, measured in volts.","function":false},{"term":"dv/dt","meaning":"Derivative of capacitor voltage with respect to time: takes v(t) and returns how fast it changes, in volts per second; current is C times this rate.","function":true}],"explanation":"A capacitor is two conductors separated by an insulator; it stores charge Q = CV and energy in its electric field. Because current is i = C dv/dt, a capacitor passes changing signals but blocks steady DC, and its voltage cannot jump instantly. It is used for filtering, decoupling power rails, timing and coupling AC signals between stages.","origin":"The Leyden jar, the first capacitor, was invented independently by Ewald von Kleist and Pieter van Musschenbroek in 1745-46.","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Models capacitors with the C element in netlists."}]},"SY.4":{"spoken":[{"line":2,"text":"Curved plate equals negative; observe polarity."}],"terms":[{"term":"=","meaning":"Used here to mean 'indicates': the curved plate in the symbol marks the capacitor's negative terminal.","function":false}],"explanation":"A polarized capacitor, usually aluminium electrolytic or tantalum, packs large capacitance into a small case but works only with one polarity. The symbol marks the negative side with a curved plate (and often a + on the straight one). Reverse voltage damages the oxide dielectric and can make the part overheat or burst, so orientation on the board must match the schematic.","origin":"Charles Pollak patented the aluminium electrolytic capacitor in the 1890s.","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Models it as an ideal C; polarity limits are not enforced."}]},"SY.5":{"spoken":[{"line":2,"text":"v equals L d i d t, and E equals one half L I squared."}],"terms":[{"term":"v","meaning":"Instantaneous voltage across the inductor, measured in volts.","function":false},{"term":"L","meaning":"Inductance, the voltage induced per unit rate of change of current, measured in henries (H).","function":false},{"term":"di/dt","meaning":"Derivative of inductor current with respect to time: takes i(t) and returns its rate of change in amperes per second; the voltage is L times this.","function":true},{"term":"i","meaning":"Instantaneous current through the inductor, measured in amperes.","function":false},{"term":"E","meaning":"Energy stored in the inductor's magnetic field, measured in joules (J).","function":false},{"term":"I","meaning":"Current through the inductor, in amperes, used to compute the stored energy.","function":false}],"explanation":"An inductor is a coil of wire that stores energy in its magnetic field, E = ½LI². Its voltage is v = L di/dt, so it opposes sudden changes in current and its current cannot jump instantly. Inductors appear in filters, switching power supplies, chokes and tuned circuits. The symbol is a series of loops or bumps representing the coil turns.","origin":"Michael Faraday and Joseph Henry independently discovered electromagnetic induction around 1831.","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Models inductors with the L element in netlists."}]},"SY.6":{"spoken":[{"line":2,"text":"V sub s over V sub p equals N sub s over N sub p."}],"terms":[{"term":"V_s","meaning":"Secondary (output) winding voltage of the transformer, measured in volts.","function":false},{"term":"V_p","meaning":"Primary (input) winding voltage of the transformer, measured in volts.","function":false},{"term":"N_s","meaning":"Number of wire turns on the secondary winding; a dimensionless count.","function":false},{"term":"N_p","meaning":"Number of wire turns on the primary winding; a dimensionless count.","function":false}],"explanation":"A transformer couples two coils through a shared magnetic core so a changing current in the primary induces a voltage in the secondary. In the ideal case the voltage ratio equals the turns ratio, Vs/Vp = Ns/Np, while current scales inversely so power is conserved. Transformers step voltages up or down, isolate circuits and match impedances; they work only with AC.","origin":"Faraday demonstrated induction with an iron ring and two coils in 1831; practical power transformers appeared in the mid-1880s.","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Models transformers as coupled inductors using the K element."}]},"SY.8":{"spoken":[{"line":2,"text":"Open equals no current, closed equals short."}],"terms":[{"term":"=","meaning":"Used here to mean 'behaves as': an open switch passes no current, and a closed switch acts as a short circuit of zero resistance.","function":false}],"explanation":"A single-pole single-throw switch has one input and one output contact and simply makes or breaks a circuit. Open, it is ideally an infinite resistance with no current; closed, it is ideally a short circuit with zero voltage across it. The symbol shows a hinged line that either touches or lifts away from a contact, as in a basic on/off light switch.","origin":"","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Models switches with voltage- or current-controlled switch elements (S, W)."}]},"SY.9":{"spoken":[{"line":2,"text":"A resistive load: P equals V squared over R."}],"terms":[{"term":"P","meaning":"Power dissipated by the lamp as light and heat, measured in watts (W).","function":false},{"term":"V","meaning":"Voltage applied across the lamp's terminals, measured in volts.","function":false},{"term":"R","meaning":"Resistance of the lamp filament treated as a resistive load, measured in ohms.","function":false}],"explanation":"A lamp symbol (a circle with a cross or filament loop) represents an incandescent bulb, which behaves roughly as a resistive load. Its power is P = V²/R, so for a fixed supply a lower filament resistance draws more power and glows brighter. In practice the filament's resistance rises sharply as it heats, so the cold bulb draws a large inrush current.","origin":"Joseph Swan and Thomas Edison developed practical incandescent lamps around 1878-1880.","implementations":[]},"SY.10":{"spoken":[{"line":2,"text":"Long plate equals plus, short plate equals minus."}],"terms":[{"term":"+","meaning":"Positive terminal of the battery, the higher-potential side, drawn as the long plate in the symbol.","function":false},{"term":"−","meaning":"Negative terminal of the battery, the lower-potential side, drawn as the short plate in the symbol.","function":false}],"explanation":"A battery converts chemical energy into a DC voltage. Its symbol stacks pairs of plates: the long plate is the positive terminal and the short plate the negative; several pairs indicate a multi-cell battery. In circuit analysis it is often treated as an ideal voltage source, sometimes with a small series internal resistance that makes the terminal voltage sag under load.","origin":"Alessandro Volta built the first battery, the voltaic pile, in 1800.","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Models a battery as a DC voltage source (V element)."}]},"SY.11":{"spoken":[{"line":2,"text":"V equals constant."}],"terms":[{"term":"V","meaning":"Output voltage of the DC source, measured in volts; it stays fixed regardless of time or load current.","function":false}],"explanation":"An ideal independent DC voltage source holds a fixed voltage across its terminals no matter how much current the circuit draws. It is drawn as a circle with + and − marks (or a battery symbol). Real supplies approximate it within their current limits; adding a series resistance gives a more realistic model, which is exactly the Thévenin form.","origin":"","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Defines DC sources with the V element."}]},"SY.12":{"spoken":[{"line":2,"text":"v of t equals V sub m times sine of the quantity omega t plus phi."}],"terms":[{"term":"v(t)","meaning":"Instantaneous voltage of the AC source at time t, measured in volts.","function":true},{"term":"t","meaning":"Time at which the instantaneous source voltage is evaluated, measured in seconds.","function":false},{"term":"V_m","meaning":"Peak (maximum) amplitude of the sinusoidal voltage, measured in volts.","function":false},{"term":"sin","meaning":"Sine function: takes the phase angle in radians and returns a value between −1 and 1, giving the waveform its sinusoidal shape.","function":true},{"term":"ω","meaning":"Angular frequency of the source, equal to 2 pi f, measured in radians per second.","function":false},{"term":"ϕ","meaning":"Phase angle, the waveform's offset at t equals zero, measured in radians or degrees.","function":false}],"explanation":"An AC voltage source produces a sinusoid v(t) = Vm sin(ωt + φ), where Vm is the peak amplitude, ω = 2πf the angular frequency and φ the phase shift. It is drawn as a circle containing a sine wave. It models mains power, signal generators and test tones, and is the starting point for phasor analysis of circuits.","origin":"","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Defines sinusoidal sources with SIN() on a V element."},{"name":"numpy.sin","library":"NumPy","note":"Generates sampled sinusoid values."}]},"SY.13":{"spoken":[{"line":2,"text":"I equals constant, arrow gives direction."}],"terms":[{"term":"I","meaning":"Current delivered by the ideal current source, measured in amperes; fixed regardless of the voltage across it.","function":false}],"explanation":"An ideal independent current source forces a fixed current through its branch regardless of the voltage needed. The circle symbol contains an arrow showing the direction of current. It is the dual of a voltage source and appears in Norton equivalents, transistor models and bias circuits; real versions are built with transistors or op-amps over a limited voltage range.","origin":"","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Defines current sources with the I element."}]},"SY.14":{"spoken":[{"line":1,"text":"Reference node equals zero volts."}],"terms":[{"term":"V","meaning":"Volt, the SI unit of electric potential; ground is defined as the zero-volt reference for all node voltages.","function":false}],"explanation":"Ground is the reference node that all other node voltages are measured against, defined as 0 V. It can be a physical earth connection or simply a common return path, such as a chassis or the negative rail. Its symbol, stacked horizontal lines of decreasing length, lets schematics connect many points to the same node without drawing wires.","origin":"","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Requires node 0 as the ground reference in every netlist."}]},"SY.15":{"spoken":[{"line":2,"text":"Connect in parallel; R sub in approaches infinity."}],"terms":[{"term":"R_in","meaning":"Input resistance of the voltmeter, in ohms; ideally infinite so the meter draws no current from the circuit.","function":false},{"term":"→","meaning":"Approaches or tends toward; describes the limiting ideal value of the meter's input resistance.","function":false},{"term":"∞","meaning":"Infinity; an ideal voltmeter has unboundedly large input resistance, acting as an open circuit.","function":false}],"explanation":"A voltmeter measures the potential difference between two points, so it is connected in parallel with the part being measured. To avoid disturbing the circuit it should draw almost no current, which means an ideally infinite input resistance; real digital meters are typically around 10 MΩ. The symbol is a circle containing the letter V.","origin":"","implementations":[]},"SY.16":{"spoken":[{"line":2,"text":"Connect in series; R sub in approaches zero."}],"terms":[{"term":"R_in","meaning":"Input resistance of the ammeter, in ohms; ideally zero so the meter adds no voltage drop to the circuit.","function":false},{"term":"→","meaning":"Approaches or tends toward; describes the limiting ideal value of the meter's input resistance.","function":false}],"explanation":"An ammeter measures the current flowing through a branch, so the circuit must be broken and the meter inserted in series. To avoid adding a voltage drop it should have nearly zero internal resistance. Connecting an ammeter in parallel across a source effectively shorts it, a common way to blow a meter fuse. The symbol is a circle with the letter A.","origin":"","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Measures branch current via a 0 V voltage source in series."}]},"SY.17":{"spoken":[{"line":1,"text":"Dot equals wires connected, a node."},{"line":2,"text":"No dot equals wires cross, not connected."}],"terms":[{"term":"=","meaning":"Used here to mean 'indicates': a junction dot marks an electrical connection, while its absence means the wires merely cross.","function":false}],"explanation":"Schematics distinguish connected wires from wires that merely cross. A dot where lines meet marks a junction, meaning the wires form one electrical node. Lines that cross without a dot are not connected; some older drawings show this with a small hop or arc. Good practice avoids four-way junctions and uses T-junctions with dots to remove ambiguity.","origin":"","implementations":[]},"SY.18":{"spoken":[{"line":2,"text":"Anode to cathode, the bar; approximately 0.7 volt drop."}],"terms":[{"term":"→","meaning":"Direction of conventional forward current through the diode, from the anode into the cathode (the bar).","function":false},{"term":"≈","meaning":"Approximately equal to; the forward voltage of a silicon diode is roughly, not exactly, 0.7 volts.","function":false},{"term":"V","meaning":"Volt, the unit of the diode's forward voltage drop when it conducts.","function":false}],"explanation":"A diode lets current flow easily from anode to cathode but blocks it in reverse, like a one-way valve. The symbol's triangle points in the direction of conventional current and the bar marks the cathode. A silicon diode needs roughly 0.7 V forward bias before conducting significantly. Diodes are used for rectification, reverse-polarity protection and clamping voltages.","origin":"Karl Ferdinand Braun discovered rectification in 1874; John Ambrose Fleming invented the vacuum-tube diode in 1904.","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Models diodes with the D element and a .model card."}]},"SY.19":{"spoken":[{"line":2,"text":"Needs a series resistor: R equals the quantity V sub s minus V sub f, all over I."}],"terms":[{"term":"R","meaning":"Series current-limiting resistance placed with the LED, measured in ohms.","function":false},{"term":"V_s","meaning":"Supply voltage feeding the LED and resistor, measured in volts.","function":false},{"term":"V_f","meaning":"Forward voltage drop of the LED when lit, typically about 1.8 to 3.3 volts depending on color.","function":false},{"term":"I","meaning":"Desired forward current through the LED, measured in amperes (often 10 to 20 milliamps).","function":false}],"explanation":"A light-emitting diode emits light when forward biased, with a forward voltage Vf of roughly 1.8 to 3.3 V depending on colour. Because its current rises steeply with voltage, it needs a series resistor R = (Vs − Vf)/I to set a safe current, typically a few to 20 mA. The symbol is a diode with outward arrows representing emitted light.","origin":"Nick Holonyak Jr. demonstrated the first visible-light LED in 1962.","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Models LEDs as diodes with fitted .model parameters."}]},"SY.21":{"spoken":[{"line":2,"text":"I sub C is approximately beta I sub B; emitter arrow points out."}],"terms":[{"term":"I_C","meaning":"Collector current of the NPN transistor, measured in amperes.","function":false},{"term":"β","meaning":"Current gain of the BJT (also called h_FE), the dimensionless ratio of collector current to base current, typically 50 to 300.","function":false},{"term":"I_B","meaning":"Base current driving the NPN transistor, measured in amperes.","function":false}],"explanation":"An NPN bipolar junction transistor uses a small base current to control a much larger collector current, IC ≈ βIB, where β is typically 50 to 300. The emitter arrow points outward, showing conventional current leaving the emitter (PNP arrows point in). Biased in its active region it amplifies; driven fully on or off it acts as a switch.","origin":"John Bardeen and Walter Brattain built the first transistor at Bell Labs in 1947; William Shockley invented the junction transistor in 1948.","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Models BJTs with the Q element (Gummel-Poon model)."}]},"SY.23":{"spoken":[{"line":2,"text":"V sub out equals A times the quantity V sub plus minus V sub minus; ideal: V sub plus equals V sub minus."}],"terms":[{"term":"V_out","meaning":"Output voltage of the op-amp, measured in volts.","function":false},{"term":"A","meaning":"Open-loop voltage gain of the op-amp, dimensionless and very large (often 100,000 or more).","function":false},{"term":"V_+","meaning":"Voltage at the non-inverting (plus) input terminal, measured in volts.","function":false},{"term":"V_−","meaning":"Voltage at the inverting (minus) input terminal, measured in volts.","function":false}],"explanation":"An operational amplifier is a high-gain differential amplifier: Vout = A(V+ − V−), with open-loop gain A often above 100,000. Its triangle symbol has inverting (−) and non-inverting (+) inputs. With negative feedback the output drives the inputs to nearly equal voltages, so the ideal model assumes V+ = V− and no input current, which makes amplifier gain set by resistors.","origin":"John Ragazzini and colleagues coined the term operational amplifier in 1947; Fairchild's µA741 (1968) became the classic integrated op-amp.","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Simulates op-amps using vendor subcircuit models."}]},"SY.24":{"spoken":[{"line":1,"text":"Y equals A and B."}],"terms":[{"term":"Y","meaning":"Output of the AND gate, a binary logic value of 0 or 1.","function":false},{"term":"A","meaning":"First binary input to the gate, logic 0 or 1.","function":false},{"term":"·","meaning":"Boolean AND operator: takes two bits and returns 1 only when both inputs are 1.","function":true},{"term":"B","meaning":"Second binary input to the gate, logic 0 or 1.","function":false}],"explanation":"An AND gate outputs 1 only when all of its inputs are 1, implementing Boolean multiplication Y = A·B. Its symbol has a flat back and a semicircular front. AND gates are used to enable signals, mask bits and combine conditions that must all be true. Chips such as the 7408 provide four two-input AND gates.","origin":"George Boole developed the underlying algebra in 1847-1854; Claude Shannon applied it to switching circuits in 1937.","implementations":[{"name":"numpy.logical_and","library":"NumPy","note":"Element-wise logical AND of arrays."},{"name":"operator.and_","library":"Python standard library","note":"Bitwise AND, equivalent to a & b."}]},"SY.25":{"spoken":[{"line":1,"text":"Y equals A or B."}],"terms":[{"term":"Y","meaning":"Output of the OR gate, a binary logic value of 0 or 1.","function":false},{"term":"A","meaning":"First binary input to the gate, logic 0 or 1.","function":false},{"term":"+","meaning":"Boolean OR operator (not addition): takes two bits and returns 1 when at least one input is 1.","function":true},{"term":"B","meaning":"Second binary input to the gate, logic 0 or 1.","function":false}],"explanation":"An OR gate outputs 1 when at least one input is 1, implementing Boolean addition Y = A + B (here 1 + 1 = 1). Its symbol has a curved back and a pointed front. OR gates combine alternative conditions, such as multiple alarm triggers. The 7432 chip contains four two-input OR gates.","origin":"George Boole developed the underlying algebra in 1847-1854; Claude Shannon applied it to switching circuits in 1937.","implementations":[{"name":"numpy.logical_or","library":"NumPy","note":"Element-wise logical OR of arrays."},{"name":"operator.or_","library":"Python standard library","note":"Bitwise OR, equivalent to a | b."}]},"SY.26":{"spoken":[{"line":1,"text":"Y equals A bar, that is, not A."}],"terms":[{"term":"Y","meaning":"Output of the inverter, a binary logic value of 0 or 1.","function":false},{"term":"A","meaning":"Single binary input to the inverter, logic 0 or 1.","function":false},{"term":"A̅","meaning":"Boolean NOT (complement) of A, shown by the overbar: takes one bit and returns its opposite, 0 becomes 1 and 1 becomes 0.","function":true}],"explanation":"A NOT gate, or inverter, has one input and outputs its complement, Y = Ā: a 1 becomes 0 and a 0 becomes 1. The symbol is a triangle with a small bubble at the output; that bubble means inversion wherever it appears on other gates. Inverters fix signal polarity, buffer signals and form oscillators when chained in a ring.","origin":"","implementations":[{"name":"numpy.logical_not","library":"NumPy","note":"Element-wise logical NOT of an array."},{"name":"operator.not_","library":"Python standard library","note":"Logical negation of a value."}]},"SY.27":{"spoken":[{"line":1,"text":"Y equals the quantity A and B, bar; that is, not the quantity A and B."}],"terms":[{"term":"Y","meaning":"Output of the NAND gate, a binary logic value of 0 or 1.","function":false},{"term":"A","meaning":"First binary input to the gate, logic 0 or 1.","function":false},{"term":"·","meaning":"Boolean AND operator: returns 1 only when both inputs are 1.","function":true},{"term":"B","meaning":"Second binary input to the gate, logic 0 or 1.","function":false},{"term":"overbar","meaning":"Bar over the whole expression A·B, meaning NOT: it inverts the AND result, so the output is 0 only when both inputs are 1.","function":true}],"explanation":"A NAND gate is an AND followed by NOT, Y = (A·B)̅, so it outputs 0 only when all inputs are 1. It is functionally complete: NOT, AND, OR and every other Boolean function can be built from NAND gates alone. That universality and its simple transistor implementation make it the workhorse of CMOS logic and flash memory. The 7400 chip holds four.","origin":"Henry Sheffer proved in 1913 that a single operator (the Sheffer stroke, NAND) suffices for all of Boolean logic; Charles Peirce had noted this earlier.","implementations":[]},"SY.28":{"spoken":[{"line":1,"text":"Y equals A x-or B."}],"terms":[{"term":"Y","meaning":"Output of the XOR gate, a binary logic value of 0 or 1.","function":false},{"term":"A","meaning":"First binary input to the gate, logic 0 or 1.","function":false},{"term":"⊕","meaning":"Exclusive-OR operator: takes two bits and returns 1 when exactly one input is 1, and 0 when the inputs match.","function":true},{"term":"B","meaning":"Second binary input to the gate, logic 0 or 1.","function":false}],"explanation":"An XOR (exclusive OR) gate outputs 1 when its inputs differ and 0 when they match, Y = A ⊕ B. Equivalently it is addition modulo 2, which makes it the sum bit of a half adder. XOR is also used for parity checks, comparators, controllable inverters and in cryptography and checksums. Its symbol is an OR gate with an extra curved line behind it.","origin":"","implementations":[{"name":"numpy.logical_xor","library":"NumPy","note":"Element-wise logical XOR of arrays."},{"name":"operator.xor","library":"Python standard library","note":"Bitwise XOR, equivalent to a ^ b."}]},"EE.1":{"spoken":[{"line":0,"text":"I equals d Q d t; V equals W over Q."},{"line":1,"text":"P equals V I; E equals P t."},{"line":2,"text":"1 kilowatt-hour equals 3.6 times 10 to the sixth joules."}],"terms":[{"term":"I","meaning":"Electric current, the rate at which charge flows past a point, measured in amperes (coulombs per second).","function":false},{"term":"dQ/dt","meaning":"Time derivative of charge: takes Q(t) and returns how fast charge moves, in coulombs per second, which defines current.","function":true},{"term":"Q","meaning":"Electric charge being moved or counted, measured in coulombs (C).","function":false},{"term":"t","meaning":"Time, measured in seconds (or hours when computing energy in kilowatt-hours).","function":false},{"term":"V","meaning":"Voltage, the energy per unit charge between two points, measured in volts (joules per coulomb).","function":false},{"term":"W","meaning":"Work or energy needed to move the charge, measured in joules.","function":false},{"term":"P","meaning":"Power, the rate of energy transfer, measured in watts (joules per second).","function":false},{"term":"E","meaning":"Energy delivered or consumed over a time interval, measured in joules or kilowatt-hours.","function":false},{"term":"kWh","meaning":"Kilowatt-hour, a unit of energy equal to 1,000 watts sustained for one hour; used on utility bills.","function":false},{"term":"J","meaning":"Joule, the SI unit of energy; one kilowatt-hour is 3.6 million joules.","function":false}],"explanation":"Current is the rate of charge flow, I = dQ/dt, and voltage is energy per unit charge, V = W/Q. Multiplying them gives power, P = VI, the rate of energy transfer, and energy accumulates as E = Pt for constant power. Utilities bill in kilowatt-hours, where 1 kWh equals 3.6 million joules. The water analogy maps voltage to pressure and current to flow.","origin":"The units honor Alessandro Volta, André-Marie Ampère, James Watt and James Prescott Joule.","implementations":[{"name":"pint","library":"Pint (Python)","note":"Unit-aware quantities with conversions like kWh to joules."},{"name":"scipy.constants","library":"SciPy","note":"Physical constants and unit conversion factors."}]},"EE.2":{"spoken":[{"line":0,"text":"KCL: the sum of I sub in equals the sum of I sub out."},{"line":1,"text":"KVL: the sum around a loop of V equals zero."}],"terms":[{"term":"KCL","meaning":"Kirchhoff's Current Law: charge is conserved at a node, so currents entering equal currents leaving.","function":false},{"term":"Σ","meaning":"Summation operator: takes a set of terms (currents or voltages) and returns their total; here it adds all branch currents or loop voltages.","function":true},{"term":"I_in","meaning":"Each current flowing into a node, measured in amperes.","function":false},{"term":"I_out","meaning":"Each current flowing out of a node, measured in amperes.","function":false},{"term":"KVL","meaning":"Kirchhoff's Voltage Law: energy is conserved, so voltage rises and drops around any closed loop total zero.","function":false},{"term":"Σ_loop","meaning":"Summation taken over every element around one closed loop, adding signed voltage rises and drops.","function":true},{"term":"V","meaning":"Voltage across each element in the loop, measured in volts, with sign set by direction of travel.","function":false}],"explanation":"Kirchhoff's current law says the currents entering any node sum to the currents leaving it, because charge is conserved. His voltage law says the voltage rises and drops around any closed loop sum to zero, because energy is conserved. Together with component laws such as Ohm's law, they yield enough equations to solve any lumped circuit.","origin":"Gustav Kirchhoff stated the circuit laws in 1845.","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Solves circuits by enforcing KCL/KVL via modified nodal analysis."}]},"EE.3":{"spoken":[{"line":0,"text":"V sub out equals V sub in times R sub 2 over the quantity R sub 1 plus R sub 2."},{"line":1,"text":"I sub 1 equals I times R sub 2 over the quantity R sub 1 plus R sub 2."}],"terms":[{"term":"V_out","meaning":"Output voltage of the divider, taken across R_2, measured in volts.","function":false},{"term":"V_in","meaning":"Input voltage applied across the series pair R_1 and R_2, measured in volts.","function":false},{"term":"R_2","meaning":"Second resistor, in ohms; across which the output voltage is taken, or the opposite branch in the current divider.","function":false},{"term":"R_1","meaning":"First resistor, in ohms; in the series divider it is the top resistor, in the current divider it is branch 1.","function":false},{"term":"I_1","meaning":"Current through branch resistor R_1 in a two-resistor parallel current divider, measured in amperes.","function":false},{"term":"I","meaning":"Total current entering the parallel pair of resistors, measured in amperes.","function":false}],"explanation":"A voltage divider of two series resistors gives Vout = Vin·R2/(R1 + R2), the fraction of the input across R2. A current divider of two parallel resistors splits current inversely: I1 = I·R2/(R1 + R2), so the opposite resistor appears on top. Dividers set reference voltages, scale signals into ADC ranges and bias transistors, assuming the load draws little current.","origin":"","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Verifies divider outputs including loading effects."}]},"EE.4":{"spoken":[{"line":0,"text":"V sub th equals V sub open; R sub th equals V sub o c over I sub s c."},{"line":1,"text":"I sub N equals V sub th over R sub th."},{"line":2,"text":"R sub L equals R sub th implies P sub max equals V sub th squared over 4 R sub th."}],"terms":[{"term":"V_th","meaning":"Thévenin equivalent voltage, the open-circuit voltage seen at the output terminals, measured in volts.","function":false},{"term":"V_open","meaning":"Voltage measured across the terminals with no load connected (open circuit), in volts.","function":false},{"term":"R_th","meaning":"Thévenin equivalent resistance seen looking into the terminals with sources zeroed, in ohms.","function":false},{"term":"V_oc","meaning":"Open-circuit voltage at the terminals, in volts; the same as V_th.","function":false},{"term":"I_sc","meaning":"Short-circuit current that flows when the terminals are shorted together, in amperes.","function":false},{"term":"I_N","meaning":"Norton equivalent current source value, equal to the short-circuit current, in amperes.","function":false},{"term":"R_L","meaning":"Load resistance connected to the terminals, in ohms.","function":false},{"term":"⇒","meaning":"Implies: when the load matches the Thévenin resistance, the maximum power result follows.","function":false},{"term":"P_max","meaning":"Maximum power deliverable to the load, achieved when R_L equals R_th, measured in watts.","function":false}],"explanation":"Thévenin's theorem replaces any linear two-terminal network with one voltage source Vth in series with Rth; Norton's uses a current source IN = Vth/Rth in parallel with the same resistance. Vth is the open-circuit voltage and Rth = Voc/Isc. A load receives maximum power when RL = Rth, delivering Pmax = Vth²/(4Rth) at only 50% efficiency.","origin":"Léon Charles Thévenin published his theorem in 1883 (anticipated by Hermann von Helmholtz in 1853); Edward Norton described the current-source form in 1926.","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Finds Voc and Isc to extract Thévenin parameters."}]},"EE.5":{"spoken":[{"line":0,"text":"KCL at each node, gives G times bold v equals bold i."},{"line":1,"text":"KVL around each mesh, gives R times bold i equals bold v."}],"terms":[{"term":"KCL","meaning":"Kirchhoff's Current Law, applied at every non-reference node to write one current-balance equation per node.","function":false},{"term":"→","meaning":"Leads to; writing the node or mesh equations produces the matrix system that follows.","function":false},{"term":"G","meaning":"Conductance matrix of the circuit, built from branch conductances in siemens; multiplies node voltages to give injected currents.","function":false},{"term":"𝐯","meaning":"In nodal analysis, the vector of unknown node voltages; in mesh analysis, the vector of source voltages around each mesh, in volts.","function":false},{"term":"𝐢","meaning":"In nodal analysis, the vector of source currents injected into nodes; in mesh analysis, the vector of unknown mesh currents, in amperes.","function":false},{"term":"KVL","meaning":"Kirchhoff's Voltage Law, applied around every mesh to write one voltage-balance equation per loop.","function":false},{"term":"R","meaning":"Resistance matrix of the circuit, built from mesh resistances in ohms; multiplies mesh currents to give mesh voltages.","function":false}],"explanation":"Nodal analysis writes KCL at each non-reference node with unknown node voltages, giving a linear system G v = i where G is the conductance matrix. Mesh analysis writes KVL around each independent loop with unknown mesh currents, giving R i = v. Both turn a circuit into simultaneous linear equations solvable by matrix methods; nodal analysis underlies circuit simulators.","origin":"","implementations":[{"name":"numpy.linalg.solve","library":"NumPy","note":"Solves the linear system G v = i."},{"name":"scipy.linalg.solve","library":"SciPy","note":"Solves dense linear systems."},{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Uses modified nodal analysis internally."}]},"EE.6":{"spoken":[{"line":0,"text":"Q equals C V; i equals C d v d t; v equals L d i d t."},{"line":1,"text":"E sub C equals one half C V squared; E sub L equals one half L I squared."},{"line":2,"text":"C sub par equals C sub 1 plus C sub 2; 1 over C sub ser equals 1 over C sub 1 plus 1 over C sub 2."}],"terms":[{"term":"Q","meaning":"Charge stored on the capacitor, measured in coulombs.","function":false},{"term":"C","meaning":"Capacitance, charge stored per volt, measured in farads.","function":false},{"term":"V","meaning":"Voltage across the capacitor's terminals, measured in volts (V).","function":false},{"term":"i","meaning":"Instantaneous current through the capacitor or inductor, measured in amperes.","function":false},{"term":"dv/dt","meaning":"Time derivative of capacitor voltage: takes v(t) and returns its rate of change in volts per second; capacitor current equals C times it.","function":true},{"term":"v","meaning":"Instantaneous voltage across the capacitor or inductor, measured in volts.","function":false},{"term":"L","meaning":"Inductance, measured in henries; relates inductor voltage to the rate of change of current.","function":false},{"term":"di/dt","meaning":"Time derivative of inductor current: takes i(t) and returns its rate of change in amperes per second; inductor voltage equals L times it.","function":true},{"term":"E_C","meaning":"Energy stored in the capacitor's electric field, measured in joules.","function":false},{"term":"E_L","meaning":"Energy stored in the inductor's magnetic field, measured in joules.","function":false},{"term":"I","meaning":"Current through the inductor, in amperes, used for its stored energy.","function":false},{"term":"C_par","meaning":"Total equivalent capacitance of capacitors connected in parallel, in farads; capacitances simply add.","function":false},{"term":"C_1","meaning":"Capacitance of the first capacitor in the combination, in farads.","function":false},{"term":"C_2","meaning":"Capacitance of the second capacitor in the combination, in farads.","function":false},{"term":"C_ser","meaning":"Total equivalent capacitance of capacitors in series, in farads; its reciprocal is the sum of reciprocals.","function":false}],"explanation":"Capacitors store charge Q = CV with current i = C dv/dt; inductors produce v = L di/dt. Their stored energies are ½CV² in the electric field and ½LI² in the magnetic field. Capacitors add directly in parallel and reciprocally in series, the opposite of resistors. A capacitor resists sudden voltage changes; an inductor resists sudden current changes.","origin":"","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Simulates C and L elements in transient and AC analyses."}]},"EE.7":{"spoken":[{"line":0,"text":"v sub C of t equals V sub s times the quantity 1 minus e to the negative t over tau, where tau equals R C."},{"line":1,"text":"i sub L of t equals V sub s over R, times the quantity 1 minus e to the negative t over tau, where tau equals L over R."},{"line":2,"text":"5 tau is approximately fully settled."}],"terms":[{"term":"v_C(t)","meaning":"Capacitor voltage as a function of time during charging, in volts, rising from zero toward V_s.","function":true},{"term":"t","meaning":"Time elapsed since the source was switched on, measured in seconds.","function":false},{"term":"V_s","meaning":"Step source voltage applied to the circuit, measured in volts.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, the base of natural exponential growth and decay.","function":false},{"term":"e^(−t/τ)","meaning":"Decaying exponential: takes elapsed time over the time constant and returns the fraction of the transient remaining, falling from 1 toward 0.","function":true},{"term":"τ","meaning":"Time constant of the circuit, in seconds; the time to reach about 63 percent of the final value.","function":false},{"term":"R","meaning":"Resistance in the RC or RL circuit, measured in ohms.","function":false},{"term":"C","meaning":"Capacitance in the RC circuit, measured in farads.","function":false},{"term":"i_L(t)","meaning":"Inductor current as a function of time after the step, in amperes, rising from zero toward V_s over R.","function":true},{"term":"L","meaning":"Inductance in the RL circuit, measured in henries.","function":false}],"explanation":"When a step is applied, a capacitor charging through a resistor follows vC(t) = Vs(1 − e^(−t/τ)) with time constant τ = RC; an RL circuit's current rises as (Vs/R)(1 − e^(−t/τ)) with τ = L/R. After one τ the response is 63% complete, and after five it is above 99%, so 5τ is treated as fully settled.","origin":"","implementations":[{"name":"scipy.signal.step","library":"SciPy","note":"Step response of a continuous-time linear system."},{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Transient (.tran) analysis of RC and RL circuits."}]},"EE.8":{"spoken":[{"line":0,"text":"v of t equals V sub m times sine of the quantity omega t plus phi."},{"line":1,"text":"Omega equals 2 pi f; T equals 1 over f."},{"line":2,"text":"V sub r m s equals V sub m over the square root of 2."}],"terms":[{"term":"v(t)","meaning":"Instantaneous AC voltage at time t, measured in volts.","function":true},{"term":"t","meaning":"Time at which the instantaneous AC voltage is evaluated, measured in seconds.","function":false},{"term":"V_m","meaning":"Peak amplitude of the sinusoidal voltage, measured in volts.","function":false},{"term":"sin","meaning":"Sine function: takes the phase angle in radians and returns a value from −1 to 1, shaping the AC waveform.","function":true},{"term":"ω","meaning":"Angular frequency, measured in radians per second; equals 2 pi times f.","function":false},{"term":"ϕ","meaning":"Phase shift of the waveform at t equals zero, in radians or degrees.","function":false},{"term":"π","meaning":"Pi, about 3.14159; 2 pi radians make one full cycle.","function":false},{"term":"f","meaning":"Frequency, the number of cycles per second, measured in hertz (Hz).","function":false},{"term":"T","meaning":"Period, the duration of one full cycle, measured in seconds.","function":false},{"term":"V_rms","meaning":"Root-mean-square voltage, the equivalent DC value delivering the same power, in volts; about 0.707 times the peak.","function":false},{"term":"√","meaning":"Square root: takes a non-negative number and returns the value that squared gives it; here root 2 converts peak to RMS for a sine.","function":true}],"explanation":"A sinusoidal signal v(t) = Vm sin(ωt + φ) is described by peak amplitude Vm, angular frequency ω = 2πf, period T = 1/f and phase φ. The RMS value is the square root of the mean of the squared signal, the DC level that would deliver the same power to a resistor. For a sine wave Vrms = Vm/√2, so 120 V mains peaks near 170 V.","origin":"","implementations":[{"name":"numpy.sqrt","library":"NumPy","note":"Combined with numpy.mean of squares to compute RMS."},{"name":"scipy.signal.sawtooth","library":"SciPy","note":"Generates non-sinusoidal periodic test waveforms."}]},"EE.9":{"spoken":[{"line":0,"text":"Z sub R equals R; Z sub L equals j omega L; Z sub C equals 1 over j omega C."},{"line":1,"text":"V tilde equals I tilde Z; the magnitude of Z equals the square root of the quantity R squared plus X squared."},{"line":2,"text":"Theta equals the inverse tangent of X over R."}],"terms":[{"term":"Z_R","meaning":"Impedance of a resistor, purely real and equal to its resistance, in ohms.","function":false},{"term":"R","meaning":"Resistance, the real part of impedance, measured in ohms.","function":false},{"term":"Z_L","meaning":"Impedance of an inductor, j omega L, purely imaginary and positive, in ohms.","function":false},{"term":"j","meaning":"Imaginary unit, the square root of −1; engineers use j instead of i to avoid confusion with current.","function":false},{"term":"ω","meaning":"Angular frequency of the AC signal, in radians per second.","function":false},{"term":"L","meaning":"Inductance of the inductor whose impedance is j omega L, measured in henries.","function":false},{"term":"Z_C","meaning":"Impedance of a capacitor, 1 over j omega C, purely imaginary and negative, in ohms.","function":false},{"term":"C","meaning":"Capacitance of the capacitor whose impedance is 1 over j omega C, measured in farads.","function":false},{"term":"Ṽ","meaning":"Voltage phasor, a complex number holding the sinusoid's amplitude and phase angle, in volts.","function":false},{"term":"Ĩ","meaning":"Current phasor, a complex number holding the current's amplitude and phase angle, in amperes.","function":false},{"term":"Z","meaning":"Complex impedance, R plus j X, the AC generalization of resistance, in ohms.","function":false},{"term":"|Z|","meaning":"Magnitude of impedance: takes the complex Z and returns its length, the square root of R squared plus X squared, in ohms.","function":true},{"term":"√","meaning":"Square root: takes R squared plus X squared and returns the impedance magnitude.","function":true},{"term":"X","meaning":"Reactance, the imaginary part of impedance from inductors and capacitors, in ohms.","function":false},{"term":"θ","meaning":"Phase angle of the impedance, by which voltage leads current, in degrees or radians.","function":false},{"term":"tan⁻¹","meaning":"Inverse tangent (arctangent): takes the ratio X over R and returns the angle whose tangent it is, the impedance phase angle.","function":true}],"explanation":"Phasors represent sinusoids as complex numbers, turning differential equations into algebra. Each element gets an impedance: ZR = R, ZL = jωL and ZC = 1/(jωC), and Ohm's law becomes V = IZ. The magnitude |Z| = √(R² + X²) and angle θ = tan⁻¹(X/R) give the size and phase shift; voltage leads current in inductors and lags it in capacitors.","origin":"Charles Proteus Steinmetz introduced complex-number phasor methods for AC circuits in 1893.","implementations":[{"name":"numpy.abs","library":"NumPy","note":"Magnitude of complex impedances."},{"name":"numpy.angle","library":"NumPy","note":"Phase angle of complex numbers."},{"name":"cmath.polar","library":"Python standard library","note":"Converts a complex number to magnitude and phase."}]},"EE.10":{"spoken":[{"line":0,"text":"P equals V sub r m s times I sub r m s times cosine theta."},{"line":1,"text":"Q equals V sub r m s times I sub r m s times sine theta."},{"line":2,"text":"The magnitude of S, squared, equals P squared plus Q squared; p f equals cosine theta."}],"terms":[{"term":"P","meaning":"Real (active) power actually consumed by the load, measured in watts (W).","function":false},{"term":"V_rms","meaning":"Root-mean-square (effective) voltage across the AC load, measured in volts.","function":false},{"term":"I_rms","meaning":"Root-mean-square (effective) current through the AC load, measured in amperes.","function":false},{"term":"cos θ","meaning":"Cosine of the voltage-current phase angle: takes θ and returns a value from 0 to 1, the fraction of apparent power that is real power.","function":true},{"term":"θ","meaning":"Phase angle between voltage and current, set by the load impedance angle.","function":false},{"term":"Q","meaning":"Reactive power exchanged back and forth with inductors and capacitors, measured in volt-amperes reactive (VAR).","function":false},{"term":"sin θ","meaning":"Sine of the phase angle: takes θ and returns the fraction of apparent power that is reactive.","function":true},{"term":"|S|","meaning":"Magnitude of complex power, the apparent power V_rms times I_rms, measured in volt-amperes (VA).","function":true},{"term":"S","meaning":"Complex power, P plus j Q, combining real and reactive power.","function":false},{"term":"pf","meaning":"Power factor, the ratio of real to apparent power, equal to cos θ; ranges from 0 to 1.","function":false}],"explanation":"In AC circuits, real power P = Vrms·Irms·cos θ does useful work, while reactive power Q = Vrms·Irms·sin θ sloshes back and forth in inductors and capacitors. Apparent power |S| combines them as |S|² = P² + Q², forming the power triangle. The power factor cos θ measures how efficiently current delivers real power; utilities penalize low power factor.","origin":"","implementations":[{"name":"numpy.cos","library":"NumPy","note":"Computes power factor from the phase angle."}]},"EE.11":{"spoken":[{"line":0,"text":"Omega sub 0 equals 1 over the square root of L C; f sub 0 equals 1 over the quantity 2 pi times the square root of L C."},{"line":1,"text":"Q sub series equals 1 over R times the square root of L over C."},{"line":2,"text":"B W equals omega sub 0 over Q."}],"terms":[{"term":"ω_0","meaning":"Resonant angular frequency, where inductive and capacitive reactances cancel, in radians per second.","function":false},{"term":"√","meaning":"Square root: takes L C (or L over C) and returns its positive root, setting the resonant frequency and quality factor.","function":true},{"term":"L","meaning":"Inductance of the inductor in the RLC circuit, measured in henries.","function":false},{"term":"C","meaning":"Capacitance of the capacitor in the RLC circuit, measured in farads.","function":false},{"term":"f_0","meaning":"Resonant frequency in cycles per second, measured in hertz; equals ω_0 over 2 pi.","function":false},{"term":"π","meaning":"Pi, about 3.14159, converting between radians per second and hertz.","function":false},{"term":"Q_series","meaning":"Quality factor of a series RLC circuit, dimensionless; higher Q means a sharper, narrower resonance peak.","function":false},{"term":"R","meaning":"Series resistance of the RLC circuit, in ohms, which damps the resonance.","function":false},{"term":"BW","meaning":"Bandwidth, the width of the resonance between the half-power points, in radians per second here.","function":false},{"term":"Q","meaning":"Quality factor of the resonant circuit, dimensionless, dividing ω_0 to give the bandwidth.","function":false}],"explanation":"A series or parallel RLC circuit resonates when inductive and capacitive reactances cancel, at ω0 = 1/√(LC), or f0 = 1/(2π√(LC)). The quality factor Q = (1/R)√(L/C) for a series circuit measures how sharp the resonance is, and bandwidth is BW = ω0/Q. High-Q circuits select narrow frequency bands, as in radio tuners and oscillators.","origin":"","implementations":[{"name":"scipy.signal.freqs","library":"SciPy","note":"Frequency response of an analog transfer function."},{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"AC sweep (.ac) analysis showing the resonant peak."}]},"EE.12":{"spoken":[{"line":0,"text":"H of j omega equals 1 over the quantity 1 plus j omega R C."},{"line":1,"text":"f sub c equals 1 over 2 pi R C."},{"line":2,"text":"The magnitude of H in decibels equals 20 log base 10 of the magnitude of H."},{"line":3,"text":"Negative 3 decibels at f sub c; negative 20 decibels per decade."}],"terms":[{"term":"H(jω)","meaning":"Transfer function of the RC low-pass filter: takes angular frequency and returns the complex ratio of output to input voltage.","function":true},{"term":"j","meaning":"Imaginary unit, the square root of −1, marking the capacitor's reactive contribution.","function":false},{"term":"ω","meaning":"Angular frequency of the input signal, in radians per second.","function":false},{"term":"R","meaning":"Series resistance of the RC low-pass filter, measured in ohms.","function":false},{"term":"C","meaning":"Shunt capacitance of the RC low-pass filter, measured in farads.","function":false},{"term":"f_c","meaning":"Cutoff (corner) frequency where output falls to 0.707 of the input, measured in hertz.","function":false},{"term":"π","meaning":"Pi, about 3.14159, converting angular frequency to hertz.","function":false},{"term":"|H|","meaning":"Magnitude of the transfer function: takes the complex H and returns the dimensionless gain, output amplitude over input amplitude.","function":true},{"term":"|H|_dB","meaning":"Filter gain expressed in decibels, a logarithmic scale; negative values mean attenuation.","function":false},{"term":"log₁₀","meaning":"Base-10 logarithm: takes a positive ratio and returns its power of ten; times 20 converts a voltage gain into decibels.","function":true},{"term":"dB","meaning":"Decibel, a logarithmic unit of ratio; −3 dB is the half-power point.","function":false},{"term":"dB/decade","meaning":"Slope of the gain curve per tenfold change in frequency; a first-order filter rolls off at −20 dB per decade.","function":false}],"explanation":"A first-order RC low-pass filter has transfer function H(jω) = 1/(1 + jωRC) and cutoff fc = 1/(2πRC). Gain in decibels is 20 log10|H|; at the cutoff |H| = 1/√2, or −3 dB, the half-power point. Above fc the response falls 20 dB per decade per RC stage. Bode plots show this magnitude and phase against log frequency.","origin":"Hendrik Bode developed the asymptotic frequency-response (Bode) plot at Bell Labs in the 1930s.","implementations":[{"name":"scipy.signal.bode","library":"SciPy","note":"Bode magnitude and phase of a continuous system."},{"name":"scipy.signal.butter","library":"SciPy","note":"Designs Butterworth filters of a given order and cutoff."},{"name":"scipy.signal.freqz","library":"SciPy","note":"Frequency response of a digital filter."}]},"EE.13":{"spoken":[{"line":0,"text":"Ideal: V sub plus equals V sub minus, I sub in equals zero."},{"line":1,"text":"Inverting: A equals negative R sub f over R sub in."},{"line":2,"text":"Non-inverting: A equals 1 plus R sub f over R sub g."}],"terms":[{"term":"V_+","meaning":"Voltage at the op-amp's non-inverting input, in volts.","function":false},{"term":"V_−","meaning":"Voltage at the op-amp's inverting input, in volts; equal to V_+ under negative feedback (virtual short).","function":false},{"term":"I_in","meaning":"Current flowing into the op-amp input terminals, in amperes; zero for an ideal op-amp.","function":false},{"term":"A","meaning":"Closed-loop voltage gain of the amplifier circuit, the dimensionless ratio of output to input voltage.","function":false},{"term":"R_f","meaning":"Feedback resistor from output to the inverting input, in ohms.","function":false},{"term":"R_in","meaning":"Input resistor from the signal source to the inverting input, in ohms.","function":false},{"term":"R_g","meaning":"Ground resistor from the inverting input to ground in the non-inverting amplifier, in ohms.","function":false}],"explanation":"With negative feedback, an ideal op-amp obeys two rules: its inputs sit at the same voltage, and no current flows into them. Applying them gives an inverting amplifier gain of −Rf/Rin and a non-inverting gain of 1 + Rf/Rg. Because gain depends only on resistor ratios, op-amp circuits are precise and stable; the same rules analyze summers, integrators and filters.","origin":"The two golden rules phrasing was popularized by Horowitz and Hill's The Art of Electronics (1980).","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Simulates op-amp circuits with vendor macromodels."}]},"EE.14":{"spoken":[{"line":0,"text":"I equals I sub s times the quantity e to the V over the quantity n V sub T, minus 1."},{"line":1,"text":"V sub T equals k T over q, which is approximately 25.9 millivolts."},{"line":2,"text":"R sub L E D equals the quantity V sub s minus V sub f, all over I."}],"terms":[{"term":"I","meaning":"Diode current in the Shockley equation, or the desired LED current in the resistor formula, in amperes.","function":false},{"term":"I_s","meaning":"Reverse saturation current of the diode, a tiny leakage current in amperes, often picoamps to nanoamps.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, base of the exponential.","function":false},{"term":"e^(V/(nV_T))","meaning":"Exponential function: takes the scaled diode voltage and returns a rapidly growing factor, so diode current rises exponentially with voltage.","function":true},{"term":"V","meaning":"Voltage across the diode, anode to cathode, in volts.","function":false},{"term":"n","meaning":"Ideality factor, a dimensionless number between about 1 and 2 describing how closely the diode follows ideal behavior.","function":false},{"term":"V_T","meaning":"Thermal voltage, k T over q, about 25.9 millivolts at room temperature.","function":false},{"term":"k","meaning":"Boltzmann constant, about 1.381 times 10 to the minus 23 joules per kelvin.","function":false},{"term":"T","meaning":"Absolute temperature of the junction, in kelvins (about 300 K at room temperature).","function":false},{"term":"q","meaning":"Elementary charge of an electron, about 1.602 times 10 to the minus 19 coulombs.","function":false},{"term":"mV","meaning":"Millivolt, one thousandth of a volt; the unit of the thermal voltage here.","function":false},{"term":"R_LED","meaning":"Series current-limiting resistor for the LED, in ohms.","function":false},{"term":"V_s","meaning":"Supply voltage feeding the LED circuit, in volts.","function":false},{"term":"V_f","meaning":"Forward voltage drop of the LED when conducting, in volts.","function":false}],"explanation":"The Shockley diode equation I = Is(e^(V/(nVT)) − 1) shows current growing exponentially with forward voltage, where Is is saturation current, n the ideality factor and VT = kT/q ≈ 25.9 mV the thermal voltage at room temperature. This steepness makes silicon diodes appear to turn on near 0.7 V. LEDs need a series resistor (Vs − Vf)/I to limit current.","origin":"William Shockley derived the ideal diode equation in 1949.","implementations":[{"name":"scipy.constants.k","library":"SciPy","note":"Boltzmann constant for computing kT/q."},{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Models diodes with exponential I-V characteristics."}]},"EE.15":{"spoken":[{"line":0,"text":"V sub s over V sub p equals N sub s over N sub p equals I sub p over I sub s."},{"line":1,"text":"P sub 3 phi equals the square root of 3 times V sub L times I sub L times p f."},{"line":2,"text":"Losses equal I squared R."}],"terms":[{"term":"V_s","meaning":"Voltage across the transformer's secondary (output) winding, measured in volts.","function":false},{"term":"V_p","meaning":"Voltage across the transformer's primary (input) winding, measured in volts.","function":false},{"term":"N_s","meaning":"Number of turns on the secondary winding, dimensionless.","function":false},{"term":"N_p","meaning":"Number of turns on the primary winding, dimensionless.","function":false},{"term":"I_p","meaning":"Primary winding current, in amperes; current scales inversely with the turns ratio.","function":false},{"term":"I_s","meaning":"Current in the transformer's secondary (output) winding, measured in amperes.","function":false},{"term":"P_3ϕ","meaning":"Total real power delivered by a balanced three-phase system, in watts.","function":false},{"term":"√","meaning":"Square root; root 3, about 1.732, relates line and phase quantities in a balanced three-phase system.","function":true},{"term":"V_L","meaning":"Line-to-line voltage of the three-phase system, in volts.","function":false},{"term":"I_L","meaning":"Line current in each of the three conductors, in amperes.","function":false},{"term":"pf","meaning":"Power factor of the load, cos θ, dimensionless between 0 and 1.","function":false},{"term":"losses","meaning":"Resistive (copper) power loss in conductors or windings, dissipated as heat, in watts.","function":false},{"term":"I","meaning":"Current through the conductor or winding, in amperes; losses grow with its square.","function":false},{"term":"R","meaning":"Resistance of the conductor or winding, in ohms.","function":false}],"explanation":"An ideal transformer scales voltage by the turns ratio, Vs/Vp = Ns/Np, and current by its inverse, so power in equals power out. Stepping voltage up for transmission cuts current and therefore I²R line losses. Three-phase systems deliver smooth power P = √3·VL·IL·pf using line voltage and current, and need less conductor than equivalent single-phase systems.","origin":"Practical AC transformers were developed in the mid-1880s; three-phase power was pioneered by Nikola Tesla and Mikhail Dolivo-Dobrovolsky in the late 1880s.","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Models transformers as coupled inductors (K element)."}]},"EE.16":{"spoken":[{"line":0,"text":"F equals k times q sub 1 q sub 2 over r squared, where k equals 8.99 times 10 to the ninth."},{"line":1,"text":"B equals mu sub 0 I over 2 pi r."},{"line":2,"text":"Script E equals negative N d Phi d t."},{"line":3,"text":"Bold F equals q times the quantity bold E plus bold v cross bold B."}],"terms":[{"term":"F","meaning":"Magnitude of the electrostatic force between two point charges (Coulomb's law), in newtons.","function":false},{"term":"k","meaning":"Coulomb's constant, about 8.99 times 10 to the ninth newton square meters per coulomb squared.","function":false},{"term":"q_1","meaning":"First point charge in Coulomb's law, measured in coulombs; its sign sets attraction or repulsion.","function":false},{"term":"q_2","meaning":"Second point charge in Coulomb's law, measured in coulombs; its sign sets attraction or repulsion.","function":false},{"term":"r","meaning":"Distance between the charges, or from the wire to the field point, in meters.","function":false},{"term":"B","meaning":"Magnetic flux density around a long straight current-carrying wire, in teslas.","function":false},{"term":"μ_0","meaning":"Permeability of free space, about 4 pi times 10 to the minus 7 henries per meter.","function":false},{"term":"I","meaning":"Current flowing in the long straight wire, measured in amperes.","function":false},{"term":"π","meaning":"Pi, about 3.14159; 2 pi r is the circumference around the wire.","function":false},{"term":"ℰ","meaning":"Induced electromotive force (EMF) in a coil, from Faraday's law, in volts.","function":false},{"term":"N","meaning":"Number of turns of wire in the coil, a dimensionless count.","function":false},{"term":"dΦ/dt","meaning":"Time derivative of magnetic flux: takes Φ(t) and returns its rate of change in webers per second; the minus sign is Lenz's law.","function":true},{"term":"Φ","meaning":"Magnetic flux through one turn of the coil, in webers.","function":false},{"term":"𝐅","meaning":"Lorentz force vector on a moving charge, in newtons.","function":false},{"term":"q","meaning":"Electric charge of the moving particle feeling the Lorentz force, in coulombs.","function":false},{"term":"𝐄","meaning":"Electric field vector, in volts per meter (newtons per coulomb).","function":false},{"term":"𝐯","meaning":"Velocity vector of the charged particle, in meters per second.","function":false},{"term":"×","meaning":"Vector cross product: takes two vectors and returns a vector perpendicular to both; gives the magnetic force direction.","function":true},{"term":"𝐁","meaning":"Magnetic field vector acting on the moving charge, measured in teslas.","function":false}],"explanation":"Coulomb's law F = kq1q2/r² gives the force between point charges. A long straight wire carrying current I produces a magnetic field B = μ0I/(2πr). Faraday's law ℰ = −N dΦ/dt says a changing magnetic flux induces an EMF, the minus sign (Lenz's law) meaning it opposes the change. The Lorentz force F = q(E + v × B) combines both fields' effects on a moving charge.","origin":"Coulomb published his law in 1785, Faraday discovered induction in 1831, Lenz stated his rule in 1834, and Lorentz formulated the force law in the 1890s.","implementations":[{"name":"scipy.constants.mu_0","library":"SciPy","note":"Vacuum permeability constant."},{"name":"scipy.constants.epsilon_0","library":"SciPy","note":"Vacuum permittivity, giving k = 1/(4πε0)."},{"name":"numpy.cross","library":"NumPy","note":"Cross product for v × B."}]},"EE.17":{"spoken":[{"line":0,"text":"N equals the sum of b sub i times 2 to the i; n bits gives 2 to the n values."},{"line":1,"text":"The quantity A and B, bar, equals A bar or B bar."},{"line":2,"text":"The quantity A or B, bar, equals A bar and B bar."}],"terms":[{"term":"N","meaning":"Decimal value of a binary number, an integer.","function":false},{"term":"Σ","meaning":"Summation over bit positions i: adds each bit times its place value to produce the number's decimal value.","function":true},{"term":"b_i","meaning":"The bit (0 or 1) at position i of the binary number, counting from 0 at the least significant bit.","function":false},{"term":"2^i","meaning":"Place value of bit position i, a power of two.","function":false},{"term":"i","meaning":"Index of the bit position, starting at 0 for the rightmost bit.","function":false},{"term":"n","meaning":"Number of bits in a binary word, a positive integer.","function":false},{"term":"2^n","meaning":"Number of distinct values representable with n bits.","function":false},{"term":"A","meaning":"First Boolean variable in De Morgan's laws, logic 0 or 1.","function":false},{"term":"·","meaning":"Boolean AND: returns 1 only when both inputs are 1.","function":true},{"term":"B","meaning":"Second Boolean variable in De Morgan's laws, logic 0 or 1.","function":false},{"term":"overbar","meaning":"Boolean NOT (complement): a bar over a variable or expression inverts it; De Morgan's laws move the bar and swap AND with OR.","function":true},{"term":"+","meaning":"Boolean OR (not addition): returns 1 when at least one input is 1.","function":true}],"explanation":"A binary number's value is N = Σ bi·2^i, so n bits represent 2^n distinct values. Boolean algebra manipulates logic expressions using AND, OR and NOT. De Morgan's laws convert between them: the complement of A·B equals Ā + B̄, and the complement of A + B equals Ā·B̄. They let designers rewrite circuits using only NAND or only NOR gates.","origin":"George Boole introduced Boolean algebra in 1847-1854, and Augustus De Morgan stated his laws in 1847.","implementations":[{"name":"bin","library":"Python built-in","note":"Converts an integer to a binary string."},{"name":"int","library":"Python built-in","note":"int(s, 2) parses a binary string."},{"name":"sympy.logic.boolalg.simplify_logic","library":"SymPy","note":"Simplifies Boolean expressions."}]},"EE.18":{"spoken":[{"line":0,"text":"f sub s is greater than 2 f sub max."},{"line":1,"text":"Resolution equals V sub ref over 2 to the N."},{"line":2,"text":"S Q N R is approximately 6.02 N plus 1.76 decibels."}],"terms":[{"term":"f_s","meaning":"Sampling rate, the number of samples taken per second, in hertz.","function":false},{"term":"f_max","meaning":"Highest frequency component in the signal, in hertz; sampling above twice this avoids aliasing (Nyquist criterion).","function":false},{"term":"resolution","meaning":"Smallest voltage step an ADC can distinguish, one least significant bit, in volts.","function":false},{"term":"V_ref","meaning":"Reference voltage setting the ADC's full-scale input range, in volts.","function":false},{"term":"N","meaning":"Number of bits of resolution of the analog-to-digital converter.","function":false},{"term":"2^N","meaning":"Number of discrete quantization levels for an N-bit converter.","function":false},{"term":"SQNR","meaning":"Signal-to-quantization-noise ratio, the ideal ratio of full-scale sine power to quantization noise power, in decibels.","function":false},{"term":"dB","meaning":"Decibel, a logarithmic ratio unit; each extra bit adds about 6 dB.","function":false}],"explanation":"The sampling theorem says a band-limited signal can be reconstructed exactly if sampled faster than twice its highest frequency, fs > 2fmax; slower sampling causes aliasing. An N-bit converter divides its reference range into 2^N steps, giving resolution Vref/2^N. Ideal quantization noise yields SQNR ≈ 6.02N + 1.76 dB for a full-scale sine, about 6 dB per bit.","origin":"Harry Nyquist laid the groundwork in 1928 and Claude Shannon proved the sampling theorem in 1949; Whittaker and Kotelnikov reached it independently.","implementations":[{"name":"scipy.signal.resample","library":"SciPy","note":"Resamples a signal using the Fourier method."},{"name":"scipy.signal.decimate","library":"SciPy","note":"Downsamples with an anti-aliasing filter."}]},"EE.19":{"spoken":[{"line":0,"text":"Decibels equal 10 log base 10 of P sub 2 over P sub 1, which equals 20 log base 10 of V sub 2 over V sub 1."},{"line":1,"text":"S N R equals P sub signal over P sub noise."},{"line":2,"text":"C equals B log base 2 of the quantity 1 plus S N R."}],"terms":[{"term":"dB","meaning":"Decibel, a logarithmic measure of the ratio between two power or voltage levels.","function":false},{"term":"log₁₀","meaning":"Base-10 logarithm: takes a positive ratio and returns its exponent of ten; scaled by 10 for power or 20 for voltage to give decibels.","function":true},{"term":"P_2","meaning":"Output or measured power level being compared, in watts.","function":false},{"term":"P_1","meaning":"Reference or input power level for the comparison, in watts.","function":false},{"term":"V_2","meaning":"Output or measured voltage being compared, measured in volts.","function":false},{"term":"V_1","meaning":"Reference or input voltage for the comparison, measured in volts.","function":false},{"term":"SNR","meaning":"Signal-to-noise ratio, signal power over noise power; dimensionless (linear) in the capacity formula.","function":false},{"term":"P_signal","meaning":"Average power of the desired signal, in watts.","function":false},{"term":"P_noise","meaning":"Average power of the unwanted noise in the channel, in watts.","function":false},{"term":"C","meaning":"Shannon channel capacity, the maximum error-free data rate, in bits per second.","function":false},{"term":"B","meaning":"Bandwidth of the communication channel, measured in hertz.","function":false},{"term":"log₂","meaning":"Base-2 logarithm: takes 1 plus SNR and returns bits per symbol, converting signal quality into information rate.","function":true}],"explanation":"Decibels express ratios logarithmically: 10 log10(P2/P1) for power or 20 log10(V2/V1) for voltage, since power scales with voltage squared. Signal-to-noise ratio compares signal power to noise power. The Shannon–Hartley theorem C = B log2(1 + SNR) gives the maximum error-free data rate of a channel with bandwidth B, using SNR as a linear ratio.","origin":"Claude Shannon established channel capacity in 1948, building on Ralph Hartley's 1928 work; the decibel was named for Alexander Graham Bell in the 1920s.","implementations":[{"name":"numpy.log10","library":"NumPy","note":"Computes decibel values from ratios."},{"name":"numpy.log2","library":"NumPy","note":"Base-2 logarithm for channel capacity."}]},"EE.20":{"spoken":[{"line":0,"text":"x of t equals the sum over n of c sub n times e to the j n omega sub 0 t."},{"line":1,"text":"X sub k equals the sum from n equals 0 to N minus 1 of x sub n times e to the negative j 2 pi k n over N."},{"line":2,"text":"Delta f equals f sub s over N."},{"line":3,"text":"FFT: big O of N log N."}],"terms":[{"term":"x(t)","meaning":"Periodic continuous-time signal being represented as a sum of complex exponentials.","function":true},{"term":"t","meaning":"Continuous time variable of the periodic signal, measured in seconds.","function":false},{"term":"Σ","meaning":"Summation: over all harmonics n for the Fourier series, or over samples n from 0 to N minus 1 for the DFT.","function":true},{"term":"n","meaning":"Harmonic index in the Fourier series, or sample index in the DFT.","function":false},{"term":"c_n","meaning":"Complex Fourier coefficient of harmonic n, giving its amplitude and phase.","function":false},{"term":"e^(jnω₀t)","meaning":"Complex exponential: takes time and returns a rotating unit phasor at harmonic n, cos plus j sin of n ω_0 t.","function":true},{"term":"j","meaning":"Imaginary unit, the square root of −1, used in complex exponentials.","function":false},{"term":"ω_0","meaning":"Fundamental angular frequency of the periodic signal, in radians per second.","function":false},{"term":"X_k","meaning":"DFT output at frequency bin k: takes the N samples and returns a complex number for that frequency's amplitude and phase.","function":true},{"term":"k","meaning":"Frequency bin index, from 0 to N minus 1.","function":false},{"term":"N","meaning":"Number of samples in the DFT block (and FFT size).","function":false},{"term":"x_n","meaning":"The n-th time-domain sample of the discrete signal.","function":false},{"term":"π","meaning":"Pi, about 3.14159; 2 pi radians correspond to one full cycle.","function":false},{"term":"Δf","meaning":"Frequency resolution, the spacing between DFT bins, in hertz.","function":false},{"term":"f_s","meaning":"Sampling rate of the discrete signal, measured in hertz (samples per second).","function":false},{"term":"FFT","meaning":"Fast Fourier Transform, an efficient algorithm that computes the DFT.","function":false},{"term":"O(·)","meaning":"Big-O notation: takes a function of input size and describes how the algorithm's running time grows; the FFT grows as N log N.","function":true},{"term":"log","meaning":"Logarithm (base 2 for radix-2 FFT): takes N and returns the number of halving stages.","function":true}],"explanation":"A Fourier series writes a periodic signal as a sum of complex exponentials cn·e^(jnω0t) at harmonics of its fundamental. The discrete Fourier transform Xk = Σ xn e^(−j2πkn/N) does the same for N samples, with frequency resolution Δf = fs/N. Computed directly it costs O(N²); the fast Fourier transform reduces this to O(N log N).","origin":"Joseph Fourier introduced Fourier series in 1807-1822; James Cooley and John Tukey published the FFT algorithm in 1965, though Gauss had found it around 1805.","implementations":[{"name":"numpy.fft.fft","library":"NumPy","note":"Fast Fourier transform of a signal."},{"name":"numpy.fft.fftfreq","library":"NumPy","note":"Frequency bins for FFT output."},{"name":"scipy.fft.fft","library":"SciPy","note":"Fast Fourier transform with extra options."},{"name":"FFTW","library":"FFTW (C library)","note":"High-performance FFT implementation."}]},"EE.21":{"spoken":[{"line":0,"text":"E in watt-hours equals V times amp-hours."},{"line":1,"text":"t equals capacity in amp-hours over I."},{"line":2,"text":"C-rate equals I over capacity."}],"terms":[{"term":"E","meaning":"Energy stored in the battery, measured in watt-hours (Wh).","function":false},{"term":"Wh","meaning":"Watt-hour, a unit of energy equal to one watt for one hour (3,600 joules).","function":false},{"term":"V","meaning":"Nominal terminal voltage of the battery, measured in volts.","function":false},{"term":"Ah","meaning":"Amp-hour, a unit of charge capacity equal to one ampere for one hour.","function":false},{"term":"t","meaning":"Runtime of the battery at the given load current, in hours.","function":false},{"term":"capacity","meaning":"Battery charge capacity, the total charge it can deliver, in amp-hours.","function":false},{"term":"I","meaning":"Load or charging current drawn from the battery, in amperes.","function":false},{"term":"C-rate","meaning":"Charge or discharge current relative to capacity, per hour; 1C empties the battery in one hour.","function":false}],"explanation":"Battery capacity in amp-hours (Ah) is charge; multiplying by voltage gives energy in watt-hours, E = V × Ah, the fair way to compare batteries. Runtime is roughly capacity divided by load current, t = Ah/I. C-rate expresses current relative to capacity: 1C empties the battery in an hour. Real capacity falls at high C-rates and low temperatures.","origin":"Alessandro Volta built the first battery in 1800; Sony commercialized the lithium-ion battery in 1991.","implementations":[{"name":"PyBaMM","library":"PyBaMM (Python)","note":"Physics-based battery modelling and simulation."}]},"EE.22":{"spoken":[{"line":0,"text":"Resistor: V equals I R."},{"line":1,"text":"Capacitor: i equals C d v d t."},{"line":2,"text":"Inductor: v equals L d i d t."},{"line":3,"text":"Transformer: V sub s over V sub p equals N sub s over N sub p."}],"terms":[{"term":"V","meaning":"Voltage across the resistor's terminals, measured in volts.","function":false},{"term":"I","meaning":"Current flowing through the resistor, measured in amperes.","function":false},{"term":"R","meaning":"Resistance of the resistor, opposing current flow, measured in ohms.","function":false},{"term":"i","meaning":"Instantaneous current through the capacitor or inductor, in amperes.","function":false},{"term":"C","meaning":"Capacitance of the capacitor, charge stored per volt, measured in farads.","function":false},{"term":"dv/dt","meaning":"Time derivative of capacitor voltage: returns its rate of change in volts per second; capacitor current is C times it.","function":true},{"term":"v","meaning":"Instantaneous voltage across the capacitor or inductor, in volts.","function":false},{"term":"L","meaning":"Inductance of the inductor, opposing changes in current, measured in henries.","function":false},{"term":"di/dt","meaning":"Time derivative of inductor current: returns its rate of change in amperes per second; inductor voltage is L times it.","function":true},{"term":"V_s","meaning":"Secondary winding voltage of the transformer, in volts.","function":false},{"term":"V_p","meaning":"Primary winding voltage of the transformer, in volts.","function":false},{"term":"N_s","meaning":"Number of wire turns on the transformer's secondary winding, dimensionless.","function":false},{"term":"N_p","meaning":"Number of wire turns on the transformer's primary winding, dimensionless.","function":false}],"explanation":"Passive component symbols each encode a defining law. The zigzag resistor obeys V = IR; the parallel-plate capacitor obeys i = C dv/dt; the coiled inductor obeys v = L di/dt; and the transformer, two coils sharing a core, scales voltage by turns ratio, Vs/Vp = Ns/Np. Switches are drawn as hinged contacts that open or close a path.","origin":"","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Simulates R, C, L, K and switch elements."}]},"EE.23":{"spoken":[{"line":0,"text":"Ideal voltage source: fixed V."},{"line":1,"text":"Ideal current source: fixed I."},{"line":3,"text":"Ground equals zero volts."}],"terms":[{"term":"V","meaning":"Voltage held constant by an ideal voltage source regardless of the current drawn, in volts; also the unit volt for ground.","function":false},{"term":"I","meaning":"Current held constant by an ideal current source regardless of the voltage across it, in amperes.","function":false}],"explanation":"Ideal voltage sources fix the voltage across them and ideal current sources fix the current through them, regardless of load. Ground marks the 0 V reference node. Meters follow the rule volts across, amps through: a voltmeter connects in parallel with high input resistance, while an ammeter is inserted in series with near-zero resistance so neither disturbs the circuit.","origin":"","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Defines V and I sources with node 0 as ground."}]},"EE.24":{"spoken":[{"line":1,"text":"I equals I sub s times the quantity e to the V over n V sub T, minus 1."},{"line":2,"text":"Op-amp: V sub out equals A times the quantity V sub plus minus V sub minus."}],"terms":[{"term":"I","meaning":"Diode current in the Shockley diode equation, in amperes.","function":false},{"term":"I_s","meaning":"Reverse saturation current of the diode, a tiny leakage current in amperes.","function":false},{"term":"e","meaning":"Euler's number, about 2.718, base of the exponential.","function":false},{"term":"e^(V/nV_T)","meaning":"Exponential function: takes the scaled diode voltage and returns a rapidly growing factor, making diode current rise exponentially with voltage.","function":true},{"term":"V","meaning":"Voltage across the diode from anode to cathode, in volts.","function":false},{"term":"n","meaning":"Ideality factor of the diode, dimensionless, between about 1 and 2.","function":false},{"term":"V_T","meaning":"Thermal voltage, k T over q, about 25.9 millivolts at room temperature.","function":false},{"term":"V_out","meaning":"Output voltage of the op-amp, measured in volts.","function":false},{"term":"A","meaning":"Open-loop gain of the op-amp, dimensionless and very large.","function":false},{"term":"V_+","meaning":"Voltage at the op-amp's non-inverting (plus) input, in volts.","function":false},{"term":"V_−","meaning":"Voltage at the op-amp's inverting (minus) input, in volts.","function":false}],"explanation":"The diode symbol's triangle points along conventional current from anode to cathode, with the bar marking the cathode; its current follows the Shockley equation I = Is(e^(V/nVT) − 1). The op-amp triangle has + and − inputs and outputs Vout = A(V+ − V−) with very large gain A, so feedback is used to set practical gain.","origin":"","implementations":[{"name":"SPICE","library":"Circuit simulator (ngspice, LTspice)","note":"Models diodes (D element) and op-amps (subcircuits)."}]},"EE.25":{"spoken":[{"line":0,"text":"AND: A and B. OR: A or B. NOT: A bar."},{"line":1,"text":"NAND: the quantity A and B, bar. XOR: A x-or B."}],"terms":[{"term":"A","meaning":"First binary logic input to the gate, logic 0 or 1.","function":false},{"term":"·","meaning":"Boolean AND operator: returns 1 only when both inputs are 1.","function":true},{"term":"B","meaning":"Second binary logic input to the gate, logic 0 or 1.","function":false},{"term":"+","meaning":"Boolean OR operator (not addition): returns 1 when at least one input is 1.","function":true},{"term":"overbar","meaning":"Boolean NOT: a bar over a variable or expression inverts it; over A·B it forms NAND.","function":true},{"term":"⊕","meaning":"Exclusive-OR operator: returns 1 when exactly one of the two inputs is 1.","function":true}],"explanation":"Logic gate symbols follow shape conventions: AND has a flat back and round front, OR has a curved back and pointed front, and XOR adds a second curved line. A bubble on an output means inversion, turning AND into NAND (the complement of A·B) and OR into NOR. NOT is a triangle with a bubble. These map directly to Boolean expressions.","origin":"Distinctive-shape gate symbols are standardized in IEEE Std 91 / ANSI Y32.14.","implementations":[{"name":"Logisim","library":"Logisim (logic simulator)","note":"Draw and simulate gate-level logic circuits."}]},"AL.1":{"spoken":[{"line":0,"text":"Supervised, regression. Fits y hat equals X beta by least squares. Used for: pricing, forecasting, effect sizes."}],"terms":[{"term":"ŷ","meaning":"Vector of predicted target values produced by the fitted linear regression model.","function":false},{"term":"X","meaning":"Design matrix of features, one row per observation and one column per predictor, often with an intercept column.","function":false},{"term":"β","meaning":"Vector of regression coefficients, chosen by least squares to minimize the sum of squared residuals.","function":false}],"explanation":"Linear regression models a continuous target as a weighted sum of features, ŷ = Xβ. Ordinary least squares picks β to minimize the sum of squared residuals, with closed-form solution β = (XᵀX)⁻¹Xᵀy. It is fast and interpretable, each coefficient estimating a feature's effect holding the others fixed, and is widely used for pricing, forecasting and measuring effect sizes.","origin":"Adrien-Marie Legendre published least squares in 1805 and Carl Friedrich Gauss in 1809; Francis Galton coined regression in the 1880s.","implementations":[{"name":"sklearn.linear_model.LinearRegression","library":"scikit-learn","note":"Ordinary least squares regression estimator."},{"name":"statsmodels.api.OLS","library":"statsmodels","note":"OLS with standard errors and inference."},{"name":"numpy.linalg.lstsq","library":"NumPy","note":"Least-squares solution to a linear system."},{"name":"lm","library":"R (stats)","note":"Fits linear models."}]},"AL.23":{"spoken":[{"line":0,"text":"Unsupervised, or collaborative filtering. Low-rank user by item factors. Used for: recommender systems."}],"terms":[{"term":"×","meaning":"Read 'by': denotes the user-by-item rating matrix, which is approximated by a product of low-rank user and item factor matrices.","function":false}],"explanation":"Matrix factorization approximates a sparse user × item rating matrix as the product of two low-rank matrices of latent factors. Each user and item gets a short vector, and their dot product predicts a rating. Fitted by alternating least squares or stochastic gradient descent on observed entries, it powers collaborative-filtering recommender systems that generalize to unseen user-item pairs.","origin":"It was popularized for recommendations during the Netflix Prize competition (2006-2009).","implementations":[{"name":"surprise.SVD","library":"Surprise","note":"Funk-style SVD matrix factorization for ratings."},{"name":"implicit.als.AlternatingLeastSquares","library":"implicit","note":"ALS factorization for implicit feedback."},{"name":"sklearn.decomposition.NMF","library":"scikit-learn","note":"Non-negative matrix factorization."},{"name":"pyspark.ml.recommendation.ALS","library":"Apache Spark MLlib","note":"Distributed ALS recommender."}]},"AC.12":{"spoken":[{"line":0,"text":"Rectified Linear Unit: activation max of 0 comma x."}],"terms":[{"term":"max","meaning":"Maximum function: takes two numbers and returns the larger; max(0, x) passes positive inputs unchanged and zeroes negatives.","function":true},{"term":"x","meaning":"Input to the activation, a neuron's pre-activation value (weighted sum plus bias).","function":false}],"explanation":"The Rectified Linear Unit is the activation function max(0, x): it passes positive inputs unchanged and outputs zero for negative ones. It is cheap to compute and its gradient is 1 for positive inputs, which avoids the vanishing gradients of sigmoid and tanh and speeds training of deep networks. Its main drawback is dead units that output zero permanently.","origin":"Kunihiko Fukushima used rectification in 1969; Nair and Hinton (2010) and Glorot et al. (2011) popularized ReLU in deep learning.","implementations":[{"name":"torch.nn.ReLU","library":"PyTorch","note":"ReLU activation layer."},{"name":"torch.nn.functional.relu","library":"PyTorch","note":"Functional ReLU on tensors."},{"name":"tf.nn.relu","library":"TensorFlow","note":"Applies ReLU to a tensor."},{"name":"numpy.maximum","library":"NumPy","note":"numpy.maximum(0, x) computes ReLU."}]},"AC.16":{"spoken":[{"line":0,"text":"Singular Value Decomposition: A equals U Sigma V transpose."}],"terms":[{"term":"A","meaning":"Any real m by n data matrix being decomposed.","function":false},{"term":"U","meaning":"Orthogonal matrix whose columns are the left singular vectors of A.","function":false},{"term":"Σ","meaning":"Diagonal matrix of non-negative singular values, sorted largest first; not a summation here.","function":false},{"term":"V","meaning":"Orthogonal matrix whose columns are the right singular vectors of A.","function":false},{"term":"⊤","meaning":"Transpose operator: takes a matrix and returns it with rows and columns swapped.","function":true}],"explanation":"Singular value decomposition factors any matrix as A = UΣVᵀ, where U and V have orthonormal columns and Σ is diagonal with non-negative singular values in decreasing order. Keeping only the largest singular values gives the best low-rank approximation. SVD underlies PCA, pseudoinverses, least squares, latent semantic analysis, image compression and recommender systems.","origin":"Eugenio Beltrami (1873) and Camille Jordan (1874) discovered it; Gene Golub and William Kahan developed the standard computation in 1965.","implementations":[{"name":"numpy.linalg.svd","library":"NumPy","note":"Full or reduced SVD of a matrix."},{"name":"scipy.linalg.svd","library":"SciPy","note":"SVD via LAPACK."},{"name":"sklearn.decomposition.TruncatedSVD","library":"scikit-learn","note":"Top-k SVD for large sparse data."},{"name":"torch.linalg.svd","library":"PyTorch","note":"SVD of tensors."}]},"AC.25":{"spoken":[{"line":0,"text":"Maximum Likelihood Estimate, or Maximum A Posteriori estimate, likelihood times prior."}],"terms":[{"term":"×","meaning":"Multiplication of the likelihood by the prior, which is proportional to the posterior that MAP maximizes.","function":false}],"explanation":"Maximum likelihood estimation picks the parameter values that make the observed data most probable, maximizing the likelihood p(data | θ). Maximum a posteriori estimation also multiplies in a prior, maximizing p(data | θ)·p(θ), the mode of the Bayesian posterior. MAP acts like regularized MLE (a Gaussian prior gives L2 regularization) and converges to MLE as data grows.","origin":"Ronald Fisher developed and named maximum likelihood between 1912 and 1922.","implementations":[{"name":"scipy.stats.norm.fit","library":"SciPy","note":"MLE of normal distribution parameters."},{"name":"scipy.optimize.minimize","library":"SciPy","note":"Minimizes negative log-likelihood or log-posterior."},{"name":"statsmodels.base.model.GenericLikelihoodModel","library":"statsmodels","note":"Custom MLE models."}]},"AC.30":{"spoken":[{"line":0,"text":"Interquartile Range, Q sub 3 minus Q sub 1."}],"terms":[{"term":"Q_3","meaning":"Third quartile, the 75th percentile of the data.","function":false},{"term":"Q_1","meaning":"First quartile, the 25th percentile of the data.","function":false}],"explanation":"The interquartile range is Q3 − Q1, the spread of the middle 50% of data. Because it ignores the extreme quarters, it is robust to outliers, unlike the standard deviation. It sets the box length in a box plot, and Tukey's rule flags points beyond 1.5 × IQR from the quartiles as potential outliers.","origin":"John Tukey popularized the box plot and the 1.5 × IQR outlier rule in Exploratory Data Analysis (1977).","implementations":[{"name":"scipy.stats.iqr","library":"SciPy","note":"Computes the interquartile range."},{"name":"numpy.percentile","library":"NumPy","note":"Quartiles for computing Q3 − Q1."},{"name":"pandas.Series.quantile","library":"pandas","note":"Quantiles of a Series."},{"name":"IQR","library":"R (stats)","note":"Interquartile range of a vector."}]},"KT.4":{"spoken":[{"line":0,"text":"Even: f of negative x equals f of x, symmetric about the y-axis. Odd: f of negative x equals negative f of x, symmetric about the origin."}],"terms":[{"term":"f","meaning":"A real-valued function: takes an input x and returns an output; its behavior under negating x determines even or odd.","function":true},{"term":"x","meaning":"Input variable of the function, any real number in its domain.","function":false},{"term":"y","meaning":"Vertical axis of the graph; even functions mirror across the y-axis.","function":false}],"explanation":"A function is even if f(−x) = f(x), making its graph mirror-symmetric about the y-axis, like x² or cos x. It is odd if f(−x) = −f(x), giving rotational symmetry about the origin, like x³ or sin x. Any function splits into even and odd parts, and over symmetric intervals odd functions integrate to zero.","origin":"","implementations":[]},"KT.8":{"spoken":[{"line":0,"text":"A is necessary for B if B implies A; sufficient if A implies B."}],"terms":[{"term":"A","meaning":"A condition or statement being tested as necessary or sufficient.","function":false},{"term":"B","meaning":"The outcome or statement whose conditions are being described.","function":false},{"term":"⇒","meaning":"Logical implication: 'if the left is true, the right is true'; P implies Q fails only when P is true and Q false.","function":true}],"explanation":"A is necessary for B when B cannot hold without A, written B ⇒ A. A is sufficient for B when A alone guarantees B, written A ⇒ B. When both hold, A and B are equivalent (A ⇔ B, if and only if). For example, being a square is sufficient but not necessary for being a rectangle.","origin":"","implementations":[]},"KT.10":{"spoken":[{"line":0,"text":"Parameter describes a population, mu; statistic describes a sample, x bar."}],"terms":[{"term":"μ","meaning":"Population mean, a fixed, usually unknown parameter of the whole population.","function":false},{"term":"x̄","meaning":"Sample mean, the average of observed sample values, a statistic used to estimate μ.","function":false}],"explanation":"A parameter is a fixed, usually unknown number describing a whole population, such as the population mean μ or standard deviation σ. A statistic is a quantity computed from a sample, such as the sample mean x̄, and varies from sample to sample. Statistical inference uses statistics as estimators of parameters and quantifies their uncertainty.","origin":"Ronald Fisher introduced the term statistic in this sense in 1922.","implementations":[{"name":"numpy.mean","library":"NumPy","note":"Sample mean, a statistic estimating μ."},{"name":"scipy.stats.describe","library":"SciPy","note":"Summary statistics of a sample."}]},"KT.23":{"spoken":[{"line":0,"text":"Normalization rescales to the closed interval from 0 to 1; standardization gives mean 0, SD 1."}],"terms":[{"term":"[0, 1]","meaning":"Closed interval from 0 to 1 inclusive, the target range of min-max normalization.","function":false}],"explanation":"Normalization (min-max scaling) maps each feature to [0, 1] via (x − min)/(max − min). Standardization (z-scoring) subtracts the mean and divides by the standard deviation, giving mean 0 and SD 1. Both put features on comparable scales for distance-based and gradient-trained models; standardization is less sensitive to outliers and does not bound the range.","origin":"","implementations":[{"name":"sklearn.preprocessing.MinMaxScaler","library":"scikit-learn","note":"Scales features to a given range, default [0, 1]."},{"name":"sklearn.preprocessing.StandardScaler","library":"scikit-learn","note":"Standardizes features to mean 0, SD 1."},{"name":"scipy.stats.zscore","library":"SciPy","note":"Computes z-scores of an array."}]},"KT.32":{"spoken":[{"line":1,"text":"Softmax of Q K transpose over the square root of d, times V."}],"terms":[{"term":"softmax","meaning":"Softmax function: takes a row of scores and returns positive weights summing to 1; here it turns query-key similarities into attention weights.","function":true},{"term":"Q","meaning":"Query matrix, one row per token, holding what each position is looking for.","function":false},{"term":"K","meaning":"Key matrix, one row per token, describing what each position offers for matching.","function":false},{"term":"⊤","meaning":"Transpose: swaps rows and columns of K so Q times K transpose gives all query-key dot products.","function":true},{"term":"√","meaning":"Square root: takes d and returns its root, used to scale scores so softmax does not saturate.","function":true},{"term":"d","meaning":"Dimension of the query and key vectors (often written d_k).","function":false},{"term":"V","meaning":"Value matrix, one row per token; the attention weights average these rows to form the output.","function":false}],"explanation":"Attention lets a model weight its inputs by relevance. Scaled dot-product attention compares query vectors Q with key vectors K, divides by √d to keep scores well-scaled, applies softmax to get weights summing to one, and uses them to average the value vectors V. Multi-head attention runs several such computations in parallel and is the core of transformers.","origin":"Bahdanau, Cho and Bengio introduced neural attention in 2014; Vaswani et al. introduced scaled dot-product attention in the 2017 Transformer.","implementations":[{"name":"torch.nn.MultiheadAttention","library":"PyTorch","note":"Multi-head attention layer."},{"name":"torch.nn.functional.scaled_dot_product_attention","library":"PyTorch","note":"Fused scaled dot-product attention."},{"name":"tf.keras.layers.MultiHeadAttention","library":"TensorFlow / Keras","note":"Multi-head attention layer."}]},"ET.6":{"spoken":[{"line":0,"text":"AC generalization of resistance, Z equals R plus j X, in ohms."}],"terms":[{"term":"Z","meaning":"Complex impedance, the total opposition to AC current, in ohms.","function":false},{"term":"R","meaning":"Resistance, the real part of impedance, dissipating power, in ohms.","function":false},{"term":"j","meaning":"Imaginary unit, the square root of −1, marking the reactive part.","function":false},{"term":"X","meaning":"Reactance, the imaginary part of impedance from inductors and capacitors, in ohms.","function":false}],"explanation":"Impedance generalizes resistance to AC as the complex number Z = R + jX, measured in ohms. The real part R dissipates energy, while the imaginary reactance X stores and returns it, shifting the phase between voltage and current. Ohm's law becomes V = IZ with phasors, so AC circuits can be analyzed with the same algebra as resistive ones.","origin":"Oliver Heaviside coined the term impedance in 1886.","implementations":[{"name":"numpy.abs","library":"NumPy","note":"Magnitude |Z| of complex impedance."},{"name":"numpy.angle","library":"NumPy","note":"Phase angle of complex impedance."}]},"ET.7":{"spoken":[{"line":0,"text":"The imaginary part of impedance from inductors, positive, and capacitors, negative."}],"terms":[{"term":"(+)","meaning":"Inductive reactance is positive, X_L equals omega L, in ohms.","function":false},{"term":"(−)","meaning":"Capacitive reactance is negative, X_C equals minus 1 over omega C, in ohms.","function":false}],"explanation":"Reactance X is the imaginary part of impedance, representing energy stored in fields rather than dissipated. Inductors have positive reactance XL = ωL, rising with frequency; capacitors have negative reactance XC = −1/(ωC), shrinking in magnitude with frequency. When they cancel the circuit is resonant, and net reactance sets whether current lags or leads voltage.","origin":"","implementations":[]},"ET.8":{"spoken":[{"line":0,"text":"Reciprocal of resistance, G equals 1 over R, in siemens."}],"terms":[{"term":"G","meaning":"Conductance, how easily current flows, measured in siemens (S).","function":false},{"term":"R","meaning":"Resistance, the reciprocal of conductance, measured in ohms.","function":false}],"explanation":"Conductance G = 1/R measures how easily current flows, in siemens (S); it is the reciprocal of resistance. It is convenient for parallel circuits, where conductances simply add, and in nodal analysis, where the conductance matrix relates node voltages to injected currents. Its AC counterpart is admittance, Y = 1/Z, whose real part is conductance.","origin":"The siemens, named after Werner von Siemens, replaced the older unit mho as the SI unit in 1971.","implementations":[]},"FT.15":{"spoken":[{"line":0,"text":"Rising market, bull, versus falling market, typically negative 20 percent or more, bear."}],"terms":[{"term":"%","meaning":"Percent; a bear market is commonly defined as a decline of 20 percent or more from a recent peak.","function":false}],"explanation":"A bull market is a sustained period of rising prices and optimism; a bear market is a sustained decline, conventionally defined as a fall of 20% or more from a recent peak. A drop of 10% to 20% is usually called a correction. The terms describe market sentiment and trends and are applied to stocks, indexes and other assets.","origin":"","implementations":[]}};
})(window.Site = window.Site || {});
